VALUES (1,'OA','1.OA.1','Use Addition & Subtraction Within 20 to Solve Word Problems (Easy)','Students use addition and subtraction within 20 to solve word problems involving situations of adding to, taking from, putting together, taking apart, and comparing - with unknowns in all positions. T','practice',1,10,1,'[{"id":1,"text":"Tom has 3 apples. He gets 2 more. How many apples does he have now?","type":"numeric","correct_answer":"5","explanation":"3 + 2 = 5. This is an \"adding to\" problem. Start with 3 and count on 2 more.","standard_code":"1.OA.1","difficulty":1},{"id":2,"text":"Sara has 6 flowers. She gives 1 away. How many flowers does she have left?","type":"numeric","correct_answer":"5","explanation":"6 - 1 = 5. This is a \"taking from\" problem. Start with 6 and take away 1.","standard_code":"1.OA.1","difficulty":1},{"id":3,"text":"There are 4 birds on a branch. 3 more birds fly over. How many birds are there now?","type":"numeric","correct_answer":"7","explanation":"4 + 3 = 7. This is a \"putting together\" problem. Combine both groups.","standard_code":"1.OA.1","difficulty":1},{"id":4,"text":"Mike has 8 crayons. He loses 3. How many crayons does he have now?","type":"numeric","correct_answer":"5","explanation":"8 - 3 = 5. Start with 8 and take away 3.","standard_code":"1.OA.1","difficulty":1},{"id":5,"text":"A basket has 5 red apples and 4 green apples. How many apples are there altogether?","type":"numeric","correct_answer":"9","explanation":"5 + 4 = 9. This is a \"putting together\" problem. Add both groups.","standard_code":"1.OA.1","difficulty":1}]'::jsonb);

VALUES (1,'OA','1.OA.1','Use Addition & Subtraction Within 20 to Solve Word Problems (Medium)','Students use addition and subtraction within 20 to solve word problems involving situations of adding to, taking from, putting together, taking apart, and comparing - with unknowns in all positions. T','practice',2,15,2,'[{"id":1,"text":"There were 12 children at the park. 5 went home. How many are still at the park?","type":"numeric","correct_answer":"7","explanation":"12 - 5 = 7. Use make-a-ten: 12 - 2 = 10, 10 - 3 = 7.","standard_code":"1.OA.1","difficulty":2},{"id":2,"text":"Jake scored 7 points in game 1 and 8 points in game 2. How many points total?","type":"numeric","correct_answer":"15","explanation":"7 + 8 = 15. Use make-a-ten: 7 + 3 = 10, then 10 + 5 = 15.","standard_code":"1.OA.1","difficulty":2},{"id":3,"text":"Maria picked 14 berries. She ate some and had 9 left. How many did she eat?","type":"numeric","correct_answer":"5","explanation":"14 - 9 = 5. Think: 9 + ? = 14. Count up from 9 to 14: that is 5 more.","standard_code":"1.OA.1","difficulty":2},{"id":4,"text":"There are 6 cats and some dogs. Together there are 13 animals. How many dogs are there?","type":"numeric","correct_answer":"7","explanation":"6 + ? = 13. Think: 13 - 6 = 7. There are 7 dogs.","standard_code":"1.OA.1","difficulty":2},{"id":5,"text":"Ann has 9 stickers. She gives 4 to a friend, then gets 6 more from her teacher. How many does she have now?","type":"numeric","correct_answer":"11","explanation":"9 - 4 = 5, then 5 + 6 = 11. Solve one step at a time.","standard_code":"1.OA.1","difficulty":2}]'::jsonb);

VALUES (1,'OA','1.OA.1','Use Addition & Subtraction Within 20 to Solve Word Problems (Hard)','Students use addition and subtraction within 20 to solve word problems involving situations of adding to, taking from, putting together, taking apart, and comparing - with unknowns in all positions. T','practice',3,20,3,'[{"id":1,"text":"Lily read 8 pages on Monday and some pages on Tuesday. She read 17 pages in total. How many pages did she read on Tuesday?","type":"numeric","correct_answer":"9","explanation":"8 + ? = 17. Think: 17 - 8 = 9. Make-a-ten: 8 + 2 = 10, 10 + 7 = 17, so 2 + 7 = 9.","standard_code":"1.OA.1","difficulty":3},{"id":2,"text":"Sam had some toy cars. He got 7 more and now has 15. How many did he start with?","type":"numeric","correct_answer":"8","explanation":"? + 7 = 15. Think: 15 - 7 = 8. Make-a-ten: 7 + 3 = 10, 10 + 5 = 15, so 3 + 5 = 8.","standard_code":"1.OA.1","difficulty":3},{"id":3,"text":"Max had 16 apples. He ate 4 and gave 3 to his sister. How many does he have left?","type":"numeric","correct_answer":"9","explanation":"16 - 4 = 12, then 12 - 3 = 9. Solve step by step.","standard_code":"1.OA.1","difficulty":3},{"id":4,"text":"There are 9 girls and some boys in a class of 16 students. How many more girls than boys are there?","type":"multiple_choice","correct_answer":"2 more girls","explanation":"Boys = 16 - 9 = 7. Difference = 9 - 7 = 2. There are 2 more girls than boys.","standard_code":"1.OA.1","difficulty":3,"options":[{"label":"5 more girls","value":"5 more girls"},{"label":"2 more girls","value":"2 more girls"},{"label":"7 more girls","value":"7 more girls"},{"label":"2 more boys","value":"2 more boys"}]},{"id":5,"text":"Ben had 20 stickers. He gave some to Ana and now has 11. Ana gave 3 stickers back to Ben. How many stickers does Ana have now?","type":"numeric","correct_answer":"6","explanation":"Ben gave away: 20 - 11 = 9. Ana got 9 and gave 3 back: 9 - 3 = 6.","standard_code":"1.OA.1","difficulty":3}]'::jsonb);

VALUES (1,'OA','1.OA.2','Add Three Whole Numbers Whose Sum Is 20 or Less (Easy)','Students add three whole numbers whose sum is 20 or less. They apply strategies such as making ten, using doubles, or looking for pairs of numbers that are easy to add to improve efficiency.','practice',1,10,4,'[{"id":1,"text":"2 + 3 + 1 = ?","type":"numeric","correct_answer":"6","explanation":"2 + 3 = 5, then 5 + 1 = 6. Add from left to right.","standard_code":"1.OA.2","difficulty":1},{"id":2,"text":"1 + 4 + 2 = ?","type":"numeric","correct_answer":"7","explanation":"1 + 4 = 5, then 5 + 2 = 7.","standard_code":"1.OA.2","difficulty":1},{"id":3,"text":"3 + 2 + 3 = ?","type":"numeric","correct_answer":"8","explanation":"3 + 2 = 5, then 5 + 3 = 8.","standard_code":"1.OA.2","difficulty":1},{"id":4,"text":"1 + 1 + 5 = ?","type":"numeric","correct_answer":"7","explanation":"1 + 1 = 2, then 2 + 5 = 7.","standard_code":"1.OA.2","difficulty":1},{"id":5,"text":"2 + 2 + 4 = ?","type":"numeric","correct_answer":"8","explanation":"2 + 2 = 4, then 4 + 4 = 8.","standard_code":"1.OA.2","difficulty":1}]'::jsonb);

VALUES (1,'OA','1.OA.2','Add Three Whole Numbers Whose Sum Is 20 or Less (Medium)','Students add three whole numbers whose sum is 20 or less. They apply strategies such as making ten, using doubles, or looking for pairs of numbers that are easy to add to improve efficiency.','practice',2,15,5,'[{"id":1,"text":"4 + 6 + 3 = ?","type":"numeric","correct_answer":"13","explanation":"Make-a-ten: 4 + 6 = 10, then 10 + 3 = 13.","standard_code":"1.OA.2","difficulty":2},{"id":2,"text":"5 + 3 + 7 = ?","type":"numeric","correct_answer":"15","explanation":"Make-a-ten: 3 + 7 = 10, then 10 + 5 = 15.","standard_code":"1.OA.2","difficulty":2},{"id":3,"text":"2 + 8 + 6 = ?","type":"numeric","correct_answer":"16","explanation":"Make-a-ten: 2 + 8 = 10, then 10 + 6 = 16.","standard_code":"1.OA.2","difficulty":2},{"id":4,"text":"4 + 6 + 5 = ?","type":"numeric","correct_answer":"15","explanation":"Make-a-ten: 4 + 6 = 10, then 10 + 5 = 15.","standard_code":"1.OA.2","difficulty":2},{"id":5,"text":"7 + 3 + 5 = ?","type":"numeric","correct_answer":"15","explanation":"Make-a-ten: 7 + 3 = 10, then 10 + 5 = 15.","standard_code":"1.OA.2","difficulty":2}]'::jsonb);

VALUES (1,'OA','1.OA.2','Add Three Whole Numbers Whose Sum Is 20 or Less (Hard)','Students add three whole numbers whose sum is 20 or less. They apply strategies such as making ten, using doubles, or looking for pairs of numbers that are easy to add to improve efficiency.','practice',3,20,6,'[{"id":1,"text":"8 + 4 + 5 = ?","type":"numeric","correct_answer":"17","explanation":"Decompose 4 as 2 + 2: 8 + 2 = 10, then 10 + 2 + 5 = 17.","standard_code":"1.OA.2","difficulty":3},{"id":2,"text":"Find three different numbers that add up to 18.","type":"multiple_choice","correct_answer":"Many valid answers, e.g. 5 + 6 + 7 = 18","explanation":"5 + 6 + 7 = 18; or 3 + 6 + 9 = 18. Look for pairs that make ten first.","standard_code":"1.OA.2","difficulty":3,"options":[{"label":"1 + 9 + 10 = 18","value":"1 + 9 + 10 = 18"},{"label":"Many valid answers, e.g. 5 + 6 + 7 = 18","value":"Many valid answers, e.g. 5 + 6 + 7 = 18"},{"label":"3 + 4 + 11 = 18","value":"3 + 4 + 11 = 18"},{"label":"2 + 8 + 8 = 18","value":"2 + 8 + 8 = 18"}]},{"id":3,"text":"7 + 6 + ? = 20. What is the missing number?","type":"numeric","correct_answer":"7","explanation":"7 + 6 = 13. Then 20 - 13 = 7.","standard_code":"1.OA.2","difficulty":3},{"id":4,"text":"8 + 2 + 9 = ?","type":"numeric","correct_answer":"19","explanation":"Make-a-ten: 8 + 2 = 10, then 10 + 9 = 19.","standard_code":"1.OA.2","difficulty":3},{"id":5,"text":"6 + 5 + 9 = ?","type":"numeric","correct_answer":"20","explanation":"5 + 9 = 14 (near-doubles: 5 + 5 = 10, 5 + 9 = 14), then 14 + 6 = 20.","standard_code":"1.OA.2","difficulty":3}]'::jsonb);

VALUES (1,'OA','1.OA.3','Apply Properties of Operations to Add and Subtract (Easy)','Students apply properties as strategies: the commutative property (order does not change the sum: 3 + 5 = 5 + 3), the associative property (grouping does not change the sum: (2 + 6) + 4 = 2 + (6 + 4))','practice',1,10,7,'[{"id":1,"text":"If 5 + 3 = 8, what is 3 + 5?","type":"numeric","correct_answer":"8","explanation":"Commutative property: changing the order of addends does not change the sum.","standard_code":"1.OA.3","difficulty":1},{"id":2,"text":"If 7 + 2 = 9, what is 2 + 7?","type":"numeric","correct_answer":"9","explanation":"Commutative property: 2 + 7 = 9, same as 7 + 2.","standard_code":"1.OA.3","difficulty":1},{"id":3,"text":"If 1 + 4 = 5, what is 4 + 1?","type":"numeric","correct_answer":"5","explanation":"Commutative property: switching the order gives the same answer.","standard_code":"1.OA.3","difficulty":1},{"id":4,"text":"If 6 + 3 = 9, what is 3 + 6?","type":"numeric","correct_answer":"9","explanation":"Commutative property: 3 + 6 = 9.","standard_code":"1.OA.3","difficulty":1},{"id":5,"text":"If 2 + 5 = 7, what is 5 + 2?","type":"numeric","correct_answer":"7","explanation":"Commutative property: numbers can be added in any order.","standard_code":"1.OA.3","difficulty":1}]'::jsonb);

VALUES (1,'OA','1.OA.3','Apply Properties of Operations to Add and Subtract (Medium)','Students apply properties as strategies: the commutative property (order does not change the sum: 3 + 5 = 5 + 3), the associative property (grouping does not change the sum: (2 + 6) + 4 = 2 + (6 + 4))','practice',2,15,8,'[{"id":1,"text":"(3 + 7) + 6 = ? Use the grouping that makes it easiest.","type":"numeric","correct_answer":"16","explanation":"Associative property: group 3 + 7 = 10 first, then 10 + 6 = 16.","standard_code":"1.OA.3","difficulty":2},{"id":2,"text":"8 + (2 + 5) = ?","type":"numeric","correct_answer":"15","explanation":"Associative property: 8 + 2 = 10 (make a ten), then 10 + 5 = 15.","standard_code":"1.OA.3","difficulty":2},{"id":3,"text":"(9 + 1) + 4 = ?","type":"numeric","correct_answer":"14","explanation":"9 + 1 = 10, then 10 + 4 = 14.","standard_code":"1.OA.3","difficulty":2},{"id":4,"text":"If 4 + 8 = 12, write two related subtraction facts.","type":"multiple_choice","correct_answer":"12 - 8 = 4 and 12 - 4 = 8","explanation":"Addition and subtraction are inverse operations. If a + b = c, then c - a = b and c - b = a.","standard_code":"1.OA.3","difficulty":2,"options":[{"label":"4 + 8 = 12 and 12 - 4 = 8","value":"4 + 8 = 12 and 12 - 4 = 8"},{"label":"12 - 8 = 4 and 12 - 4 = 8","value":"12 - 8 = 4 and 12 - 4 = 8"},{"label":"8 - 4 = 4 and 8 - 12 = -4","value":"8 - 4 = 4 and 8 - 12 = -4"},{"label":"12 - 4 = 8 and 12 - 9 = 3","value":"12 - 4 = 8 and 12 - 9 = 3"}]},{"id":5,"text":"6 + (4 + 7) = ?","type":"numeric","correct_answer":"17","explanation":"Group 6 + 4 = 10, then 10 + 7 = 17.","standard_code":"1.OA.3","difficulty":2}]'::jsonb);

VALUES (1,'OA','1.OA.3','Apply Properties of Operations to Add and Subtract (Hard)','Students apply properties as strategies: the commutative property (order does not change the sum: 3 + 5 = 5 + 3), the associative property (grouping does not change the sum: (2 + 6) + 4 = 2 + (6 + 4))','practice',3,20,9,'[{"id":1,"text":"5 + (5 + 8) = ? Show two different ways to solve it.","type":"numeric","correct_answer":"18","explanation":"Way 1: 5 + 5 = 10, then 10 + 8 = 18. Way 2: 5 + 8 = 13, then 13 + 5 = 18. Both use the associative property.","standard_code":"1.OA.3","difficulty":3},{"id":2,"text":"If 7 + 9 = 16, write two subtraction sentences using the same numbers.","type":"multiple_choice","correct_answer":"16 - 7 = 9 and 16 - 9 = 7","explanation":"Inverse operations: if 7 + 9 = 16, then 16 - 7 = 9 and 16 - 9 = 7.","standard_code":"1.OA.3","difficulty":3,"options":[{"label":"16 - 9 = 7 and 7 + 9 = 16","value":"16 - 9 = 7 and 7 + 9 = 16"},{"label":"16 - 7 = 9 and 9 - 7 = 2","value":"16 - 7 = 9 and 9 - 7 = 2"},{"label":"7 + 9 = 16 and 16 + 7 = 23","value":"7 + 9 = 16 and 16 + 7 = 23"},{"label":"16 - 7 = 9 and 16 - 9 = 7","value":"16 - 7 = 9 and 16 - 9 = 7"}]},{"id":3,"text":"(6 + 4) + (7 + 3) = ?","type":"numeric","correct_answer":"20","explanation":"Group: 6 + 4 = 10 and 7 + 3 = 10. Then 10 + 10 = 20.","standard_code":"1.OA.3","difficulty":3},{"id":4,"text":"Decompose 6 to make adding easier: 9 + 6 = ?","type":"numeric","correct_answer":"15","explanation":"Decompose 6 as 1 + 5: 9 + 1 = 10, then 10 + 5 = 15.","standard_code":"1.OA.3","difficulty":3},{"id":5,"text":"Is 8 + (7 + 5) the same as (8 + 7) + 5? Explain.","type":"multiple_choice","correct_answer":"Yes, both equal 20","explanation":"Associative property: grouping does not change the sum. 8 + 12 = 20 and 15 + 5 = 20.","standard_code":"1.OA.3","difficulty":3,"options":[{"label":"Yes, both equal 25","value":"Yes, both equal 25"},{"label":"No, one equals 20 and the other equals 23","value":"No, one equals 20 and the other equals 23"},{"label":"No, they are not the same","value":"No, they are not the same"},{"label":"Yes, both equal 20","value":"Yes, both equal 20"}]}]'::jsonb);

VALUES (1,'OA','1.OA.4','Understand Subtraction as an Unknown-Addend Problem (Easy)','Students understand that subtraction can be thought of as finding an unknown addend. For example, 10 - 8 = ? is the same as asking 8 + ? = 10. This links subtraction to addition and helps students use','practice',1,10,10,'[{"id":1,"text":"5 - 2 = ? Think: 2 + ? = 5","type":"numeric","correct_answer":"3","explanation":"2 + 3 = 5, so 5 - 2 = 3. Count up from 2 to 5: that is 3 counts.","standard_code":"1.OA.4","difficulty":1},{"id":2,"text":"7 - 3 = ? Think: 3 + ? = 7","type":"numeric","correct_answer":"4","explanation":"3 + 4 = 7, so 7 - 3 = 4.","standard_code":"1.OA.4","difficulty":1},{"id":3,"text":"6 - 1 = ? Think: 1 + ? = 6","type":"numeric","correct_answer":"5","explanation":"1 + 5 = 6, so 6 - 1 = 5.","standard_code":"1.OA.4","difficulty":1},{"id":4,"text":"8 - 4 = ? Think: 4 + ? = 8","type":"numeric","correct_answer":"4","explanation":"4 + 4 = 8, so 8 - 4 = 4. Count up from 4 to 8.","standard_code":"1.OA.4","difficulty":1},{"id":5,"text":"9 - 5 = ? Think: 5 + ? = 9","type":"numeric","correct_answer":"4","explanation":"5 + 4 = 9, so 9 - 5 = 4.","standard_code":"1.OA.4","difficulty":1}]'::jsonb);

VALUES (1,'OA','1.OA.4','Understand Subtraction as an Unknown-Addend Problem (Medium)','Students understand that subtraction can be thought of as finding an unknown addend. For example, 10 - 8 = ? is the same as asking 8 + ? = 10. This links subtraction to addition and helps students use','practice',2,15,11,'[{"id":1,"text":"10 - 6 = ? Think: 6 + ? = 10","type":"numeric","correct_answer":"4","explanation":"6 + 4 = 10, so 10 - 6 = 4. You need 4 more to get from 6 to 10.","standard_code":"1.OA.4","difficulty":2},{"id":2,"text":"12 - 7 = ? Think: 7 + ? = 12","type":"numeric","correct_answer":"5","explanation":"Make-a-ten: 7 + 3 = 10, then 10 + 2 = 12, so 3 + 2 = 5.","standard_code":"1.OA.4","difficulty":2},{"id":3,"text":"14 - 8 = ? Think: 8 + ? = 14","type":"numeric","correct_answer":"6","explanation":"Make-a-ten: 8 + 2 = 10, then 10 + 4 = 14, so 2 + 4 = 6.","standard_code":"1.OA.4","difficulty":2},{"id":4,"text":"There are 11 children. 5 are girls. How many are boys? Think: 5 + ? = 11","type":"numeric","correct_answer":"6","explanation":"5 + 6 = 11, so there are 6 boys.","standard_code":"1.OA.4","difficulty":2},{"id":5,"text":"15 - 9 = ? Think: 9 + ? = 15","type":"numeric","correct_answer":"6","explanation":"Make-a-ten: 9 + 1 = 10, then 10 + 5 = 15, so 1 + 5 = 6.","standard_code":"1.OA.4","difficulty":2}]'::jsonb);

VALUES (1,'OA','1.OA.4','Understand Subtraction as an Unknown-Addend Problem (Hard)','Students understand that subtraction can be thought of as finding an unknown addend. For example, 10 - 8 = ? is the same as asking 8 + ? = 10. This links subtraction to addition and helps students use','practice',3,20,12,'[{"id":1,"text":"16 - 9 = ? Write it as an unknown addend equation and solve.","type":"numeric","correct_answer":"7","explanation":"9 + ? = 16. Make-a-ten: 9 + 1 = 10, 10 + 6 = 16, so 1 + 6 = 7.","standard_code":"1.OA.4","difficulty":3},{"id":2,"text":"Write both a subtraction and an unknown-addend equation for: ? relates 9 and 18.","type":"multiple_choice","correct_answer":"18 - 9 = 9 and 9 + ? = 18, ? = 9","explanation":"9 + 9 = 18 (doubles fact), so 18 - 9 = 9.","standard_code":"1.OA.4","difficulty":3,"options":[{"label":"18 - 9 = 9 and 9 + 9 = 18","value":"18 - 9 = 9 and 9 + 9 = 18"},{"label":"9 + 18 = 27 and 18 - 9 = 9","value":"9 + 18 = 27 and 18 - 9 = 9"},{"label":"18 - 9 = 9 and 9 + ? = 18, ? = 9","value":"18 - 9 = 9 and 9 + ? = 18, ? = 9"},{"label":"9 - 9 = 0 and 9 + ? = 18, ? = 9","value":"9 - 9 = 0 and 9 + ? = 18, ? = 9"}]},{"id":3,"text":"A farmer has 20 eggs. He sold some and has 13 left. Write an unknown-addend equation and solve.","type":"multiple_choice","correct_answer":"? + 13 = 20, ? = 7","explanation":"13 + 7 = 20, so he sold 7 eggs.","standard_code":"1.OA.4","difficulty":3,"options":[{"label":"20 + ? = 13, ? = -7","value":"20 + ? = 13, ? = -7"},{"label":"? + 13 = 20, ? = 7","value":"? + 13 = 20, ? = 7"},{"label":"13 + ? = 20, ? = 7","value":"13 + ? = 20, ? = 7"},{"label":"? - 13 = 20, ? = 33","value":"? - 13 = 20, ? = 33"}]},{"id":4,"text":"? + 8 = 17. What is the missing number?","type":"numeric","correct_answer":"9","explanation":"8 + ? = 17. Make-a-ten: 8 + 2 = 10, 10 + 7 = 17, so 2 + 7 = 9.","standard_code":"1.OA.4","difficulty":3},{"id":5,"text":"Is 15 - 6 = 9 true? Write the unknown-addend equation to verify.","type":"multiple_choice","correct_answer":"Yes; 6 + 9 = 15","explanation":"6 + 9 = 15 is true, so 15 - 6 = 9 is also true.","standard_code":"1.OA.4","difficulty":3,"options":[{"label":"No; 6 + 8 = 14","value":"No; 6 + 8 = 14"},{"label":"Yes; 6 + 9 = 15","value":"Yes; 6 + 9 = 15"},{"label":"Yes; 9 - 6 = 3","value":"Yes; 9 - 6 = 3"},{"label":"Yes; 15 - 9 = 6","value":"Yes; 15 - 9 = 6"}]}]'::jsonb);

VALUES (1,'OA','1.OA.5','Relate Counting to Addition and Subtraction (Easy)','Students relate counting sequences to addition and subtraction. Counting on (starting at one number and counting up) represents addition; counting back represents subtraction. Counting up from the sma','practice',1,10,13,'[{"id":1,"text":"Start at 4 and count on 2. What number do you land on?","type":"numeric","correct_answer":"6","explanation":"4 ... 5, 6. Counting on 2 from 4 is the same as 4 + 2 = 6.","standard_code":"1.OA.5","difficulty":1},{"id":2,"text":"Start at 7 and count back 3. What number do you land on?","type":"numeric","correct_answer":"4","explanation":"7 ... 6, 5, 4. Counting back 3 from 7 is the same as 7 - 3 = 4.","standard_code":"1.OA.5","difficulty":1},{"id":3,"text":"Count on 3 from 5. What is the answer?","type":"numeric","correct_answer":"8","explanation":"5 ... 6, 7, 8. This is the same as 5 + 3 = 8.","standard_code":"1.OA.5","difficulty":1},{"id":4,"text":"Count back 2 from 8. What do you get?","type":"numeric","correct_answer":"6","explanation":"8 ... 7, 6. This is the same as 8 - 2 = 6.","standard_code":"1.OA.5","difficulty":1},{"id":5,"text":"6 + 3 = ? Use counting on to find the answer.","type":"numeric","correct_answer":"9","explanation":"Start at 6, count on 3: 7, 8, 9. The answer is 9.","standard_code":"1.OA.5","difficulty":1}]'::jsonb);

VALUES (1,'OA','1.OA.5','Relate Counting to Addition and Subtraction (Medium)','Students relate counting sequences to addition and subtraction. Counting on (starting at one number and counting up) represents addition; counting back represents subtraction. Counting up from the sma','practice',2,15,14,'[{"id":1,"text":"To find 13 - 5, count up from 5 to 13. How many counts is that?","type":"numeric","correct_answer":"8","explanation":"5 ... 6, 7, 8, 9, 10, 11, 12, 13. That is 8 counts. So 13 - 5 = 8.","standard_code":"1.OA.5","difficulty":2},{"id":2,"text":"11 - 7 = ? Count up from 7 to 11 to find the answer.","type":"numeric","correct_answer":"4","explanation":"7 ... 8, 9, 10, 11. That is 4 counts. 11 - 7 = 4.","standard_code":"1.OA.5","difficulty":2},{"id":3,"text":"Count on 6 from 9. Write the addition equation.","type":"multiple_choice","correct_answer":"15; equation: 9 + 6 = 15","explanation":"9, 10, 11, 12, 13, 14, 15. Same as 9 + 6 = 15.","standard_code":"1.OA.5","difficulty":2,"options":[{"label":"15; equation: 9 + 6 = 15","value":"15; equation: 9 + 6 = 15"},{"label":"21; equation: 6 + 9 = 15","value":"21; equation: 6 + 9 = 15"},{"label":"24; equation: 9 + 15 = 24","value":"24; equation: 9 + 15 = 24"},{"label":"14; equation: 9 + 5 = 14","value":"14; equation: 9 + 5 = 14"}]},{"id":4,"text":"14 - 6 = ? Use counting up or counting back to solve.","type":"numeric","correct_answer":"8","explanation":"Count up from 6: 7, 8, 9, 10, 11, 12, 13, 14. That is 8 counts. 14 - 6 = 8.","standard_code":"1.OA.5","difficulty":2},{"id":5,"text":"A number line shows 15. Count back 7 steps. Where do you land?","type":"numeric","correct_answer":"8","explanation":"15, 14, 13, 12, 11, 10, 9, 8. Same as 15 - 7 = 8.","standard_code":"1.OA.5","difficulty":2}]'::jsonb);

VALUES (1,'OA','1.OA.5','Relate Counting to Addition and Subtraction (Hard)','Students relate counting sequences to addition and subtraction. Counting on (starting at one number and counting up) represents addition; counting back represents subtraction. Counting up from the sma','practice',3,20,15,'[{"id":1,"text":"Mia counts up 8 times starting at 9. Write an addition equation and give the answer.","type":"multiple_choice","correct_answer":"9 + 8 = 17","explanation":"Starting at 9 and counting up 8 times: 9 + 8 = 17.","standard_code":"1.OA.5","difficulty":3,"options":[{"label":"9 + 8 = 16","value":"9 + 8 = 16"},{"label":"8 + 8 = 16","value":"8 + 8 = 16"},{"label":"9 + 8 = 17","value":"9 + 8 = 17"},{"label":"9 + 9 = 18","value":"9 + 9 = 18"}]},{"id":2,"text":"A frog jumps back 5 spaces from 14 on a number line. Write a subtraction equation.","type":"multiple_choice","correct_answer":"14 - 5 = 9","explanation":"14 ... 13, 12, 11, 10, 9. Same as 14 - 5 = 9.","standard_code":"1.OA.5","difficulty":3,"options":[{"label":"14 - 5 = 9","value":"14 - 5 = 9"},{"label":"9 - 5 = 4","value":"9 - 5 = 4"},{"label":"14 - 9 = 5","value":"14 - 9 = 5"},{"label":"14 + 5 = 19","value":"14 + 5 = 19"}]},{"id":3,"text":"7 + ? = 20. Use counting on to find the missing number.","type":"numeric","correct_answer":"13","explanation":"Start at 7, count up to 20: that is 13 counts. 7 + 13 = 20.","standard_code":"1.OA.5","difficulty":3},{"id":4,"text":"How many counts from 6 to 18? Write an addition equation.","type":"multiple_choice","correct_answer":"12 counts; 6 + 12 = 18","explanation":"Count up from 6 to 18: 12 counts. Equation: 6 + 12 = 18.","standard_code":"1.OA.5","difficulty":3,"options":[{"label":"12 counts; 6 + 12 = 18","value":"12 counts; 6 + 12 = 18"},{"label":"18 counts; 6 + 18 = 24","value":"18 counts; 6 + 18 = 24"},{"label":"6 counts; 6 + 6 = 12","value":"6 counts; 6 + 6 = 12"},{"label":"11 counts; 6 + 11 = 17","value":"11 counts; 6 + 11 = 17"}]},{"id":5,"text":"20 - 8 = ? Count back on a number line to solve.","type":"numeric","correct_answer":"12","explanation":"Start at 20, count back 8: 19, 18, 17, 16, 15, 14, 13, 12. Answer is 12.","standard_code":"1.OA.5","difficulty":3}]'::jsonb);

VALUES (1,'OA','1.OA.6','Add and Subtract Within 20 - Fluency Within 10 (Easy)','Students develop fluency with addition and subtraction within 20, using strategies such as making ten, decomposing a number to make ten, using doubles, using near-doubles, and counting on. They are ex','practice',1,10,16,'[{"id":1,"text":"4 + 3 = ?","type":"numeric","correct_answer":"7","explanation":"Basic fact: 4 + 3 = 7. Know this from memory.","standard_code":"1.OA.6","difficulty":1},{"id":2,"text":"9 - 4 = ?","type":"numeric","correct_answer":"5","explanation":"Basic fact: 9 - 4 = 5. Know this from memory.","standard_code":"1.OA.6","difficulty":1},{"id":3,"text":"6 + 2 = ?","type":"numeric","correct_answer":"8","explanation":"Basic fact: 6 + 2 = 8. Know this from memory.","standard_code":"1.OA.6","difficulty":1},{"id":4,"text":"7 - 5 = ?","type":"numeric","correct_answer":"2","explanation":"Basic fact: 7 - 5 = 2. Know this from memory.","standard_code":"1.OA.6","difficulty":1},{"id":5,"text":"5 + 5 = ?","type":"numeric","correct_answer":"10","explanation":"Doubles fact: 5 + 5 = 10. Know this from memory.","standard_code":"1.OA.6","difficulty":1}]'::jsonb);

VALUES (1,'OA','1.OA.6','Add and Subtract Within 20 - Fluency Within 10 (Medium)','Students develop fluency with addition and subtraction within 20, using strategies such as making ten, decomposing a number to make ten, using doubles, using near-doubles, and counting on. They are ex','practice',2,15,17,'[{"id":1,"text":"7 + 6 = ? (Use near-doubles)","type":"numeric","correct_answer":"13","explanation":"Near-doubles: 7 + 7 = 14, so 7 + 6 = 13 (one less).","standard_code":"1.OA.6","difficulty":2},{"id":2,"text":"8 + 5 = ? (Use make-a-ten)","type":"numeric","correct_answer":"13","explanation":"Make-a-ten: 8 + 2 = 10, then 10 + 3 = 13. Decompose 5 as 2 + 3.","standard_code":"1.OA.6","difficulty":2},{"id":3,"text":"13 - 6 = ?","type":"numeric","correct_answer":"7","explanation":"Think of the related addition fact: 6 + 7 = 13, so 13 - 6 = 7.","standard_code":"1.OA.6","difficulty":2},{"id":4,"text":"9 + 4 = ?","type":"numeric","correct_answer":"13","explanation":"Make-a-ten: 9 + 1 = 10, then 10 + 3 = 13. Decompose 4 as 1 + 3.","standard_code":"1.OA.6","difficulty":2},{"id":5,"text":"15 - 7 = ?","type":"numeric","correct_answer":"8","explanation":"7 + 8 = 15, so 15 - 7 = 8. Or: 15 - 5 = 10, 10 - 2 = 8.","standard_code":"1.OA.6","difficulty":2}]'::jsonb);

VALUES (1,'OA','1.OA.6','Add and Subtract Within 20 - Fluency Within 10 (Hard)','Students develop fluency with addition and subtraction within 20, using strategies such as making ten, decomposing a number to make ten, using doubles, using near-doubles, and counting on. They are ex','practice',3,20,18,'[{"id":1,"text":"16 - 8 = ?","type":"numeric","correct_answer":"8","explanation":"Doubles fact: 8 + 8 = 16, so 16 - 8 = 8.","standard_code":"1.OA.6","difficulty":3},{"id":2,"text":"9 + 8 = ?","type":"numeric","correct_answer":"17","explanation":"Make-a-ten: 9 + 1 = 10, 10 + 7 = 17. Or near-doubles: 8 + 8 = 16, so 9 + 8 = 17.","standard_code":"1.OA.6","difficulty":3},{"id":3,"text":"18 - 9 = ?","type":"numeric","correct_answer":"9","explanation":"Doubles fact: 9 + 9 = 18, so 18 - 9 = 9.","standard_code":"1.OA.6","difficulty":3},{"id":4,"text":"7 + 8 = ?","type":"numeric","correct_answer":"15","explanation":"Make-a-ten: 7 + 3 = 10, 10 + 5 = 15. Or near-doubles: 7 + 7 = 14, so 7 + 8 = 15.","standard_code":"1.OA.6","difficulty":3},{"id":5,"text":"14 - 6 = ?","type":"numeric","correct_answer":"8","explanation":"Related fact: 6 + 8 = 14, so 14 - 6 = 8.","standard_code":"1.OA.6","difficulty":3}]'::jsonb);

VALUES (1,'OA','1.OA.7','Understand the Equal Sign - True or False Equations (Easy)','Students understand the meaning of the equal sign as "the same value as," not just as "the answer comes next." They determine whether addition and subtraction equations are true or false, including eq','practice',1,10,19,'[{"id":1,"text":"Is 3 + 4 = 7 true or false?","type":"multiple_choice","correct_answer":"True","explanation":"3 + 4 = 7. The left side equals the right side, so it is true.","standard_code":"1.OA.7","difficulty":1,"options":[{"label":"True","value":"True"},{"label":"False","value":"False"}]},{"id":2,"text":"Is 5 - 2 = 4 true or false?","type":"multiple_choice","correct_answer":"False","explanation":"5 - 2 = 3, not 4. The equation is false.","standard_code":"1.OA.7","difficulty":1,"options":[{"label":"True","value":"True"},{"label":"False","value":"False"}]},{"id":3,"text":"Is 6 = 6 true or false?","type":"multiple_choice","correct_answer":"True","explanation":"A number always equals itself. 6 = 6 is true.","standard_code":"1.OA.7","difficulty":1,"options":[{"label":"True","value":"True"},{"label":"False","value":"False"}]},{"id":4,"text":"Is 8 = 5 + 3 true or false?","type":"multiple_choice","correct_answer":"True","explanation":"5 + 3 = 8. The equal sign means both sides have the same value.","standard_code":"1.OA.7","difficulty":1,"options":[{"label":"True","value":"True"},{"label":"False","value":"False"}]},{"id":5,"text":"Is 4 + 3 = 8 true or false?","type":"multiple_choice","correct_answer":"False","explanation":"4 + 3 = 7, not 8. The equation is false.","standard_code":"1.OA.7","difficulty":1,"options":[{"label":"True","value":"True"},{"label":"False","value":"False"}]}]'::jsonb);

VALUES (1,'OA','1.OA.7','Understand the Equal Sign - True or False Equations (Medium)','Students understand the meaning of the equal sign as "the same value as," not just as "the answer comes next." They determine whether addition and subtraction equations are true or false, including eq','practice',2,15,20,'[{"id":1,"text":"Is 4 + 5 = 3 + 6 true or false?","type":"multiple_choice","correct_answer":"True","explanation":"4 + 5 = 9 and 3 + 6 = 9. Both sides equal 9, so it is true.","standard_code":"1.OA.7","difficulty":2,"options":[{"label":"True","value":"True"},{"label":"False","value":"False"}]},{"id":2,"text":"Is 7 - 2 = 6 - 1 true or false?","type":"multiple_choice","correct_answer":"True","explanation":"7 - 2 = 5 and 6 - 1 = 5. Both equal 5, so it is true.","standard_code":"1.OA.7","difficulty":2,"options":[{"label":"True","value":"True"},{"label":"False","value":"False"}]},{"id":3,"text":"Is 10 = 7 + 4 true or false?","type":"multiple_choice","correct_answer":"False","explanation":"7 + 4 = 11, not 10. The equation is false.","standard_code":"1.OA.7","difficulty":2,"options":[{"label":"True","value":"True"},{"label":"False","value":"False"}]},{"id":4,"text":"Is 8 + 2 = 4 + 6 true or false?","type":"multiple_choice","correct_answer":"True","explanation":"8 + 2 = 10 and 4 + 6 = 10. Both equal 10.","standard_code":"1.OA.7","difficulty":2,"options":[{"label":"True","value":"True"},{"label":"False","value":"False"}]},{"id":5,"text":"Is 9 - 3 = 5 + 1 true or false?","type":"multiple_choice","correct_answer":"True","explanation":"9 - 3 = 6 and 5 + 1 = 6. Both equal 6.","standard_code":"1.OA.7","difficulty":2,"options":[{"label":"True","value":"True"},{"label":"False","value":"False"}]}]'::jsonb);

VALUES (1,'OA','1.OA.7','Understand the Equal Sign - True or False Equations (Hard)','Students understand the meaning of the equal sign as "the same value as," not just as "the answer comes next." They determine whether addition and subtraction equations are true or false, including eq','practice',3,20,21,'[{"id":1,"text":"7 + ? = 4 + 6. What is the missing number?","type":"numeric","correct_answer":"3","explanation":"4 + 6 = 10. So 7 + ? = 10, which means ? = 3.","standard_code":"1.OA.7","difficulty":3},{"id":2,"text":"Is 12 - 5 = 3 + 4 true or false?","type":"multiple_choice","correct_answer":"True","explanation":"12 - 5 = 7 and 3 + 4 = 7. Both equal 7, so it is true.","standard_code":"1.OA.7","difficulty":3,"options":[{"label":"True","value":"True"},{"label":"False","value":"False"}]},{"id":3,"text":"? = 8 + 7 - 5. What is the missing number?","type":"numeric","correct_answer":"10","explanation":"8 + 7 = 15, then 15 - 5 = 10. So ? = 10.","standard_code":"1.OA.7","difficulty":3},{"id":4,"text":"Is 15 - 8 = 9 - 2 true or false?","type":"multiple_choice","correct_answer":"True","explanation":"15 - 8 = 7 and 9 - 2 = 7. Both equal 7.","standard_code":"1.OA.7","difficulty":3,"options":[{"label":"True","value":"True"},{"label":"False","value":"False"}]},{"id":5,"text":"Write a true equation using 9, 4, and 5 on both sides of the equal sign.","type":"multiple_choice","correct_answer":"9 = 4 + 5 (or 4 + 5 = 9)","explanation":"4 + 5 = 9. The equal sign shows both sides have the same value.","standard_code":"1.OA.7","difficulty":3,"options":[{"label":"9 = 4 + 5 (or 4 + 5 = 9)","value":"9 = 4 + 5 (or 4 + 5 = 9)"},{"label":"9 - 4 = 5","value":"9 - 4 = 5"},{"label":"9 + 4 = 5","value":"9 + 4 = 5"},{"label":"5 = 9 - 4","value":"5 = 9 - 4"}]}]'::jsonb);

VALUES (1,'OA','1.OA.8','Determine the Unknown in Addition and Subtraction Equations (Easy)','Students determine the unknown whole number in addition or subtraction equations, with the unknown in any position - beginning, middle, or end. They use inverse operations, related facts, and algebrai','practice',1,10,22,'[{"id":1,"text":"3 + 4 = ?","type":"numeric","correct_answer":"7","explanation":"3 + 4 = 7. Count on 4 from 3.","standard_code":"1.OA.8","difficulty":1},{"id":2,"text":"8 - 3 = ?","type":"numeric","correct_answer":"5","explanation":"8 - 3 = 5. Count back 3 from 8.","standard_code":"1.OA.8","difficulty":1},{"id":3,"text":"2 + ? = 7","type":"numeric","correct_answer":"5","explanation":"Think: 7 - 2 = 5. So the missing number is 5.","standard_code":"1.OA.8","difficulty":1},{"id":4,"text":"? + 4 = 9","type":"numeric","correct_answer":"5","explanation":"Think: 9 - 4 = 5. So 5 + 4 = 9.","standard_code":"1.OA.8","difficulty":1},{"id":5,"text":"6 - ? = 2","type":"numeric","correct_answer":"4","explanation":"Think: 2 + 4 = 6. So 6 - 4 = 2.","standard_code":"1.OA.8","difficulty":1}]'::jsonb);

VALUES (1,'OA','1.OA.8','Determine the Unknown in Addition and Subtraction Equations (Medium)','Students determine the unknown whole number in addition or subtraction equations, with the unknown in any position - beginning, middle, or end. They use inverse operations, related facts, and algebrai','practice',2,15,23,'[{"id":1,"text":"? + 7 = 15","type":"numeric","correct_answer":"8","explanation":"Think: 15 - 7 = 8. So 8 + 7 = 15.","standard_code":"1.OA.8","difficulty":2},{"id":2,"text":"13 - ? = 5","type":"numeric","correct_answer":"8","explanation":"Think: 5 + 8 = 13. So 13 - 8 = 5.","standard_code":"1.OA.8","difficulty":2},{"id":3,"text":"9 + ? = 18","type":"numeric","correct_answer":"9","explanation":"Doubles: 9 + 9 = 18. So ? = 9.","standard_code":"1.OA.8","difficulty":2},{"id":4,"text":"? - 6 = 7","type":"numeric","correct_answer":"13","explanation":"Think: 7 + 6 = 13. If ? - 6 = 7, then ? = 7 + 6 = 13.","standard_code":"1.OA.8","difficulty":2},{"id":5,"text":"16 - 8 = ?","type":"numeric","correct_answer":"8","explanation":"Doubles: 8 + 8 = 16, so 16 - 8 = 8.","standard_code":"1.OA.8","difficulty":2}]'::jsonb);

VALUES (1,'OA','1.OA.8','Determine the Unknown in Addition and Subtraction Equations (Hard)','Students determine the unknown whole number in addition or subtraction equations, with the unknown in any position - beginning, middle, or end. They use inverse operations, related facts, and algebrai','practice',3,20,24,'[{"id":1,"text":"? + 9 = 20","type":"numeric","correct_answer":"11","explanation":"Think: 20 - 9 = 11. So 11 + 9 = 20.","standard_code":"1.OA.8","difficulty":3},{"id":2,"text":"18 - ? = 9","type":"numeric","correct_answer":"9","explanation":"Doubles: 9 + 9 = 18, so 18 - 9 = 9.","standard_code":"1.OA.8","difficulty":3},{"id":3,"text":"A jar had some cookies. 7 were eaten and 8 remain. Write an equation and find how many were there at the start.","type":"multiple_choice","correct_answer":"? - 7 = 8, so ? = 15","explanation":"? - 7 = 8. Think: 8 + 7 = 15. There were 15 cookies to start.","standard_code":"1.OA.8","difficulty":3,"options":[{"label":"? - 7 = 8, so ? = 15","value":"? - 7 = 8, so ? = 15"},{"label":"7 + ? = 8, so ? = 1","value":"7 + ? = 8, so ? = 1"},{"label":"8 + 7 = 15, so ? = 15","value":"8 + 7 = 15, so ? = 15"},{"label":"? - 7 = 8, so ? = 1","value":"? - 7 = 8, so ? = 1"}]},{"id":4,"text":"? - 8 = 6","type":"numeric","correct_answer":"14","explanation":"Think: 6 + 8 = 14. If ? - 8 = 6, then ? = 6 + 8 = 14.","standard_code":"1.OA.8","difficulty":3},{"id":5,"text":"20 - ? = 11","type":"numeric","correct_answer":"9","explanation":"Think: 11 + 9 = 20. So ? = 9. Check: 20 - 9 = 11.","standard_code":"1.OA.8","difficulty":3}]'::jsonb);

VALUES (1,'NBT','1.NBT.1','Count to 120 - Read and Write Numerals (Easy)','Students count to 120 starting at any number less than 120. In the range of 1-120, they read and write numerals and represent a number of objects with a written numeral. They extend patterns beyond 10','practice',1,10,25,'[{"id":1,"text":"What number comes after 15?","type":"numeric","correct_answer":"16","explanation":"Counting order: ...14, 15, 16...","standard_code":"1.NBT.1","difficulty":1},{"id":2,"text":"What number comes before 10?","type":"numeric","correct_answer":"9","explanation":"Counting backwards: ...8, 9, 10...","standard_code":"1.NBT.1","difficulty":1},{"id":3,"text":"Fill in the missing number: 1, 2, 3, __, 5","type":"numeric","correct_answer":"4","explanation":"The counting sequence is 1, 2, 3, 4, 5.","standard_code":"1.NBT.1","difficulty":1},{"id":4,"text":"How do you write the number seventeen?","type":"numeric","correct_answer":"17","explanation":"Seventeen is written as 17 (1 ten and 7 ones).","standard_code":"1.NBT.1","difficulty":1},{"id":5,"text":"Count these objects: * * * * * * (6 stars). What number is this?","type":"numeric","correct_answer":"6","explanation":"Count each star: 1, 2, 3, 4, 5, 6.","standard_code":"1.NBT.1","difficulty":1}]'::jsonb);

VALUES (1,'NBT','1.NBT.1','Count to 120 - Read and Write Numerals (Medium)','Students count to 120 starting at any number less than 120. In the range of 1-120, they read and write numerals and represent a number of objects with a written numeral. They extend patterns beyond 10','practice',2,15,26,'[{"id":1,"text":"What number comes after 99?","type":"numeric","correct_answer":"100","explanation":"After 99 comes 100. We enter a new group of hundreds.","standard_code":"1.NBT.1","difficulty":2},{"id":2,"text":"Count by 10s: 10, 20, 30, __, 50. What is missing?","type":"numeric","correct_answer":"40","explanation":"Count by tens: 10, 20, 30, 40, 50.","standard_code":"1.NBT.1","difficulty":2},{"id":3,"text":"What number comes between 109 and 111?","type":"numeric","correct_answer":"110","explanation":"Counting: ...108, 109, 110, 111...","standard_code":"1.NBT.1","difficulty":2},{"id":4,"text":"Write one hundred five in numerals.","type":"numeric","correct_answer":"105","explanation":"One hundred five = 100 + 5 = 105.","standard_code":"1.NBT.1","difficulty":2},{"id":5,"text":"Fill in the missing number: 115, 116, 117, __, 119","type":"numeric","correct_answer":"118","explanation":"Counting sequence: 115, 116, 117, 118, 119.","standard_code":"1.NBT.1","difficulty":2}]'::jsonb);

VALUES (1,'NBT','1.NBT.1','Count to 120 - Read and Write Numerals (Hard)','Students count to 120 starting at any number less than 120. In the range of 1-120, they read and write numerals and represent a number of objects with a written numeral. They extend patterns beyond 10','practice',3,20,27,'[{"id":1,"text":"Start at 97 and count to 103. Write all the numbers.","type":"multiple_choice","correct_answer":"97, 98, 99, 100, 101, 102, 103","explanation":"After 99 comes 100, then 101, 102, 103. The pattern continues even past 100.","standard_code":"1.NBT.1","difficulty":3,"options":[{"label":"97, 98, 99, 100, 101, 102","value":"97, 98, 99, 100, 101, 102"},{"label":"98, 99, 100, 101, 102, 103","value":"98, 99, 100, 101, 102, 103"},{"label":"97, 98, 99, 100, 101, 102, 103, 104","value":"97, 98, 99, 100, 101, 102, 103, 104"},{"label":"97, 98, 99, 100, 101, 102, 103","value":"97, 98, 99, 100, 101, 102, 103"}]},{"id":2,"text":"Write the number that is 1 less than 120.","type":"numeric","correct_answer":"119","explanation":"120 - 1 = 119. The number before 120 is 119.","standard_code":"1.NBT.1","difficulty":3},{"id":3,"text":"Nina counted: 108, 109, 110, 120. What mistake did she make?","type":"multiple_choice","correct_answer":"She skipped 111 through 119","explanation":"After 110 comes 111, not 120. She skipped 9 numbers.","standard_code":"1.NBT.1","difficulty":3,"options":[{"label":"She counted 110 twice","value":"She counted 110 twice"},{"label":"She skipped 110 through 119","value":"She skipped 110 through 119"},{"label":"She skipped 115","value":"She skipped 115"},{"label":"She skipped 111 through 119","value":"She skipped 111 through 119"}]},{"id":4,"text":"How many tens are in 110?","type":"multiple_choice","correct_answer":"11 tens","explanation":"110 = 11 groups of 10. 11 x 10 = 110.","standard_code":"1.NBT.1","difficulty":3,"options":[{"label":"11 tens","value":"11 tens"},{"label":"10 tens","value":"10 tens"},{"label":"1 ten","value":"1 ten"},{"label":"110 tens","value":"110 tens"}]},{"id":5,"text":"Count backwards from 105 to 100. Write the sequence.","type":"multiple_choice","correct_answer":"105, 104, 103, 102, 101, 100","explanation":"Counting down by ones: 105, 104, 103, 102, 101, 100.","standard_code":"1.NBT.1","difficulty":3,"options":[{"label":"100, 101, 102, 103, 104, 105","value":"100, 101, 102, 103, 104, 105"},{"label":"105, 104, 103, 102, 101","value":"105, 104, 103, 102, 101"},{"label":"105, 104, 103, 102, 101, 100, 99","value":"105, 104, 103, 102, 101, 100, 99"},{"label":"105, 104, 103, 102, 101, 100","value":"105, 104, 103, 102, 101, 100"}]}]'::jsonb);

VALUES (1,'NBT','1.NBT.2','Understand Place Value - Tens and Ones (Easy)','Students understand that the two digits of a two-digit number represent amounts of tens and ones. For example, 27 = 2 tens + 7 ones = 20 + 7. They also know that 10 ones make 1 ten, and that the decad','practice',1,10,28,'[{"id":1,"text":"How many tens and ones are in 24?","type":"multiple_choice","correct_answer":"2 tens and 4 ones","explanation":"24 = 20 + 4 = 2 tens and 4 ones.","standard_code":"1.NBT.2","difficulty":1,"options":[{"label":"4 tens and 2 ones","value":"4 tens and 2 ones"},{"label":"2 ones and 4 tens","value":"2 ones and 4 tens"},{"label":"2 tens and 4 ones","value":"2 tens and 4 ones"},{"label":"24 tens and 0 ones","value":"24 tens and 0 ones"}]},{"id":2,"text":"What number has 1 ten and 5 ones?","type":"numeric","correct_answer":"15","explanation":"1 ten = 10, plus 5 ones = 15.","standard_code":"1.NBT.2","difficulty":1},{"id":3,"text":"How many ones are in 30?","type":"multiple_choice","correct_answer":"0 ones (3 tens, 0 ones)","explanation":"30 = 3 tens and 0 ones. There are no extra ones.","standard_code":"1.NBT.2","difficulty":1,"options":[{"label":"0 ones (3 tens, 0 ones)","value":"0 ones (3 tens, 0 ones)"},{"label":"3 ones","value":"3 ones"},{"label":"30 ones","value":"30 ones"},{"label":"10 ones","value":"10 ones"}]},{"id":4,"text":"Write 3 tens and 2 ones as a number.","type":"numeric","correct_answer":"32","explanation":"3 tens = 30, plus 2 ones = 32.","standard_code":"1.NBT.2","difficulty":1},{"id":5,"text":"17 has how many tens and how many ones?","type":"multiple_choice","correct_answer":"1 ten and 7 ones","explanation":"17 = 10 + 7 = 1 ten and 7 ones.","standard_code":"1.NBT.2","difficulty":1,"options":[{"label":"7 tens and 1 one","value":"7 tens and 1 one"},{"label":"1 ten and 7 ones","value":"1 ten and 7 ones"},{"label":"17 tens and 0 ones","value":"17 tens and 0 ones"},{"label":"1 ten and 17 ones","value":"1 ten and 17 ones"}]}]'::jsonb);

VALUES (1,'NBT','1.NBT.2','Understand Place Value - Tens and Ones (Medium)','Students understand that the two digits of a two-digit number represent amounts of tens and ones. For example, 27 = 2 tens + 7 ones = 20 + 7. They also know that 10 ones make 1 ten, and that the decad','practice',2,15,29,'[{"id":1,"text":"What is the value of the digit 5 in 57?","type":"multiple_choice","correct_answer":"50 (5 tens)","explanation":"In 57, the 5 is in the tens place, so it means 5 tens = 50.","standard_code":"1.NBT.2","difficulty":2,"options":[{"label":"5","value":"5"},{"label":"50 (5 tens)","value":"50 (5 tens)"},{"label":"5 ones","value":"5 ones"},{"label":"500 (5 hundreds)","value":"500 (5 hundreds)"}]},{"id":2,"text":"40 + 8 = ?","type":"numeric","correct_answer":"48","explanation":"40 = 4 tens, plus 8 ones = 48.","standard_code":"1.NBT.2","difficulty":2},{"id":3,"text":"How many tens are in 90?","type":"multiple_choice","correct_answer":"9 tens","explanation":"90 = 9 tens and 0 ones.","standard_code":"1.NBT.2","difficulty":2,"options":[{"label":"90","value":"90"},{"label":"10 tens","value":"10 tens"},{"label":"9 tens","value":"9 tens"},{"label":"19 tens","value":"19 tens"}]},{"id":4,"text":"A number has 7 tens and 3 ones. What is the number?","type":"numeric","correct_answer":"73","explanation":"7 tens = 70, plus 3 ones = 73.","standard_code":"1.NBT.2","difficulty":2},{"id":5,"text":"What is the value of the digit 2 in 62?","type":"multiple_choice","correct_answer":"2 (2 ones)","explanation":"In 62, the 2 is in the ones place, so it means 2 ones = 2.","standard_code":"1.NBT.2","difficulty":2,"options":[{"label":"2 (2 ones)","value":"2 (2 ones)"},{"label":"20","value":"20"},{"label":"2 tens","value":"2 tens"},{"label":"60","value":"60"}]}]'::jsonb);

VALUES (1,'NBT','1.NBT.2','Understand Place Value - Tens and Ones (Hard)','Students understand that the two digits of a two-digit number represent amounts of tens and ones. For example, 27 = 2 tens + 7 ones = 20 + 7. They also know that 10 ones make 1 ten, and that the decad','practice',3,20,30,'[{"id":1,"text":"58 = 5 tens + ? ones","type":"numeric","correct_answer":"8","explanation":"58 = 50 + 8 = 5 tens + 8 ones.","standard_code":"1.NBT.2","difficulty":3},{"id":2,"text":"Write two different ways to show 43 using tens and ones.","type":"multiple_choice","correct_answer":"4 tens 3 ones; or 3 tens 13 ones","explanation":"43 = 4 tens + 3 ones, or 3 tens + 13 ones. Both equal 43.","standard_code":"1.NBT.2","difficulty":3,"options":[{"label":"4 tens 3 ones; or 5 tens 0 ones","value":"4 tens 3 ones; or 5 tens 0 ones"},{"label":"4 tens 3 ones; or 2 tens 14 ones","value":"4 tens 3 ones; or 2 tens 14 ones"},{"label":"4 tens 3 ones; or 3 tens 13 ones","value":"4 tens 3 ones; or 3 tens 13 ones"},{"label":"3 tens 4 ones; or 2 tens 23 ones","value":"3 tens 4 ones; or 2 tens 23 ones"}]},{"id":3,"text":"10 ones = ? ten(s)","type":"multiple_choice","correct_answer":"1 ten","explanation":"10 ones bundled together make 1 ten. 10 = 1 ten.","standard_code":"1.NBT.2","difficulty":3,"options":[{"label":"10 tens","value":"10 tens"},{"label":"1 ten","value":"1 ten"},{"label":"10 ones","value":"10 ones"},{"label":"0 tens","value":"0 tens"}]},{"id":4,"text":"What number has the same digit in both the tens and ones place, and is between 20 and 40?","type":"numeric","correct_answer":"33","explanation":"33 = 3 tens and 3 ones. Both digits are 3, and 20 < 33 < 40.","standard_code":"1.NBT.2","difficulty":3},{"id":5,"text":"A number is between 50 and 60. Its ones digit is 3 less than its tens digit. What is the number?","type":"numeric","correct_answer":"52","explanation":"Tens digit = 5. Ones digit = 5 - 3 = 2. The number is 52.","standard_code":"1.NBT.2","difficulty":3}]'::jsonb);

VALUES (1,'NBT','1.NBT.3','Compare Two Two-Digit Numbers Using >, =, < (Easy)','Students compare two two-digit numbers using the symbols > (greater than), = (equal to), and < (less than). The comparison strategy is to look at tens first; if tens are equal, then compare the ones d','practice',1,10,31,'[{"id":1,"text":"Which is greater: 34 or 38?","type":"numeric","correct_answer":"38","explanation":"Both have 3 tens. Compare ones: 8 > 4, so 38 > 34.","standard_code":"1.NBT.3","difficulty":1},{"id":2,"text":"Use >, =, or < to compare: 25 __ 25","type":"multiple_choice","correct_answer":"=","explanation":"25 = 25. They are the same number.","standard_code":"1.NBT.3","difficulty":1,"options":[{"label":"<","value":"<"},{"label":">","value":">"},{"label":"=","value":"="},{"label":"+","value":"+"}]},{"id":3,"text":"Which is less: 47 or 41?","type":"numeric","correct_answer":"41","explanation":"Both have 4 tens. Compare ones: 1 < 7, so 41 < 47.","standard_code":"1.NBT.3","difficulty":1},{"id":4,"text":"Use >, =, or < to compare: 60 __ 50","type":"multiple_choice","correct_answer":">","explanation":"6 tens > 5 tens, so 60 > 50.","standard_code":"1.NBT.3","difficulty":1,"options":[{"label":">","value":">"},{"label":"=","value":"="},{"label":"<","value":"<"},{"label":"-","value":"-"}]},{"id":5,"text":"Circle the greater number: 72 or 79.","type":"numeric","correct_answer":"79","explanation":"Both have 7 tens. Compare ones: 9 > 2, so 79 > 72.","standard_code":"1.NBT.3","difficulty":1}]'::jsonb);

VALUES (1,'NBT','1.NBT.3','Compare Two Two-Digit Numbers Using >, =, < (Medium)','Students compare two two-digit numbers using the symbols > (greater than), = (equal to), and < (less than). The comparison strategy is to look at tens first; if tens are equal, then compare the ones d','practice',2,15,32,'[{"id":1,"text":"Use >, =, or < to compare: 53 __ 49","type":"multiple_choice","correct_answer":">","explanation":"5 tens > 4 tens, so 53 > 49 (no need to compare ones).","standard_code":"1.NBT.3","difficulty":2,"options":[{"label":"<","value":"<"},{"label":">","value":">"},{"label":"49","value":"49"},{"label":"=","value":"="}]},{"id":2,"text":"Which is greater: 81 or 78?","type":"numeric","correct_answer":"81","explanation":"8 tens > 7 tens, so 81 > 78.","standard_code":"1.NBT.3","difficulty":2},{"id":3,"text":"Use >, =, or < to compare: 66 __ 68","type":"multiple_choice","correct_answer":"<","explanation":"Same tens (6). Compare ones: 6 < 8, so 66 < 68.","standard_code":"1.NBT.3","difficulty":2,"options":[{"label":">","value":">"},{"label":"=","value":"="},{"label":"68","value":"68"},{"label":"<","value":"<"}]},{"id":4,"text":"Order from least to greatest: 45, 54, 44.","type":"multiple_choice","correct_answer":"44, 45, 54","explanation":"44 < 45 (same tens, 4 < 5). 45 < 54 (4 tens < 5 tens).","standard_code":"1.NBT.3","difficulty":2,"options":[{"label":"44, 45, 54","value":"44, 45, 54"},{"label":"54, 45, 44","value":"54, 45, 44"},{"label":"45, 44, 54","value":"45, 44, 54"},{"label":"44, 54, 45","value":"44, 54, 45"}]},{"id":5,"text":"Use >, =, or < to compare: 90 __ 89","type":"multiple_choice","correct_answer":">","explanation":"9 tens > 8 tens, so 90 > 89.","standard_code":"1.NBT.3","difficulty":2,"options":[{"label":"=","value":"="},{"label":">","value":">"},{"label":"<","value":"<"},{"label":"89","value":"89"}]}]'::jsonb);

VALUES (1,'NBT','1.NBT.3','Compare Two Two-Digit Numbers Using >, =, < (Hard)','Students compare two two-digit numbers using the symbols > (greater than), = (equal to), and < (less than). The comparison strategy is to look at tens first; if tens are equal, then compare the ones d','practice',3,20,33,'[{"id":1,"text":"Name two numbers between 30 and 40 where one is greater, and write a comparison.","type":"multiple_choice","correct_answer":"e.g., 37 > 32","explanation":"Any two numbers between 30-40 work. e.g., 37 > 32 because both have 3 tens but 7 > 2.","standard_code":"1.NBT.3","difficulty":3,"options":[{"label":"e.g., 37 > 32","value":"e.g., 37 > 32"},{"label":"e.g., 35 < 38","value":"e.g., 35 < 38"},{"label":"e.g., 30 > 40","value":"e.g., 30 > 40"},{"label":"e.g., 39 < 31","value":"e.g., 39 < 31"}]},{"id":2,"text":"My number is less than 75 and greater than 72. What could it be?","type":"multiple_choice","correct_answer":"73 or 74","explanation":"73 and 74 are both less than 75 and greater than 72.","standard_code":"1.NBT.3","difficulty":3,"options":[{"label":"70 or 71","value":"70 or 71"},{"label":"75 or 76","value":"75 or 76"},{"label":"73 or 74","value":"73 or 74"},{"label":"71 or 72","value":"71 or 72"}]},{"id":3,"text":"Use >, =, or < to compare: (4 tens + 7 ones) __ 52","type":"multiple_choice","correct_answer":"<","explanation":"4 tens + 7 ones = 47. Compare: 4 tens < 5 tens, so 47 < 52.","standard_code":"1.NBT.3","difficulty":3,"options":[{"label":"<","value":"<"},{"label":">","value":">"},{"label":"47","value":"47"},{"label":"=","value":"="}]},{"id":4,"text":"Write three numbers that are greater than 85.","type":"multiple_choice","correct_answer":"Any three of: 86, 87, 88, 89, 90, ...","explanation":"86, 87, 88 (or any three numbers above 85).","standard_code":"1.NBT.3","difficulty":3,"options":[{"label":"80, 81, 82","value":"80, 81, 82"},{"label":"Any three of: 86, 87, 88, 89, 90, ...","value":"Any three of: 86, 87, 88, 89, 90, ..."},{"label":"82, 83, 84","value":"82, 83, 84"},{"label":"84, 85, 86","value":"84, 85, 86"}]},{"id":5,"text":"A two-digit number has 6 in the ones place and is greater than 70. What could it be?","type":"multiple_choice","correct_answer":"76, 86, or 96","explanation":"76, 86, and 96 all have 6 in the ones place and are greater than 70.","standard_code":"1.NBT.3","difficulty":3,"options":[{"label":"36, 46, 56","value":"36, 46, 56"},{"label":"76, 86, or 96","value":"76, 86, or 96"},{"label":"56, 66, 76","value":"56, 66, 76"},{"label":"66, 46, 26","value":"66, 46, 26"}]}]'::jsonb);

VALUES (1,'NBT','1.NBT.4','Add Within 100 - Two-Digit Plus One-Digit or Multiple of 10 (Easy)','Students add within 100, using strategies based on place value: a two-digit number plus a one-digit number, or a two-digit number plus a multiple of 10. When adding tens, only the tens digit changes. ','practice',1,10,34,'[{"id":1,"text":"30 + 20 = ?","type":"numeric","correct_answer":"50","explanation":"3 tens + 2 tens = 5 tens = 50.","standard_code":"1.NBT.4","difficulty":1},{"id":2,"text":"45 + 10 = ?","type":"numeric","correct_answer":"55","explanation":"4 tens + 1 ten = 5 tens; ones stay the same. Answer: 55.","standard_code":"1.NBT.4","difficulty":1},{"id":3,"text":"62 + 20 = ?","type":"numeric","correct_answer":"82","explanation":"6 tens + 2 tens = 8 tens; ones stay the same. Answer: 82.","standard_code":"1.NBT.4","difficulty":1},{"id":4,"text":"71 + 10 = ?","type":"numeric","correct_answer":"81","explanation":"7 tens + 1 ten = 8 tens; ones unchanged. Answer: 81.","standard_code":"1.NBT.4","difficulty":1},{"id":5,"text":"50 + 30 = ?","type":"numeric","correct_answer":"80","explanation":"5 tens + 3 tens = 8 tens = 80.","standard_code":"1.NBT.4","difficulty":1}]'::jsonb);

VALUES (1,'NBT','1.NBT.4','Add Within 100 - Two-Digit Plus One-Digit or Multiple of 10 (Medium)','Students add within 100, using strategies based on place value: a two-digit number plus a one-digit number, or a two-digit number plus a multiple of 10. When adding tens, only the tens digit changes. ','practice',2,15,35,'[{"id":1,"text":"43 + 5 = ?","type":"numeric","correct_answer":"48","explanation":"40 + (3 + 5) = 40 + 8 = 48. Only the ones change.","standard_code":"1.NBT.4","difficulty":2},{"id":2,"text":"61 + 7 = ?","type":"numeric","correct_answer":"68","explanation":"60 + (1 + 7) = 60 + 8 = 68.","standard_code":"1.NBT.4","difficulty":2},{"id":3,"text":"34 + 20 = ?","type":"numeric","correct_answer":"54","explanation":"Add the tens: 30 + 20 = 50, plus 4 ones = 54.","standard_code":"1.NBT.4","difficulty":2},{"id":4,"text":"52 + 6 = ?","type":"numeric","correct_answer":"58","explanation":"50 + (2 + 6) = 50 + 8 = 58.","standard_code":"1.NBT.4","difficulty":2},{"id":5,"text":"73 + 4 = ?","type":"numeric","correct_answer":"77","explanation":"70 + (3 + 4) = 70 + 7 = 77.","standard_code":"1.NBT.4","difficulty":2}]'::jsonb);

VALUES (1,'NBT','1.NBT.4','Add Within 100 - Two-Digit Plus One-Digit or Multiple of 10 (Hard)','Students add within 100, using strategies based on place value: a two-digit number plus a one-digit number, or a two-digit number plus a multiple of 10. When adding tens, only the tens digit changes. ','practice',3,20,36,'[{"id":1,"text":"47 + 6 = ?","type":"numeric","correct_answer":"53","explanation":"Make a ten: 47 + 3 = 50, then 50 + 3 = 53. Decompose 6 as 3 + 3.","standard_code":"1.NBT.4","difficulty":3},{"id":2,"text":"68 + 5 = ?","type":"numeric","correct_answer":"73","explanation":"Make a ten: 68 + 2 = 70, then 70 + 3 = 73. Decompose 5 as 2 + 3.","standard_code":"1.NBT.4","difficulty":3},{"id":3,"text":"35 + 28 = ?","type":"numeric","correct_answer":"63","explanation":"Add tens: 30 + 20 = 50. Add ones: 5 + 8 = 13. Total: 50 + 13 = 63.","standard_code":"1.NBT.4","difficulty":3},{"id":4,"text":"59 + 4 = ?","type":"numeric","correct_answer":"63","explanation":"Make a ten: 59 + 1 = 60, then 60 + 3 = 63.","standard_code":"1.NBT.4","difficulty":3},{"id":5,"text":"A store has 46 red apples and 30 green apples. How many apples are there in all?","type":"numeric","correct_answer":"76","explanation":"46 + 30: add the tens: 40 + 30 = 70; ones unchanged: 70 + 6 = 76.","standard_code":"1.NBT.4","difficulty":3}]'::jsonb);

VALUES (1,'NBT','1.NBT.5','Mentally Find 10 More or 10 Less (Easy)','Students mentally find 10 more or 10 less than any two-digit number, without counting. They understand that adding 10 increases only the tens digit by 1, and subtracting 10 decreases only the tens dig','practice',1,10,37,'[{"id":1,"text":"What is 10 more than 23?","type":"numeric","correct_answer":"33","explanation":"23 + 10 = 33. The tens digit goes from 2 to 3; the ones digit stays 3.","standard_code":"1.NBT.5","difficulty":1},{"id":2,"text":"What is 10 less than 35?","type":"numeric","correct_answer":"25","explanation":"35 - 10 = 25. The tens digit goes from 3 to 2; the ones digit stays 5.","standard_code":"1.NBT.5","difficulty":1},{"id":3,"text":"What is 10 more than 40?","type":"numeric","correct_answer":"50","explanation":"40 + 10 = 50. Tens digit: 4 becomes 5.","standard_code":"1.NBT.5","difficulty":1},{"id":4,"text":"What is 10 less than 50?","type":"numeric","correct_answer":"40","explanation":"50 - 10 = 40. Tens digit: 5 becomes 4.","standard_code":"1.NBT.5","difficulty":1},{"id":5,"text":"17 + 10 = ?","type":"numeric","correct_answer":"27","explanation":"17 + 10 = 27. Tens digit: 1 becomes 2. Ones digit stays 7.","standard_code":"1.NBT.5","difficulty":1}]'::jsonb);

VALUES (1,'NBT','1.NBT.5','Mentally Find 10 More or 10 Less (Medium)','Students mentally find 10 more or 10 less than any two-digit number, without counting. They understand that adding 10 increases only the tens digit by 1, and subtracting 10 decreases only the tens dig','practice',2,15,38,'[{"id":1,"text":"What is 10 more than 78?","type":"numeric","correct_answer":"88","explanation":"78 + 10 = 88. Tens digit: 7 becomes 8.","standard_code":"1.NBT.5","difficulty":2},{"id":2,"text":"What is 10 less than 91?","type":"numeric","correct_answer":"81","explanation":"91 - 10 = 81. Tens digit: 9 becomes 8.","standard_code":"1.NBT.5","difficulty":2},{"id":3,"text":"64 + 10 = ?","type":"numeric","correct_answer":"74","explanation":"64 + 10 = 74. Only the tens digit changes.","standard_code":"1.NBT.5","difficulty":2},{"id":4,"text":"? - 10 = 53. What is ?","type":"numeric","correct_answer":"63","explanation":"If ? - 10 = 53, then ? = 53 + 10 = 63.","standard_code":"1.NBT.5","difficulty":2},{"id":5,"text":"10 less than 100 is ?","type":"numeric","correct_answer":"90","explanation":"100 - 10 = 90.","standard_code":"1.NBT.5","difficulty":2}]'::jsonb);

VALUES (1,'NBT','1.NBT.5','Mentally Find 10 More or 10 Less (Hard)','Students mentally find 10 more or 10 less than any two-digit number, without counting. They understand that adding 10 increases only the tens digit by 1, and subtracting 10 decreases only the tens dig','practice',3,20,39,'[{"id":1,"text":"Start at 45. Add 10 three times. Where do you end up?","type":"numeric","correct_answer":"75","explanation":"45 + 10 = 55, 55 + 10 = 65, 65 + 10 = 75.","standard_code":"1.NBT.5","difficulty":3},{"id":2,"text":"What is 10 more than 10 less than 67?","type":"numeric","correct_answer":"67","explanation":"67 - 10 = 57, then 57 + 10 = 67. You end where you started!","standard_code":"1.NBT.5","difficulty":3},{"id":3,"text":"Complete the pattern: 34, 44, 54, __.","type":"numeric","correct_answer":"64","explanation":"Each number is 10 more than the previous. 54 + 10 = 64.","standard_code":"1.NBT.5","difficulty":3},{"id":4,"text":"A pattern: 99, 89, 79, __ . What comes next?","type":"numeric","correct_answer":"69","explanation":"Each number is 10 less than the previous. 79 - 10 = 69.","standard_code":"1.NBT.5","difficulty":3},{"id":5,"text":"Start at 99. What is 10 less? What is 10 more?","type":"multiple_choice","correct_answer":"10 less: 89; 10 more: 109","explanation":"99 - 10 = 89; 99 + 10 = 109. Note: 109 has three digits.","standard_code":"1.NBT.5","difficulty":3,"options":[{"label":"10 less: 90; 10 more: 109","value":"10 less: 90; 10 more: 109"},{"label":"10 less: 89; 10 more: 99","value":"10 less: 89; 10 more: 99"},{"label":"10 less: 98; 10 more: 109","value":"10 less: 98; 10 more: 109"},{"label":"10 less: 89; 10 more: 109","value":"10 less: 89; 10 more: 109"}]}]'::jsonb);

VALUES (1,'NBT','1.NBT.6','Subtract Multiples of 10 (10-90) (Easy)','Students subtract multiples of 10 (10, 20, 30, ... 90) from two-digit numbers within the range 10-90. They use place-value understanding and strategies to find the difference, recognizing that subtrac','practice',1,10,40,'[{"id":1,"text":"50 - 10 = ?","type":"numeric","correct_answer":"40","explanation":"5 tens - 1 ten = 4 tens = 40.","standard_code":"1.NBT.6","difficulty":1},{"id":2,"text":"30 - 20 = ?","type":"numeric","correct_answer":"10","explanation":"3 tens - 2 tens = 1 ten = 10.","standard_code":"1.NBT.6","difficulty":1},{"id":3,"text":"80 - 30 = ?","type":"numeric","correct_answer":"50","explanation":"8 tens - 3 tens = 5 tens = 50.","standard_code":"1.NBT.6","difficulty":1},{"id":4,"text":"70 - 40 = ?","type":"numeric","correct_answer":"30","explanation":"7 tens - 4 tens = 3 tens = 30.","standard_code":"1.NBT.6","difficulty":1},{"id":5,"text":"60 - 20 = ?","type":"numeric","correct_answer":"40","explanation":"6 tens - 2 tens = 4 tens = 40.","standard_code":"1.NBT.6","difficulty":1}]'::jsonb);

VALUES (1,'NBT','1.NBT.6','Subtract Multiples of 10 (10-90) (Medium)','Students subtract multiples of 10 (10, 20, 30, ... 90) from two-digit numbers within the range 10-90. They use place-value understanding and strategies to find the difference, recognizing that subtrac','practice',2,15,41,'[{"id":1,"text":"74 - 30 = ?","type":"numeric","correct_answer":"44","explanation":"70 - 30 = 40, plus 4 ones = 44. Only the tens change.","standard_code":"1.NBT.6","difficulty":2},{"id":2,"text":"87 - 50 = ?","type":"numeric","correct_answer":"37","explanation":"80 - 50 = 30, plus 7 ones = 37.","standard_code":"1.NBT.6","difficulty":2},{"id":3,"text":"65 - 40 = ?","type":"numeric","correct_answer":"25","explanation":"60 - 40 = 20, plus 5 = 25.","standard_code":"1.NBT.6","difficulty":2},{"id":4,"text":"93 - 60 = ?","type":"numeric","correct_answer":"33","explanation":"90 - 60 = 30, plus 3 = 33.","standard_code":"1.NBT.6","difficulty":2},{"id":5,"text":"58 - 20 = ?","type":"numeric","correct_answer":"38","explanation":"50 - 20 = 30, plus 8 = 38.","standard_code":"1.NBT.6","difficulty":2}]'::jsonb);

VALUES (1,'NBT','1.NBT.6','Subtract Multiples of 10 (10-90) (Hard)','Students subtract multiples of 10 (10, 20, 30, ... 90) from two-digit numbers within the range 10-90. They use place-value understanding and strategies to find the difference, recognizing that subtrac','practice',3,20,42,'[{"id":1,"text":"? - 40 = 35. What is the missing number?","type":"numeric","correct_answer":"75","explanation":"If ? - 40 = 35, then ? = 35 + 40 = 75.","standard_code":"1.NBT.6","difficulty":3},{"id":2,"text":"90 - ? = 20. What is the missing number?","type":"numeric","correct_answer":"70","explanation":"Think: 20 + 70 = 90. So ? = 70.","standard_code":"1.NBT.6","difficulty":3},{"id":3,"text":"A store had 82 apples. They sold a full box of 30. How many are left?","type":"numeric","correct_answer":"52","explanation":"82 - 30 = 52. Only the tens change: 80 - 30 = 50, plus 2 = 52.","standard_code":"1.NBT.6","difficulty":3},{"id":4,"text":"60 - 30 + 20 = ?","type":"numeric","correct_answer":"50","explanation":"60 - 30 = 30, then 30 + 20 = 50.","standard_code":"1.NBT.6","difficulty":3},{"id":5,"text":"Ben had 79 trading cards. He gave away 40. How many does he have now?","type":"numeric","correct_answer":"39","explanation":"79 - 40 = 39. Tens: 7 - 4 = 3; ones stay the same: 9.","standard_code":"1.NBT.6","difficulty":3}]'::jsonb);

VALUES (1,'MD','1.MD.1','Order and Compare Lengths of Objects (Easy)','Students order three objects by length and compare the lengths of two objects indirectly by using a third object. They use comparison vocabulary such as longer, shorter, tallest, and shortest. Indirec','practice',1,10,43,'[{"id":1,"text":"A pencil is 7 inches long. A crayon is 4 inches long. Which is longer?","type":"multiple_choice","correct_answer":"The pencil","explanation":"7 > 4. The pencil is longer than the crayon.","standard_code":"1.MD.1","difficulty":1,"options":[{"label":"They are the same length","value":"They are the same length"},{"label":"The pencil is 3 inches longer","value":"The pencil is 3 inches longer"},{"label":"The crayon","value":"The crayon"},{"label":"The pencil","value":"The pencil"}]},{"id":2,"text":"A book is taller than a cup. A cup is taller than a coin. Which is tallest?","type":"multiple_choice","correct_answer":"The book","explanation":"Book > cup > coin. The book is the tallest of the three.","standard_code":"1.MD.1","difficulty":1,"options":[{"label":"The book","value":"The book"},{"label":"They are all the same height","value":"They are all the same height"},{"label":"The cup","value":"The cup"},{"label":"The coin","value":"The coin"}]},{"id":3,"text":"Put in order from shortest to longest: a paper clip, a ruler, a pencil.","type":"multiple_choice","correct_answer":"Paper clip, pencil, ruler","explanation":"Paper clips are shortest, pencils are medium length, rulers are longest.","standard_code":"1.MD.1","difficulty":1,"options":[{"label":"Ruler, pencil, paper clip","value":"Ruler, pencil, paper clip"},{"label":"Pencil, paper clip, ruler","value":"Pencil, paper clip, ruler"},{"label":"Paper clip, pencil, ruler","value":"Paper clip, pencil, ruler"},{"label":"Paper clip, ruler, pencil","value":"Paper clip, ruler, pencil"}]},{"id":4,"text":"Two ribbons: one is 8 cm, one is 5 cm. Which is shorter?","type":"multiple_choice","correct_answer":"The 5 cm ribbon","explanation":"5 < 8. The 5 cm ribbon is shorter.","standard_code":"1.MD.1","difficulty":1,"options":[{"label":"Both ribbons are the same","value":"Both ribbons are the same"},{"label":"Neither ribbon is shorter","value":"Neither ribbon is shorter"},{"label":"The 5 cm ribbon","value":"The 5 cm ribbon"},{"label":"The 8 cm ribbon","value":"The 8 cm ribbon"}]},{"id":5,"text":"Tim''s shoe is longer than Dan''s shoe. Dan''s shoe is longer than Sue''s shoe. Whose shoe is shortest?","type":"multiple_choice","correct_answer":"Sue''s","explanation":"Tim > Dan > Sue. Sue''s shoe is the shortest.","standard_code":"1.MD.1","difficulty":1,"options":[{"label":"They are all the same length","value":"They are all the same length"},{"label":"Dan''s","value":"Dan''s"},{"label":"Sue''s","value":"Sue''s"},{"label":"Tim''s","value":"Tim''s"}]}]'::jsonb);

VALUES (1,'MD','1.MD.1','Order and Compare Lengths of Objects (Medium)','Students order three objects by length and compare the lengths of two objects indirectly by using a third object. They use comparison vocabulary such as longer, shorter, tallest, and shortest. Indirec','practice',2,15,44,'[{"id":1,"text":"A red stick is longer than a blue stick. The blue stick is longer than a yellow stick. Order from longest to shortest.","type":"multiple_choice","correct_answer":"Red, blue, yellow","explanation":"Red > blue > yellow.","standard_code":"1.MD.1","difficulty":2,"options":[{"label":"Yellow, blue, red","value":"Yellow, blue, red"},{"label":"Red, yellow, blue","value":"Red, yellow, blue"},{"label":"Red, blue, yellow","value":"Red, blue, yellow"},{"label":"Blue, red, yellow","value":"Blue, red, yellow"}]},{"id":2,"text":"String A is 12 cm. String B is 9 cm. String C is 15 cm. Order from shortest to longest.","type":"multiple_choice","correct_answer":"B, A, C","explanation":"9 < 12 < 15. B is shortest, then A, then C.","standard_code":"1.MD.1","difficulty":2,"options":[{"label":"B, A, C","value":"B, A, C"},{"label":"A, B, C","value":"A, B, C"},{"label":"C, B, A","value":"C, B, A"},{"label":"B, C, A","value":"B, C, A"}]},{"id":3,"text":"If a table is shorter than a door but taller than a chair, which object is tallest?","type":"multiple_choice","correct_answer":"The door","explanation":"Door > table > chair. The door is the tallest.","standard_code":"1.MD.1","difficulty":2,"options":[{"label":"The door","value":"The door"},{"label":"The chair and door are equal","value":"The chair and door are equal"},{"label":"The chair","value":"The chair"},{"label":"The table","value":"The table"}]},{"id":4,"text":"Three crayons: blue = 6 cm, red = 6 cm, green = 4 cm. Which two are the same length?","type":"multiple_choice","correct_answer":"Blue and red","explanation":"Both blue and red crayons are 6 cm long.","standard_code":"1.MD.1","difficulty":2,"options":[{"label":"Red and green","value":"Red and green"},{"label":"Blue and red","value":"Blue and red"},{"label":"All three are the same length","value":"All three are the same length"},{"label":"Blue and green","value":"Blue and green"}]},{"id":5,"text":"Sam measures his foot: 18 cm. He measures his hand: 14 cm. How much longer is his foot than his hand?","type":"numeric","correct_answer":"4","explanation":"18 - 14 = 4 cm. His foot is 4 cm longer.","standard_code":"1.MD.1","difficulty":2}]'::jsonb);

VALUES (1,'MD','1.MD.1','Order and Compare Lengths of Objects (Hard)','Students order three objects by length and compare the lengths of two objects indirectly by using a third object. They use comparison vocabulary such as longer, shorter, tallest, and shortest. Indirec','practice',3,20,45,'[{"id":1,"text":"Four strings: A = 10 cm, B = 7 cm, C = 13 cm, D = 10 cm. Which two are equal? Order all four from shortest to longest.","type":"multiple_choice","correct_answer":"A and D are equal; order: B, A = D, C","explanation":"A = D = 10 cm. Order: B (7) < A = D (10) < C (13).","standard_code":"1.MD.1","difficulty":3,"options":[{"label":"A and D are equal; order: B, A, D, C","value":"A and D are equal; order: B, A, D, C"},{"label":"A and D are equal; order: B, C, A = D","value":"A and D are equal; order: B, C, A = D"},{"label":"B and C are equal; order: A, B = C, D","value":"B and C are equal; order: A, B = C, D"},{"label":"A and D are equal; order: B, A = D, C","value":"A and D are equal; order: B, A = D, C"}]},{"id":2,"text":"A worm is shorter than a pencil. A pencil is shorter than a ruler. A ruler is shorter than a table. Which is the longest?","type":"multiple_choice","correct_answer":"The table","explanation":"Worm < pencil < ruler < table. The table is longest.","standard_code":"1.MD.1","difficulty":3,"options":[{"label":"The pencil","value":"The pencil"},{"label":"The ruler","value":"The ruler"},{"label":"The table","value":"The table"},{"label":"The worm","value":"The worm"}]},{"id":3,"text":"Mark says a stick is about 4 paper clips long. Kate says it is about 3 large buttons long. Who measured with a smaller unit?","type":"multiple_choice","correct_answer":"Mark (paper clips are the smaller unit)","explanation":"Paper clips are smaller than large buttons, so Mark needed more of them to measure the same length.","standard_code":"1.MD.1","difficulty":3,"options":[{"label":"Mark (paper clips are the smaller unit)","value":"Mark (paper clips are the smaller unit)"},{"label":"Mark used a larger unit","value":"Mark used a larger unit"},{"label":"They both measured with the same size unit","value":"They both measured with the same size unit"},{"label":"Kate (large buttons are the smaller unit)","value":"Kate (large buttons are the smaller unit)"}]},{"id":4,"text":"Arrange from longest to shortest: 6 inches, 2 feet, 1 foot, 3 inches.","type":"multiple_choice","correct_answer":"2 feet, 1 foot, 6 inches, 3 inches","explanation":"2 ft > 1 ft > 6 in > 3 in. (1 ft = 12 in)","standard_code":"1.MD.1","difficulty":3,"options":[{"label":"2 feet, 6 inches, 1 foot, 3 inches","value":"2 feet, 6 inches, 1 foot, 3 inches"},{"label":"2 feet, 1 foot, 6 inches, 3 inches","value":"2 feet, 1 foot, 6 inches, 3 inches"},{"label":"2 feet, 1 foot, 3 inches, 6 inches","value":"2 feet, 1 foot, 3 inches, 6 inches"},{"label":"1 foot, 2 feet, 6 inches, 3 inches","value":"1 foot, 2 feet, 6 inches, 3 inches"}]},{"id":5,"text":"If rope X is longer than rope Y, and rope Y is longer than rope Z, can you say rope X is longer than rope Z?","type":"multiple_choice","correct_answer":"Yes","explanation":"This is indirect comparison (transitivity). If X > Y and Y > Z, then X > Z.","standard_code":"1.MD.1","difficulty":3,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]}]'::jsonb);

VALUES (1,'MD','1.MD.2','Measure Lengths Using Same-Size Length Units (Easy)','Students express the length of an object as a whole number of same-size length units by laying multiple copies of a shorter object end-to-end. They understand that the size of the unit affects the mea','practice',1,10,46,'[{"id":1,"text":"A pencil is as long as 5 paper clips placed end to end. How long is the pencil?","type":"multiple_choice","correct_answer":"5 paper clips","explanation":"The pencil is 5 paper clips long. Paper clips are the unit of measurement.","standard_code":"1.MD.2","difficulty":1,"options":[{"label":"1 paper clip","value":"1 paper clip"},{"label":"4 paper clips","value":"4 paper clips"},{"label":"6 paper clips","value":"6 paper clips"},{"label":"5 paper clips","value":"5 paper clips"}]},{"id":2,"text":"A book is 4 crayons long. A ruler is 8 crayons long. Which is longer?","type":"multiple_choice","correct_answer":"The ruler","explanation":"8 crayons > 4 crayons. The ruler is longer.","standard_code":"1.MD.2","difficulty":1,"options":[{"label":"You cannot compare different units","value":"You cannot compare different units"},{"label":"The ruler","value":"The ruler"},{"label":"The book","value":"The book"},{"label":"They are the same length","value":"They are the same length"}]},{"id":3,"text":"A crayon is 3 blocks long. How many blocks long is the crayon?","type":"multiple_choice","correct_answer":"3 blocks","explanation":"Count the blocks placed end-to-end: 3.","standard_code":"1.MD.2","difficulty":1,"options":[{"label":"3 blocks","value":"3 blocks"},{"label":"5 blocks","value":"5 blocks"},{"label":"4 blocks","value":"4 blocks"},{"label":"2 blocks","value":"2 blocks"}]},{"id":4,"text":"Sam laid 5 coins end-to-end along a pencil. How long is the pencil in coins?","type":"multiple_choice","correct_answer":"5 coins","explanation":"5 coins end-to-end = 5 coins long.","standard_code":"1.MD.2","difficulty":1,"options":[{"label":"10 coins","value":"10 coins"},{"label":"4 coins","value":"4 coins"},{"label":"6 coins","value":"6 coins"},{"label":"5 coins","value":"5 coins"}]},{"id":5,"text":"Maya measures a book with paper clips and uses 8 paper clips. How long is the book?","type":"multiple_choice","correct_answer":"8 paper clips","explanation":"The book is 8 paper clips long.","standard_code":"1.MD.2","difficulty":1,"options":[{"label":"7 paper clips","value":"7 paper clips"},{"label":"6 paper clips","value":"6 paper clips"},{"label":"9 paper clips","value":"9 paper clips"},{"label":"8 paper clips","value":"8 paper clips"}]}]'::jsonb);

VALUES (1,'MD','1.MD.2','Measure Lengths Using Same-Size Length Units (Medium)','Students express the length of an object as a whole number of same-size length units by laying multiple copies of a shorter object end-to-end. They understand that the size of the unit affects the mea','practice',2,15,47,'[{"id":1,"text":"Object A is 6 paper clips long. Object B is 4 paper clips long. Which is longer and by how much?","type":"multiple_choice","correct_answer":"Object A; by 2 paper clips","explanation":"6 - 4 = 2. Object A is longer by 2 paper clips.","standard_code":"1.MD.2","difficulty":2,"options":[{"label":"Object B; by 2 paper clips","value":"Object B; by 2 paper clips"},{"label":"Object B; by 10 paper clips","value":"Object B; by 10 paper clips"},{"label":"Object A; by 4 paper clips","value":"Object A; by 4 paper clips"},{"label":"Object A; by 2 paper clips","value":"Object A; by 2 paper clips"}]},{"id":2,"text":"The same object measures 4 blocks long OR 8 buttons long. Which unit is bigger - a block or a button?","type":"multiple_choice","correct_answer":"A block","explanation":"Fewer units means each unit is bigger. 4 big units = 8 small units, so blocks are bigger.","standard_code":"1.MD.2","difficulty":2,"options":[{"label":"A block","value":"A block"},{"label":"Cannot tell from this information","value":"Cannot tell from this information"},{"label":"A button","value":"A button"},{"label":"They are the same size","value":"They are the same size"}]},{"id":3,"text":"A table is 10 pencils wide. A desk is 7 pencils wide. How much wider is the table?","type":"multiple_choice","correct_answer":"3 pencils wider","explanation":"10 - 7 = 3 pencils.","standard_code":"1.MD.2","difficulty":2,"options":[{"label":"4 pencils wider","value":"4 pencils wider"},{"label":"17 pencils wider","value":"17 pencils wider"},{"label":"2 pencils wider","value":"2 pencils wider"},{"label":"3 pencils wider","value":"3 pencils wider"}]},{"id":4,"text":"Sam measured the door with his foot: 9 feet. Lisa measured it with her foot: 11 feet. Why are the answers different?","type":"multiple_choice","correct_answer":"Their feet are different sizes (different unit lengths)","explanation":"If units are different sizes, the same object will give different measurements.","standard_code":"1.MD.2","difficulty":2,"options":[{"label":"Their feet are different sizes (different unit lengths)","value":"Their feet are different sizes (different unit lengths)"},{"label":"They measured different doors","value":"They measured different doors"},{"label":"Sam''s foot is longer than Lisa''s","value":"Sam''s foot is longer than Lisa''s"},{"label":"The door is different sizes on different days","value":"The door is different sizes on different days"}]},{"id":5,"text":"A book is 5 large cubes or 10 small cubes long. Are the large cubes bigger or smaller than the small cubes?","type":"multiple_choice","correct_answer":"Larger","explanation":"5 large units = 10 small units, so each large unit is bigger.","standard_code":"1.MD.2","difficulty":2,"options":[{"label":"It depends on the book","value":"It depends on the book"},{"label":"The same size","value":"The same size"},{"label":"Smaller","value":"Smaller"},{"label":"Larger","value":"Larger"}]}]'::jsonb);

VALUES (1,'MD','1.MD.2','Measure Lengths Using Same-Size Length Units (Hard)','Students express the length of an object as a whole number of same-size length units by laying multiple copies of a shorter object end-to-end. They understand that the size of the unit affects the mea','practice',3,20,48,'[{"id":1,"text":"A pencil is 6 buttons long. An eraser needs to measure 18 buttons long. How many pencils long is the eraser?","type":"multiple_choice","correct_answer":"3 pencils","explanation":"18 buttons / 6 buttons per pencil = 3 pencils.","standard_code":"1.MD.2","difficulty":3,"options":[{"label":"4 pencils","value":"4 pencils"},{"label":"18 pencils","value":"18 pencils"},{"label":"3 pencils","value":"3 pencils"},{"label":"2 pencils","value":"2 pencils"}]},{"id":2,"text":"Which ruler is shorter: one that measures a table as 4 units, or one that measures the same table as 8 units?","type":"multiple_choice","correct_answer":"The ruler that gives 8 units (the shorter ruler)","explanation":"Smaller units require more of them. 8 units means each unit is shorter.","standard_code":"1.MD.2","difficulty":3,"options":[{"label":"The ruler that gives 4 units (the longer ruler)","value":"The ruler that gives 4 units (the longer ruler)"},{"label":"Neither ruler is shorter","value":"Neither ruler is shorter"},{"label":"Both rulers are the same length","value":"Both rulers are the same length"},{"label":"The ruler that gives 8 units (the shorter ruler)","value":"The ruler that gives 8 units (the shorter ruler)"}]},{"id":3,"text":"A path is 12 small steps long. Big steps are twice as long as small steps. How many big steps long is the path?","type":"multiple_choice","correct_answer":"6 big steps","explanation":"12 small steps / 2 = 6 big steps.","standard_code":"1.MD.2","difficulty":3,"options":[{"label":"3 big steps","value":"3 big steps"},{"label":"6 big steps","value":"6 big steps"},{"label":"12 big steps","value":"12 big steps"},{"label":"24 big steps","value":"24 big steps"}]},{"id":4,"text":"Ana measured her desk with paper clips and got 20. Her desk is also 10 crayons long. How long is each crayon in paper clips?","type":"multiple_choice","correct_answer":"2 paper clips","explanation":"20 paper clips = 10 crayons, so 1 crayon = 2 paper clips.","standard_code":"1.MD.2","difficulty":3,"options":[{"label":"10 paper clips","value":"10 paper clips"},{"label":"2 paper clips","value":"2 paper clips"},{"label":"1 paper clip","value":"1 paper clip"},{"label":"20 paper clips","value":"20 paper clips"}]},{"id":5,"text":"If you use a longer unit to measure a room, will you get a bigger or smaller number?","type":"multiple_choice","correct_answer":"Smaller number","explanation":"The longer the unit, the fewer units you need to cover the same length.","standard_code":"1.MD.2","difficulty":3,"options":[{"label":"The same number","value":"The same number"},{"label":"It depends on the room","value":"It depends on the room"},{"label":"Smaller number","value":"Smaller number"},{"label":"Bigger number","value":"Bigger number"}]}]'::jsonb);

VALUES (1,'MD','1.MD.3','Tell and Write Time - Hours and Half-Hours (Easy)','Students tell and write time in hours and half-hours using analog and digital clocks. On an analog clock: the short hand (hour hand) indicates the hour, the long hand (minute hand) points to 12 for th','practice',1,10,49,'[{"id":1,"text":"The clock shows the hour hand on 3 and the minute hand on 12. What time is it?","type":"multiple_choice","correct_answer":"3:00 (3 o''clock)","explanation":"Minute hand on 12 = exactly on the hour. Hour hand on 3 = 3 o''clock.","standard_code":"1.MD.3","difficulty":1,"options":[{"label":"12:03","value":"12:03"},{"label":"2:00","value":"2:00"},{"label":"3:30","value":"3:30"},{"label":"3:00 (3 o''clock)","value":"3:00 (3 o''clock)"}]},{"id":2,"text":"What does 5:00 mean?","type":"multiple_choice","correct_answer":"5 o''clock","explanation":"5:00 on a digital clock means it is exactly 5 o''clock. The hour hand points to 5, minute hand to 12.","standard_code":"1.MD.3","difficulty":1,"options":[{"label":"5 and 30 minutes","value":"5 and 30 minutes"},{"label":"5 o''clock","value":"5 o''clock"},{"label":"Half past 5","value":"Half past 5"},{"label":"50 minutes past the hour","value":"50 minutes past the hour"}]},{"id":3,"text":"The hour hand is on 7 and the minute hand is on 12. What time is it?","type":"multiple_choice","correct_answer":"7:00","explanation":"7 o''clock. Minute hand on 12 means it is exactly on the hour.","standard_code":"1.MD.3","difficulty":1,"options":[{"label":"12:07","value":"12:07"},{"label":"7:12","value":"7:12"},{"label":"7:00","value":"7:00"},{"label":"9:30","value":"9:30"}]},{"id":4,"text":"For 2:00, where does the hour hand point? Where does the minute hand point?","type":"multiple_choice","correct_answer":"Hour hand on 2, minute hand on 12","explanation":"For 2 o''clock, hour hand points to 2, minute hand points to 12.","standard_code":"1.MD.3","difficulty":1,"options":[{"label":"Hour hand on 12, minute hand on 2","value":"Hour hand on 12, minute hand on 2"},{"label":"Hour hand on 2, minute hand on 12","value":"Hour hand on 2, minute hand on 12"},{"label":"Hour hand between 2 and 3, minute hand on 12","value":"Hour hand between 2 and 3, minute hand on 12"},{"label":"Hour hand on 1, minute hand on 12","value":"Hour hand on 1, minute hand on 12"}]},{"id":5,"text":"Hour hand points to 9, minute hand points to 12. What time is it?","type":"multiple_choice","correct_answer":"9:00","explanation":"9 o''clock.","standard_code":"1.MD.3","difficulty":1,"options":[{"label":"9:30","value":"9:30"},{"label":"12:09","value":"12:09"},{"label":"9:00","value":"9:00"},{"label":"8:00","value":"8:00"}]}]'::jsonb);

VALUES (1,'MD','1.MD.3','Tell and Write Time - Hours and Half-Hours (Medium)','Students tell and write time in hours and half-hours using analog and digital clocks. On an analog clock: the short hand (hour hand) indicates the hour, the long hand (minute hand) points to 12 for th','practice',2,15,50,'[{"id":1,"text":"The minute hand is on 6 and the hour hand is between 4 and 5. What time is it?","type":"multiple_choice","correct_answer":"4:30","explanation":"Minute hand on 6 = 30 minutes past. Hour hand between 4 and 5 = half past 4 = 4:30.","standard_code":"1.MD.3","difficulty":2,"options":[{"label":"4:20","value":"4:20"},{"label":"5:30","value":"5:30"},{"label":"4:45","value":"4:45"},{"label":"4:30","value":"4:30"}]},{"id":2,"text":"What time is half past 2?","type":"multiple_choice","correct_answer":"2:30","explanation":"Half past 2 = 2:30. Minute hand points to 6, hour hand is between 2 and 3.","standard_code":"1.MD.3","difficulty":2,"options":[{"label":"3:30","value":"3:30"},{"label":"2:00","value":"2:00"},{"label":"2:30","value":"2:30"},{"label":"2:20","value":"2:20"}]},{"id":3,"text":"For 6:30, where do the clock hands point?","type":"multiple_choice","correct_answer":"Hour hand between 6 and 7, minute hand on 6","explanation":"6:30 means half past 6. The hour hand is halfway between 6 and 7.","standard_code":"1.MD.3","difficulty":2,"options":[{"label":"Hour hand on 6, minute hand between 6 and 7","value":"Hour hand on 6, minute hand between 6 and 7"},{"label":"Hour hand between 6 and 7, minute hand on 6","value":"Hour hand between 6 and 7, minute hand on 6"},{"label":"Hour hand on 7, minute hand on 6","value":"Hour hand on 7, minute hand on 6"},{"label":"Hour hand between 7 and 8, minute hand on 12","value":"Hour hand between 7 and 8, minute hand on 12"}]},{"id":4,"text":"What does 8:30 mean?","type":"multiple_choice","correct_answer":"Half past 8; 30 minutes after 8 o''clock","explanation":"8:30 = 8 hours and 30 minutes = half past 8.","standard_code":"1.MD.3","difficulty":2,"options":[{"label":"Half past 8; 30 minutes after 8 o''clock","value":"Half past 8; 30 minutes after 8 o''clock"},{"label":"30 minutes before 9 o''clock","value":"30 minutes before 9 o''clock"},{"label":"8 o''clock","value":"8 o''clock"},{"label":"Half past 9","value":"Half past 9"}]},{"id":5,"text":"Is 3:30 an o''clock time or a half-hour time?","type":"multiple_choice","correct_answer":"Half-hour","explanation":"3:30 has 30 minutes past, so it is a half-hour time.","standard_code":"1.MD.3","difficulty":2,"options":[{"label":"O''clock","value":"O''clock"},{"label":"Past-hour","value":"Past-hour"},{"label":"Half-hour","value":"Half-hour"},{"label":"Neither","value":"Neither"}]}]'::jsonb);

VALUES (1,'MD','1.MD.3','Tell and Write Time - Hours and Half-Hours (Hard)','Students tell and write time in hours and half-hours using analog and digital clocks. On an analog clock: the short hand (hour hand) indicates the hour, the long hand (minute hand) points to 12 for th','practice',3,20,51,'[{"id":1,"text":"School starts at 8 o''clock. Write this time two ways.","type":"multiple_choice","correct_answer":"8:00 and \"8 o''clock\"","explanation":"8 o''clock is written as 8:00 on a digital clock.","standard_code":"1.MD.3","difficulty":3,"options":[{"label":"8:30 and \"8 thirty\"","value":"8:30 and \"8 thirty\""},{"label":"8:00 and \"8 o''clock\"","value":"8:00 and \"8 o''clock\""},{"label":"8:00 and \"half past 8\"","value":"8:00 and \"half past 8\""},{"label":"8 and \"8:00\"","value":"8 and \"8:00\""}]},{"id":2,"text":"If it is 3:00 now, what time will it be in half an hour?","type":"multiple_choice","correct_answer":"3:30","explanation":"3:00 + 30 minutes = 3:30.","standard_code":"1.MD.3","difficulty":3,"options":[{"label":"3:15","value":"3:15"},{"label":"2:30","value":"2:30"},{"label":"4:00","value":"4:00"},{"label":"3:30","value":"3:30"}]},{"id":3,"text":"Lunch is at 12:30. Is this before or after noon?","type":"multiple_choice","correct_answer":"After noon (it is half past noon)","explanation":"12:30 is 30 minutes after noon.","standard_code":"1.MD.3","difficulty":3,"options":[{"label":"After noon (it is half past noon)","value":"After noon (it is half past noon)"},{"label":"Exactly noon","value":"Exactly noon"},{"label":"Before noon (it is half past midnight)","value":"Before noon (it is half past midnight)"},{"label":"It depends on the day","value":"It depends on the day"}]},{"id":4,"text":"The minute hand moved from 12 to 6. How many minutes passed?","type":"multiple_choice","correct_answer":"30 minutes","explanation":"From 12 to 6 on the minute hand = 30 minutes. This is half an hour.","standard_code":"1.MD.3","difficulty":3,"options":[{"label":"60 minutes","value":"60 minutes"},{"label":"15 minutes","value":"15 minutes"},{"label":"45 minutes","value":"45 minutes"},{"label":"30 minutes","value":"30 minutes"}]},{"id":5,"text":"At 7:00, Tom starts reading. At 7:30, he stops. How long did he read?","type":"multiple_choice","correct_answer":"30 minutes","explanation":"From 7:00 to 7:30 is 30 minutes (one half-hour).","standard_code":"1.MD.3","difficulty":3,"options":[{"label":"60 minutes","value":"60 minutes"},{"label":"30 minutes","value":"30 minutes"},{"label":"23 minutes","value":"23 minutes"},{"label":"7 minutes","value":"7 minutes"}]}]'::jsonb);

VALUES (1,'MD','1.MD.4','Organize, Represent, and Interpret Data (Easy)','Students organize, represent, and interpret data with up to three categories. They answer questions about the total number of data points, how many are in each category, and how many more or fewer in ','practice',1,10,52,'[{"id":1,"text":"5 students chose apples and 3 chose bananas. How many students chose fruit in all?","type":"numeric","correct_answer":"8","explanation":"5 + 3 = 8 students chose fruit.","standard_code":"1.MD.4","difficulty":1},{"id":2,"text":"A chart shows 4 cats and 6 dogs. Which has more?","type":"multiple_choice","correct_answer":"Dogs","explanation":"6 > 4. More dogs were counted.","standard_code":"1.MD.4","difficulty":1,"options":[{"label":"Neither","value":"Neither"},{"label":"Dogs","value":"Dogs"},{"label":"Cats","value":"Cats"},{"label":"They are equal","value":"They are equal"}]},{"id":3,"text":"In a class, 7 students like red and 5 like blue. How many more students like red than blue?","type":"multiple_choice","correct_answer":"2 more","explanation":"7 - 5 = 2 more students like red.","standard_code":"1.MD.4","difficulty":1,"options":[{"label":"2 more","value":"2 more"},{"label":"1 more","value":"1 more"},{"label":"3 more","value":"3 more"},{"label":"12 more","value":"12 more"}]},{"id":4,"text":"A bar graph shows 3 sunny days and 4 rainy days. How many days in all?","type":"multiple_choice","correct_answer":"7 days","explanation":"3 + 4 = 7 days.","standard_code":"1.MD.4","difficulty":1,"options":[{"label":"4 days","value":"4 days"},{"label":"1 day","value":"1 day"},{"label":"7 days","value":"7 days"},{"label":"12 days","value":"12 days"}]},{"id":5,"text":"Tally marks: cats = |||| (4), dogs = ||| (3). How many animals in all?","type":"numeric","correct_answer":"7","explanation":"Cats = 4, Dogs = 3. Total = 4 + 3 = 7.","standard_code":"1.MD.4","difficulty":1}]'::jsonb);

VALUES (1,'MD','1.MD.4','Organize, Represent, and Interpret Data (Medium)','Students organize, represent, and interpret data with up to three categories. They answer questions about the total number of data points, how many are in each category, and how many more or fewer in ','practice',2,15,53,'[{"id":1,"text":"Favorite colors: Red = 5, Blue = 3, Green = 7. Which color got the most votes?","type":"multiple_choice","correct_answer":"Green","explanation":"7 > 5 > 3. Green got the most votes.","standard_code":"1.MD.4","difficulty":2,"options":[{"label":"Red","value":"Red"},{"label":"Blue","value":"Blue"},{"label":"Green","value":"Green"},{"label":"They are all equal","value":"They are all equal"}]},{"id":2,"text":"A graph shows: apples = 6, bananas = 4, oranges = 5. How many fruit were counted in all?","type":"numeric","correct_answer":"15","explanation":"6 + 4 + 5 = 15 fruits.","standard_code":"1.MD.4","difficulty":2},{"id":3,"text":"Sports: Soccer = 8, Baseball = 5, Swimming = 3. How many more chose soccer than swimming?","type":"multiple_choice","correct_answer":"5 more","explanation":"8 - 3 = 5 more students chose soccer.","standard_code":"1.MD.4","difficulty":2,"options":[{"label":"3 more","value":"3 more"},{"label":"5 more","value":"5 more"},{"label":"13 more","value":"13 more"},{"label":"8 more","value":"8 more"}]},{"id":4,"text":"A pictograph shows 4 sunny days, 3 cloudy days, 2 rainy days. How many days does it show?","type":"multiple_choice","correct_answer":"9 days","explanation":"4 + 3 + 2 = 9 days.","standard_code":"1.MD.4","difficulty":2,"options":[{"label":"9 days","value":"9 days"},{"label":"10 days","value":"10 days"},{"label":"5 days","value":"5 days"},{"label":"6 days","value":"6 days"}]},{"id":5,"text":"Pets: Dogs = 7, Cats = 5, Fish = 3. How many more dogs than fish?","type":"multiple_choice","correct_answer":"4 more","explanation":"7 - 3 = 4 more dogs than fish.","standard_code":"1.MD.4","difficulty":2,"options":[{"label":"3 more","value":"3 more"},{"label":"10 more","value":"10 more"},{"label":"4 more","value":"4 more"},{"label":"2 more","value":"2 more"}]}]'::jsonb);

VALUES (1,'MD','1.MD.4','Organize, Represent, and Interpret Data (Hard)','Students organize, represent, and interpret data with up to three categories. They answer questions about the total number of data points, how many are in each category, and how many more or fewer in ','practice',3,20,54,'[{"id":1,"text":"Favorite lunch: Pizza = 9, Sandwich = 6, Salad = 3. How many more students chose pizza than sandwich and salad combined?","type":"multiple_choice","correct_answer":"0 (they are equal)","explanation":"Sandwich + Salad = 6 + 3 = 9 = Pizza. They are equal.","standard_code":"1.MD.4","difficulty":3,"options":[{"label":"3 more","value":"3 more"},{"label":"6 more","value":"6 more"},{"label":"9 more","value":"9 more"},{"label":"0 (they are equal)","value":"0 (they are equal)"}]},{"id":2,"text":"A class surveyed 20 students about pets. Dogs = 8, Cats = 7. How many students chose neither?","type":"numeric","correct_answer":"5","explanation":"20 - 8 - 7 = 5 students have neither a dog nor a cat.","standard_code":"1.MD.4","difficulty":3},{"id":3,"text":"Survey results: Jump rope = 12, Tag = 8, Blocks = 5. How many students were surveyed?","type":"numeric","correct_answer":"25","explanation":"12 + 8 + 5 = 25 students.","standard_code":"1.MD.4","difficulty":3},{"id":4,"text":"Using the data (Red = 4, Blue = 6, Yellow = 5), write one question and answer it.","type":"multiple_choice","correct_answer":"e.g., \"How many more chose blue than red?\" Answer: 6 - 4 = 2","explanation":"Many valid questions are possible. The key is to use the data to compare categories.","standard_code":"1.MD.4","difficulty":3,"options":[{"label":"e.g., \"How many more chose blue than red?\" Answer: 6 - 4 = 2","value":"e.g., \"How many more chose blue than red?\" Answer: 6 - 4 = 2"},{"label":"e.g., ''How many chose red?'' Answer: 4","value":"e.g., ''How many chose red?'' Answer: 4"},{"label":"e.g., ''Which color got the least?'' Answer: Red","value":"e.g., ''Which color got the least?'' Answer: Red"},{"label":"e.g., ''How many total?'' Answer: 4 + 6 + 5 = 15","value":"e.g., ''How many total?'' Answer: 4 + 6 + 5 = 15"}]},{"id":5,"text":"In a class: boys = 12, girls = 10. If 5 boys and 3 girls are absent, how many students are present?","type":"numeric","correct_answer":"14","explanation":"Present boys: 12 - 5 = 7. Present girls: 10 - 3 = 7. Total: 7 + 7 = 14.","standard_code":"1.MD.4","difficulty":3}]'::jsonb);

VALUES (1,'G','1.G.1','Distinguish Defining vs. Non-Defining Attributes of Shapes (Easy)','Students distinguish between attributes that define a shape (defining attributes) and attributes that do not (non-defining attributes). Defining attributes: number of sides, number of corners, being a','practice',1,10,55,'[{"id":1,"text":"How many sides does a triangle have?","type":"numeric","correct_answer":"3","explanation":"A triangle always has exactly 3 sides. This is a defining attribute of a triangle.","standard_code":"1.G.1","difficulty":1},{"id":2,"text":"How many corners does a square have?","type":"numeric","correct_answer":"4","explanation":"A square has 4 corners (vertices). This is a defining attribute.","standard_code":"1.G.1","difficulty":1},{"id":3,"text":"A shape has 4 sides and 4 corners. Could it be a rectangle?","type":"multiple_choice","correct_answer":"Yes","explanation":"A rectangle has 4 sides and 4 corners. Those are its defining attributes.","standard_code":"1.G.1","difficulty":1,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]},{"id":4,"text":"A circle is very large. Is it still a circle?","type":"multiple_choice","correct_answer":"Yes","explanation":"Size is a non-defining attribute. A large circle is still a circle.","standard_code":"1.G.1","difficulty":1,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]},{"id":5,"text":"A triangle is red. Does being red make it a triangle?","type":"multiple_choice","correct_answer":"No","explanation":"Color is not a defining attribute. A triangle is defined by having 3 sides and 3 corners.","standard_code":"1.G.1","difficulty":1,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]}]'::jsonb);

VALUES (1,'G','1.G.1','Distinguish Defining vs. Non-Defining Attributes of Shapes (Medium)','Students distinguish between attributes that define a shape (defining attributes) and attributes that do not (non-defining attributes). Defining attributes: number of sides, number of corners, being a','practice',2,15,56,'[{"id":1,"text":"Maria has a yellow triangle and a blue triangle. What makes both shapes triangles?","type":"multiple_choice","correct_answer":"Both have 3 sides and 3 corners","explanation":"Color does not matter. 3 sides and 3 corners define a triangle.","standard_code":"1.G.1","difficulty":2,"options":[{"label":"Both have 3 sides and 3 corners","value":"Both have 3 sides and 3 corners"},{"label":"Both have the same size","value":"Both have the same size"},{"label":"Both are yellow and blue","value":"Both are yellow and blue"},{"label":"Both are shapes","value":"Both are shapes"}]},{"id":2,"text":"Sort these into defining vs. non-defining attributes: color, number of sides, size, number of corners.","type":"multiple_choice","correct_answer":"Defining: number of sides, number of corners. Non-defining: color, size","explanation":"Defining attributes determine what shape it is. Non-defining ones can change without changing the shape type.","standard_code":"1.G.1","difficulty":2,"options":[{"label":"Defining: number of sides, number of corners. Non-defining: color, size","value":"Defining: number of sides, number of corners. Non-defining: color, size"},{"label":"All are non-defining attributes","value":"All are non-defining attributes"},{"label":"Defining: color, number of sides. Non-defining: number of corners, size","value":"Defining: color, number of sides. Non-defining: number of corners, size"},{"label":"Defining: color, size. Non-defining: number of sides, number of corners","value":"Defining: color, size. Non-defining: number of sides, number of corners"}]},{"id":3,"text":"A shape has 6 sides. What is it?","type":"multiple_choice","correct_answer":"Hexagon","explanation":"A hexagon has 6 sides and 6 corners.","standard_code":"1.G.1","difficulty":2,"options":[{"label":"Pentagon","value":"Pentagon"},{"label":"Rectangle","value":"Rectangle"},{"label":"Octagon","value":"Octagon"},{"label":"Hexagon","value":"Hexagon"}]},{"id":4,"text":"Can two different shape types both have 4 sides?","type":"multiple_choice","correct_answer":"Yes (e.g., square and rectangle)","explanation":"Squares and rectangles both have 4 sides. They are both quadrilaterals.","standard_code":"1.G.1","difficulty":2,"options":[{"label":"No, shapes with 4 sides are always the same","value":"No, shapes with 4 sides are always the same"},{"label":"No, only the same shape type can have the same number of sides","value":"No, only the same shape type can have the same number of sides"},{"label":"Yes (e.g., square and rectangle)","value":"Yes (e.g., square and rectangle)"},{"label":"Maybe, depending on their colors","value":"Maybe, depending on their colors"}]},{"id":5,"text":"What is one defining attribute of a circle?","type":"multiple_choice","correct_answer":"No straight sides and no corners; it is a closed curved shape","explanation":"A circle has no straight sides and no corners. This defines it.","standard_code":"1.G.1","difficulty":2,"options":[{"label":"It is round and large","value":"It is round and large"},{"label":"No straight sides and no corners; it is a closed curved shape","value":"No straight sides and no corners; it is a closed curved shape"},{"label":"It has no sides","value":"It has no sides"},{"label":"It has 4 sides","value":"It has 4 sides"}]}]'::jsonb);

VALUES (1,'G','1.G.1','Distinguish Defining vs. Non-Defining Attributes of Shapes (Hard)','Students distinguish between attributes that define a shape (defining attributes) and attributes that do not (non-defining attributes). Defining attributes: number of sides, number of corners, being a','practice',3,20,57,'[{"id":1,"text":"Jake says this shape is not a square because it is blue. Is he right?","type":"multiple_choice","correct_answer":"No","explanation":"Color is a non-defining attribute. A square is defined by 4 equal sides and 4 right corners.","standard_code":"1.G.1","difficulty":3,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]},{"id":2,"text":"Name a non-defining attribute for a triangle. Explain why it is non-defining.","type":"multiple_choice","correct_answer":"e.g., Color. It does not affect the number of sides or corners.","explanation":"Non-defining attributes (color, size, position) can change without changing whether the shape is a triangle.","standard_code":"1.G.1","difficulty":3,"options":[{"label":"e.g., Number of sides. It does not change the type of triangle","value":"e.g., Number of sides. It does not change the type of triangle"},{"label":"e.g., Color. It does not affect the number of sides or corners.","value":"e.g., Color. It does not affect the number of sides or corners."},{"label":"e.g., Size. It does not affect whether it is a shape","value":"e.g., Size. It does not affect whether it is a shape"},{"label":"e.g., Corner count. Triangles can have different corner amounts","value":"e.g., Corner count. Triangles can have different corner amounts"}]},{"id":3,"text":"How is a square different from a rectangle in terms of defining attributes?","type":"multiple_choice","correct_answer":"A square has 4 equal sides. A rectangle has 4 sides where opposite sides are equal. A square is a special rectangle.","explanation":"Both have 4 sides and 4 right corners, but a square requires all 4 sides to be equal length.","standard_code":"1.G.1","difficulty":3,"options":[{"label":"They are exactly the same shape with no differences","value":"They are exactly the same shape with no differences"},{"label":"A square has 4 sides and a rectangle has 5 sides","value":"A square has 4 sides and a rectangle has 5 sides"},{"label":"A square is round and a rectangle is curved","value":"A square is round and a rectangle is curved"},{"label":"A square has 4 equal sides. A rectangle has 4 sides where opposite sides are equal. A square is a special rectangle.","value":"A square has 4 equal sides. A rectangle has 4 sides where opposite sides are equal. A square is a special rectangle."}]},{"id":4,"text":"A shape is large, green, and has 4 equal sides and 4 right corners. What shape is it?","type":"multiple_choice","correct_answer":"A square","explanation":"The defining attributes are 4 equal sides and 4 right corners = square. Color and size are non-defining.","standard_code":"1.G.1","difficulty":3,"options":[{"label":"A hexagon","value":"A hexagon"},{"label":"A square","value":"A square"},{"label":"A rectangle","value":"A rectangle"},{"label":"A triangle","value":"A triangle"}]},{"id":5,"text":"Write two defining and two non-defining attributes of a rectangle.","type":"multiple_choice","correct_answer":"Defining: 4 sides, 4 corners. Non-defining: color, size","explanation":"Rectangles always have 4 sides and 4 corners. Their color and size can vary.","standard_code":"1.G.1","difficulty":3,"options":[{"label":"Defining: color, size. Non-defining: 4 sides, 4 corners","value":"Defining: color, size. Non-defining: 4 sides, 4 corners"},{"label":"Defining: 4 corners only. Non-defining: 4 sides, color, size","value":"Defining: 4 corners only. Non-defining: 4 sides, color, size"},{"label":"Defining: 4 sides, 4 corners. Non-defining: color, size","value":"Defining: 4 sides, 4 corners. Non-defining: color, size"},{"label":"Defining: size, color. Non-defining: 4 sides, 4 corners","value":"Defining: size, color. Non-defining: 4 sides, 4 corners"}]}]'::jsonb);

VALUES (1,'G','1.G.2','Compose Two- and Three-Dimensional Shapes (Easy)','Students compose 2D shapes (triangles, squares, rectangles, trapezoids, half-circles, quarter-circles) and 3D shapes (cubes, rectangular prisms, cones, cylinders) to create a composite shape. They bui','practice',1,10,58,'[{"id":1,"text":"What shape do you make when you put two equal right triangles together along their longest sides?","type":"multiple_choice","correct_answer":"A rectangle (or square)","explanation":"Two right triangles placed together form a rectangle or square.","standard_code":"1.G.2","difficulty":1,"options":[{"label":"A pentagon","value":"A pentagon"},{"label":"A triangle","value":"A triangle"},{"label":"A rectangle (or square)","value":"A rectangle (or square)"},{"label":"A parallelogram","value":"A parallelogram"}]},{"id":2,"text":"Name a 3D shape that looks like a soup can.","type":"multiple_choice","correct_answer":"Cylinder","explanation":"A soup can is shaped like a cylinder: circular top and bottom, curved side.","standard_code":"1.G.2","difficulty":1,"options":[{"label":"Cube","value":"Cube"},{"label":"Cylinder","value":"Cylinder"},{"label":"Sphere","value":"Sphere"},{"label":"Prism","value":"Prism"}]},{"id":3,"text":"What 2D shape is each face of a cube?","type":"multiple_choice","correct_answer":"Square","explanation":"All 6 faces of a cube are squares.","standard_code":"1.G.2","difficulty":1,"options":[{"label":"Square","value":"Square"},{"label":"Rectangle","value":"Rectangle"},{"label":"Circle","value":"Circle"},{"label":"Triangle","value":"Triangle"}]},{"id":4,"text":"What shape can you make with two equal squares placed side by side?","type":"multiple_choice","correct_answer":"Rectangle","explanation":"Two equal squares placed side by side form a rectangle.","standard_code":"1.G.2","difficulty":1,"options":[{"label":"Square","value":"Square"},{"label":"Rectangle","value":"Rectangle"},{"label":"Triangle","value":"Triangle"},{"label":"Trapezoid","value":"Trapezoid"}]},{"id":5,"text":"A cone has how many flat faces?","type":"multiple_choice","correct_answer":"1 (the circular base)","explanation":"A cone has 1 flat circular face at the base and comes to a point at the top.","standard_code":"1.G.2","difficulty":1,"options":[{"label":"0","value":"0"},{"label":"1 (the circular base)","value":"1 (the circular base)"},{"label":"2","value":"2"},{"label":"3","value":"3"}]}]'::jsonb);

VALUES (1,'G','1.G.2','Compose Two- and Three-Dimensional Shapes (Medium)','Students compose 2D shapes (triangles, squares, rectangles, trapezoids, half-circles, quarter-circles) and 3D shapes (cubes, rectangular prisms, cones, cylinders) to create a composite shape. They bui','practice',2,15,59,'[{"id":1,"text":"A large equilateral triangle can be made from how many smaller equal triangles?","type":"numeric","correct_answer":"4","explanation":"A large equilateral triangle can be divided into 4 smaller equal equilateral triangles.","standard_code":"1.G.2","difficulty":2},{"id":2,"text":"How many faces does a rectangular prism have?","type":"numeric","correct_answer":"6","explanation":"A rectangular prism has 6 rectangular faces.","standard_code":"1.G.2","difficulty":2},{"id":3,"text":"What 3D shape has one circular face and comes to a point?","type":"multiple_choice","correct_answer":"Cone","explanation":"A cone has one circular base and a pointed top.","standard_code":"1.G.2","difficulty":2,"options":[{"label":"Sphere","value":"Sphere"},{"label":"Cylinder","value":"Cylinder"},{"label":"Cone","value":"Cone"},{"label":"Pyramid","value":"Pyramid"}]},{"id":4,"text":"Name two 2D shapes you could use to make a simple house outline.","type":"multiple_choice","correct_answer":"A rectangle (walls) and a triangle (roof)","explanation":"A rectangle for the walls and a triangle on top for the roof.","standard_code":"1.G.2","difficulty":2,"options":[{"label":"Two triangles (walls) and a rectangle (roof)","value":"Two triangles (walls) and a rectangle (roof)"},{"label":"A triangle (walls) and a rectangle (roof)","value":"A triangle (walls) and a rectangle (roof)"},{"label":"A rectangle (walls) and a triangle (roof)","value":"A rectangle (walls) and a triangle (roof)"},{"label":"A square (walls) and a circle (roof)","value":"A square (walls) and a circle (roof)"}]},{"id":5,"text":"What is the same and different between a cube and a rectangular prism?","type":"multiple_choice","correct_answer":"Same: 6 faces, 8 corners. Different: cube has all square faces; rectangular prism can have rectangular faces.","explanation":"Both have 6 faces and 8 vertices (corners), but a cube has equal square faces.","standard_code":"1.G.2","difficulty":2,"options":[{"label":"Same: both are flat shapes. Different: cube is 3D; rectangular prism is 2D.","value":"Same: both are flat shapes. Different: cube is 3D; rectangular prism is 2D."},{"label":"Same: 6 faces, 8 corners. Different: cube has all square faces; rectangular prism can have rectangular faces.","value":"Same: 6 faces, 8 corners. Different: cube has all square faces; rectangular prism can have rectangular faces."},{"label":"Same: 8 corners. Different: cube has square faces; rectangular prism has rectangular faces.","value":"Same: 8 corners. Different: cube has square faces; rectangular prism has rectangular faces."},{"label":"Same: 6 square faces. Different: cube has 8 corners; rectangular prism has 4 corners.","value":"Same: 6 square faces. Different: cube has 8 corners; rectangular prism has 4 corners."}]}]'::jsonb);

VALUES (1,'G','1.G.2','Compose Two- and Three-Dimensional Shapes (Hard)','Students compose 2D shapes (triangles, squares, rectangles, trapezoids, half-circles, quarter-circles) and 3D shapes (cubes, rectangular prisms, cones, cylinders) to create a composite shape. They bui','practice',3,20,60,'[{"id":1,"text":"Ben has 4 small cubes. He stacks 2 and places 2 side by side. What shape does he create?","type":"multiple_choice","correct_answer":"A larger rectangular prism","explanation":"Combining cubes in a rectangular arrangement creates a larger rectangular prism.","standard_code":"1.G.2","difficulty":3,"options":[{"label":"A pyramid","value":"A pyramid"},{"label":"A larger rectangular prism","value":"A larger rectangular prism"},{"label":"A smaller cube","value":"A smaller cube"},{"label":"A triangular prism","value":"A triangular prism"}]},{"id":2,"text":"Name three real-world objects shaped like a sphere.","type":"multiple_choice","correct_answer":"e.g., ball, globe, orange","explanation":"Spheres are perfectly round: balls, globes, oranges are all sphere-shaped.","standard_code":"1.G.2","difficulty":3,"options":[{"label":"Dice, box, book","value":"Dice, box, book"},{"label":"e.g., ball, globe, orange","value":"e.g., ball, globe, orange"},{"label":"Wheel, tire, ring","value":"Wheel, tire, ring"},{"label":"Marble, coin, plate","value":"Marble, coin, plate"}]},{"id":3,"text":"A regular hexagon can be made from how many equilateral triangles?","type":"numeric","correct_answer":"6","explanation":"A regular hexagon can be divided into 6 equilateral triangles arranged around a center point.","standard_code":"1.G.2","difficulty":3},{"id":4,"text":"What 3D shape has two triangular faces and three rectangular faces?","type":"multiple_choice","correct_answer":"Triangular prism","explanation":"A triangular prism has 2 triangular faces (ends) and 3 rectangular faces (sides).","standard_code":"1.G.2","difficulty":3,"options":[{"label":"Triangular prism","value":"Triangular prism"},{"label":"Rectangular prism","value":"Rectangular prism"},{"label":"Triangular pyramid","value":"Triangular pyramid"},{"label":"Square prism","value":"Square prism"}]},{"id":5,"text":"You have some triangles and squares. Describe a composite shape you can make and name it.","type":"multiple_choice","correct_answer":"e.g., A square with a triangle on top looks like a house or a pentagon","explanation":"A square with an equilateral triangle on top creates a house-like pentagon composite shape.","standard_code":"1.G.2","difficulty":3,"options":[{"label":"e.g., Four squares make a larger square or a rectangle","value":"e.g., Four squares make a larger square or a rectangle"},{"label":"e.g., Three circles stacked make a tower","value":"e.g., Three circles stacked make a tower"},{"label":"e.g., A square with a triangle on top looks like a house or a pentagon","value":"e.g., A square with a triangle on top looks like a house or a pentagon"},{"label":"e.g., Two triangles make a square or a parallelogram","value":"e.g., Two triangles make a square or a parallelogram"}]}]'::jsonb);

VALUES (1,'G','1.G.3','Partition Circles and Rectangles into Equal Shares (Easy)','Students partition circles and rectangles into 2 or 4 equal shares, using vocabulary: halves, fourths, quarters. They understand that the more equal shares a whole is divided into, the smaller each sh','practice',1,10,61,'[{"id":1,"text":"A circle is cut into 2 equal pieces. What is each piece called?","type":"multiple_choice","correct_answer":"A half","explanation":"Two equal pieces of a whole are called halves. Each piece is one-half.","standard_code":"1.G.3","difficulty":1,"options":[{"label":"A quarter","value":"A quarter"},{"label":"A section","value":"A section"},{"label":"A third","value":"A third"},{"label":"A half","value":"A half"}]},{"id":2,"text":"If you fold a rectangle into 2 equal parts, how many halves are there?","type":"multiple_choice","correct_answer":"2 halves","explanation":"2 equal parts = 2 halves.","standard_code":"1.G.3","difficulty":1,"options":[{"label":"2 halves","value":"2 halves"},{"label":"1 half","value":"1 half"},{"label":"4 halves","value":"4 halves"},{"label":"3 halves","value":"3 halves"}]},{"id":3,"text":"Is half of 8 equal to 4?","type":"multiple_choice","correct_answer":"Yes","explanation":"8 / 2 = 4. Half of 8 is 4.","standard_code":"1.G.3","difficulty":1,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]},{"id":4,"text":"A pizza is cut in half. You eat one piece. How much of the pizza did you eat?","type":"multiple_choice","correct_answer":"One half (1/2)","explanation":"One out of two equal pieces = one-half.","standard_code":"1.G.3","difficulty":1,"options":[{"label":"One half (1/2)","value":"One half (1/2)"},{"label":"One third (1/3)","value":"One third (1/3)"},{"label":"Two thirds (2/3)","value":"Two thirds (2/3)"},{"label":"One fourth (1/4)","value":"One fourth (1/4)"}]},{"id":5,"text":"A sandwich is cut into 2 equal halves. Are the pieces bigger or smaller than the whole sandwich?","type":"multiple_choice","correct_answer":"Smaller","explanation":"Any piece of a whole is smaller than the whole.","standard_code":"1.G.3","difficulty":1,"options":[{"label":"Smaller","value":"Smaller"},{"label":"The same size","value":"The same size"},{"label":"Bigger","value":"Bigger"},{"label":"It depends on the sandwich","value":"It depends on the sandwich"}]}]'::jsonb);

VALUES (1,'G','1.G.3','Partition Circles and Rectangles into Equal Shares (Medium)','Students partition circles and rectangles into 2 or 4 equal shares, using vocabulary: halves, fourths, quarters. They understand that the more equal shares a whole is divided into, the smaller each sh','practice',2,15,62,'[{"id":1,"text":"A circle is cut into 4 equal pieces. What is each piece called?","type":"multiple_choice","correct_answer":"A fourth, or a quarter","explanation":"Four equal pieces = fourths or quarters. Each is one-fourth.","standard_code":"1.G.3","difficulty":2,"options":[{"label":"A third","value":"A third"},{"label":"A fourth, or a quarter","value":"A fourth, or a quarter"},{"label":"A half","value":"A half"},{"label":"A whole","value":"A whole"}]},{"id":2,"text":"If you cut a rectangle into 4 equal parts, how many fourths are there?","type":"multiple_choice","correct_answer":"4 fourths","explanation":"4 equal parts = 4 fourths.","standard_code":"1.G.3","difficulty":2,"options":[{"label":"8 fourths","value":"8 fourths"},{"label":"2 fourths","value":"2 fourths"},{"label":"4 fourths","value":"4 fourths"},{"label":"3 fourths","value":"3 fourths"}]},{"id":3,"text":"Which is bigger: one-half of a pizza or one-fourth of the same pizza?","type":"multiple_choice","correct_answer":"One-half","explanation":"The more pieces you cut, the smaller each piece is. A half is bigger than a fourth.","standard_code":"1.G.3","difficulty":2,"options":[{"label":"One-half","value":"One-half"},{"label":"One-third","value":"One-third"},{"label":"They are the same","value":"They are the same"},{"label":"One-fourth","value":"One-fourth"}]},{"id":4,"text":"A square is cut into 4 equal parts. Each part is called a ___.","type":"multiple_choice","correct_answer":"Fourth (or quarter)","explanation":"Four equal parts of a whole are called fourths or quarters.","standard_code":"1.G.3","difficulty":2,"options":[{"label":"Half","value":"Half"},{"label":"Third","value":"Third"},{"label":"Whole","value":"Whole"},{"label":"Fourth (or quarter)","value":"Fourth (or quarter)"}]},{"id":5,"text":"4 fourths = ___ whole(s)","type":"multiple_choice","correct_answer":"1 whole","explanation":"4 fourths put back together = 1 whole.","standard_code":"1.G.3","difficulty":2,"options":[{"label":"1 whole","value":"1 whole"},{"label":"2 wholes","value":"2 wholes"},{"label":"4 wholes","value":"4 wholes"},{"label":"1/2 whole","value":"1/2 whole"}]}]'::jsonb);

VALUES (1,'G','1.G.3','Partition Circles and Rectangles into Equal Shares (Hard)','Students partition circles and rectangles into 2 or 4 equal shares, using vocabulary: halves, fourths, quarters. They understand that the more equal shares a whole is divided into, the smaller each sh','practice',3,20,63,'[{"id":1,"text":"Can a rectangle be cut into 4 equal shares in different ways? Explain.","type":"multiple_choice","correct_answer":"Yes (e.g., 4 horizontal strips, 4 vertical strips, or a 2x2 grid - all are fourths)","explanation":"Equal shares do not need to have the same shape. A rectangle can be quartered in multiple ways.","standard_code":"1.G.3","difficulty":3,"options":[{"label":"No, a rectangle can only be cut into 4 equal shares one way","value":"No, a rectangle can only be cut into 4 equal shares one way"},{"label":"Yes (e.g., 4 horizontal strips, 4 vertical strips, or a 2x2 grid - all are fourths)","value":"Yes (e.g., 4 horizontal strips, 4 vertical strips, or a 2x2 grid - all are fourths)"},{"label":"No, rectangles cannot be divided into equal shares","value":"No, rectangles cannot be divided into equal shares"},{"label":"Yes, but only by cutting it into 4 vertical strips","value":"Yes, but only by cutting it into 4 vertical strips"}]},{"id":2,"text":"Sam cuts a circle into 2 equal pieces. Ana cuts a same-size circle into 4 equal pieces. Whose pieces are bigger?","type":"multiple_choice","correct_answer":"Sam''s (halves are bigger than fourths)","explanation":"Fewer equal pieces means each piece is larger. 2 pieces > 4 pieces in individual size.","standard_code":"1.G.3","difficulty":3,"options":[{"label":"It depends on the size of the circle","value":"It depends on the size of the circle"},{"label":"They are the same size","value":"They are the same size"},{"label":"Sam''s (halves are bigger than fourths)","value":"Sam''s (halves are bigger than fourths)"},{"label":"Ana''s (fourths are bigger than halves)","value":"Ana''s (fourths are bigger than halves)"}]},{"id":3,"text":"A rectangle is cut into 2 equal halves. Each half is then cut in half again. What fraction is each piece?","type":"multiple_choice","correct_answer":"One-fourth (1/4)","explanation":"Half of a half = one-fourth. 1/2 x 1/2 = 1/4.","standard_code":"1.G.3","difficulty":3,"options":[{"label":"One-half (1/2)","value":"One-half (1/2)"},{"label":"One-eighth (1/8)","value":"One-eighth (1/8)"},{"label":"One-third (1/3)","value":"One-third (1/3)"},{"label":"One-fourth (1/4)","value":"One-fourth (1/4)"}]},{"id":4,"text":"Two identical rectangles: one cut into halves, one into fourths. Which rectangle has smaller pieces?","type":"multiple_choice","correct_answer":"The one cut into fourths","explanation":"More equal pieces means each piece is smaller.","standard_code":"1.G.3","difficulty":3,"options":[{"label":"The one cut into fourths","value":"The one cut into fourths"},{"label":"They have the same size pieces","value":"They have the same size pieces"},{"label":"It depends on how big the rectangles are","value":"It depends on how big the rectangles are"},{"label":"The one cut into halves","value":"The one cut into halves"}]},{"id":5,"text":"A pizza is shared equally among 4 friends. Is each share a half or a fourth? Who gets a bigger piece - 1 of 2 friends sharing, or 1 of 4 friends sharing?","type":"multiple_choice","correct_answer":"Each of 4 friends gets a fourth. 1 of 2 friends gets a bigger piece.","explanation":"4 equal shares = fourths. 1/2 > 1/4, so sharing between 2 people gives bigger pieces.","standard_code":"1.G.3","difficulty":3,"options":[{"label":"Each of 4 friends gets a fourth. 1 of 4 friends gets a bigger piece.","value":"Each of 4 friends gets a fourth. 1 of 4 friends gets a bigger piece."},{"label":"Each of 4 friends gets a fourth. 1 of 2 friends gets a bigger piece.","value":"Each of 4 friends gets a fourth. 1 of 2 friends gets a bigger piece."},{"label":"Each of 4 friends gets a half. 1 of 4 friends gets a bigger piece.","value":"Each of 4 friends gets a half. 1 of 4 friends gets a bigger piece."},{"label":"Each of 4 friends gets a half. 1 of 2 friends gets a bigger piece.","value":"Each of 4 friends gets a half. 1 of 2 friends gets a bigger piece."}]}]'::jsonb);

-- ============================================================
-- GRADE 2
-- ============================================================

VALUES (2,'OA','2.OA.1','Solve One- and Two-Step Word Problems Within 100 (Easy)','Students use addition and subtraction within 100 to solve one- and two-step word problems involving adding to, taking from, putting together, taking apart, and comparing situations - with unknowns in ','practice',1,10,64,'[{"id":1,"text":"Amy has 23 stickers. She gets 15 more. How many does she have now?","type":"numeric","correct_answer":"38","explanation":"23 + 15 = 38. Add ones: 3+5=8. Add tens: 20+10=30. Total: 38.","standard_code":"2.OA.1","difficulty":1},{"id":2,"text":"There are 45 apples in a bowl. 12 are eaten. How many remain?","type":"numeric","correct_answer":"33","explanation":"45 - 12 = 33. Subtract ones: 5-2=3. Subtract tens: 40-10=30. Total: 33.","standard_code":"2.OA.1","difficulty":1},{"id":3,"text":"Sam has 30 red crayons and 25 blue crayons. How many crayons in all?","type":"numeric","correct_answer":"55","explanation":"30 + 25 = 55. Add tens and ones: 50 + 5 = 55.","standard_code":"2.OA.1","difficulty":1},{"id":4,"text":"A bag has 56 marbles. 20 roll away. How many are left?","type":"numeric","correct_answer":"36","explanation":"56 - 20 = 36. Subtract the tens only.","standard_code":"2.OA.1","difficulty":1},{"id":5,"text":"18 birds are on a wire. 14 more land. How many birds are there now?","type":"numeric","correct_answer":"32","explanation":"18 + 14 = 32. Make a ten: 18 + 2 = 20, then 20 + 12 = 32.","standard_code":"2.OA.1","difficulty":1}]'::jsonb);

VALUES (2,'OA','2.OA.1','Solve One- and Two-Step Word Problems Within 100 (Medium)','Students use addition and subtraction within 100 to solve one- and two-step word problems involving adding to, taking from, putting together, taking apart, and comparing situations - with unknowns in ','practice',2,15,65,'[{"id":1,"text":"Lily had 72 pages to read. She read 38. How many are left?","type":"numeric","correct_answer":"34","explanation":"72 - 38 = 34. Decompose: 72 - 30 = 42, then 42 - 8 = 34.","standard_code":"2.OA.1","difficulty":2},{"id":2,"text":"There are 47 boys and 35 girls in a school play. How many students in all?","type":"numeric","correct_answer":"82","explanation":"47 + 35 = 82. 47 + 3 = 50, then 50 + 32 = 82.","standard_code":"2.OA.1","difficulty":2},{"id":3,"text":"A farmer picks 63 tomatoes. He gives 27 away. How many are left?","type":"numeric","correct_answer":"36","explanation":"63 - 27 = 36. 63 - 20 = 43, then 43 - 7 = 36.","standard_code":"2.OA.1","difficulty":2},{"id":4,"text":"Jan has 54 pennies. She spends 29. How many does she have left?","type":"numeric","correct_answer":"25","explanation":"54 - 29 = 25. Compensation: 54 - 30 = 24, then 24 + 1 = 25.","standard_code":"2.OA.1","difficulty":2},{"id":5,"text":"A box has 46 chocolates. Someone adds 38 more. How many?","type":"numeric","correct_answer":"84","explanation":"46 + 38 = 84. 46 + 4 = 50, then 50 + 34 = 84.","standard_code":"2.OA.1","difficulty":2}]'::jsonb);

VALUES (2,'OA','2.OA.1','Solve One- and Two-Step Word Problems Within 100 (Hard)','Students use addition and subtraction within 100 to solve one- and two-step word problems involving adding to, taking from, putting together, taking apart, and comparing situations - with unknowns in ','practice',3,20,66,'[{"id":1,"text":"Tyler had some books. He gave 27 away and has 45 left. How many did he start with?","type":"numeric","correct_answer":"72","explanation":"? - 27 = 45, so ? = 45 + 27 = 72.","standard_code":"2.OA.1","difficulty":3},{"id":2,"text":"A class collected 48 cans, then 37 more. They need 100 total. How many more do they need?","type":"numeric","correct_answer":"15","explanation":"Step 1: 48 + 37 = 85. Step 2: 100 - 85 = 15.","standard_code":"2.OA.1","difficulty":3},{"id":3,"text":"There were 63 people. 28 left and then 18 more arrived. How many people are there now?","type":"numeric","correct_answer":"53","explanation":"63 - 28 = 35, then 35 + 18 = 53.","standard_code":"2.OA.1","difficulty":3},{"id":4,"text":"Sam read 24 pages on Monday and 18 on Tuesday. He needs 67 pages total. How many more pages does he need?","type":"numeric","correct_answer":"25","explanation":"24 + 18 = 42. Then 67 - 42 = 25 more pages.","standard_code":"2.OA.1","difficulty":3},{"id":5,"text":"A plank is 86 cm long. A worker cuts some off and it is now 58 cm. Then another 15 cm is cut. How long is the plank now?","type":"numeric","correct_answer":"43","explanation":"86 - 58 = 28 cm cut the first time. Remaining after second cut: 58 - 15 = 43 cm.","standard_code":"2.OA.1","difficulty":3}]'::jsonb);

VALUES (2,'OA','2.OA.2','Fluently Add and Subtract Within 20 (Easy)','Students demonstrate fluency - accuracy, efficiency, and flexibility - with addition and subtraction within 20. By end of Grade 2, they know all sums of two one-digit numbers from memory, using strate','practice',1,10,67,'[{"id":1,"text":"9 + 6 = ?","type":"numeric","correct_answer":"15","explanation":"Make a ten: 9 + 1 = 10, then 10 + 5 = 15.","standard_code":"2.OA.2","difficulty":1},{"id":2,"text":"14 - 8 = ?","type":"numeric","correct_answer":"6","explanation":"Think of the related fact: 8 + 6 = 14, so 14 - 8 = 6.","standard_code":"2.OA.2","difficulty":1},{"id":3,"text":"7 + 8 = ?","type":"numeric","correct_answer":"15","explanation":"Near-doubles: 7 + 7 = 14, so 7 + 8 = 15.","standard_code":"2.OA.2","difficulty":1},{"id":4,"text":"6 + 6 = ?","type":"numeric","correct_answer":"12","explanation":"Doubles fact: 6 + 6 = 12. Know this from memory.","standard_code":"2.OA.2","difficulty":1},{"id":5,"text":"17 - 9 = ?","type":"numeric","correct_answer":"8","explanation":"9 + 8 = 17, so 17 - 9 = 8.","standard_code":"2.OA.2","difficulty":1}]'::jsonb);

VALUES (2,'OA','2.OA.2','Fluently Add and Subtract Within 20 (Medium)','Students demonstrate fluency - accuracy, efficiency, and flexibility - with addition and subtraction within 20. By end of Grade 2, they know all sums of two one-digit numbers from memory, using strate','practice',2,15,68,'[{"id":1,"text":"8 + 7 = ?","type":"numeric","correct_answer":"15","explanation":"Near-doubles: 7 + 7 = 14, so 8 + 7 = 15. Or: 8 + 2 = 10, 10 + 5 = 15.","standard_code":"2.OA.2","difficulty":2},{"id":2,"text":"13 - 7 = ?","type":"numeric","correct_answer":"6","explanation":"Related fact: 7 + 6 = 13, so 13 - 7 = 6.","standard_code":"2.OA.2","difficulty":2},{"id":3,"text":"9 + 9 = ?","type":"numeric","correct_answer":"18","explanation":"Doubles fact: 9 + 9 = 18.","standard_code":"2.OA.2","difficulty":2},{"id":4,"text":"16 - 8 = ?","type":"numeric","correct_answer":"8","explanation":"Doubles: 8 + 8 = 16, so 16 - 8 = 8.","standard_code":"2.OA.2","difficulty":2},{"id":5,"text":"5 + 8 = ?","type":"numeric","correct_answer":"13","explanation":"Make a ten: 8 + 2 = 10, then 10 + 3 = 13.","standard_code":"2.OA.2","difficulty":2}]'::jsonb);

VALUES (2,'OA','2.OA.2','Fluently Add and Subtract Within 20 (Hard)','Students demonstrate fluency - accuracy, efficiency, and flexibility - with addition and subtraction within 20. By end of Grade 2, they know all sums of two one-digit numbers from memory, using strate','practice',3,20,69,'[{"id":1,"text":"? + 7 = 15","type":"numeric","correct_answer":"8","explanation":"15 - 7 = 8. Check: 8 + 7 = 15.","standard_code":"2.OA.2","difficulty":3},{"id":2,"text":"20 - ? = 13","type":"numeric","correct_answer":"7","explanation":"13 + 7 = 20, so ? = 7.","standard_code":"2.OA.2","difficulty":3},{"id":3,"text":"6 + ? = 14","type":"numeric","correct_answer":"8","explanation":"Make a ten: 6 + 4 = 10, then 10 + 4 = 14. So 4 + 4 = 8.","standard_code":"2.OA.2","difficulty":3},{"id":4,"text":"? - 8 = 9","type":"numeric","correct_answer":"17","explanation":"9 + 8 = 17. If ? - 8 = 9, then ? = 9 + 8 = 17.","standard_code":"2.OA.2","difficulty":3},{"id":5,"text":"4 + 7 + 9 = ?","type":"numeric","correct_answer":"20","explanation":"7 + 9 = 16, then 16 + 4 = 20. Or: 4 + 6 = 10 (take 6 from 7), 10 + 1 + 9 = 20.","standard_code":"2.OA.2","difficulty":3}]'::jsonb);

VALUES (2,'OA','2.OA.3','Determine Odd or Even; Express Even Numbers as Two Equal Addends (Easy)','Students determine whether a group of objects (up to 20) has an odd or even number. Even numbers can be expressed as a sum of two equal addends (e.g., 8 = 4 + 4) and can be paired with no remainder. O','practice',1,10,70,'[{"id":1,"text":"Is 6 odd or even?","type":"multiple_choice","correct_answer":"Even","explanation":"6 = 3 + 3. It can be split into two equal groups. Even numbers pair perfectly with no remainder.","standard_code":"2.OA.3","difficulty":1,"options":[{"label":"Can''t tell","value":"Can''t tell"},{"label":"Odd","value":"Odd"},{"label":"Neither odd nor even","value":"Neither odd nor even"},{"label":"Even","value":"Even"}]},{"id":2,"text":"Is 7 odd or even?","type":"multiple_choice","correct_answer":"Odd","explanation":"7 cannot be paired evenly: 3 + 3 = 6, with 1 left over. 7 is odd.","standard_code":"2.OA.3","difficulty":1,"options":[{"label":"Can''t tell","value":"Can''t tell"},{"label":"Neither odd nor even","value":"Neither odd nor even"},{"label":"Odd","value":"Odd"},{"label":"Even","value":"Even"}]},{"id":3,"text":"Is 4 even? How do you know?","type":"multiple_choice","correct_answer":"Yes, 4 is even","explanation":"4 = 2 + 2. It can be expressed as two equal addends with no remainder.","standard_code":"2.OA.3","difficulty":1,"options":[{"label":"No, 4 is neither","value":"No, 4 is neither"},{"label":"Yes, 4 is even","value":"Yes, 4 is even"},{"label":"Yes, because it''s a bigger number","value":"Yes, because it''s a bigger number"},{"label":"No, 4 is odd","value":"No, 4 is odd"}]},{"id":4,"text":"Is 9 odd or even?","type":"multiple_choice","correct_answer":"Odd","explanation":"9 = 4 + 4 + 1. There is 1 left over, so 9 is odd.","standard_code":"2.OA.3","difficulty":1,"options":[{"label":"Even","value":"Even"},{"label":"Can''t tell","value":"Can''t tell"},{"label":"Odd","value":"Odd"},{"label":"Neither odd nor even","value":"Neither odd nor even"}]},{"id":5,"text":"Write 8 as two equal addends.","type":"multiple_choice","correct_answer":"4 + 4 = 8","explanation":"8 divided equally = 4 + 4. Even numbers can always be written this way.","standard_code":"2.OA.3","difficulty":1,"options":[{"label":"5 + 3 = 8","value":"5 + 3 = 8"},{"label":"4 + 4 = 8","value":"4 + 4 = 8"},{"label":"3 + 3 = 8","value":"3 + 3 = 8"},{"label":"6 + 2 = 8","value":"6 + 2 = 8"}]}]'::jsonb);

VALUES (2,'OA','2.OA.3','Determine Odd or Even; Express Even Numbers as Two Equal Addends (Medium)','Students determine whether a group of objects (up to 20) has an odd or even number. Even numbers can be expressed as a sum of two equal addends (e.g., 8 = 4 + 4) and can be paired with no remainder. O','practice',2,15,71,'[{"id":1,"text":"Is 14 odd or even? How do you know?","type":"multiple_choice","correct_answer":"Even","explanation":"14 = 7 + 7. It can be expressed as two equal addends, so it is even.","standard_code":"2.OA.3","difficulty":2,"options":[{"label":"Even","value":"Even"},{"label":"Odd","value":"Odd"},{"label":"Neither odd nor even","value":"Neither odd nor even"},{"label":"Odd, because it ends in 4","value":"Odd, because it ends in 4"}]},{"id":2,"text":"Write 18 as two equal addends.","type":"multiple_choice","correct_answer":"9 + 9 = 18","explanation":"18 / 2 = 9. So 18 = 9 + 9.","standard_code":"2.OA.3","difficulty":2,"options":[{"label":"9 + 9 = 18","value":"9 + 9 = 18"},{"label":"8 + 10 = 18","value":"8 + 10 = 18"},{"label":"6 + 12 = 18","value":"6 + 12 = 18"},{"label":"7 + 11 = 18","value":"7 + 11 = 18"}]},{"id":3,"text":"Mia has 15 stickers. Can she share them equally with one friend, with none left over?","type":"multiple_choice","correct_answer":"No","explanation":"15 is odd. 15 = 7 + 7 + 1. There would be 1 leftover sticker.","standard_code":"2.OA.3","difficulty":2,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]},{"id":4,"text":"Is 20 odd or even? Write it as two equal addends.","type":"multiple_choice","correct_answer":"Even; 10 + 10 = 20","explanation":"20 = 10 + 10. Even.","standard_code":"2.OA.3","difficulty":2,"options":[{"label":"Odd; 15 + 5 = 20","value":"Odd; 15 + 5 = 20"},{"label":"Even; 12 + 8 = 20","value":"Even; 12 + 8 = 20"},{"label":"Odd; 5 + 5 + 5 + 5 = 20","value":"Odd; 5 + 5 + 5 + 5 = 20"},{"label":"Even; 10 + 10 = 20","value":"Even; 10 + 10 = 20"}]},{"id":5,"text":"Which numbers between 11 and 20 are even?","type":"multiple_choice","correct_answer":"12, 14, 16, 18, 20","explanation":"Even numbers end in 0, 2, 4, 6, or 8: 12, 14, 16, 18, 20.","standard_code":"2.OA.3","difficulty":2,"options":[{"label":"13, 14, 15, 16, 17","value":"13, 14, 15, 16, 17"},{"label":"12, 14, 16, 18, 20","value":"12, 14, 16, 18, 20"},{"label":"11, 13, 15, 17, 19","value":"11, 13, 15, 17, 19"},{"label":"12, 13, 14, 15, 16","value":"12, 13, 14, 15, 16"}]}]'::jsonb);

VALUES (2,'OA','2.OA.3','Determine Odd or Even; Express Even Numbers as Two Equal Addends (Hard)','Students determine whether a group of objects (up to 20) has an odd or even number. Even numbers can be expressed as a sum of two equal addends (e.g., 8 = 4 + 4) and can be paired with no remainder. O','practice',3,20,72,'[{"id":1,"text":"Can an odd number always be written as two equal addends? Explain.","type":"multiple_choice","correct_answer":"No","explanation":"Odd numbers always have 1 left over when split in half. e.g., 7 = 3 + 3 + 1. There are no two equal whole-number addends.","standard_code":"2.OA.3","difficulty":3,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]},{"id":2,"text":"What happens when you add two even numbers? Give an example.","type":"multiple_choice","correct_answer":"The result is always even","explanation":"Example: 4 + 6 = 10. Even + Even = Even. The pairs from each number combine neatly.","standard_code":"2.OA.3","difficulty":3,"options":[{"label":"The result is always even","value":"The result is always even"},{"label":"The result is sometimes even and sometimes odd","value":"The result is sometimes even and sometimes odd"},{"label":"The result is always zero","value":"The result is always zero"},{"label":"The result is always odd","value":"The result is always odd"}]},{"id":3,"text":"What happens when you add two odd numbers? Give an example.","type":"multiple_choice","correct_answer":"The result is always even","explanation":"Example: 3 + 5 = 8. The two leftover ones from each odd number pair up, making the total even.","standard_code":"2.OA.3","difficulty":3,"options":[{"label":"The result is always even","value":"The result is always even"},{"label":"The result is always odd","value":"The result is always odd"},{"label":"The result is sometimes even and sometimes odd","value":"The result is sometimes even and sometimes odd"},{"label":"The result is always zero","value":"The result is always zero"}]},{"id":4,"text":"Is the sum of an even and an odd number odd or even? Explain.","type":"multiple_choice","correct_answer":"Odd","explanation":"Example: 4 + 3 = 7. The one leftover one from the odd number stays unpaired, making the total odd.","standard_code":"2.OA.3","difficulty":3,"options":[{"label":"Even","value":"Even"},{"label":"Sometimes odd and sometimes even","value":"Sometimes odd and sometimes even"},{"label":"Zero","value":"Zero"},{"label":"Odd","value":"Odd"}]},{"id":5,"text":"Explain why 16 is even using two equal addends.","type":"multiple_choice","correct_answer":"16 = 8 + 8. It can be split into two equal groups of 8 with no remainder.","explanation":"16 / 2 = 8. If you arrange 16 objects into 2 rows, each row has 8 - equal with nothing left over.","standard_code":"2.OA.3","difficulty":3,"options":[{"label":"16 = 12 + 4. It can be split into two equal groups of 8 with no remainder.","value":"16 = 12 + 4. It can be split into two equal groups of 8 with no remainder."},{"label":"16 = 9 + 7. It can be split into two unequal groups.","value":"16 = 9 + 7. It can be split into two unequal groups."},{"label":"16 = 10 + 6. It can be split into two equal groups of 8 with no remainder.","value":"16 = 10 + 6. It can be split into two equal groups of 8 with no remainder."},{"label":"16 = 8 + 8. It can be split into two equal groups of 8 with no remainder.","value":"16 = 8 + 8. It can be split into two equal groups of 8 with no remainder."}]}]'::jsonb);

VALUES (2,'OA','2.OA.4','Use Addition with Rectangular Arrays (Up to 5x5) (Easy)','Students use addition to find the total number of objects in a rectangular array with up to 5 rows and 5 columns. They write equations using equal addends (one per row or column) to represent the tota','practice',1,10,73,'[{"id":1,"text":"An array has 2 rows and 3 columns. How many objects are there?","type":"numeric","correct_answer":"6","explanation":"2 rows of 3: 3 + 3 = 6.","standard_code":"2.OA.4","difficulty":1},{"id":2,"text":"Write an addition equation for a 3 x 3 array.","type":"multiple_choice","correct_answer":"3 + 3 + 3 = 9","explanation":"3 rows of 3: 3 + 3 + 3 = 9.","standard_code":"2.OA.4","difficulty":1,"options":[{"label":"2 + 2 + 2 = 6","value":"2 + 2 + 2 = 6"},{"label":"3 + 3 = 6","value":"3 + 3 = 6"},{"label":"4 + 4 + 4 = 12","value":"4 + 4 + 4 = 12"},{"label":"3 + 3 + 3 = 9","value":"3 + 3 + 3 = 9"}]},{"id":3,"text":"An array has 4 rows of 2 objects each. How many objects?","type":"numeric","correct_answer":"8","explanation":"4 rows of 2: 2 + 2 + 2 + 2 = 8.","standard_code":"2.OA.4","difficulty":1},{"id":4,"text":"What is the total in a 2 x 5 array?","type":"numeric","correct_answer":"10","explanation":"2 rows of 5: 5 + 5 = 10.","standard_code":"2.OA.4","difficulty":1},{"id":5,"text":"A 1 x 4 array has how many objects?","type":"numeric","correct_answer":"4","explanation":"1 row of 4: just 4 objects.","standard_code":"2.OA.4","difficulty":1}]'::jsonb);

VALUES (2,'OA','2.OA.4','Use Addition with Rectangular Arrays (Up to 5x5) (Medium)','Students use addition to find the total number of objects in a rectangular array with up to 5 rows and 5 columns. They write equations using equal addends (one per row or column) to represent the tota','practice',2,15,74,'[{"id":1,"text":"For a 3 x 4 array, write two different addition equations (one by rows, one by columns).","type":"multiple_choice","correct_answer":"4 + 4 + 4 = 12 (by rows) and 3 + 3 + 3 + 3 = 12 (by columns)","explanation":"3 rows of 4 gives 4+4+4=12. 4 columns of 3 gives 3+3+3+3=12. Both equal 12.","standard_code":"2.OA.4","difficulty":2,"options":[{"label":"4 + 4 + 4 = 12 (by rows) and 3 + 3 + 3 + 3 = 12 (by columns)","value":"4 + 4 + 4 = 12 (by rows) and 3 + 3 + 3 + 3 = 12 (by columns)"},{"label":"4 + 4 = 8 (by rows) and 3 + 3 = 6 (by columns)","value":"4 + 4 = 8 (by rows) and 3 + 3 = 6 (by columns)"},{"label":"3 + 3 + 3 = 9 (by rows) and 4 + 4 + 4 + 4 = 16 (by columns)","value":"3 + 3 + 3 = 9 (by rows) and 4 + 4 + 4 + 4 = 16 (by columns)"},{"label":"3 + 3 + 3 + 3 = 12 (by rows) and 4 + 4 + 4 = 12 (by columns)","value":"3 + 3 + 3 + 3 = 12 (by rows) and 4 + 4 + 4 = 12 (by columns)"}]},{"id":2,"text":"A fruit tray has 5 rows with 4 oranges in each row. How many oranges?","type":"numeric","correct_answer":"20","explanation":"5 rows of 4: 4 + 4 + 4 + 4 + 4 = 20.","standard_code":"2.OA.4","difficulty":2},{"id":3,"text":"Write the addition equation for a 4 x 4 array.","type":"multiple_choice","correct_answer":"4 + 4 + 4 + 4 = 16","explanation":"4 rows of 4 = 4 + 4 + 4 + 4 = 16.","standard_code":"2.OA.4","difficulty":2,"options":[{"label":"4 + 4 + 4 + 4 + 4 = 20","value":"4 + 4 + 4 + 4 + 4 = 20"},{"label":"4 + 4 + 4 = 12","value":"4 + 4 + 4 = 12"},{"label":"4 + 4 + 4 + 4 = 16","value":"4 + 4 + 4 + 4 = 16"},{"label":"4 × 4 = 16","value":"4 × 4 = 16"}]},{"id":4,"text":"An array has 15 objects with 5 in each row. How many rows are there?","type":"multiple_choice","correct_answer":"3 rows","explanation":"5 + 5 + 5 = 15. There are 3 rows of 5.","standard_code":"2.OA.4","difficulty":2,"options":[{"label":"5 rows","value":"5 rows"},{"label":"3 rows","value":"3 rows"},{"label":"10 rows","value":"10 rows"},{"label":"15 rows","value":"15 rows"}]},{"id":5,"text":"A 5 x 3 array - how many total? Show your work.","type":"numeric","correct_answer":"15","explanation":"5 rows of 3: 3 + 3 + 3 + 3 + 3 = 15.","standard_code":"2.OA.4","difficulty":2}]'::jsonb);

VALUES (2,'OA','2.OA.4','Use Addition with Rectangular Arrays (Up to 5x5) (Hard)','Students use addition to find the total number of objects in a rectangular array with up to 5 rows and 5 columns. They write equations using equal addends (one per row or column) to represent the tota','practice',3,20,75,'[{"id":1,"text":"For a 4 x 5 array, write two equations (by rows and by columns).","type":"multiple_choice","correct_answer":"5 + 5 + 5 + 5 = 20 and 4 + 4 + 4 + 4 + 4 = 20","explanation":"4 rows of 5 and 5 rows of 4 both give a total of 20.","standard_code":"2.OA.4","difficulty":3,"options":[{"label":"4 + 4 + 4 + 4 + 4 = 20 and 5 + 5 + 5 + 5 = 20","value":"4 + 4 + 4 + 4 + 4 = 20 and 5 + 5 + 5 + 5 = 20"},{"label":"4 + 4 + 4 + 4 = 16 and 5 + 5 + 5 + 5 + 5 = 25","value":"4 + 4 + 4 + 4 = 16 and 5 + 5 + 5 + 5 + 5 = 25"},{"label":"5 + 5 + 5 + 5 = 20 and 5 + 5 + 5 + 5 + 5 = 25","value":"5 + 5 + 5 + 5 = 20 and 5 + 5 + 5 + 5 + 5 = 25"},{"label":"5 + 5 + 5 + 5 = 20 and 4 + 4 + 4 + 4 + 4 = 20","value":"5 + 5 + 5 + 5 = 20 and 4 + 4 + 4 + 4 + 4 = 20"}]},{"id":2,"text":"There are 20 objects in an array with 4 rows. How many columns?","type":"multiple_choice","correct_answer":"5 columns","explanation":"Each row has 20 / 4 = 5 objects. There are 5 columns.","standard_code":"2.OA.4","difficulty":3,"options":[{"label":"10 columns","value":"10 columns"},{"label":"6 columns","value":"6 columns"},{"label":"4 columns","value":"4 columns"},{"label":"5 columns","value":"5 columns"}]},{"id":3,"text":"Write the equation for a 5 x 5 array.","type":"multiple_choice","correct_answer":"5 + 5 + 5 + 5 + 5 = 25","explanation":"5 rows of 5: 5 + 5 + 5 + 5 + 5 = 25.","standard_code":"2.OA.4","difficulty":3,"options":[{"label":"5 + 5 + 5 + 5 + 5 = 25","value":"5 + 5 + 5 + 5 + 5 = 25"},{"label":"5 + 5 + 5 = 15","value":"5 + 5 + 5 = 15"},{"label":"5 + 5 + 5 + 5 = 20","value":"5 + 5 + 5 + 5 = 20"},{"label":"5 + 5 + 5 + 5 + 5 + 5 = 30","value":"5 + 5 + 5 + 5 + 5 + 5 = 30"}]},{"id":4,"text":"Compare: a 3 x 4 array and a 4 x 3 array. Do they have the same total?","type":"multiple_choice","correct_answer":"Yes, both equal 12","explanation":"3 rows of 4 = 12. 4 rows of 3 = 12. Rotating the array does not change the total.","standard_code":"2.OA.4","difficulty":3,"options":[{"label":"Yes, both equal 12","value":"Yes, both equal 12"},{"label":"No, 3 × 4 equals 12 but 4 × 3 equals 13","value":"No, 3 × 4 equals 12 but 4 × 3 equals 13"},{"label":"No, they do not have the same total","value":"No, they do not have the same total"},{"label":"Yes, both equal 24","value":"Yes, both equal 24"}]},{"id":5,"text":"A classroom has 4 rows of desks with 5 desks each. 2 desks are empty. How many students are seated?","type":"numeric","correct_answer":"18","explanation":"4 + 4 + 4 + 4 + 4 = 20 desks total. 20 - 2 = 18 students.","standard_code":"2.OA.4","difficulty":3}]'::jsonb);

VALUES (2,'NBT','2.NBT.1','Understand Place Value of Three-Digit Numbers (Easy)','Students understand that the three digits of a three-digit number represent amounts of hundreds, tens, and ones. For example, 352 = 3 hundreds + 5 tens + 2 ones = 300 + 50 + 2. They also know that 100','practice',1,10,76,'[{"id":1,"text":"What is the value of each digit in 345?","type":"multiple_choice","correct_answer":"3 hundreds (300), 4 tens (40), 5 ones (5)","explanation":"345 = 300 + 40 + 5.","standard_code":"2.NBT.1","difficulty":1,"options":[{"label":"3 hundreds (300), 4 tens (40), 5 ones (5)","value":"3 hundreds (300), 4 tens (40), 5 ones (5)"},{"label":"3 tens (30), 4 hundreds (400), 5 ones (5)","value":"3 tens (30), 4 hundreds (400), 5 ones (5)"},{"label":"3 ones (3), 4 tens (40), 5 hundreds (500)","value":"3 ones (3), 4 tens (40), 5 hundreds (500)"},{"label":"3 hundreds (300), 4 ones (4), 5 tens (50)","value":"3 hundreds (300), 4 ones (4), 5 tens (50)"}]},{"id":2,"text":"Write 200 + 70 + 3 as a number.","type":"numeric","correct_answer":"273","explanation":"2 hundreds + 7 tens + 3 ones = 273.","standard_code":"2.NBT.1","difficulty":1},{"id":3,"text":"How many hundreds are in 500?","type":"multiple_choice","correct_answer":"5 hundreds","explanation":"500 = 5 groups of 100.","standard_code":"2.NBT.1","difficulty":1,"options":[{"label":"1 hundred","value":"1 hundred"},{"label":"5 hundreds","value":"5 hundreds"},{"label":"500 hundreds","value":"500 hundreds"},{"label":"50 hundreds","value":"50 hundreds"}]},{"id":4,"text":"What is the value of the digit 4 in 482?","type":"multiple_choice","correct_answer":"400 (4 hundreds)","explanation":"4 is in the hundreds place. Its value is 4 x 100 = 400.","standard_code":"2.NBT.1","difficulty":1,"options":[{"label":"400 (4 hundreds)","value":"400 (4 hundreds)"},{"label":"40 (4 tens)","value":"40 (4 tens)"},{"label":"4000 (4 thousands)","value":"4000 (4 thousands)"},{"label":"4 (4 ones)","value":"4 (4 ones)"}]},{"id":5,"text":"Write 6 hundreds, 3 tens, 8 ones as a number.","type":"numeric","correct_answer":"638","explanation":"600 + 30 + 8 = 638.","standard_code":"2.NBT.1","difficulty":1}]'::jsonb);

VALUES (2,'NBT','2.NBT.1','Understand Place Value of Three-Digit Numbers (Medium)','Students understand that the three digits of a three-digit number represent amounts of hundreds, tens, and ones. For example, 352 = 3 hundreds + 5 tens + 2 ones = 300 + 50 + 2. They also know that 100','practice',2,15,77,'[{"id":1,"text":"What is the value of the digit 7 in 374?","type":"multiple_choice","correct_answer":"70 (7 tens)","explanation":"7 is in the tens place. Its value is 7 x 10 = 70.","standard_code":"2.NBT.1","difficulty":2,"options":[{"label":"700 (7 hundreds)","value":"700 (7 hundreds)"},{"label":"70 (7 tens)","value":"70 (7 tens)"},{"label":"7 (7 ones)","value":"7 (7 ones)"},{"label":"7000 (7 thousands)","value":"7000 (7 thousands)"}]},{"id":2,"text":"100 = ? tens","type":"multiple_choice","correct_answer":"10 tens","explanation":"100 = 10 groups of 10. Ten tens make one hundred.","standard_code":"2.NBT.1","difficulty":2,"options":[{"label":"10 tens","value":"10 tens"},{"label":"5 tens","value":"5 tens"},{"label":"100 tens","value":"100 tens"},{"label":"1 ten","value":"1 ten"}]},{"id":3,"text":"A number has 5 hundreds, 0 tens, and 6 ones. What is the number?","type":"numeric","correct_answer":"506","explanation":"500 + 0 + 6 = 506.","standard_code":"2.NBT.1","difficulty":2},{"id":4,"text":"What is 400 + 30 + 7?","type":"numeric","correct_answer":"437","explanation":"4 hundreds + 3 tens + 7 ones = 437.","standard_code":"2.NBT.1","difficulty":2},{"id":5,"text":"How many ones are in 100?","type":"multiple_choice","correct_answer":"100 ones","explanation":"100 = 100 individual ones.","standard_code":"2.NBT.1","difficulty":2,"options":[{"label":"100 ones","value":"100 ones"},{"label":"10 ones","value":"10 ones"},{"label":"1000 ones","value":"1000 ones"},{"label":"1 one","value":"1 one"}]}]'::jsonb);

VALUES (2,'NBT','2.NBT.1','Understand Place Value of Three-Digit Numbers (Hard)','Students understand that the three digits of a three-digit number represent amounts of hundreds, tens, and ones. For example, 352 = 3 hundreds + 5 tens + 2 ones = 300 + 50 + 2. They also know that 100','practice',3,20,78,'[{"id":1,"text":"835 = 8 hundreds + ? tens + ? ones","type":"multiple_choice","correct_answer":"3 tens and 5 ones","explanation":"835 = 800 + 30 + 5.","standard_code":"2.NBT.1","difficulty":3,"options":[{"label":"8 tens and 3 ones","value":"8 tens and 3 ones"},{"label":"5 tens and 3 ones","value":"5 tens and 3 ones"},{"label":"3 tens and 5 ones","value":"3 tens and 5 ones"},{"label":"3 ones and 5 tens","value":"3 ones and 5 tens"}]},{"id":2,"text":"Write 712 in two different ways using hundreds, tens, and ones.","type":"multiple_choice","correct_answer":"7 hundreds 1 ten 2 ones; OR 6 hundreds 11 tens 2 ones","explanation":"712 = 700 + 10 + 2, or 600 + 110 + 2. Both equal 712.","standard_code":"2.NBT.1","difficulty":3,"options":[{"label":"7 hundreds 2 tens 1 one; OR 6 hundreds 12 tens 1 one","value":"7 hundreds 2 tens 1 one; OR 6 hundreds 12 tens 1 one"},{"label":"7 hundreds 1 ten 2 ones; OR 7 hundreds 11 tens 2 ones","value":"7 hundreds 1 ten 2 ones; OR 7 hundreds 11 tens 2 ones"},{"label":"7 hundreds 1 ten 2 ones; OR 6 hundreds 11 tens 2 ones","value":"7 hundreds 1 ten 2 ones; OR 6 hundreds 11 tens 2 ones"},{"label":"7 hundreds 1 one 2 tens; OR 6 hundreds 11 ones 2 tens","value":"7 hundreds 1 one 2 tens; OR 6 hundreds 11 ones 2 tens"}]},{"id":3,"text":"How many tens are in 430?","type":"multiple_choice","correct_answer":"43 tens","explanation":"430 = 43 groups of 10. 43 x 10 = 430.","standard_code":"2.NBT.1","difficulty":3,"options":[{"label":"43 tens","value":"43 tens"},{"label":"4300 tens","value":"4300 tens"},{"label":"430 tens","value":"430 tens"},{"label":"4 tens","value":"4 tens"}]},{"id":4,"text":"A three-digit number has the same digit in the hundreds and ones place, and 0 in the tens. The digit is 5. What is the number?","type":"numeric","correct_answer":"505","explanation":"5 hundreds + 0 tens + 5 ones = 505.","standard_code":"2.NBT.1","difficulty":3},{"id":5,"text":"Is 9 hundreds + 10 tens equal to 1000? Explain.","type":"multiple_choice","correct_answer":"Yes","explanation":"9 hundreds = 900. 10 tens = 100. 900 + 100 = 1000.","standard_code":"2.NBT.1","difficulty":3,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]}]'::jsonb);

VALUES (2,'NBT','2.NBT.2','Count Within 1000; Skip-Count by 5s, 10s, and 100s (Easy)','Students count within 1000 and skip-count by 5s, 10s, and 100s. Skip-counting by 5s builds fluency with multiples of 5; skip-counting by 10s shows the tens pattern; skip-counting by 100s reveals the h','practice',1,10,79,'[{"id":1,"text":"Skip-count by 5s: 5, 10, 15, __, 25. What is missing?","type":"numeric","correct_answer":"20","explanation":"Each step adds 5. 15 + 5 = 20.","standard_code":"2.NBT.2","difficulty":1},{"id":2,"text":"Skip-count by 10s: 10, 20, 30, __, 50. What is missing?","type":"numeric","correct_answer":"40","explanation":"Each step adds 10. 30 + 10 = 40.","standard_code":"2.NBT.2","difficulty":1},{"id":3,"text":"Skip-count by 100s: 100, 200, 300, __, 500.","type":"numeric","correct_answer":"400","explanation":"Each step adds 100. 300 + 100 = 400.","standard_code":"2.NBT.2","difficulty":1},{"id":4,"text":"Continue: 25, 30, 35, __","type":"numeric","correct_answer":"40","explanation":"Skip-counting by 5s: 35 + 5 = 40.","standard_code":"2.NBT.2","difficulty":1},{"id":5,"text":"Continue: 200, 300, 400, __","type":"numeric","correct_answer":"500","explanation":"Skip-counting by 100s: 400 + 100 = 500.","standard_code":"2.NBT.2","difficulty":1}]'::jsonb);

VALUES (2,'NBT','2.NBT.2','Count Within 1000; Skip-Count by 5s, 10s, and 100s (Medium)','Students count within 1000 and skip-count by 5s, 10s, and 100s. Skip-counting by 5s builds fluency with multiples of 5; skip-counting by 10s shows the tens pattern; skip-counting by 100s reveals the h','practice',2,15,80,'[{"id":1,"text":"Skip-count by 5s starting at 45: 45, 50, 55, __","type":"numeric","correct_answer":"60","explanation":"55 + 5 = 60.","standard_code":"2.NBT.2","difficulty":2},{"id":2,"text":"Skip-count by 10s: 65, 75, 85, __","type":"numeric","correct_answer":"95","explanation":"85 + 10 = 95.","standard_code":"2.NBT.2","difficulty":2},{"id":3,"text":"Skip-count by 100s from 350: 350, 450, 550, __","type":"numeric","correct_answer":"650","explanation":"550 + 100 = 650.","standard_code":"2.NBT.2","difficulty":2},{"id":4,"text":"Fill in: 730, 740, 750, __, 770","type":"numeric","correct_answer":"760","explanation":"Skip-counting by 10s: 750 + 10 = 760.","standard_code":"2.NBT.2","difficulty":2},{"id":5,"text":"Fill in: 85, 90, 95, __, 105","type":"numeric","correct_answer":"100","explanation":"Skip-counting by 5s: 95 + 5 = 100.","standard_code":"2.NBT.2","difficulty":2}]'::jsonb);

VALUES (2,'NBT','2.NBT.2','Count Within 1000; Skip-Count by 5s, 10s, and 100s (Hard)','Students count within 1000 and skip-count by 5s, 10s, and 100s. Skip-counting by 5s builds fluency with multiples of 5; skip-counting by 10s shows the tens pattern; skip-counting by 100s reveals the h','practice',3,20,81,'[{"id":1,"text":"Count backwards by 10s: 150, 140, 130, __","type":"numeric","correct_answer":"120","explanation":"Counting back by 10s: 130 - 10 = 120.","standard_code":"2.NBT.2","difficulty":3},{"id":2,"text":"Skip-count by 5s: 970, 975, 980, 985, __","type":"numeric","correct_answer":"990","explanation":"985 + 5 = 990.","standard_code":"2.NBT.2","difficulty":3},{"id":3,"text":"A pattern: 200, 400, 600, __. What type of skip-count is this?","type":"multiple_choice","correct_answer":"800; skip-counting by 200s","explanation":"Each number is 200 more than the previous.","standard_code":"2.NBT.2","difficulty":3,"options":[{"label":"1000; skip-counting by 100s","value":"1000; skip-counting by 100s"},{"label":"800; skip-counting by 400s","value":"800; skip-counting by 400s"},{"label":"1200; skip-counting by 200s","value":"1200; skip-counting by 200s"},{"label":"800; skip-counting by 200s","value":"800; skip-counting by 200s"}]},{"id":4,"text":"Fill in: 755, 760, 765, __, 775","type":"numeric","correct_answer":"770","explanation":"Skip-counting by 5s: 765 + 5 = 770.","standard_code":"2.NBT.2","difficulty":3},{"id":5,"text":"Count back by 100s: 900, 800, 700, __, 500","type":"numeric","correct_answer":"600","explanation":"700 - 100 = 600.","standard_code":"2.NBT.2","difficulty":3}]'::jsonb);

VALUES (2,'NBT','2.NBT.3','Read and Write Numbers to 1000 - Numerals, Names, Expanded Form (Easy)','Students read and write numbers to 1000 using base-ten numerals, number names (words), and expanded form. Expanded form breaks a number into the value of each digit (e.g., 347 = 300 + 40 + 7).','practice',1,10,82,'[{"id":1,"text":"Write \"three hundred forty-two\" as a numeral.","type":"numeric","correct_answer":"342","explanation":"3 hundreds + 4 tens + 2 ones = 342.","standard_code":"2.NBT.3","difficulty":1},{"id":2,"text":"Write 516 in words.","type":"multiple_choice","correct_answer":"Five hundred sixteen","explanation":"500 + 10 + 6 = five hundred sixteen.","standard_code":"2.NBT.3","difficulty":1,"options":[{"label":"Fifty-six hundred","value":"Fifty-six hundred"},{"label":"Five hundred sixty","value":"Five hundred sixty"},{"label":"Five hundred sixteen","value":"Five hundred sixteen"},{"label":"Five thousands sixteen","value":"Five thousands sixteen"}]},{"id":3,"text":"Write 728 in expanded form.","type":"multiple_choice","correct_answer":"700 + 20 + 8","explanation":"7 hundreds + 2 tens + 8 ones.","standard_code":"2.NBT.3","difficulty":1,"options":[{"label":"700 + 20 + 8","value":"700 + 20 + 8"},{"label":"700 + 28","value":"700 + 28"},{"label":"700 + 20 + 80","value":"700 + 20 + 80"},{"label":"72 + 8","value":"72 + 8"}]},{"id":4,"text":"What is the numeral for nine hundred five?","type":"numeric","correct_answer":"905","explanation":"9 hundreds + 0 tens + 5 ones = 905.","standard_code":"2.NBT.3","difficulty":1},{"id":5,"text":"Write 400 + 60 + 3 as a number.","type":"numeric","correct_answer":"463","explanation":"4 hundreds + 6 tens + 3 ones = 463.","standard_code":"2.NBT.3","difficulty":1}]'::jsonb);

VALUES (2,'NBT','2.NBT.3','Read and Write Numbers to 1000 - Numerals, Names, Expanded Form (Medium)','Students read and write numbers to 1000 using base-ten numerals, number names (words), and expanded form. Expanded form breaks a number into the value of each digit (e.g., 347 = 300 + 40 + 7).','practice',2,15,83,'[{"id":1,"text":"Write 804 in expanded form.","type":"multiple_choice","correct_answer":"800 + 0 + 4 (or 800 + 4)","explanation":"8 hundreds + 0 tens + 4 ones = 804.","standard_code":"2.NBT.3","difficulty":2,"options":[{"label":"800 + 0 + 4 (or 800 + 4)","value":"800 + 0 + 4 (or 800 + 4)"},{"label":"800 + 4","value":"800 + 4"},{"label":"84 + 0","value":"84 + 0"},{"label":"800 + 40","value":"800 + 40"}]},{"id":2,"text":"Write 600 + 90 as a number and in words.","type":"multiple_choice","correct_answer":"690; six hundred ninety","explanation":"6 hundreds + 9 tens + 0 ones = 690.","standard_code":"2.NBT.3","difficulty":2,"options":[{"label":"690; six hundred nine","value":"690; six hundred nine"},{"label":"609; six hundred ninety","value":"609; six hundred ninety"},{"label":"69; sixty nine","value":"69; sixty nine"},{"label":"690; six hundred ninety","value":"690; six hundred ninety"}]},{"id":3,"text":"What number is 200 + 50? Write it in words.","type":"multiple_choice","correct_answer":"250; two hundred fifty","explanation":"250 = two hundred fifty.","standard_code":"2.NBT.3","difficulty":2,"options":[{"label":"300; three hundred","value":"300; three hundred"},{"label":"250; two hundred fifty","value":"250; two hundred fifty"},{"label":"200; two hundred","value":"200; two hundred"},{"label":"250; two hundred five","value":"250; two hundred five"}]},{"id":4,"text":"Write 1000 in words.","type":"multiple_choice","correct_answer":"One thousand","explanation":"1000 = one thousand.","standard_code":"2.NBT.3","difficulty":2,"options":[{"label":"One thousand","value":"One thousand"},{"label":"Ten thousand","value":"Ten thousand"},{"label":"One hundred","value":"One hundred"},{"label":"One hundred thousand","value":"One hundred thousand"}]},{"id":5,"text":"A number in expanded form is 300 + 0 + 7. Write the numeral and the number name.","type":"multiple_choice","correct_answer":"307; three hundred seven","explanation":"307 = three hundred seven.","standard_code":"2.NBT.3","difficulty":2,"options":[{"label":"307; three hundred seven","value":"307; three hundred seven"},{"label":"703; seven hundred three","value":"703; seven hundred three"},{"label":"300; three hundred","value":"300; three hundred"},{"label":"370; three hundred seventy","value":"370; three hundred seventy"}]}]'::jsonb);

VALUES (2,'NBT','2.NBT.3','Read and Write Numbers to 1000 - Numerals, Names, Expanded Form (Hard)','Students read and write numbers to 1000 using base-ten numerals, number names (words), and expanded form. Expanded form breaks a number into the value of each digit (e.g., 347 = 300 + 40 + 7).','practice',3,20,84,'[{"id":1,"text":"John wrote 670 in expanded form as 600 + 7. What mistake did he make?","type":"multiple_choice","correct_answer":"He forgot the tens: it should be 600 + 70 + 0","explanation":"670 = 600 + 70. The digit 7 is in the tens place, worth 70, not 7.","standard_code":"2.NBT.3","difficulty":3,"options":[{"label":"He forgot the tens: it should be 600 + 70 + 0","value":"He forgot the tens: it should be 600 + 70 + 0"},{"label":"He wrote the hundreds wrong: it should be 700 + 70","value":"He wrote the hundreds wrong: it should be 700 + 70"},{"label":"He forgot the hundreds: it should be 60 + 7","value":"He forgot the hundreds: it should be 60 + 7"},{"label":"He forgot the ones: it should be 600 + 70 + 1","value":"He forgot the ones: it should be 600 + 70 + 1"}]},{"id":2,"text":"Write the number that has 8 hundreds, 3 ones, and 0 tens. Give its expanded form.","type":"multiple_choice","correct_answer":"803; 800 + 0 + 3","explanation":"8 hundreds + 0 tens + 3 ones = 803.","standard_code":"2.NBT.3","difficulty":3,"options":[{"label":"830; 800 + 30 + 0","value":"830; 800 + 30 + 0"},{"label":"380; 300 + 80 + 0","value":"380; 300 + 80 + 0"},{"label":"803; 800 + 0 + 3","value":"803; 800 + 0 + 3"},{"label":"308; 300 + 0 + 8","value":"308; 300 + 0 + 8"}]},{"id":3,"text":"Write 500 + 40 + 9 in words.","type":"multiple_choice","correct_answer":"Five hundred forty-nine","explanation":"549 = five hundred forty-nine.","standard_code":"2.NBT.3","difficulty":3,"options":[{"label":"Five hundred forty-nine","value":"Five hundred forty-nine"},{"label":"Five hundred ninety-four","value":"Five hundred ninety-four"},{"label":"Five hundred forty-eight","value":"Five hundred forty-eight"},{"label":"Five hundred forty","value":"Five hundred forty"}]},{"id":4,"text":"Write 999 in expanded form and in words.","type":"multiple_choice","correct_answer":"900 + 90 + 9; nine hundred ninety-nine","explanation":"9 hundreds + 9 tens + 9 ones.","standard_code":"2.NBT.3","difficulty":3,"options":[{"label":"900 + 9 + 9; nine hundred ninety","value":"900 + 9 + 9; nine hundred ninety"},{"label":"900 + 90 + 0; nine hundred ninety","value":"900 + 90 + 0; nine hundred ninety"},{"label":"990 + 9; nine hundred ninety-nine","value":"990 + 9; nine hundred ninety-nine"},{"label":"900 + 90 + 9; nine hundred ninety-nine","value":"900 + 90 + 9; nine hundred ninety-nine"}]},{"id":5,"text":"Is 700 + 30 + 5 the same as \"seven hundred thirty-five\"?","type":"multiple_choice","correct_answer":"Yes","explanation":"700 + 30 + 5 = 735 = seven hundred thirty-five. They all represent the same number.","standard_code":"2.NBT.3","difficulty":3,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]}]'::jsonb);

VALUES (2,'NBT','2.NBT.4','Compare Two Three-Digit Numbers Using >, =, < (Easy)','Students compare two three-digit numbers using > (greater than), = (equal to), or < (less than). Strategy: compare hundreds first. If equal, compare tens. If still equal, compare ones.','practice',1,10,85,'[{"id":1,"text":"Which is greater: 345 or 267?","type":"numeric","correct_answer":"345","explanation":"3 hundreds > 2 hundreds, so 345 > 267.","standard_code":"2.NBT.4","difficulty":1},{"id":2,"text":"Use >, =, or <: 500 __ 500","type":"multiple_choice","correct_answer":"=","explanation":"500 = 500. Same number.","standard_code":"2.NBT.4","difficulty":1,"options":[{"label":"=","value":"="},{"label":">","value":">"},{"label":"<","value":"<"},{"label":"+","value":"+"}]},{"id":3,"text":"Which is less: 728 or 782?","type":"numeric","correct_answer":"728","explanation":"Same hundreds (7). Compare tens: 2 < 8, so 728 < 782.","standard_code":"2.NBT.4","difficulty":1},{"id":4,"text":"Use >, =, or <: 600 __ 590","type":"multiple_choice","correct_answer":">","explanation":"6 hundreds > 5 hundreds, so 600 > 590.","standard_code":"2.NBT.4","difficulty":1,"options":[{"label":"=","value":"="},{"label":">","value":">"},{"label":"+","value":"+"},{"label":"<","value":"<"}]},{"id":5,"text":"Circle the greater number: 413 or 431.","type":"numeric","correct_answer":"431","explanation":"Same hundreds (4). Tens: 3 > 1, so 431 > 413.","standard_code":"2.NBT.4","difficulty":1}]'::jsonb);

VALUES (2,'NBT','2.NBT.4','Compare Two Three-Digit Numbers Using >, =, < (Medium)','Students compare two three-digit numbers using > (greater than), = (equal to), or < (less than). Strategy: compare hundreds first. If equal, compare tens. If still equal, compare ones.','practice',2,15,86,'[{"id":1,"text":"Use >, =, or <: 856 __ 865","type":"multiple_choice","correct_answer":"<","explanation":"Same hundreds (8), same tens (6). Ones: 5 < 6, so 856 < 865.","standard_code":"2.NBT.4","difficulty":2,"options":[{"label":"≠","value":"≠"},{"label":"<","value":"<"},{"label":">","value":">"},{"label":"=","value":"="}]},{"id":2,"text":"Order from least to greatest: 204, 402, 240.","type":"multiple_choice","correct_answer":"204, 240, 402","explanation":"Hundreds: 2 < 2 < 4. For 204 and 240, compare tens: 0 < 4, so 204 < 240 < 402.","standard_code":"2.NBT.4","difficulty":2,"options":[{"label":"204, 402, 240","value":"204, 402, 240"},{"label":"240, 204, 402","value":"240, 204, 402"},{"label":"204, 240, 402","value":"204, 240, 402"},{"label":"402, 240, 204","value":"402, 240, 204"}]},{"id":3,"text":"Use >, =, or <: 999 __ 1000","type":"multiple_choice","correct_answer":"<","explanation":"999 < 1000. A three-digit number is always less than 1000.","standard_code":"2.NBT.4","difficulty":2,"options":[{"label":"=","value":"="},{"label":"<","value":"<"},{"label":">","value":">"},{"label":">","value":">"}]},{"id":4,"text":"Which is greatest: 731, 713, 317?","type":"numeric","correct_answer":"731","explanation":"7 hundreds (731, 713) > 3 hundreds (317). Of 731 and 713: tens 3 > 1, so 731 is greatest.","standard_code":"2.NBT.4","difficulty":2},{"id":5,"text":"Use >, =, or <: 450 __ 450","type":"multiple_choice","correct_answer":"=","explanation":"450 = 450.","standard_code":"2.NBT.4","difficulty":2,"options":[{"label":"≠","value":"≠"},{"label":">","value":">"},{"label":"=","value":"="},{"label":"<","value":"<"}]}]'::jsonb);

VALUES (2,'NBT','2.NBT.4','Compare Two Three-Digit Numbers Using >, =, < (Hard)','Students compare two three-digit numbers using > (greater than), = (equal to), or < (less than). Strategy: compare hundreds first. If equal, compare tens. If still equal, compare ones.','practice',3,20,87,'[{"id":1,"text":"Name two numbers between 465 and 470.","type":"multiple_choice","correct_answer":"466, 467, 468, or 469","explanation":"Any two of 466, 467, 468, 469 are between 465 and 470.","standard_code":"2.NBT.4","difficulty":3,"options":[{"label":"468, 469, 470","value":"468, 469, 470"},{"label":"466, 467, 468, or 469","value":"466, 467, 468, or 469"},{"label":"465, 470","value":"465, 470"},{"label":"464, 465","value":"464, 465"}]},{"id":2,"text":"Is 30 tens greater than, equal to, or less than 300?","type":"multiple_choice","correct_answer":"Equal","explanation":"30 tens = 30 x 10 = 300. They are equal.","standard_code":"2.NBT.4","difficulty":3,"options":[{"label":"Less than","value":"Less than"},{"label":"Not equal","value":"Not equal"},{"label":"Equal","value":"Equal"},{"label":"Greater","value":"Greater"}]},{"id":3,"text":"A number has 7 in the hundreds place, 5 in the ones place, and is less than 710. What is it?","type":"numeric","correct_answer":"705","explanation":"705 = 7 hundreds + 0 tens + 5 ones. 705 < 710.","standard_code":"2.NBT.4","difficulty":3},{"id":4,"text":"Write three numbers that are greater than 850 and less than 900.","type":"multiple_choice","correct_answer":"Any three of 851 to 899, e.g., 860, 875, 899","explanation":"Any number between 851 and 899 works.","standard_code":"2.NBT.4","difficulty":3,"options":[{"label":"890, 891, 900","value":"890, 891, 900"},{"label":"850, 851, 852","value":"850, 851, 852"},{"label":"800, 810, 820","value":"800, 810, 820"},{"label":"Any three of 851 to 899, e.g., 860, 875, 899","value":"Any three of 851 to 899, e.g., 860, 875, 899"}]},{"id":5,"text":"Two numbers both have 4 hundreds and 2 tens. The first number has a ones digit 3 more than the second. The second number is 421. What is the first?","type":"numeric","correct_answer":"424","explanation":"Second = 421, ones digit = 1. First ones digit = 1 + 3 = 4. First number = 424.","standard_code":"2.NBT.4","difficulty":3}]'::jsonb);

VALUES (2,'NBT','2.NBT.5','Fluently Add and Subtract Within 100 (Easy)','Students fluently add and subtract within 100 using strategies based on place value, properties of operations, and the relationship between addition and subtraction. They may use concrete models or dr','practice',1,10,88,'[{"id":1,"text":"34 + 25 = ?","type":"numeric","correct_answer":"59","explanation":"Add tens: 30 + 20 = 50. Add ones: 4 + 5 = 9. Total: 59.","standard_code":"2.NBT.5","difficulty":1},{"id":2,"text":"67 - 43 = ?","type":"numeric","correct_answer":"24","explanation":"Subtract tens: 60 - 40 = 20. Subtract ones: 7 - 3 = 4. Total: 24.","standard_code":"2.NBT.5","difficulty":1},{"id":3,"text":"52 + 17 = ?","type":"numeric","correct_answer":"69","explanation":"50 + 10 = 60; 2 + 7 = 9; total: 69.","standard_code":"2.NBT.5","difficulty":1},{"id":4,"text":"85 - 32 = ?","type":"numeric","correct_answer":"53","explanation":"80 - 30 = 50; 5 - 2 = 3; total: 53.","standard_code":"2.NBT.5","difficulty":1},{"id":5,"text":"41 + 48 = ?","type":"numeric","correct_answer":"89","explanation":"40 + 40 = 80; 1 + 8 = 9; total: 89.","standard_code":"2.NBT.5","difficulty":1}]'::jsonb);

VALUES (2,'NBT','2.NBT.5','Fluently Add and Subtract Within 100 (Medium)','Students fluently add and subtract within 100 using strategies based on place value, properties of operations, and the relationship between addition and subtraction. They may use concrete models or dr','practice',2,15,89,'[{"id":1,"text":"47 + 35 = ?","type":"numeric","correct_answer":"82","explanation":"40 + 30 = 70; 7 + 5 = 12; 70 + 12 = 82.","standard_code":"2.NBT.5","difficulty":2},{"id":2,"text":"73 - 48 = ?","type":"numeric","correct_answer":"25","explanation":"73 - 40 = 33; 33 - 8 = 25.","standard_code":"2.NBT.5","difficulty":2},{"id":3,"text":"56 + 29 = ?","type":"numeric","correct_answer":"85","explanation":"56 + 4 = 60; 60 + 25 = 85. Or: 50 + 20 = 70; 6 + 9 = 15; 70 + 15 = 85.","standard_code":"2.NBT.5","difficulty":2},{"id":4,"text":"92 - 37 = ?","type":"numeric","correct_answer":"55","explanation":"92 - 30 = 62; 62 - 7 = 55.","standard_code":"2.NBT.5","difficulty":2},{"id":5,"text":"65 + 26 = ?","type":"numeric","correct_answer":"91","explanation":"65 + 5 = 70; 70 + 21 = 91. Or: 60 + 20 = 80; 5 + 6 = 11; 80 + 11 = 91.","standard_code":"2.NBT.5","difficulty":2}]'::jsonb);

VALUES (2,'NBT','2.NBT.5','Fluently Add and Subtract Within 100 (Hard)','Students fluently add and subtract within 100 using strategies based on place value, properties of operations, and the relationship between addition and subtraction. They may use concrete models or dr','practice',3,20,90,'[{"id":1,"text":"99 - 54 = ?","type":"numeric","correct_answer":"45","explanation":"99 - 50 = 49; 49 - 4 = 45.","standard_code":"2.NBT.5","difficulty":3},{"id":2,"text":"68 + 17 + 5 = ?","type":"numeric","correct_answer":"90","explanation":"68 + 17 = 85; 85 + 5 = 90.","standard_code":"2.NBT.5","difficulty":3},{"id":3,"text":"? - 38 = 45","type":"numeric","correct_answer":"83","explanation":"45 + 38 = 83. If ? - 38 = 45, then ? = 45 + 38 = 83.","standard_code":"2.NBT.5","difficulty":3},{"id":4,"text":"A baker made 54 rolls and 29 muffins. He sold 37 items. How many does he have left?","type":"numeric","correct_answer":"46","explanation":"54 + 29 = 83 total. 83 - 37 = 46.","standard_code":"2.NBT.5","difficulty":3},{"id":5,"text":"100 - 47 = ?","type":"numeric","correct_answer":"53","explanation":"100 - 40 = 60; 60 - 7 = 53. Or think: 47 + 53 = 100.","standard_code":"2.NBT.5","difficulty":3}]'::jsonb);

VALUES (2,'NBT','2.NBT.6','Add Up to Four Two-Digit Numbers (Easy)','Students add up to four two-digit numbers using place value strategies and properties of operations. Useful approaches include looking for pairs that make tens (associative property), adding left to r','practice',1,10,91,'[{"id":1,"text":"21 + 34 = ?","type":"numeric","correct_answer":"55","explanation":"20 + 30 = 50; 1 + 4 = 5; total: 55.","standard_code":"2.NBT.6","difficulty":1},{"id":2,"text":"43 + 26 = ?","type":"numeric","correct_answer":"69","explanation":"40 + 20 = 60; 3 + 6 = 9; total: 69.","standard_code":"2.NBT.6","difficulty":1},{"id":3,"text":"15 + 32 = ?","type":"numeric","correct_answer":"47","explanation":"10 + 30 = 40; 5 + 2 = 7; total: 47.","standard_code":"2.NBT.6","difficulty":1},{"id":4,"text":"62 + 17 = ?","type":"numeric","correct_answer":"79","explanation":"60 + 10 = 70; 2 + 7 = 9; total: 79.","standard_code":"2.NBT.6","difficulty":1},{"id":5,"text":"30 + 45 = ?","type":"numeric","correct_answer":"75","explanation":"30 + 40 = 70; 0 + 5 = 5; total: 75.","standard_code":"2.NBT.6","difficulty":1}]'::jsonb);

VALUES (2,'NBT','2.NBT.6','Add Up to Four Two-Digit Numbers (Medium)','Students add up to four two-digit numbers using place value strategies and properties of operations. Useful approaches include looking for pairs that make tens (associative property), adding left to r','practice',2,15,92,'[{"id":1,"text":"13 + 24 + 35 = ?","type":"numeric","correct_answer":"72","explanation":"13 + 24 = 37; 37 + 35 = 72.","standard_code":"2.NBT.6","difficulty":2},{"id":2,"text":"21 + 18 + 30 = ?","type":"numeric","correct_answer":"69","explanation":"21 + 30 = 51; 51 + 18 = 69. Or: 21 + 18 = 39; 39 + 30 = 69.","standard_code":"2.NBT.6","difficulty":2},{"id":3,"text":"45 + 12 + 23 = ?","type":"numeric","correct_answer":"80","explanation":"45 + 12 = 57; 57 + 23 = 80.","standard_code":"2.NBT.6","difficulty":2},{"id":4,"text":"16 + 14 + 20 = ?","type":"numeric","correct_answer":"50","explanation":"16 + 14 = 30 (they make a round number); 30 + 20 = 50.","standard_code":"2.NBT.6","difficulty":2},{"id":5,"text":"33 + 27 + 19 = ?","type":"numeric","correct_answer":"79","explanation":"33 + 27 = 60; 60 + 19 = 79.","standard_code":"2.NBT.6","difficulty":2}]'::jsonb);

VALUES (2,'NBT','2.NBT.6','Add Up to Four Two-Digit Numbers (Hard)','Students add up to four two-digit numbers using place value strategies and properties of operations. Useful approaches include looking for pairs that make tens (associative property), adding left to r','practice',3,20,93,'[{"id":1,"text":"14 + 26 + 33 + 17 = ?","type":"numeric","correct_answer":"90","explanation":"Look for pairs: 14 + 26 = 40; 33 + 17 = 50; 40 + 50 = 90.","standard_code":"2.NBT.6","difficulty":3},{"id":2,"text":"22 + 18 + 15 + 25 = ?","type":"numeric","correct_answer":"80","explanation":"22 + 18 = 40; 15 + 25 = 40; 40 + 40 = 80.","standard_code":"2.NBT.6","difficulty":3},{"id":3,"text":"31 + 19 + 28 + 12 = ?","type":"numeric","correct_answer":"90","explanation":"31 + 19 = 50; 28 + 12 = 40; 50 + 40 = 90.","standard_code":"2.NBT.6","difficulty":3},{"id":4,"text":"25 + 13 + 15 + 37 = ?","type":"numeric","correct_answer":"90","explanation":"25 + 15 = 40; 13 + 37 = 50; 40 + 50 = 90.","standard_code":"2.NBT.6","difficulty":3},{"id":5,"text":"A store sold 24, 16, 35, and 15 items on four days. How many items in total?","type":"numeric","correct_answer":"90","explanation":"24 + 16 = 40; 35 + 15 = 50; 40 + 50 = 90.","standard_code":"2.NBT.6","difficulty":3}]'::jsonb);

VALUES (2,'NBT','2.NBT.7','Add and Subtract Within 1000 (Easy)','Students add and subtract within 1000 using concrete models or drawings and place-value strategies, composing or decomposing hundreds, tens, and ones as needed. They relate these strategies to written','practice',1,10,94,'[{"id":1,"text":"234 + 152 = ?","type":"numeric","correct_answer":"386","explanation":"Hundreds: 200+100=300. Tens: 30+50=80. Ones: 4+2=6. Total: 386.","standard_code":"2.NBT.7","difficulty":1},{"id":2,"text":"567 - 234 = ?","type":"numeric","correct_answer":"333","explanation":"Hundreds: 500-200=300. Tens: 60-30=30. Ones: 7-4=3. Total: 333.","standard_code":"2.NBT.7","difficulty":1},{"id":3,"text":"400 + 300 = ?","type":"numeric","correct_answer":"700","explanation":"4 hundreds + 3 hundreds = 7 hundreds = 700.","standard_code":"2.NBT.7","difficulty":1},{"id":4,"text":"650 - 230 = ?","type":"numeric","correct_answer":"420","explanation":"600 - 200 = 400; 50 - 30 = 20; total: 420.","standard_code":"2.NBT.7","difficulty":1},{"id":5,"text":"125 + 364 = ?","type":"numeric","correct_answer":"489","explanation":"100+300=400; 20+60=80; 5+4=9; total: 489.","standard_code":"2.NBT.7","difficulty":1}]'::jsonb);

VALUES (2,'NBT','2.NBT.7','Add and Subtract Within 1000 (Medium)','Students add and subtract within 1000 using concrete models or drawings and place-value strategies, composing or decomposing hundreds, tens, and ones as needed. They relate these strategies to written','practice',2,15,95,'[{"id":1,"text":"347 + 285 = ?","type":"numeric","correct_answer":"632","explanation":"300+200=500; 40+80=120; 7+5=12; 500+120+12=632.","standard_code":"2.NBT.7","difficulty":2},{"id":2,"text":"724 - 368 = ?","type":"numeric","correct_answer":"356","explanation":"724 - 300 = 424; 424 - 60 = 364; 364 - 8 = 356.","standard_code":"2.NBT.7","difficulty":2},{"id":3,"text":"500 - 247 = ?","type":"numeric","correct_answer":"253","explanation":"500 - 200 = 300; 300 - 47 = 253.","standard_code":"2.NBT.7","difficulty":2},{"id":4,"text":"463 + 179 = ?","type":"numeric","correct_answer":"642","explanation":"400+100=500; 60+70=130; 3+9=12; 500+130+12=642.","standard_code":"2.NBT.7","difficulty":2},{"id":5,"text":"800 - 356 = ?","type":"numeric","correct_answer":"444","explanation":"800 - 300 = 500; 500 - 56 = 444.","standard_code":"2.NBT.7","difficulty":2}]'::jsonb);

VALUES (2,'NBT','2.NBT.7','Add and Subtract Within 1000 (Hard)','Students add and subtract within 1000 using concrete models or drawings and place-value strategies, composing or decomposing hundreds, tens, and ones as needed. They relate these strategies to written','practice',3,20,96,'[{"id":1,"text":"587 + 248 = ?","type":"numeric","correct_answer":"835","explanation":"500+200=700; 80+40=120; 7+8=15; 700+120+15=835.","standard_code":"2.NBT.7","difficulty":3},{"id":2,"text":"1000 - 673 = ?","type":"numeric","correct_answer":"327","explanation":"1000 - 600 = 400; 400 - 73 = 327.","standard_code":"2.NBT.7","difficulty":3},{"id":3,"text":"A school has 345 boys and 478 girls. How many students in all?","type":"numeric","correct_answer":"823","explanation":"300+400=700; 40+70=110; 5+8=13; 700+110+13=823.","standard_code":"2.NBT.7","difficulty":3},{"id":4,"text":"902 - 456 = ?","type":"numeric","correct_answer":"446","explanation":"902 - 400 = 502; 502 - 56 = 446.","standard_code":"2.NBT.7","difficulty":3},{"id":5,"text":"A bookstore had 750 books. They sold 263 and received 145 more. How many now?","type":"numeric","correct_answer":"632","explanation":"750 - 263 = 487; 487 + 145 = 632.","standard_code":"2.NBT.7","difficulty":3}]'::jsonb);

VALUES (2,'NBT','2.NBT.8','Mentally Add or Subtract 10 or 100 (Numbers 100-900) (Easy)','Students mentally add or subtract 10 and 100 to/from any number 100–900. Adding 10 increases only the tens digit by 1; adding 100 increases only the hundreds digit by 1. The other digits stay the same','practice',1,10,97,'[{"id":1,"text":"What is 10 more than 250?","type":"numeric","correct_answer":"260","explanation":"250 + 10 = 260. Only the tens digit changes: 5 becomes 6.","standard_code":"2.NBT.8","difficulty":1},{"id":2,"text":"What is 100 more than 300?","type":"numeric","correct_answer":"400","explanation":"300 + 100 = 400. Only the hundreds digit changes: 3 becomes 4.","standard_code":"2.NBT.8","difficulty":1},{"id":3,"text":"What is 10 less than 480?","type":"numeric","correct_answer":"470","explanation":"480 - 10 = 470. Tens digit: 8 becomes 7.","standard_code":"2.NBT.8","difficulty":1},{"id":4,"text":"What is 100 less than 700?","type":"numeric","correct_answer":"600","explanation":"700 - 100 = 600. Hundreds digit: 7 becomes 6.","standard_code":"2.NBT.8","difficulty":1},{"id":5,"text":"530 + 10 = ?","type":"numeric","correct_answer":"540","explanation":"Add 10: tens digit increases by 1. 3 becomes 4. Answer: 540.","standard_code":"2.NBT.8","difficulty":1}]'::jsonb);

VALUES (2,'NBT','2.NBT.8','Mentally Add or Subtract 10 or 100 (Numbers 100-900) (Medium)','Students mentally add or subtract 10 and 100 to/from any number 100–900. Adding 10 increases only the tens digit by 1; adding 100 increases only the hundreds digit by 1. The other digits stay the same','practice',2,15,98,'[{"id":1,"text":"Start at 450. Add 100. Then subtract 10. Where are you?","type":"numeric","correct_answer":"540","explanation":"450 + 100 = 550; 550 - 10 = 540.","standard_code":"2.NBT.8","difficulty":2},{"id":2,"text":"620 - 100 + 10 = ?","type":"numeric","correct_answer":"530","explanation":"620 - 100 = 520; 520 + 10 = 530.","standard_code":"2.NBT.8","difficulty":2},{"id":3,"text":"What is 100 more than 10 less than 350?","type":"numeric","correct_answer":"440","explanation":"350 - 10 = 340; 340 + 100 = 440.","standard_code":"2.NBT.8","difficulty":2},{"id":4,"text":"Fill in the pattern: 200, 300, 400, __ (adding 100 each time).","type":"numeric","correct_answer":"500","explanation":"400 + 100 = 500.","standard_code":"2.NBT.8","difficulty":2},{"id":5,"text":"Fill in: 780, 770, 760, __ (subtracting 10).","type":"numeric","correct_answer":"750","explanation":"760 - 10 = 750.","standard_code":"2.NBT.8","difficulty":2}]'::jsonb);

VALUES (2,'NBT','2.NBT.8','Mentally Add or Subtract 10 or 100 (Numbers 100-900) (Hard)','Students mentally add or subtract 10 and 100 to/from any number 100–900. Adding 10 increases only the tens digit by 1; adding 100 increases only the hundreds digit by 1. The other digits stay the same','practice',3,20,99,'[{"id":1,"text":"Start at 190. Add 10. What happens?","type":"numeric","correct_answer":"200","explanation":"190 + 10 = 200. The tens \"overflow\" and create a new hundred.","standard_code":"2.NBT.8","difficulty":3},{"id":2,"text":"What is 100 less than 105?","type":"numeric","correct_answer":"5","explanation":"105 - 100 = 5. The hundreds digit goes from 1 to 0.","standard_code":"2.NBT.8","difficulty":3},{"id":3,"text":"890 + 100 = ?","type":"numeric","correct_answer":"990","explanation":"890 + 100 = 990. Hundreds: 8 becomes 9.","standard_code":"2.NBT.8","difficulty":3},{"id":4,"text":"Start at 500. Add 100 three times. Then subtract 10 twice. Where are you?","type":"numeric","correct_answer":"780","explanation":"500 + 300 = 800; 800 - 20 = 780.","standard_code":"2.NBT.8","difficulty":3},{"id":5,"text":"A pattern: 850, 750, 650, __. What comes next? What kind of skip-count is this?","type":"multiple_choice","correct_answer":"550; subtracting 100","explanation":"850-100=750-100=650-100=550. This is counting back by 100s.","standard_code":"2.NBT.8","difficulty":3,"options":[{"label":"750; subtracting 200","value":"750; subtracting 200"},{"label":"650; subtracting 50","value":"650; subtracting 50"},{"label":"450; adding 100","value":"450; adding 100"},{"label":"550; subtracting 100","value":"550; subtracting 100"}]}]'::jsonb);

VALUES (2,'NBT','2.NBT.9','Explain Why Addition and Subtraction Strategies Work (Easy)','Students explain why their addition and subtraction strategies work using place value and properties of operations. They can articulate why decomposing, making tens, compensation, and using the commut','practice',1,10,100,'[{"id":1,"text":"Why does 37 + 20 = 57? Explain using place value.","type":"multiple_choice","correct_answer":"Adding 20 adds 2 tens: 30 + 20 = 50, plus 7 ones = 57.","explanation":"Only the tens digit changes when you add a multiple of 10. The ones digit stays the same.","standard_code":"2.NBT.9","difficulty":1,"options":[{"label":"The 20 is added to just the tens, making 50 + 7 = 57.","value":"The 20 is added to just the tens, making 50 + 7 = 57."},{"label":"You add 37 + 20 by combining all the digits to get 57.","value":"You add 37 + 20 by combining all the digits to get 57."},{"label":"Adding 20 adds 2 tens: 30 + 20 = 50, plus 7 ones = 57.","value":"Adding 20 adds 2 tens: 30 + 20 = 50, plus 7 ones = 57."},{"label":"Adding 2 tens to 37 gives 57, so you add the tens place and keep the ones.","value":"Adding 2 tens to 37 gives 57, so you add the tens place and keep the ones."}]},{"id":2,"text":"Why is 8 + 5 the same as 5 + 8?","type":"multiple_choice","correct_answer":"Commutative property: you can add numbers in any order.","explanation":"The sum does not change when you switch the order of the addends.","standard_code":"2.NBT.9","difficulty":1,"options":[{"label":"You get the same answer because both numbers have the same digits.","value":"You get the same answer because both numbers have the same digits."},{"label":"Commutative property: you can add numbers in any order.","value":"Commutative property: you can add numbers in any order."},{"label":"The order does not matter because addition always works the same way.","value":"The order does not matter because addition always works the same way."},{"label":"Additive property: adding the same number twice gives the same result.","value":"Additive property: adding the same number twice gives the same result."}]},{"id":3,"text":"Explain why 46 - 10 = 36.","type":"multiple_choice","correct_answer":"Subtracting 10 removes 1 ten: 4 tens - 1 ten = 3 tens; ones stay the same.","explanation":"Only the tens digit changes when you subtract 10.","standard_code":"2.NBT.9","difficulty":1,"options":[{"label":"Subtracting 10 removes 1 ten: 4 tens - 1 ten = 3 tens; add the ones back.","value":"Subtracting 10 removes 1 ten: 4 tens - 1 ten = 3 tens; add the ones back."},{"label":"Subtracting tens from the tens place gives 3, and the ones stay 6.","value":"Subtracting tens from the tens place gives 3, and the ones stay 6."},{"label":"The ones equal 6 and the tens equal 3, so 36 is correct.","value":"The ones equal 6 and the tens equal 3, so 36 is correct."},{"label":"Subtracting 10 removes 1 ten: 4 tens - 1 ten = 3 tens; ones stay the same.","value":"Subtracting 10 removes 1 ten: 4 tens - 1 ten = 3 tens; ones stay the same."}]},{"id":4,"text":"Why does grouping 4 + 6 first help you find 4 + 6 + 8?","type":"multiple_choice","correct_answer":"4 + 6 = 10, and 10 + 8 = 18 is easy to add.","explanation":"Associative property: group addends that make ten to make the calculation easier.","standard_code":"2.NBT.9","difficulty":1,"options":[{"label":"Grouping makes the numbers smaller so they are easier to multiply.","value":"Grouping makes the numbers smaller so they are easier to multiply."},{"label":"4 + 8 = 12, and 12 + 6 = 18 is easier to add.","value":"4 + 8 = 12, and 12 + 6 = 18 is easier to add."},{"label":"4 + 6 = 10, and 10 + 8 = 18 is easy to add.","value":"4 + 6 = 10, and 10 + 8 = 18 is easy to add."},{"label":"It helps you skip counting by tens instead of ones.","value":"It helps you skip counting by tens instead of ones."}]},{"id":5,"text":"Why is 50 - 30 = 20? Use place value to explain.","type":"multiple_choice","correct_answer":"50 = 5 tens, 30 = 3 tens. 5 tens - 3 tens = 2 tens = 20.","explanation":"Subtracting tens only changes the tens digit. The result is still in tens.","standard_code":"2.NBT.9","difficulty":1,"options":[{"label":"50 - 30 = 20 because you subtract the ones first.","value":"50 - 30 = 20 because you subtract the ones first."},{"label":"You can count up from 30 to 50 and get 20.","value":"You can count up from 30 to 50 and get 20."},{"label":"50 = 5 tens, 30 = 3 tens. 5 tens - 3 tens = 2 tens = 20.","value":"50 = 5 tens, 30 = 3 tens. 5 tens - 3 tens = 2 tens = 20."},{"label":"50 = 5 ones, 30 = 3 ones. 5 ones - 3 ones = 2 ones = 20.","value":"50 = 5 ones, 30 = 3 ones. 5 ones - 3 ones = 2 ones = 20."}]}]'::jsonb);

VALUES (2,'NBT','2.NBT.9','Explain Why Addition and Subtraction Strategies Work (Medium)','Students explain why their addition and subtraction strategies work using place value and properties of operations. They can articulate why decomposing, making tens, compensation, and using the commut','practice',2,15,101,'[{"id":1,"text":"Explain why 78 - 40 = 38 using place value.","type":"multiple_choice","correct_answer":"40 = 4 tens. 7 tens - 4 tens = 3 tens. Ones digit stays 8. Result: 38.","explanation":"Subtracting a multiple of 10 changes only the tens digit.","standard_code":"2.NBT.9","difficulty":2,"options":[{"label":"70 - 40 = 30, and keep the 8, so the answer is 30.","value":"70 - 40 = 30, and keep the 8, so the answer is 30."},{"label":"78 = 7 tens 8 ones. 40 = 4 tens. Add them to get 118.","value":"78 = 7 tens 8 ones. 40 = 4 tens. Add them to get 118."},{"label":"Subtract the 8 from 40 first, then subtract from 70.","value":"Subtract the 8 from 40 first, then subtract from 70."},{"label":"40 = 4 tens. 7 tens - 4 tens = 3 tens. Ones digit stays 8. Result: 38.","value":"40 = 4 tens. 7 tens - 4 tens = 3 tens. Ones digit stays 8. Result: 38."}]},{"id":2,"text":"Why does decomposing 9 + 7 as (9 + 1) + 6 = 16 work?","type":"multiple_choice","correct_answer":"Associative property: group 9+1=10 first, then 10+6=16. 7 is decomposed as 1+6.","explanation":"We can regroup numbers without changing the sum.","standard_code":"2.NBT.9","difficulty":2,"options":[{"label":"Associative property: group 9+1=10 first, then 10+6=16. 7 is decomposed as 1+6.","value":"Associative property: group 9+1=10 first, then 10+6=16. 7 is decomposed as 1+6."},{"label":"It works because you can break apart any two numbers.","value":"It works because you can break apart any two numbers."},{"label":"Decomposing means making the numbers bigger so addition is easier.","value":"Decomposing means making the numbers bigger so addition is easier."},{"label":"It works because 9 + 7 becomes 16 no matter how you group it.","value":"It works because 9 + 7 becomes 16 no matter how you group it."}]},{"id":3,"text":"Explain why 63 + 24 = 87 by adding tens and ones separately.","type":"multiple_choice","correct_answer":"Tens: 60+20=80. Ones: 3+4=7. 80+7=87.","explanation":"Place value allows us to add like units: tens with tens, ones with ones.","standard_code":"2.NBT.9","difficulty":2,"options":[{"label":"Tens: 60+20=80. Ones: 3+4=7. 80+7=87.","value":"Tens: 60+20=80. Ones: 3+4=7. 80+7=87."},{"label":"Add ones: 3+4=7. Add tens: 60+20=80. 7+80=87.","value":"Add ones: 3+4=7. Add tens: 60+20=80. 7+80=87."},{"label":"63 and 24 both have tens and ones, so add them together.","value":"63 and 24 both have tens and ones, so add them together."},{"label":"Add the first digits: 6+2=8, then the last digits: 3+4=7, so 87.","value":"Add the first digits: 6+2=8, then the last digits: 3+4=7, so 87."}]},{"id":4,"text":"Why is 100 - 47 = 53? Show a strategy and explain.","type":"multiple_choice","correct_answer":"100 - 40 = 60; 60 - 7 = 53. Or: think 47 + 53 = 100.","explanation":"Subtracting in parts or using the relationship between addition and subtraction are both valid.","standard_code":"2.NBT.9","difficulty":2,"options":[{"label":"Count backwards from 100 to 47 on your fingers.","value":"Count backwards from 100 to 47 on your fingers."},{"label":"100 - 40 = 60; 60 - 7 = 53. Or: think 47 + 53 = 100.","value":"100 - 40 = 60; 60 - 7 = 53. Or: think 47 + 53 = 100."},{"label":"100 - 50 = 50, then add 3 to get 53.","value":"100 - 50 = 50, then add 3 to get 53."},{"label":"100 - 47 = 53 because the digits add up to that number.","value":"100 - 47 = 53 because the digits add up to that number."}]},{"id":5,"text":"Why is (34 + 16) + 22 easier than 34 + (16 + 22)?","type":"multiple_choice","correct_answer":"34 + 16 = 50, a round number. Then 50 + 22 = 72 is easy.","explanation":"Associative property lets us choose any grouping. Grouping addends that make a round number simplifies the calculation.","standard_code":"2.NBT.9","difficulty":2,"options":[{"label":"50 + 22 is easier because 50 is a round number.","value":"50 + 22 is easier because 50 is a round number."},{"label":"34 + 16 = 50, a round number. Then 50 + 22 = 72 is easy.","value":"34 + 16 = 50, a round number. Then 50 + 22 = 72 is easy."},{"label":"34 + 16 is easier because both numbers are smaller.","value":"34 + 16 is easier because both numbers are smaller."},{"label":"16 + 22 = 38, which is harder than 34 + 50.","value":"16 + 22 = 38, which is harder than 34 + 50."}]}]'::jsonb);

VALUES (2,'NBT','2.NBT.9','Explain Why Addition and Subtraction Strategies Work (Hard)','Students explain why their addition and subtraction strategies work using place value and properties of operations. They can articulate why decomposing, making tens, compensation, and using the commut','practice',3,20,102,'[{"id":1,"text":"Tom said 400 + 90 + 5 = 495. Is he right? Explain.","type":"multiple_choice","correct_answer":"Yes","explanation":"400 = 4 hundreds, 90 = 9 tens, 5 = 5 ones. 495 is the correct number.","standard_code":"2.NBT.9","difficulty":3,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]},{"id":2,"text":"Amy solved 82 - 37 by doing 82 - 40 + 3 = 45. Why does this work?","type":"multiple_choice","correct_answer":"She over-subtracted by 3, then added 3 back. This is the compensation strategy.","explanation":"82 - 40 = 42; 42 + 3 = 45. Subtracting too much then compensating gives the same answer.","standard_code":"2.NBT.9","difficulty":3,"options":[{"label":"She over-subtracted by 3, then added 3 back. This is the compensation strategy.","value":"She over-subtracted by 3, then added 3 back. This is the compensation strategy."},{"label":"Adding 3 at the end makes the answer larger and correct.","value":"Adding 3 at the end makes the answer larger and correct."},{"label":"This strategy works by breaking 37 into 30 and 7 parts.","value":"This strategy works by breaking 37 into 30 and 7 parts."},{"label":"She subtracted too much, so subtracting 3 more fixes it.","value":"She subtracted too much, so subtracting 3 more fixes it."}]},{"id":3,"text":"Explain why 136 + 248 = 384 using place value.","type":"multiple_choice","correct_answer":"Hundreds: 100+200=300. Tens: 30+40=70. Ones: 6+8=14. 300+70+14=384.","explanation":"Add each place separately. Ones: 14 = 1 ten + 4 ones. Regroup: 300 + 80 + 4 = 384.","standard_code":"2.NBT.9","difficulty":3,"options":[{"label":"Add each digit: 1+2=3, 3+4=7, 6+8=14. Put them together to get 3,714.","value":"Add each digit: 1+2=3, 3+4=7, 6+8=14. Put them together to get 3,714."},{"label":"Hundreds: 100+200=300. Tens: 30+40=70. Ones: 6+8=14. 300+70+14=384.","value":"Hundreds: 100+200=300. Tens: 30+40=70. Ones: 6+8=14. 300+70+14=384."},{"label":"Hundreds: 100+200=300. Tens: 3+4=7. Ones: 6+8=14. 300+7+14=321.","value":"Hundreds: 100+200=300. Tens: 3+4=7. Ones: 6+8=14. 300+7+14=321."},{"label":"Hundreds: 100+200=300. Tens: 30+40=70. Ones: 6+8=14. 300+70+4=374.","value":"Hundreds: 100+200=300. Tens: 30+40=70. Ones: 6+8=14. 300+70+4=374."}]},{"id":4,"text":"Is 56 + 27 the same as 56 + 30 - 3? Explain why.","type":"multiple_choice","correct_answer":"Yes","explanation":"27 = 30 - 3. So 56 + 27 = 56 + 30 - 3 = 86 - 3 = 83. This is the compensation strategy.","standard_code":"2.NBT.9","difficulty":3,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]},{"id":5,"text":"Explain why counting back on a number line gives the same result as column subtraction.","type":"multiple_choice","correct_answer":"Both methods remove the same value from the starting number.","explanation":"Subtraction always means removing a quantity. The method changes, but the amount removed is the same, so the result is the same.","standard_code":"2.NBT.9","difficulty":3,"options":[{"label":"Column subtraction is faster because you write down numbers.","value":"Column subtraction is faster because you write down numbers."},{"label":"They give different answers depending on which method is easier to use.","value":"They give different answers depending on which method is easier to use."},{"label":"Number lines work by counting, while columns use place value instead.","value":"Number lines work by counting, while columns use place value instead."},{"label":"Both methods remove the same value from the starting number.","value":"Both methods remove the same value from the starting number."}]}]'::jsonb);

VALUES (2,'MD','2.MD.1','Measure Length Using Appropriate Tools (Easy)','Students measure the length of objects by selecting and using appropriate tools: rulers (inches or centimeters), yardsticks, meter sticks, and measuring tapes. They measure in both customary (inches, ','practice',1,10,103,'[{"id":1,"text":"Which tool would you use to measure a pencil: a ruler or a yardstick?","type":"multiple_choice","correct_answer":"A ruler","explanation":"A pencil is short (around 7 inches), so a ruler is the most appropriate tool.","standard_code":"2.MD.1","difficulty":1,"options":[{"label":"A ruler","value":"A ruler"},{"label":"A measuring tape","value":"A measuring tape"},{"label":"A meter stick","value":"A meter stick"},{"label":"A yardstick","value":"A yardstick"}]},{"id":2,"text":"A book is about 9 inches long. What unit is being used?","type":"multiple_choice","correct_answer":"Inches","explanation":"Inches are a customary unit used for shorter objects.","standard_code":"2.MD.1","difficulty":1,"options":[{"label":"Yards","value":"Yards"},{"label":"Inches","value":"Inches"},{"label":"Centimeters","value":"Centimeters"},{"label":"Feet","value":"Feet"}]},{"id":3,"text":"What unit would you use to measure the length of a room: inches or feet?","type":"multiple_choice","correct_answer":"Feet","explanation":"A room is too large for inches; feet are more appropriate.","standard_code":"2.MD.1","difficulty":1,"options":[{"label":"Inches","value":"Inches"},{"label":"Meters","value":"Meters"},{"label":"Feet","value":"Feet"},{"label":"Centimeters","value":"Centimeters"}]},{"id":4,"text":"A pencil measures 17 cm. What unit is being used?","type":"multiple_choice","correct_answer":"Centimeters","explanation":"Centimeters (cm) are a metric unit for shorter objects.","standard_code":"2.MD.1","difficulty":1,"options":[{"label":"Meters","value":"Meters"},{"label":"Feet","value":"Feet"},{"label":"Centimeters","value":"Centimeters"},{"label":"Inches","value":"Inches"}]},{"id":5,"text":"Would you use a ruler or a meter stick to measure a hallway?","type":"multiple_choice","correct_answer":"Meter stick (or measuring tape)","explanation":"A hallway is long; a meter stick or measuring tape is more appropriate.","standard_code":"2.MD.1","difficulty":1,"options":[{"label":"A yardstick","value":"A yardstick"},{"label":"A ruler","value":"A ruler"},{"label":"Meter stick (or measuring tape)","value":"Meter stick (or measuring tape)"},{"label":"A tape measure","value":"A tape measure"}]}]'::jsonb);

VALUES (2,'MD','2.MD.1','Measure Length Using Appropriate Tools (Medium)','Students measure the length of objects by selecting and using appropriate tools: rulers (inches or centimeters), yardsticks, meter sticks, and measuring tapes. They measure in both customary (inches, ','practice',2,15,104,'[{"id":1,"text":"A marker is 14 cm long. A crayon is 9 cm long. Which is longer and by how much?","type":"multiple_choice","correct_answer":"The marker; by 5 cm","explanation":"14 - 9 = 5 cm. The marker is longer.","standard_code":"2.MD.1","difficulty":2,"options":[{"label":"The crayon; by 8 cm","value":"The crayon; by 8 cm"},{"label":"The marker; by 26 cm","value":"The marker; by 26 cm"},{"label":"The marker; by 5 cm","value":"The marker; by 5 cm"},{"label":"The marker; by 6 cm","value":"The marker; by 6 cm"}]},{"id":2,"text":"You measure a hallway in meters and get 12 meters. How many centimeters is that?","type":"numeric","correct_answer":"1200","explanation":"1 meter = 100 cm. 12 x 100 = 1200 cm.","standard_code":"2.MD.1","difficulty":2},{"id":3,"text":"A fish is 6 inches. A book is 8 inches. How much longer is the book?","type":"multiple_choice","correct_answer":"2 inches","explanation":"8 - 6 = 2 inches.","standard_code":"2.MD.1","difficulty":2,"options":[{"label":"6 inches","value":"6 inches"},{"label":"14 inches","value":"14 inches"},{"label":"1 inch","value":"1 inch"},{"label":"2 inches","value":"2 inches"}]},{"id":4,"text":"Which unit would you use to measure a swimming pool: feet or inches?","type":"multiple_choice","correct_answer":"Feet (or yards)","explanation":"A pool is very long. Feet or yards are more appropriate than inches.","standard_code":"2.MD.1","difficulty":2,"options":[{"label":"Inches","value":"Inches"},{"label":"Centimeters","value":"Centimeters"},{"label":"Feet (or yards)","value":"Feet (or yards)"},{"label":"Meters","value":"Meters"}]},{"id":5,"text":"A leaf measures between 3 and 4 cm on a ruler. About how long is it?","type":"multiple_choice","correct_answer":"About 3.5 cm (or between 3 and 4 cm)","explanation":"If the leaf falls between 3 and 4 cm, it is approximately 3.5 cm.","standard_code":"2.MD.1","difficulty":2,"options":[{"label":"About 2.5 cm","value":"About 2.5 cm"},{"label":"About 3 cm","value":"About 3 cm"},{"label":"About 3.5 cm (or between 3 and 4 cm)","value":"About 3.5 cm (or between 3 and 4 cm)"},{"label":"About 7 cm","value":"About 7 cm"}]}]'::jsonb);

VALUES (2,'MD','2.MD.1','Measure Length Using Appropriate Tools (Hard)','Students measure the length of objects by selecting and using appropriate tools: rulers (inches or centimeters), yardsticks, meter sticks, and measuring tapes. They measure in both customary (inches, ','practice',3,20,105,'[{"id":1,"text":"About how many feet long is a car?","type":"multiple_choice","correct_answer":"About 12 to 15 feet","explanation":"A typical car is 12-15 feet long.","standard_code":"2.MD.1","difficulty":3,"options":[{"label":"About 20 to 25 feet","value":"About 20 to 25 feet"},{"label":"About 12 to 15 feet","value":"About 12 to 15 feet"},{"label":"About 5 to 6 feet","value":"About 5 to 6 feet"},{"label":"About 8 to 10 feet","value":"About 8 to 10 feet"}]},{"id":2,"text":"A table is 3 feet long. How many inches is that? (1 foot = 12 inches)","type":"multiple_choice","correct_answer":"36 inches","explanation":"3 x 12 = 36 inches.","standard_code":"2.MD.1","difficulty":3,"options":[{"label":"24 inches","value":"24 inches"},{"label":"36 inches","value":"36 inches"},{"label":"12 inches","value":"12 inches"},{"label":"48 inches","value":"48 inches"}]},{"id":3,"text":"You measure a garden with a yardstick and get 5 yards. How many feet is that? (1 yard = 3 feet)","type":"multiple_choice","correct_answer":"15 feet","explanation":"5 x 3 = 15 feet.","standard_code":"2.MD.1","difficulty":3,"options":[{"label":"5 feet","value":"5 feet"},{"label":"20 feet","value":"20 feet"},{"label":"12 feet","value":"12 feet"},{"label":"15 feet","value":"15 feet"}]},{"id":4,"text":"Estimate: Is a door about 2 meters, 20 meters, or 200 meters tall?","type":"multiple_choice","correct_answer":"About 2 meters","explanation":"A standard door is about 2 meters (approximately 6-7 feet) tall.","standard_code":"2.MD.1","difficulty":3,"options":[{"label":"About 0.2 meters","value":"About 0.2 meters"},{"label":"About 2 meters","value":"About 2 meters"},{"label":"About 200 meters","value":"About 200 meters"},{"label":"About 20 meters","value":"About 20 meters"}]},{"id":5,"text":"A student measures a desk as 24 inches. Her friend says it is 2 feet. Are they both correct?","type":"multiple_choice","correct_answer":"Yes","explanation":"24 inches = 2 feet (1 foot = 12 inches, 2 x 12 = 24). Both are correct.","standard_code":"2.MD.1","difficulty":3,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]}]'::jsonb);

VALUES (2,'MD','2.MD.2','Measure with Different Units; Relate Measurements to Unit Size (Easy)','Students measure the same object using different units and observe the relationship: smaller units produce a larger number, larger units produce a smaller number. The length of the object does not cha','practice',1,10,106,'[{"id":1,"text":"A book is 24 cm or 9 inches. Which unit gives a larger number?","type":"multiple_choice","correct_answer":"Centimeters (24)","explanation":"Centimeters are smaller units, so more of them are needed. The number is larger.","standard_code":"2.MD.2","difficulty":1,"options":[{"label":"They are the same","value":"They are the same"},{"label":"Meters (100)","value":"Meters (100)"},{"label":"Centimeters (24)","value":"Centimeters (24)"},{"label":"Inches (9)","value":"Inches (9)"}]},{"id":2,"text":"You measure a pencil and get 16 cm or about 6 inches. Which unit is smaller?","type":"multiple_choice","correct_answer":"Centimeters","explanation":"Smaller units need more of them. 16 cm > 6 in shows cm are smaller.","standard_code":"2.MD.2","difficulty":1,"options":[{"label":"Centimeters","value":"Centimeters"},{"label":"Meters","value":"Meters"},{"label":"They are the same","value":"They are the same"},{"label":"Inches","value":"Inches"}]},{"id":3,"text":"A table is 3 feet or 36 inches long. Which unit gives a smaller number?","type":"multiple_choice","correct_answer":"Feet (3)","explanation":"Larger units produce smaller numbers. 3 < 36.","standard_code":"2.MD.2","difficulty":1,"options":[{"label":"Centimeters (100)","value":"Centimeters (100)"},{"label":"Yards (1)","value":"Yards (1)"},{"label":"Inches (12)","value":"Inches (12)"},{"label":"Feet (3)","value":"Feet (3)"}]},{"id":4,"text":"If you measure a room in meters and get 5, what would happen to the number if you used centimeters?","type":"multiple_choice","correct_answer":"It would be much larger (500 cm)","explanation":"1 meter = 100 cm. 5 meters = 500 cm. Smaller units give a larger number.","standard_code":"2.MD.2","difficulty":1,"options":[{"label":"It would be much larger (500 cm)","value":"It would be much larger (500 cm)"},{"label":"It would be much smaller (0.5 cm)","value":"It would be much smaller (0.5 cm)"},{"label":"It would be slightly larger (6 cm)","value":"It would be slightly larger (6 cm)"},{"label":"It would stay about the same","value":"It would stay about the same"}]},{"id":5,"text":"A ribbon is 2 feet or 24 inches. Is this the same length?","type":"multiple_choice","correct_answer":"Yes","explanation":"2 feet = 24 inches. Different numbers, different units, same length.","standard_code":"2.MD.2","difficulty":1,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]}]'::jsonb);

VALUES (2,'MD','2.MD.2','Measure with Different Units; Relate Measurements to Unit Size (Medium)','Students measure the same object using different units and observe the relationship: smaller units produce a larger number, larger units produce a smaller number. The length of the object does not cha','practice',2,15,107,'[{"id":1,"text":"An object measures 4 large blocks or 8 small blocks. How many small blocks equal 1 large block?","type":"multiple_choice","correct_answer":"2 small blocks","explanation":"4 large = 8 small, so 1 large = 2 small.","standard_code":"2.MD.2","difficulty":2,"options":[{"label":"4 small blocks","value":"4 small blocks"},{"label":"2 small blocks","value":"2 small blocks"},{"label":"1 small block","value":"1 small block"},{"label":"0.5 small blocks","value":"0.5 small blocks"}]},{"id":2,"text":"A snake is 3 feet long. Measured in yards (1 yard = 3 feet), how many yards?","type":"multiple_choice","correct_answer":"1 yard","explanation":"3 feet = 1 yard.","standard_code":"2.MD.2","difficulty":2,"options":[{"label":"3 yards","value":"3 yards"},{"label":"1 yard","value":"1 yard"},{"label":"0.5 yards","value":"0.5 yards"},{"label":"9 yards","value":"9 yards"}]},{"id":3,"text":"Would you get a higher or lower number measuring a room in inches versus yards?","type":"multiple_choice","correct_answer":"Higher in inches","explanation":"Inches are smaller units; you need more of them to cover the same length.","standard_code":"2.MD.2","difficulty":2,"options":[{"label":"Lower in inches","value":"Lower in inches"},{"label":"Higher in inches","value":"Higher in inches"},{"label":"The same in both","value":"The same in both"},{"label":"It depends on the size","value":"It depends on the size"}]},{"id":4,"text":"A stick is 10 cm or about 4 inches. About how many centimeters are in 1 inch?","type":"multiple_choice","correct_answer":"About 2.5 cm","explanation":"10 cm / 4 inches = 2.5 cm per inch.","standard_code":"2.MD.2","difficulty":2,"options":[{"label":"About 2.5 cm","value":"About 2.5 cm"},{"label":"About 4 cm","value":"About 4 cm"},{"label":"About 10 cm","value":"About 10 cm"},{"label":"About 1 cm","value":"About 1 cm"}]},{"id":5,"text":"Jake measured a table as 60 cm. Lisa measured the same table as 2 feet. Can both be right?","type":"multiple_choice","correct_answer":"Approximately yes (60 cm is about 2 feet)","explanation":"1 foot is about 30 cm, so 2 feet is about 60 cm. Both measurements are approximately correct.","standard_code":"2.MD.2","difficulty":2,"options":[{"label":"No, they are very different","value":"No, they are very different"},{"label":"Approximately no (60 cm is about 3 feet)","value":"Approximately no (60 cm is about 3 feet)"},{"label":"Approximately yes (60 cm is about 2 feet)","value":"Approximately yes (60 cm is about 2 feet)"},{"label":"No, 60 cm is much larger","value":"No, 60 cm is much larger"}]}]'::jsonb);

VALUES (2,'MD','2.MD.2','Measure with Different Units; Relate Measurements to Unit Size (Hard)','Students measure the same object using different units and observe the relationship: smaller units produce a larger number, larger units produce a smaller number. The length of the object does not cha','practice',3,20,108,'[{"id":1,"text":"An object measured in feet gives 6. The same object measured in yards gives 2. What is the relationship between feet and yards?","type":"multiple_choice","correct_answer":"1 yard = 3 feet","explanation":"6 feet / 2 yards = 3. So 1 yard = 3 feet.","standard_code":"2.MD.2","difficulty":3,"options":[{"label":"1 yard = 2 feet","value":"1 yard = 2 feet"},{"label":"1 yard = 6 feet","value":"1 yard = 6 feet"},{"label":"1 yard = 3 feet","value":"1 yard = 3 feet"},{"label":"1 yard = 4 feet","value":"1 yard = 4 feet"}]},{"id":2,"text":"If a hallway is 9 meters, how many centimeters is that?","type":"numeric","correct_answer":"900","explanation":"1 meter = 100 cm. 9 x 100 = 900 cm.","standard_code":"2.MD.2","difficulty":3},{"id":3,"text":"You measure a paper clip as 3 cm or 30 mm. Are both measurements consistent? (1 cm = 10 mm)","type":"multiple_choice","correct_answer":"Yes","explanation":"3 cm = 30 mm. They represent the same length in different units.","standard_code":"2.MD.2","difficulty":3,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]},{"id":4,"text":"A tree is 4 meters tall. Is it more, less, or equal to 400 cm?","type":"multiple_choice","correct_answer":"Equal; 4 meters = 400 cm","explanation":"1 meter = 100 cm. 4 x 100 = 400 cm. Equal.","standard_code":"2.MD.2","difficulty":3,"options":[{"label":"More; 4 meters = 44 cm","value":"More; 4 meters = 44 cm"},{"label":"Equal; 4 meters = 400 cm","value":"Equal; 4 meters = 400 cm"},{"label":"More; 4 meters = 40 cm","value":"More; 4 meters = 40 cm"},{"label":"Less; 4 meters = 4000 cm","value":"Less; 4 meters = 4000 cm"}]},{"id":5,"text":"You measure a desk with a 30-cm ruler and need 2.5 ruler lengths. How long is the desk?","type":"numeric","correct_answer":"75","explanation":"2.5 x 30 = 75 cm.","standard_code":"2.MD.2","difficulty":3}]'::jsonb);

VALUES (2,'MD','2.MD.3','Estimate Lengths Using Inches, Feet, Centimeters, and Meters (Easy)','Students estimate lengths using units of inches, feet, centimeters, and meters. Good estimating relies on benchmark reference lengths (e.g., a fingernail is about 1 cm; a door is about 1 meter wide; a','practice',1,10,109,'[{"id":1,"text":"About how long is a pencil: 7 inches, 7 feet, or 7 meters?","type":"multiple_choice","correct_answer":"7 inches","explanation":"A pencil is about 7 inches long. 7 feet would be as tall as a person!","standard_code":"2.MD.3","difficulty":1,"options":[{"label":"7 feet","value":"7 feet"},{"label":"70 inches","value":"70 inches"},{"label":"7 inches","value":"7 inches"},{"label":"7 meters","value":"7 meters"}]},{"id":2,"text":"About how tall is a door: 2 meters or 20 meters?","type":"multiple_choice","correct_answer":"2 meters","explanation":"A standard door is about 2 meters (about 6.5 feet) tall.","standard_code":"2.MD.3","difficulty":1,"options":[{"label":"0.2 meters","value":"0.2 meters"},{"label":"20 meters","value":"20 meters"},{"label":"2 meters","value":"2 meters"},{"label":"200 meters","value":"200 meters"}]},{"id":3,"text":"About how long is a classroom: 10 meters or 100 meters?","type":"multiple_choice","correct_answer":"About 10 meters","explanation":"A typical classroom is about 8-10 meters long.","standard_code":"2.MD.3","difficulty":1,"options":[{"label":"About 100 meters","value":"About 100 meters"},{"label":"About 1 meter","value":"About 1 meter"},{"label":"About 10 meters","value":"About 10 meters"},{"label":"About 50 meters","value":"About 50 meters"}]},{"id":4,"text":"Is a paper clip about 3 cm or 30 cm long?","type":"multiple_choice","correct_answer":"About 3 cm","explanation":"A standard paper clip is about 3 cm long.","standard_code":"2.MD.3","difficulty":1,"options":[{"label":"About 0.3 cm","value":"About 0.3 cm"},{"label":"About 300 cm","value":"About 300 cm"},{"label":"About 30 cm","value":"About 30 cm"},{"label":"About 3 cm","value":"About 3 cm"}]},{"id":5,"text":"About how long is a school bus: 10 meters or 1 meter?","type":"multiple_choice","correct_answer":"About 10 meters","explanation":"A school bus is roughly 10-12 meters long.","standard_code":"2.MD.3","difficulty":1,"options":[{"label":"About 5 meters","value":"About 5 meters"},{"label":"About 100 meters","value":"About 100 meters"},{"label":"About 10 meters","value":"About 10 meters"},{"label":"About 1 meter","value":"About 1 meter"}]}]'::jsonb);

VALUES (2,'MD','2.MD.3','Estimate Lengths Using Inches, Feet, Centimeters, and Meters (Medium)','Students estimate lengths using units of inches, feet, centimeters, and meters. Good estimating relies on benchmark reference lengths (e.g., a fingernail is about 1 cm; a door is about 1 meter wide; a','practice',2,15,110,'[{"id":1,"text":"You estimate a book is 25 cm long. The actual measurement is 28 cm. How far off was your estimate?","type":"numeric","correct_answer":"3","explanation":"28 - 25 = 3 cm. Your estimate was 3 cm short.","standard_code":"2.MD.3","difficulty":2},{"id":2,"text":"A hallway is about 20 meters long. Estimate in feet. (1 meter is about 3 feet)","type":"multiple_choice","correct_answer":"About 60 feet","explanation":"20 x 3 = 60 feet.","standard_code":"2.MD.3","difficulty":2,"options":[{"label":"About 200 feet","value":"About 200 feet"},{"label":"About 20 feet","value":"About 20 feet"},{"label":"About 6 feet","value":"About 6 feet"},{"label":"About 60 feet","value":"About 60 feet"}]},{"id":3,"text":"Is a car about 4 feet, 4 meters, or 4 cm long?","type":"multiple_choice","correct_answer":"About 4 meters","explanation":"A car is approximately 4-5 meters (about 14-16 feet) long.","standard_code":"2.MD.3","difficulty":2,"options":[{"label":"About 40 meters","value":"About 40 meters"},{"label":"About 4 feet","value":"About 4 feet"},{"label":"About 4 meters","value":"About 4 meters"},{"label":"About 4 cm","value":"About 4 cm"}]},{"id":4,"text":"Which is a reasonable estimate for the height of a ceiling: 3 feet, 3 meters, or 30 meters?","type":"multiple_choice","correct_answer":"3 meters","explanation":"Ceiling height is typically about 3 meters (approximately 10 feet).","standard_code":"2.MD.3","difficulty":2,"options":[{"label":"3 feet","value":"3 feet"},{"label":"30 feet","value":"30 feet"},{"label":"30 meters","value":"30 meters"},{"label":"3 meters","value":"3 meters"}]},{"id":5,"text":"A stack of 10 books is about 30 cm tall. About how thick is each book?","type":"multiple_choice","correct_answer":"About 3 cm","explanation":"30 cm / 10 books = 3 cm per book.","standard_code":"2.MD.3","difficulty":2,"options":[{"label":"About 30 cm","value":"About 30 cm"},{"label":"About 10 cm","value":"About 10 cm"},{"label":"About 3 cm","value":"About 3 cm"},{"label":"About 2 cm","value":"About 2 cm"}]}]'::jsonb);

VALUES (2,'MD','2.MD.3','Estimate Lengths Using Inches, Feet, Centimeters, and Meters (Hard)','Students estimate lengths using units of inches, feet, centimeters, and meters. Good estimating relies on benchmark reference lengths (e.g., a fingernail is about 1 cm; a door is about 1 meter wide; a','practice',3,20,111,'[{"id":1,"text":"Estimate the length of your classroom in meters, then convert to centimeters.","type":"multiple_choice","correct_answer":"About 8-10 meters; 800-1000 cm","explanation":"Typical classroom = 8-10 m. Multiply by 100 for centimeters.","standard_code":"2.MD.3","difficulty":3,"options":[{"label":"About 5-6 meters; 500-600 cm","value":"About 5-6 meters; 500-600 cm"},{"label":"About 20 meters; 2000 cm","value":"About 20 meters; 2000 cm"},{"label":"About 12-15 meters; 1200-1500 cm","value":"About 12-15 meters; 1200-1500 cm"},{"label":"About 8-10 meters; 800-1000 cm","value":"About 8-10 meters; 800-1000 cm"}]},{"id":2,"text":"A fence post is about 1.5 meters tall. There are 8 posts spaced 1.5 meters apart. About how long is the fence?","type":"multiple_choice","correct_answer":"About 12 meters","explanation":"8 intervals x 1.5 m = 12 meters (measuring the spans between posts).","standard_code":"2.MD.3","difficulty":3,"options":[{"label":"About 16 meters","value":"About 16 meters"},{"label":"About 10.5 meters","value":"About 10.5 meters"},{"label":"About 8 meters","value":"About 8 meters"},{"label":"About 12 meters","value":"About 12 meters"}]},{"id":3,"text":"Estimate: about how many centimeters long is a dollar bill?","type":"multiple_choice","correct_answer":"About 15 cm","explanation":"A US dollar bill is about 15.6 cm (6.14 inches) long.","standard_code":"2.MD.3","difficulty":3,"options":[{"label":"About 15 cm","value":"About 15 cm"},{"label":"About 10 cm","value":"About 10 cm"},{"label":"About 12 cm","value":"About 12 cm"},{"label":"About 20 cm","value":"About 20 cm"}]},{"id":4,"text":"A student estimates a desk is 60 cm. She measures and finds 65 cm. Is her estimate reasonable?","type":"multiple_choice","correct_answer":"Yes; it is only 5 cm off (about 8% error)","explanation":"60 and 65 are close. A reasonable estimate is within about 10-15% of the actual value.","standard_code":"2.MD.3","difficulty":3,"options":[{"label":"Yes; it is only 5 cm off (about 8% error)","value":"Yes; it is only 5 cm off (about 8% error)"},{"label":"No; it is off by more than 10%","value":"No; it is off by more than 10%"},{"label":"No; 5 cm is too much error","value":"No; 5 cm is too much error"},{"label":"Yes; it is only 10 cm off","value":"Yes; it is only 10 cm off"}]},{"id":5,"text":"About how many meters is the height of a two-story building?","type":"multiple_choice","correct_answer":"About 6-8 meters","explanation":"Each story is roughly 3-4 meters. Two stories = about 6-8 meters.","standard_code":"2.MD.3","difficulty":3,"options":[{"label":"About 10-12 meters","value":"About 10-12 meters"},{"label":"About 6-8 meters","value":"About 6-8 meters"},{"label":"About 12-15 meters","value":"About 12-15 meters"},{"label":"About 4-5 meters","value":"About 4-5 meters"}]}]'::jsonb);

VALUES (2,'MD','2.MD.4','Measure and Compare - How Much Longer Is One Object? (Easy)','Students measure objects to determine how much longer one is than another, expressing the difference in standard length units. They subtract to find the difference in measurements.','practice',1,10,112,'[{"id":1,"text":"Pencil A is 12 cm. Pencil B is 7 cm. How much longer is A?","type":"numeric","correct_answer":"5","explanation":"12 - 7 = 5 cm. A is 5 cm longer.","standard_code":"2.MD.4","difficulty":1},{"id":2,"text":"A ribbon is 18 inches. A string is 10 inches. How much shorter is the string?","type":"multiple_choice","correct_answer":"8 inches","explanation":"18 - 10 = 8 inches shorter.","standard_code":"2.MD.4","difficulty":1,"options":[{"label":"8 inches","value":"8 inches"},{"label":"9 inches","value":"9 inches"},{"label":"6 inches","value":"6 inches"},{"label":"7 inches","value":"7 inches"}]},{"id":3,"text":"Book A is 9 inches tall. Book B is 6 inches tall. What is the difference?","type":"multiple_choice","correct_answer":"3 inches","explanation":"9 - 6 = 3 inches.","standard_code":"2.MD.4","difficulty":1,"options":[{"label":"2 inches","value":"2 inches"},{"label":"15 inches","value":"15 inches"},{"label":"3 inches","value":"3 inches"},{"label":"5 inches","value":"5 inches"}]},{"id":4,"text":"A desk is 80 cm wide. A table is 65 cm wide. How much wider is the desk?","type":"numeric","correct_answer":"15","explanation":"80 - 65 = 15 cm.","standard_code":"2.MD.4","difficulty":1},{"id":5,"text":"A snake is 24 cm. A worm is 8 cm. How much longer is the snake?","type":"numeric","correct_answer":"16","explanation":"24 - 8 = 16 cm.","standard_code":"2.MD.4","difficulty":1}]'::jsonb);

VALUES (2,'MD','2.MD.4','Measure and Compare - How Much Longer Is One Object? (Medium)','Students measure objects to determine how much longer one is than another, expressing the difference in standard length units. They subtract to find the difference in measurements.','practice',2,15,113,'[{"id":1,"text":"Sam''s rope is 35 cm. Lily''s rope is 27 cm. How much longer is Sam''s?","type":"numeric","correct_answer":"8","explanation":"35 - 27 = 8 cm.","standard_code":"2.MD.4","difficulty":2},{"id":2,"text":"A red crayon is 14 cm. A blue crayon is 9 cm. How much longer is the red crayon?","type":"multiple_choice","correct_answer":"5 cm longer","explanation":"14 - 9 = 5 cm.","standard_code":"2.MD.4","difficulty":2,"options":[{"label":"23 cm longer","value":"23 cm longer"},{"label":"6 cm longer","value":"6 cm longer"},{"label":"4 cm longer","value":"4 cm longer"},{"label":"5 cm longer","value":"5 cm longer"}]},{"id":3,"text":"A fish tank is 90 cm long. A fish is 15 cm long. How much longer is the tank?","type":"numeric","correct_answer":"75","explanation":"90 - 15 = 75 cm.","standard_code":"2.MD.4","difficulty":2},{"id":4,"text":"Ann''s jump: 48 inches. Ben''s jump: 39 inches. How much farther did Ann jump?","type":"multiple_choice","correct_answer":"9 inches","explanation":"48 - 39 = 9 inches.","standard_code":"2.MD.4","difficulty":2,"options":[{"label":"12 inches","value":"12 inches"},{"label":"48 inches","value":"48 inches"},{"label":"6 inches","value":"6 inches"},{"label":"9 inches","value":"9 inches"}]},{"id":5,"text":"A room is 450 cm wide. A hallway is 210 cm wide. How much wider is the room?","type":"numeric","correct_answer":"240","explanation":"450 - 210 = 240 cm.","standard_code":"2.MD.4","difficulty":2}]'::jsonb);

VALUES (2,'MD','2.MD.4','Measure and Compare - How Much Longer Is One Object? (Hard)','Students measure objects to determine how much longer one is than another, expressing the difference in standard length units. They subtract to find the difference in measurements.','practice',3,20,114,'[{"id":1,"text":"Strip A = 1 foot 3 inches (= 15 inches). Strip B = 9 inches. How much longer is A?","type":"multiple_choice","correct_answer":"6 inches","explanation":"15 - 9 = 6 inches.","standard_code":"2.MD.4","difficulty":3,"options":[{"label":"4 inches","value":"4 inches"},{"label":"7 inches","value":"7 inches"},{"label":"9 inches","value":"9 inches"},{"label":"6 inches","value":"6 inches"}]},{"id":2,"text":"Tower C is 79 cm. Tower A is 68 cm. How much taller is Tower C?","type":"numeric","correct_answer":"11","explanation":"79 - 68 = 11 cm.","standard_code":"2.MD.4","difficulty":3},{"id":3,"text":"A path is 75 meters. A trail is 48 meters. How much longer is the path? Express in meters and centimeters.","type":"multiple_choice","correct_answer":"27 meters; 2700 cm","explanation":"75 - 48 = 27 m. 27 m x 100 = 2700 cm.","standard_code":"2.MD.4","difficulty":3,"options":[{"label":"29 meters; 2900 cm","value":"29 meters; 2900 cm"},{"label":"23 meters; 2300 cm","value":"23 meters; 2300 cm"},{"label":"27 meters; 2700 cm","value":"27 meters; 2700 cm"},{"label":"25 meters; 2500 cm","value":"25 meters; 2500 cm"}]},{"id":4,"text":"A plant grew 14 cm in January and 19 cm in February. How much more did it grow in February?","type":"numeric","correct_answer":"5","explanation":"19 - 14 = 5 cm.","standard_code":"2.MD.4","difficulty":3},{"id":5,"text":"Three ropes: A = 32 cm, B = 45 cm, C = 28 cm. How much longer is the longest than the shortest?","type":"numeric","correct_answer":"17","explanation":"Longest = B = 45. Shortest = C = 28. 45 - 28 = 17 cm.","standard_code":"2.MD.4","difficulty":3}]'::jsonb);

VALUES (2,'MD','2.MD.5','Solve Word Problems About Length Using Addition and Subtraction (Easy)','Students use addition and subtraction within 100 to solve word problems involving lengths, given in the same units. They may use drawings and equations with a symbol for the unknown to represent the p','practice',1,10,115,'[{"id":1,"text":"A string is 25 cm. Another is 14 cm. How long are they together?","type":"numeric","correct_answer":"39","explanation":"25 + 14 = 39 cm.","standard_code":"2.MD.5","difficulty":1},{"id":2,"text":"A worm is 18 cm. It stretches to 24 cm. How much did it grow?","type":"numeric","correct_answer":"6","explanation":"24 - 18 = 6 cm.","standard_code":"2.MD.5","difficulty":1},{"id":3,"text":"A bookshelf is 30 cm wide. A book is 8 cm thick. How much shelf space is left?","type":"numeric","correct_answer":"22","explanation":"30 - 8 = 22 cm.","standard_code":"2.MD.5","difficulty":1},{"id":4,"text":"Two ribbons: 12 inches and 7 inches. How long are they in total?","type":"multiple_choice","correct_answer":"19 inches","explanation":"12 + 7 = 19 inches.","standard_code":"2.MD.5","difficulty":1,"options":[{"label":"19 inches","value":"19 inches"},{"label":"20 inches","value":"20 inches"},{"label":"18 inches","value":"18 inches"},{"label":"21 inches","value":"21 inches"}]},{"id":5,"text":"A plant is 15 cm tall. It grows 9 more cm. How tall is it now?","type":"numeric","correct_answer":"24","explanation":"15 + 9 = 24 cm.","standard_code":"2.MD.5","difficulty":1}]'::jsonb);

VALUES (2,'MD','2.MD.5','Solve Word Problems About Length Using Addition and Subtraction (Medium)','Students use addition and subtraction within 100 to solve word problems involving lengths, given in the same units. They may use drawings and equations with a symbol for the unknown to represent the p','practice',2,15,116,'[{"id":1,"text":"A rope is 45 cm. Jake cuts off 17 cm. How much is left?","type":"numeric","correct_answer":"28","explanation":"45 - 17 = 28 cm.","standard_code":"2.MD.5","difficulty":2},{"id":2,"text":"A fence is 62 feet long. Ann painted 38 feet. How much is unpainted?","type":"multiple_choice","correct_answer":"24 feet","explanation":"62 - 38 = 24 feet.","standard_code":"2.MD.5","difficulty":2,"options":[{"label":"24 feet","value":"24 feet"},{"label":"38 feet","value":"38 feet"},{"label":"23 feet","value":"23 feet"},{"label":"100 feet","value":"100 feet"}]},{"id":3,"text":"Carlos walked 38 meters to school and 27 meters to the park. How far did he walk in all?","type":"multiple_choice","correct_answer":"65 meters","explanation":"38 + 27 = 65 meters.","standard_code":"2.MD.5","difficulty":2,"options":[{"label":"11 meters","value":"11 meters"},{"label":"66 meters","value":"66 meters"},{"label":"65 meters","value":"65 meters"},{"label":"64 meters","value":"64 meters"}]},{"id":4,"text":"A jump rope needs to be 100 inches. It is currently 84 inches. How many more inches are needed?","type":"multiple_choice","correct_answer":"16 inches","explanation":"100 - 84 = 16 inches.","standard_code":"2.MD.5","difficulty":2,"options":[{"label":"16 inches","value":"16 inches"},{"label":"18 inches","value":"18 inches"},{"label":"20 inches","value":"20 inches"},{"label":"14 inches","value":"14 inches"}]},{"id":5,"text":"A plank is 72 cm. It is cut into two pieces. One piece is 45 cm. How long is the other?","type":"numeric","correct_answer":"27","explanation":"72 - 45 = 27 cm.","standard_code":"2.MD.5","difficulty":2}]'::jsonb);

VALUES (2,'MD','2.MD.5','Solve Word Problems About Length Using Addition and Subtraction (Hard)','Students use addition and subtraction within 100 to solve word problems involving lengths, given in the same units. They may use drawings and equations with a symbol for the unknown to represent the p','practice',3,20,117,'[{"id":1,"text":"A path is 95 meters. Workers paved 47 meters on day 1 and 28 meters on day 2. How much is left?","type":"multiple_choice","correct_answer":"20 meters","explanation":"47 + 28 = 75. 95 - 75 = 20 meters remaining.","standard_code":"2.MD.5","difficulty":3,"options":[{"label":"20 meters","value":"20 meters"},{"label":"15 meters","value":"15 meters"},{"label":"25 meters","value":"25 meters"},{"label":"18 meters","value":"18 meters"}]},{"id":2,"text":"A rope is cut into two equal pieces of 36 cm each. How long was the original rope?","type":"numeric","correct_answer":"72","explanation":"36 + 36 = 72 cm.","standard_code":"2.MD.5","difficulty":3},{"id":3,"text":"A garden border needs 100 feet. Three sections: 28 ft, 35 ft, and an unknown. How long is the unknown?","type":"multiple_choice","correct_answer":"37 feet","explanation":"28 + 35 = 63. 100 - 63 = 37 feet.","standard_code":"2.MD.5","difficulty":3,"options":[{"label":"28 feet","value":"28 feet"},{"label":"37 feet","value":"37 feet"},{"label":"63 feet","value":"63 feet"},{"label":"35 feet","value":"35 feet"}]},{"id":4,"text":"Ann is 52 inches tall. She grows 3 inches. Ben is 61 inches. How much shorter is Ann than Ben now?","type":"multiple_choice","correct_answer":"6 inches shorter","explanation":"Ann''s new height: 52 + 3 = 55 inches. 61 - 55 = 6 inches shorter.","standard_code":"2.MD.5","difficulty":3,"options":[{"label":"8 inches shorter","value":"8 inches shorter"},{"label":"9 inches shorter","value":"9 inches shorter"},{"label":"3 inches shorter","value":"3 inches shorter"},{"label":"6 inches shorter","value":"6 inches shorter"}]},{"id":5,"text":"A road is 800 meters. Three sections: 250 m, 320 m, and the rest. How long is the rest?","type":"multiple_choice","correct_answer":"230 meters","explanation":"250 + 320 = 570. 800 - 570 = 230 meters.","standard_code":"2.MD.5","difficulty":3,"options":[{"label":"230 meters","value":"230 meters"},{"label":"240 meters","value":"240 meters"},{"label":"320 meters","value":"320 meters"},{"label":"250 meters","value":"250 meters"}]}]'::jsonb);

VALUES (2,'MD','2.MD.6','Represent Sums and Differences on a Number Line (Easy)','Students represent whole-number sums and differences within 100 on a number line diagram. Addition is represented as a jump to the right; subtraction as a jump to the left. They use number lines to vi','practice',1,10,118,'[{"id":1,"text":"Show 7 + 5 on a number line. Start at 7, jump 5 right. Where do you land?","type":"numeric","correct_answer":"12","explanation":"7 + 5 = 12. Start at 7, jump 5 to the right, land on 12.","standard_code":"2.MD.6","difficulty":1},{"id":2,"text":"Show 15 - 4 on a number line. Start at 15, jump 4 left. Where do you land?","type":"numeric","correct_answer":"11","explanation":"15 - 4 = 11. Start at 15, jump 4 left to 11.","standard_code":"2.MD.6","difficulty":1},{"id":3,"text":"A number line shows a jump from 8 to 13. What addition equation does this show?","type":"multiple_choice","correct_answer":"8 + 5 = 13","explanation":"The jump is 5 units to the right: 8 + 5 = 13.","standard_code":"2.MD.6","difficulty":1,"options":[{"label":"5 + 8 = 13","value":"5 + 8 = 13"},{"label":"8 + 5 = 13","value":"8 + 5 = 13"},{"label":"8 + 8 = 16","value":"8 + 8 = 16"},{"label":"13 - 8 = 5","value":"13 - 8 = 5"}]},{"id":4,"text":"Start at 20, jump back 7. Where are you?","type":"numeric","correct_answer":"13","explanation":"20 - 7 = 13.","standard_code":"2.MD.6","difficulty":1},{"id":5,"text":"Show 10 + 6 on a number line. Where do you land?","type":"numeric","correct_answer":"16","explanation":"Start at 10, jump 6 units right, land on 16. 10 + 6 = 16.","standard_code":"2.MD.6","difficulty":1}]'::jsonb);

VALUES (2,'MD','2.MD.6','Represent Sums and Differences on a Number Line (Medium)','Students represent whole-number sums and differences within 100 on a number line diagram. Addition is represented as a jump to the right; subtraction as a jump to the left. They use number lines to vi','practice',2,15,119,'[{"id":1,"text":"A number line jump goes from 35 to 52. What addition equation does this show?","type":"multiple_choice","correct_answer":"35 + 17 = 52","explanation":"The jump is 52 - 35 = 17 units to the right.","standard_code":"2.MD.6","difficulty":2,"options":[{"label":"35 + 20 = 55","value":"35 + 20 = 55"},{"label":"35 + 12 = 47","value":"35 + 12 = 47"},{"label":"52 - 35 = 17","value":"52 - 35 = 17"},{"label":"35 + 17 = 52","value":"35 + 17 = 52"}]},{"id":2,"text":"Use a number line to solve 68 - 25.","type":"numeric","correct_answer":"43","explanation":"Start at 68, jump 25 left: 68 - 25 = 43.","standard_code":"2.MD.6","difficulty":2},{"id":3,"text":"Show how to find 47 + 36 on a number line.","type":"multiple_choice","correct_answer":"47 + 36 = 83","explanation":"Start at 47, jump 30 to 77, then jump 6 to 83.","standard_code":"2.MD.6","difficulty":2,"options":[{"label":"47 + 36 = 83","value":"47 + 36 = 83"},{"label":"47 + 36 = 81","value":"47 + 36 = 81"},{"label":"47 + 36 = 82","value":"47 + 36 = 82"},{"label":"47 + 36 = 84","value":"47 + 36 = 84"}]},{"id":4,"text":"A number line shows a start at 100 and a jump back to 64. What subtraction equation is shown?","type":"multiple_choice","correct_answer":"100 - 36 = 64","explanation":"The jump back is 36 units: 100 - 36 = 64.","standard_code":"2.MD.6","difficulty":2,"options":[{"label":"100 - 45 = 55","value":"100 - 45 = 55"},{"label":"100 - 36 = 64","value":"100 - 36 = 64"},{"label":"100 - 64 = 36","value":"100 - 64 = 36"},{"label":"64 - 36 = 28","value":"64 - 36 = 28"}]},{"id":5,"text":"Find 80 - 33 on a number line.","type":"numeric","correct_answer":"47","explanation":"Start at 80, jump back 30 to 50, then back 3 to 47.","standard_code":"2.MD.6","difficulty":2}]'::jsonb);

VALUES (2,'MD','2.MD.6','Represent Sums and Differences on a Number Line (Hard)','Students represent whole-number sums and differences within 100 on a number line diagram. Addition is represented as a jump to the right; subtraction as a jump to the left. They use number lines to vi','practice',3,20,120,'[{"id":1,"text":"On a number line, start at 15, jump 28 right, then jump 14 left. Where do you end? Write the equation.","type":"multiple_choice","correct_answer":"29; 15 + 28 - 14 = 29","explanation":"15 + 28 = 43; 43 - 14 = 29.","standard_code":"2.MD.6","difficulty":3,"options":[{"label":"43; 15 + 28 = 43","value":"43; 15 + 28 = 43"},{"label":"29; 15 + 14 + 28 = 57","value":"29; 15 + 14 + 28 = 57"},{"label":"27; 15 + 28 - 14 = 27","value":"27; 15 + 28 - 14 = 27"},{"label":"29; 15 + 28 - 14 = 29","value":"29; 15 + 28 - 14 = 29"}]},{"id":2,"text":"A jump on a number line ends at 91 and started at 54. Was it addition or subtraction? How far was the jump?","type":"multiple_choice","correct_answer":"Addition (jump right) of 37","explanation":"91 - 54 = 37. Since the endpoint is greater, it was an addition jump.","standard_code":"2.MD.6","difficulty":3,"options":[{"label":"Addition (jump right) of 37","value":"Addition (jump right) of 37"},{"label":"Addition (jump right) of 54","value":"Addition (jump right) of 54"},{"label":"Subtraction (jump left) of 54","value":"Subtraction (jump left) of 54"},{"label":"Subtraction (jump left) of 37","value":"Subtraction (jump left) of 37"}]},{"id":3,"text":"Model 100 - 67 by counting up from 67 to 100 on a number line.","type":"multiple_choice","correct_answer":"33; 67 + 33 = 100","explanation":"67 + 3 = 70; 70 + 30 = 100. Total jump: 3 + 30 = 33.","standard_code":"2.MD.6","difficulty":3,"options":[{"label":"33; 67 + 33 = 100","value":"33; 67 + 33 = 100"},{"label":"37; 67 + 37 = 104","value":"37; 67 + 37 = 104"},{"label":"34; 67 + 34 = 101","value":"34; 67 + 34 = 101"},{"label":"32; 67 + 32 = 99","value":"32; 67 + 32 = 99"}]},{"id":4,"text":"Two jumps: first +42, then -19. Start at 25. Where do you end?","type":"numeric","correct_answer":"48","explanation":"25 + 42 = 67; 67 - 19 = 48.","standard_code":"2.MD.6","difficulty":3},{"id":5,"text":"A mystery start point: a +36 jump lands on 85. What was the starting number?","type":"numeric","correct_answer":"49","explanation":"85 - 36 = 49. The start was 49.","standard_code":"2.MD.6","difficulty":3}]'::jsonb);

VALUES (2,'MD','2.MD.7','Tell and Write Time to the Nearest 5 Minutes (a.m./p.m.) (Easy)','Students tell and write time from analog and digital clocks to the nearest 5 minutes, using a.m. and p.m. They know that each number on the clock face represents 5 minutes, a.m. is midnight to noon (m','practice',1,10,121,'[{"id":1,"text":"The clock shows: hour hand on 4, minute hand on 12. What time is it?","type":"multiple_choice","correct_answer":"4:00","explanation":"4 o''clock. Minute hand on 12 = exactly on the hour.","standard_code":"2.MD.7","difficulty":1,"options":[{"label":"4:00","value":"4:00"},{"label":"4:30","value":"4:30"},{"label":"4:12","value":"4:12"},{"label":"3:00","value":"3:00"}]},{"id":2,"text":"The time is 3:30. Is the minute hand on 6 or 12?","type":"numeric","correct_answer":"6","explanation":"3:30 = half past 3. The minute hand points to 6.","standard_code":"2.MD.7","difficulty":1},{"id":3,"text":"What time is 15 minutes after 2:00?","type":"multiple_choice","correct_answer":"2:15","explanation":"15 minutes past 2 = 2:15. The minute hand points to 3.","standard_code":"2.MD.7","difficulty":1,"options":[{"label":"2:30","value":"2:30"},{"label":"2:45","value":"2:45"},{"label":"3:15","value":"3:15"},{"label":"2:15","value":"2:15"}]},{"id":4,"text":"Is 7:45 a.m. morning or evening?","type":"multiple_choice","correct_answer":"Morning","explanation":"a.m. = morning (midnight to noon).","standard_code":"2.MD.7","difficulty":1,"options":[{"label":"Morning","value":"Morning"},{"label":"Afternoon","value":"Afternoon"},{"label":"Evening","value":"Evening"},{"label":"Night","value":"Night"}]},{"id":5,"text":"Write 8:30 p.m. in words.","type":"multiple_choice","correct_answer":"Eight thirty in the evening","explanation":"8:30 p.m. = eight thirty in the evening.","standard_code":"2.MD.7","difficulty":1,"options":[{"label":"Eight forty five in the evening","value":"Eight forty five in the evening"},{"label":"Eight thirty in the morning","value":"Eight thirty in the morning"},{"label":"Eight fifteen in the evening","value":"Eight fifteen in the evening"},{"label":"Eight thirty in the evening","value":"Eight thirty in the evening"}]}]'::jsonb);

VALUES (2,'MD','2.MD.7','Tell and Write Time to the Nearest 5 Minutes (a.m./p.m.) (Medium)','Students tell and write time from analog and digital clocks to the nearest 5 minutes, using a.m. and p.m. They know that each number on the clock face represents 5 minutes, a.m. is midnight to noon (m','practice',2,15,122,'[{"id":1,"text":"The minute hand points to 7. How many minutes does this show?","type":"multiple_choice","correct_answer":"35 minutes","explanation":"Each number = 5 minutes. 7 x 5 = 35 minutes.","standard_code":"2.MD.7","difficulty":2,"options":[{"label":"42 minutes","value":"42 minutes"},{"label":"28 minutes","value":"28 minutes"},{"label":"37 minutes","value":"37 minutes"},{"label":"35 minutes","value":"35 minutes"}]},{"id":2,"text":"What time is shown: hour hand just past 6, minute hand on 4?","type":"multiple_choice","correct_answer":"6:20","explanation":"Minute hand on 4: 4 x 5 = 20 minutes. Time = 6:20.","standard_code":"2.MD.7","difficulty":2,"options":[{"label":"6:25","value":"6:25"},{"label":"6:20","value":"6:20"},{"label":"5:20","value":"5:20"},{"label":"6:40","value":"6:40"}]},{"id":3,"text":"School starts at 8:05 a.m. Write this in words.","type":"multiple_choice","correct_answer":"Eight oh five in the morning","explanation":"8:05 a.m. = eight oh five in the morning.","standard_code":"2.MD.7","difficulty":2,"options":[{"label":"Eight fifteen in the morning","value":"Eight fifteen in the morning"},{"label":"Eight oh five in the morning","value":"Eight oh five in the morning"},{"label":"Eight five in the morning","value":"Eight five in the morning"},{"label":"Eight oh four in the morning","value":"Eight oh four in the morning"}]},{"id":4,"text":"The minute hand is on 9. The hour is 2. What time is it?","type":"multiple_choice","correct_answer":"2:45","explanation":"9 x 5 = 45 minutes. Time = 2:45.","standard_code":"2.MD.7","difficulty":2,"options":[{"label":"3:00","value":"3:00"},{"label":"2:35","value":"2:35"},{"label":"2:50","value":"2:50"},{"label":"2:45","value":"2:45"}]},{"id":5,"text":"What time is 30 minutes after 4:25?","type":"multiple_choice","correct_answer":"4:55","explanation":"4:25 + 30 minutes = 4:55.","standard_code":"2.MD.7","difficulty":2,"options":[{"label":"5:25","value":"5:25"},{"label":"4:45","value":"4:45"},{"label":"4:55","value":"4:55"},{"label":"5:00","value":"5:00"}]}]'::jsonb);

VALUES (2,'MD','2.MD.7','Tell and Write Time to the Nearest 5 Minutes (a.m./p.m.) (Hard)','Students tell and write time from analog and digital clocks to the nearest 5 minutes, using a.m. and p.m. They know that each number on the clock face represents 5 minutes, a.m. is midnight to noon (m','practice',3,20,123,'[{"id":1,"text":"Soccer practice starts at 3:15 p.m. and ends at 4:45 p.m. How long is practice?","type":"multiple_choice","correct_answer":"1 hour 30 minutes","explanation":"3:15 to 4:15 = 1 hour. 4:15 to 4:45 = 30 minutes. Total: 1 hr 30 min.","standard_code":"2.MD.7","difficulty":3,"options":[{"label":"1 hour 30 minutes","value":"1 hour 30 minutes"},{"label":"1 hour 15 minutes","value":"1 hour 15 minutes"},{"label":"1 hour 45 minutes","value":"1 hour 45 minutes"},{"label":"50 minutes","value":"50 minutes"}]},{"id":2,"text":"Sam woke at 7:20 a.m. and arrived at school at 8:05 a.m. How long did the trip take?","type":"numeric","correct_answer":"45","explanation":"7:20 to 8:00 = 40 min; 8:00 to 8:05 = 5 min. Total: 45 min.","standard_code":"2.MD.7","difficulty":3},{"id":3,"text":"A movie starts at 6:35 p.m. and lasts 1 hour 25 minutes. When does it end?","type":"multiple_choice","correct_answer":"8:00 p.m.","explanation":"6:35 + 1 hour = 7:35; 7:35 + 25 min = 8:00 p.m.","standard_code":"2.MD.7","difficulty":3,"options":[{"label":"8:00 p.m.","value":"8:00 p.m."},{"label":"7:50 p.m.","value":"7:50 p.m."},{"label":"8:10 p.m.","value":"8:10 p.m."},{"label":"7:55 p.m.","value":"7:55 p.m."}]},{"id":4,"text":"Is 11:55 a.m. closer to noon or midnight?","type":"multiple_choice","correct_answer":"Noon","explanation":"11:55 a.m. is 5 minutes before noon, which is far closer to noon than to midnight.","standard_code":"2.MD.7","difficulty":3,"options":[{"label":"They are equally close","value":"They are equally close"},{"label":"Noon","value":"Noon"},{"label":"Midnight","value":"Midnight"},{"label":"12:05 a.m.","value":"12:05 a.m."}]},{"id":5,"text":"The time is 2:50 p.m. What time will it be in 25 minutes?","type":"multiple_choice","correct_answer":"3:15 p.m.","explanation":"2:50 + 10 = 3:00; 3:00 + 15 = 3:15 p.m.","standard_code":"2.MD.7","difficulty":3,"options":[{"label":"3:10 p.m.","value":"3:10 p.m."},{"label":"3:25 p.m.","value":"3:25 p.m."},{"label":"3:15 p.m.","value":"3:15 p.m."},{"label":"2:75 p.m.","value":"2:75 p.m."}]}]'::jsonb);

VALUES (2,'MD','2.MD.8','Solve Word Problems with Money (Dollars, Quarters, Dimes, Nickels, Pennies) (Easy)','Students solve word problems involving dollar bills, quarters (25 cents), dimes (10 cents), nickels (5 cents), and pennies (1 cent). They use the $ and cent symbols correctly and understand that 100 c','practice',1,10,124,'[{"id":1,"text":"You have 2 dimes and 1 nickel. How much money do you have?","type":"numeric","correct_answer":"25","explanation":"2 dimes = 20 cents; 1 nickel = 5 cents; 20 + 5 = 25 cents.","standard_code":"2.MD.8","difficulty":1},{"id":2,"text":"How much is 1 quarter?","type":"numeric","correct_answer":"25","explanation":"A quarter = 25 cents.","standard_code":"2.MD.8","difficulty":1},{"id":3,"text":"You have 3 nickels. How much is that?","type":"numeric","correct_answer":"15","explanation":"3 x 5 = 15 cents.","standard_code":"2.MD.8","difficulty":1},{"id":4,"text":"A pencil costs 10 cents. You pay with a dime. How much change do you get?","type":"multiple_choice","correct_answer":"0 cents (exact change)","explanation":"1 dime = 10 cents. Exact amount - no change needed.","standard_code":"2.MD.8","difficulty":1,"options":[{"label":"5 cents","value":"5 cents"},{"label":"10 cents","value":"10 cents"},{"label":"1 dime","value":"1 dime"},{"label":"0 cents (exact change)","value":"0 cents (exact change)"}]},{"id":5,"text":"How many pennies equal 1 dime?","type":"multiple_choice","correct_answer":"10 pennies","explanation":"1 dime = 10 cents = 10 pennies.","standard_code":"2.MD.8","difficulty":1,"options":[{"label":"10 pennies","value":"10 pennies"},{"label":"5 pennies","value":"5 pennies"},{"label":"20 pennies","value":"20 pennies"},{"label":"100 pennies","value":"100 pennies"}]}]'::jsonb);

VALUES (2,'MD','2.MD.8','Solve Word Problems with Money (Dollars, Quarters, Dimes, Nickels, Pennies) (Medium)','Students solve word problems involving dollar bills, quarters (25 cents), dimes (10 cents), nickels (5 cents), and pennies (1 cent). They use the $ and cent symbols correctly and understand that 100 c','practice',2,15,125,'[{"id":1,"text":"You have 1 quarter, 2 dimes, 1 nickel. How much total?","type":"numeric","correct_answer":"50","explanation":"25 + 20 + 5 = 50 cents.","standard_code":"2.MD.8","difficulty":2},{"id":2,"text":"A toy costs 67 cents. You pay with 3 quarters (75 cents). How much change?","type":"numeric","correct_answer":"8","explanation":"75 - 67 = 8 cents.","standard_code":"2.MD.8","difficulty":2},{"id":3,"text":"How many nickels equal 1 dollar?","type":"multiple_choice","correct_answer":"20 nickels","explanation":"100 cents / 5 cents = 20 nickels.","standard_code":"2.MD.8","difficulty":2,"options":[{"label":"10 nickels","value":"10 nickels"},{"label":"50 nickels","value":"50 nickels"},{"label":"20 nickels","value":"20 nickels"},{"label":"25 nickels","value":"25 nickels"}]},{"id":4,"text":"Sam has $1.00. He buys a snack for 62 cents. How much is left?","type":"numeric","correct_answer":"38","explanation":"100 - 62 = 38 cents.","standard_code":"2.MD.8","difficulty":2},{"id":5,"text":"List two ways to make 50 cents using quarters, dimes, and nickels.","type":"multiple_choice","correct_answer":"2 quarters; or 5 dimes; or 1 quarter + 2 dimes + 1 nickel (plus other valid combos)","explanation":"Many valid combinations: 2 x 25 = 50; 5 x 10 = 50; 1 quarter + 2 dimes + 1 nickel = 25+20+5 = 50.","standard_code":"2.MD.8","difficulty":2,"options":[{"label":"4 dimes + 2 nickels; or 1 quarter + 1 quarter + 2 dimes","value":"4 dimes + 2 nickels; or 1 quarter + 1 quarter + 2 dimes"},{"label":"3 quarters + 2 nickels; or 2 quarters + 10 dimes","value":"3 quarters + 2 nickels; or 2 quarters + 10 dimes"},{"label":"1 quarter + 5 nickels; or 10 dimes","value":"1 quarter + 5 nickels; or 10 dimes"},{"label":"2 quarters; or 5 dimes; or 1 quarter + 2 dimes + 1 nickel (plus other valid combos)","value":"2 quarters; or 5 dimes; or 1 quarter + 2 dimes + 1 nickel (plus other valid combos)"}]}]'::jsonb);

VALUES (2,'MD','2.MD.8','Solve Word Problems with Money (Dollars, Quarters, Dimes, Nickels, Pennies) (Hard)','Students solve word problems involving dollar bills, quarters (25 cents), dimes (10 cents), nickels (5 cents), and pennies (1 cent). They use the $ and cent symbols correctly and understand that 100 c','practice',3,20,126,'[{"id":1,"text":"Ana saves $1.35. She spends $0.80. How much does she have left?","type":"multiple_choice","correct_answer":"$0.55 (55 cents)","explanation":"135 - 80 = 55 cents = $0.55.","standard_code":"2.MD.8","difficulty":3,"options":[{"label":"$0.80 (80 cents)","value":"$0.80 (80 cents)"},{"label":"$0.55 (55 cents)","value":"$0.55 (55 cents)"},{"label":"$0.65 (65 cents)","value":"$0.65 (65 cents)"},{"label":"$0.45 (45 cents)","value":"$0.45 (45 cents)"}]},{"id":2,"text":"A book costs $3.50. Tom has 2 one-dollar bills and 6 quarters. Does he have enough?","type":"multiple_choice","correct_answer":"Yes - exactly $3.50","explanation":"2 dollars + 6 quarters (6 x 25 = $1.50) = $2.00 + $1.50 = $3.50. Exactly enough.","standard_code":"2.MD.8","difficulty":3,"options":[{"label":"Yes - exactly $3.50","value":"Yes - exactly $3.50"},{"label":"No - 25 cents short","value":"No - 25 cents short"},{"label":"Yes - 25 cents extra","value":"Yes - 25 cents extra"},{"label":"No - he is exactly $0.50 short","value":"No - he is exactly $0.50 short"}]},{"id":3,"text":"Three items cost 35 cents, 48 cents, and 27 cents. What is the total?","type":"multiple_choice","correct_answer":"$1.10","explanation":"35 + 48 + 27 = 110 cents = $1.10.","standard_code":"2.MD.8","difficulty":3,"options":[{"label":"$1.20","value":"$1.20"},{"label":"$1.10","value":"$1.10"},{"label":"$1.00","value":"$1.00"},{"label":"$1.15","value":"$1.15"}]},{"id":4,"text":"Ali has 1 dollar, 3 quarters, 2 dimes, 1 penny. How much total?","type":"multiple_choice","correct_answer":"$1.96","explanation":"100 + 75 + 20 + 1 = 196 cents = $1.96.","standard_code":"2.MD.8","difficulty":3,"options":[{"label":"$1.86","value":"$1.86"},{"label":"$2.01","value":"$2.01"},{"label":"$1.96","value":"$1.96"},{"label":"$1.76","value":"$1.76"}]},{"id":5,"text":"A snack costs $0.85. You have 3 quarters and 2 dimes. Do you have enough? How much extra or short?","type":"multiple_choice","correct_answer":"Yes; 10 cents extra","explanation":"3 quarters = 75 cents; 2 dimes = 20 cents; total = 95 cents. 95 - 85 = 10 cents extra.","standard_code":"2.MD.8","difficulty":3,"options":[{"label":"No; 5 cents short","value":"No; 5 cents short"},{"label":"Yes; 5 cents extra","value":"Yes; 5 cents extra"},{"label":"No; 15 cents short","value":"No; 15 cents short"},{"label":"Yes; 10 cents extra","value":"Yes; 10 cents extra"}]}]'::jsonb);

VALUES (2,'MD','2.MD.9','Generate Measurement Data; Make a Line Plot (Easy)','Students measure objects using rulers and generate measurement data. They display data on a line plot - a number line with X marks above each value - and answer questions about the data, including fin','practice',1,10,127,'[{"id":1,"text":"A line plot shows 4 Xs above 3 and 2 Xs above 4. How many objects measured 3?","type":"numeric","correct_answer":"4","explanation":"4 Xs above 3 means 4 objects were measured at 3 units.","standard_code":"2.MD.9","difficulty":1},{"id":2,"text":"A line plot has Xs at: 5 (3 Xs), 6 (5 Xs), 7 (2 Xs). Which measurement is most common?","type":"numeric","correct_answer":"6","explanation":"6 has the most Xs (5), making it the most common measurement.","standard_code":"2.MD.9","difficulty":1},{"id":3,"text":"A line plot shows crayons: 5 cm (2 Xs), 7 cm (3 Xs), 9 cm (1 X). How many crayons were measured?","type":"numeric","correct_answer":"6","explanation":"2 + 3 + 1 = 6 crayons total.","standard_code":"2.MD.9","difficulty":1},{"id":4,"text":"What is the longest measurement on a line plot with Xs at 4, 5, 6, and 7?","type":"numeric","correct_answer":"7","explanation":"7 is the largest number with an X. It is the longest measurement.","standard_code":"2.MD.9","difficulty":1},{"id":5,"text":"What is the shortest measurement on a line plot with Xs at 8, 9, 10, 11?","type":"numeric","correct_answer":"8","explanation":"8 is the smallest number with an X. It is the shortest measurement.","standard_code":"2.MD.9","difficulty":1}]'::jsonb);

VALUES (2,'MD','2.MD.9','Generate Measurement Data; Make a Line Plot (Medium)','Students measure objects using rulers and generate measurement data. They display data on a line plot - a number line with X marks above each value - and answer questions about the data, including fin','practice',2,15,128,'[{"id":1,"text":"Five crayons measure: 6, 8, 6, 7, 8 cm. On a line plot, how many Xs go above 6?","type":"multiple_choice","correct_answer":"2 Xs","explanation":"Two crayons measured 6 cm, so 2 Xs go above 6.","standard_code":"2.MD.9","difficulty":2,"options":[{"label":"4 Xs","value":"4 Xs"},{"label":"2 Xs","value":"2 Xs"},{"label":"3 Xs","value":"3 Xs"},{"label":"1 X","value":"1 X"}]},{"id":2,"text":"A class measured pencils: 14, 15, 14, 16, 15, 14 cm. Which length appears most often?","type":"numeric","correct_answer":"14","explanation":"14 appears 3 times, more than any other length.","standard_code":"2.MD.9","difficulty":2},{"id":3,"text":"A line plot shows pencil lengths 10-15 cm: 3 Xs at 12, 2 at 13, 1 at 11. How many pencils were measured?","type":"numeric","correct_answer":"6","explanation":"3 + 2 + 1 = 6 pencils.","standard_code":"2.MD.9","difficulty":2},{"id":4,"text":"Data: 5, 6, 5, 7, 5, 6, 7. Describe what a line plot would look like.","type":"multiple_choice","correct_answer":"5: 3 Xs, 6: 2 Xs, 7: 2 Xs","explanation":"Count each value: 5 appears 3 times, 6 appears 2 times, 7 appears 2 times.","standard_code":"2.MD.9","difficulty":2,"options":[{"label":"5: 2 Xs, 6: 3 Xs, 7: 2 Xs","value":"5: 2 Xs, 6: 3 Xs, 7: 2 Xs"},{"label":"5: 4 Xs, 6: 2 Xs, 7: 1 X","value":"5: 4 Xs, 6: 2 Xs, 7: 1 X"},{"label":"5: 3 Xs, 6: 2 Xs, 7: 2 Xs","value":"5: 3 Xs, 6: 2 Xs, 7: 2 Xs"},{"label":"5: 3 Xs, 6: 3 Xs, 7: 1 X","value":"5: 3 Xs, 6: 3 Xs, 7: 1 X"}]},{"id":5,"text":"A line plot: 10 cm (1 X), 11 cm (3 Xs), 12 cm (2 Xs). How many more objects measured 11 than 10?","type":"multiple_choice","correct_answer":"2 more","explanation":"11 cm: 3 Xs. 10 cm: 1 X. Difference: 3 - 1 = 2.","standard_code":"2.MD.9","difficulty":2,"options":[{"label":"5 more","value":"5 more"},{"label":"2 more","value":"2 more"},{"label":"1 more","value":"1 more"},{"label":"3 more","value":"3 more"}]}]'::jsonb);

VALUES (2,'MD','2.MD.9','Generate Measurement Data; Make a Line Plot (Hard)','Students measure objects using rulers and generate measurement data. They display data on a line plot - a number line with X marks above each value - and answer questions about the data, including fin','practice',3,20,129,'[{"id":1,"text":"Line plot: 8 cm (2 Xs), 9 cm (4 Xs), 10 cm (3 Xs), 11 cm (1 X). How many objects total?","type":"numeric","correct_answer":"10","explanation":"2 + 4 + 3 + 1 = 10 objects.","standard_code":"2.MD.9","difficulty":3},{"id":2,"text":"Using the same data above, how many objects measured more than 9 cm?","type":"multiple_choice","correct_answer":"4 (3 at 10 cm + 1 at 11 cm)","explanation":"10 cm: 3 Xs + 11 cm: 1 X = 4 objects longer than 9 cm.","standard_code":"2.MD.9","difficulty":3,"options":[{"label":"3","value":"3"},{"label":"5","value":"5"},{"label":"6","value":"6"},{"label":"4 (3 at 10 cm + 1 at 11 cm)","value":"4 (3 at 10 cm + 1 at 11 cm)"}]},{"id":3,"text":"8 items measured: 5, 5, 6, 7, 7, 7, 8, 8. Which length appears most often?","type":"numeric","correct_answer":"7","explanation":"7 appears 3 times - more than any other length.","standard_code":"2.MD.9","difficulty":3},{"id":4,"text":"Line plot: 3 cm (2 Xs), 4 cm (5 Xs), 5 cm (3 Xs). How many more objects measured 4 cm than 3 cm?","type":"multiple_choice","correct_answer":"3 more","explanation":"5 - 2 = 3 more objects measured 4 cm.","standard_code":"2.MD.9","difficulty":3,"options":[{"label":"2 more","value":"2 more"},{"label":"4 more","value":"4 more"},{"label":"3 more","value":"3 more"},{"label":"5 more","value":"5 more"}]},{"id":5,"text":"Data: 10, 12, 11, 10, 12, 12, 11, 10. Describe the line plot and identify the most common measurement(s).","type":"multiple_choice","correct_answer":"10: 3 Xs, 11: 2 Xs, 12: 3 Xs. Most common: 10 and 12 (tied at 3 each)","explanation":"10 and 12 both appear 3 times - they are tied for most common (the mode).","standard_code":"2.MD.9","difficulty":3,"options":[{"label":"10: 2 Xs, 11: 3 Xs, 12: 3 Xs. Most common: 11 and 12","value":"10: 2 Xs, 11: 3 Xs, 12: 3 Xs. Most common: 11 and 12"},{"label":"10: 3 Xs, 11: 2 Xs, 12: 3 Xs. Most common: 10 and 12 (tied at 3 each)","value":"10: 3 Xs, 11: 2 Xs, 12: 3 Xs. Most common: 10 and 12 (tied at 3 each)"},{"label":"10: 3 Xs, 11: 3 Xs, 12: 2 Xs. Most common: 10 and 11","value":"10: 3 Xs, 11: 3 Xs, 12: 2 Xs. Most common: 10 and 11"},{"label":"10: 4 Xs, 11: 2 Xs, 12: 2 Xs. Most common: 10","value":"10: 4 Xs, 11: 2 Xs, 12: 2 Xs. Most common: 10"}]}]'::jsonb);

VALUES (2,'MD','2.MD.10','Draw Picture Graphs and Bar Graphs; Solve Problems from Graphs (Easy)','Students draw picture graphs and bar graphs (with single-unit scale) to represent data with up to four categories. They solve addition and subtraction problems using information from graphs, including','practice',1,10,130,'[{"id":1,"text":"A bar graph shows: dogs = 6, cats = 4. How many more dogs than cats?","type":"numeric","correct_answer":"2","explanation":"6 - 4 = 2 more dogs.","standard_code":"2.MD.10","difficulty":1},{"id":2,"text":"A picture graph shows apples = 3, oranges = 5. How many fruits in all?","type":"numeric","correct_answer":"8","explanation":"3 + 5 = 8.","standard_code":"2.MD.10","difficulty":1},{"id":3,"text":"Which is the most popular pet in: dogs = 8, cats = 5, fish = 3?","type":"multiple_choice","correct_answer":"Dogs","explanation":"8 is the highest count.","standard_code":"2.MD.10","difficulty":1,"options":[{"label":"Cats","value":"Cats"},{"label":"Dogs and cats tied","value":"Dogs and cats tied"},{"label":"Dogs","value":"Dogs"},{"label":"Fish","value":"Fish"}]},{"id":4,"text":"A bar graph shows: red = 7, blue = 7. What does this tell you?","type":"multiple_choice","correct_answer":"Equal numbers chose red and blue","explanation":"Both bars are the same height - equal counts.","standard_code":"2.MD.10","difficulty":1,"options":[{"label":"More people chose red","value":"More people chose red"},{"label":"Equal numbers chose red and blue","value":"Equal numbers chose red and blue"},{"label":"More people chose blue","value":"More people chose blue"},{"label":"Red is more popular than blue","value":"Red is more popular than blue"}]},{"id":5,"text":"Total students in a survey: Mon = 4, Tue = 6, Wed = 5. How many in all?","type":"numeric","correct_answer":"15","explanation":"4 + 6 + 5 = 15.","standard_code":"2.MD.10","difficulty":1}]'::jsonb);

VALUES (2,'MD','2.MD.10','Draw Picture Graphs and Bar Graphs; Solve Problems from Graphs (Medium)','Students draw picture graphs and bar graphs (with single-unit scale) to represent data with up to four categories. They solve addition and subtraction problems using information from graphs, including','practice',2,15,131,'[{"id":1,"text":"Favorite seasons: Spring=12, Summer=18, Fall=9, Winter=6. Which season got the most votes?","type":"multiple_choice","correct_answer":"Summer","explanation":"18 is the highest count.","standard_code":"2.MD.10","difficulty":2,"options":[{"label":"Summer","value":"Summer"},{"label":"Winter","value":"Winter"},{"label":"Fall","value":"Fall"},{"label":"Spring","value":"Spring"}]},{"id":2,"text":"How many more voted for Summer than Winter in the graph above?","type":"multiple_choice","correct_answer":"12 more","explanation":"18 - 6 = 12.","standard_code":"2.MD.10","difficulty":2,"options":[{"label":"18 more","value":"18 more"},{"label":"12 more","value":"12 more"},{"label":"24 more","value":"24 more"},{"label":"6 more","value":"6 more"}]},{"id":3,"text":"Total votes (Spring=12, Summer=18, Fall=9, Winter=6):","type":"numeric","correct_answer":"45","explanation":"12 + 18 + 9 + 6 = 45.","standard_code":"2.MD.10","difficulty":2},{"id":4,"text":"A class surveyed 30 students. 12 liked pizza and 8 liked salad. How many liked other foods?","type":"numeric","correct_answer":"10","explanation":"30 - 12 - 8 = 10.","standard_code":"2.MD.10","difficulty":2},{"id":5,"text":"A picture graph: each symbol = 2 students. There are 4 symbols for cats. How many students chose cats?","type":"numeric","correct_answer":"8","explanation":"4 symbols x 2 = 8 students.","standard_code":"2.MD.10","difficulty":2}]'::jsonb);

VALUES (2,'MD','2.MD.10','Draw Picture Graphs and Bar Graphs; Solve Problems from Graphs (Hard)','Students draw picture graphs and bar graphs (with single-unit scale) to represent data with up to four categories. They solve addition and subtraction problems using information from graphs, including','practice',3,20,132,'[{"id":1,"text":"Bar graph: soccer=15, basketball=9, tennis=6, swimming=12. How many more chose soccer+basketball than tennis+swimming?","type":"multiple_choice","correct_answer":"6 more","explanation":"Soccer+basketball: 15+9=24. Tennis+swimming: 6+12=18. 24-18=6.","standard_code":"2.MD.10","difficulty":3,"options":[{"label":"3 more","value":"3 more"},{"label":"9 more","value":"9 more"},{"label":"6 more","value":"6 more"},{"label":"12 more","value":"12 more"}]},{"id":2,"text":"Bar graph scores: Ana=85, Ben=70, Carl=90, Dee=75. How much higher is the highest score than the lowest?","type":"numeric","correct_answer":"20","explanation":"Highest: Carl=90. Lowest: Ben=70. 90-70=20.","standard_code":"2.MD.10","difficulty":3},{"id":3,"text":"A pictograph has 3 rows: Row 1 = 4 symbols, Row 2 = 6 symbols, Row 3 = 2 symbols. Each symbol = 3 students. How many students total?","type":"numeric","correct_answer":"36","explanation":"(4+6+2) x 3 = 12 x 3 = 36 students.","standard_code":"2.MD.10","difficulty":3},{"id":4,"text":"28 students surveyed. 10 like math, 8 like reading. How many like something else?","type":"numeric","correct_answer":"10","explanation":"28 - 10 - 8 = 10 students.","standard_code":"2.MD.10","difficulty":3},{"id":5,"text":"Bar graph: cats=12, dogs=18, birds=6, fish=9. How many more dogs than birds and fish combined?","type":"multiple_choice","correct_answer":"3 more","explanation":"Birds + fish = 6 + 9 = 15. Dogs = 18. 18 - 15 = 3.","standard_code":"2.MD.10","difficulty":3,"options":[{"label":"3 more","value":"3 more"},{"label":"12 more","value":"12 more"},{"label":"9 more","value":"9 more"},{"label":"6 more","value":"6 more"}]}]'::jsonb);

VALUES (2,'G','2.G.1','Recognize and Draw Shapes; Identify Triangles, Quadrilaterals, Pentagons, Hexagons, Cubes (Easy)','Students recognize and draw shapes based on specified attributes (e.g., a given number of angles or sides). They identify triangles (3 sides), quadrilaterals (4 sides), pentagons (5 sides), hexagons (','practice',1,10,133,'[{"id":1,"text":"How many sides does a pentagon have?","type":"numeric","correct_answer":"5","explanation":"A pentagon has 5 sides (penta = five).","standard_code":"2.G.1","difficulty":1},{"id":2,"text":"How many sides does a hexagon have?","type":"numeric","correct_answer":"6","explanation":"A hexagon has 6 sides (hexa = six).","standard_code":"2.G.1","difficulty":1},{"id":3,"text":"A quadrilateral has how many sides?","type":"numeric","correct_answer":"4","explanation":"Quadri = four. A quadrilateral has 4 sides.","standard_code":"2.G.1","difficulty":1},{"id":4,"text":"Name two shapes that are quadrilaterals.","type":"multiple_choice","correct_answer":"Square and rectangle (also: rhombus, trapezoid, parallelogram)","explanation":"Any 4-sided polygon is a quadrilateral.","standard_code":"2.G.1","difficulty":1,"options":[{"label":"Triangle and circle","value":"Triangle and circle"},{"label":"Pentagon and hexagon","value":"Pentagon and hexagon"},{"label":"Trapezoid and triangle","value":"Trapezoid and triangle"},{"label":"Square and rectangle (also: rhombus, trapezoid, parallelogram)","value":"Square and rectangle (also: rhombus, trapezoid, parallelogram)"}]},{"id":5,"text":"A cube has how many faces?","type":"numeric","correct_answer":"6","explanation":"A cube has 6 square faces.","standard_code":"2.G.1","difficulty":1}]'::jsonb);

VALUES (2,'G','2.G.1','Recognize and Draw Shapes; Identify Triangles, Quadrilaterals, Pentagons, Hexagons, Cubes (Medium)','Students recognize and draw shapes based on specified attributes (e.g., a given number of angles or sides). They identify triangles (3 sides), quadrilaterals (4 sides), pentagons (5 sides), hexagons (','practice',2,15,134,'[{"id":1,"text":"A hexagon - how many corners does it have?","type":"multiple_choice","correct_answer":"6 corners","explanation":"A regular hexagon has 6 sides and 6 corners (vertices).","standard_code":"2.G.1","difficulty":2,"options":[{"label":"6 corners","value":"6 corners"},{"label":"5 corners","value":"5 corners"},{"label":"8 corners","value":"8 corners"},{"label":"7 corners","value":"7 corners"}]},{"id":2,"text":"What is the difference between a square and a rhombus?","type":"multiple_choice","correct_answer":"A square has 4 right angles; a rhombus has 4 equal sides but angles may not be right.","explanation":"Both are quadrilaterals with 4 equal sides, but a square must have right angles.","standard_code":"2.G.1","difficulty":2,"options":[{"label":"A square has 4 right angles; a rhombus has 4 equal sides but angles may not be right.","value":"A square has 4 right angles; a rhombus has 4 equal sides but angles may not be right."},{"label":"A rhombus has 4 right angles; a square does not.","value":"A rhombus has 4 right angles; a square does not."},{"label":"A square has 4 sides; a rhombus has 6 sides.","value":"A square has 4 sides; a rhombus has 6 sides."},{"label":"They are the same shape with different names.","value":"They are the same shape with different names."}]},{"id":3,"text":"How many edges does a cube have?","type":"multiple_choice","correct_answer":"12 edges","explanation":"A cube has 12 edges: 4 on top, 4 on bottom, 4 vertical.","standard_code":"2.G.1","difficulty":2,"options":[{"label":"6 edges","value":"6 edges"},{"label":"10 edges","value":"10 edges"},{"label":"8 edges","value":"8 edges"},{"label":"12 edges","value":"12 edges"}]},{"id":4,"text":"Is a stop sign a hexagon or an octagon?","type":"multiple_choice","correct_answer":"Octagon","explanation":"A stop sign has 8 sides = octagon (octo = eight).","standard_code":"2.G.1","difficulty":2,"options":[{"label":"Octagon","value":"Octagon"},{"label":"Pentagon","value":"Pentagon"},{"label":"Triangle","value":"Triangle"},{"label":"Hexagon","value":"Hexagon"}]},{"id":5,"text":"Name a quadrilateral that is NOT a rectangle.","type":"multiple_choice","correct_answer":"Rhombus, parallelogram, or trapezoid","explanation":"Many 4-sided shapes are not rectangles. A rhombus has 4 equal sides but no right angles.","standard_code":"2.G.1","difficulty":2,"options":[{"label":"Pentagon, hexagon","value":"Pentagon, hexagon"},{"label":"Square, rectangle","value":"Square, rectangle"},{"label":"Triangle, circle","value":"Triangle, circle"},{"label":"Rhombus, parallelogram, or trapezoid","value":"Rhombus, parallelogram, or trapezoid"}]}]'::jsonb);

VALUES (2,'G','2.G.1','Recognize and Draw Shapes; Identify Triangles, Quadrilaterals, Pentagons, Hexagons, Cubes (Hard)','Students recognize and draw shapes based on specified attributes (e.g., a given number of angles or sides). They identify triangles (3 sides), quadrilaterals (4 sides), pentagons (5 sides), hexagons (','practice',3,20,135,'[{"id":1,"text":"A shape has 5 equal sides. What is it? Is it a polygon?","type":"multiple_choice","correct_answer":"Regular pentagon; yes, it is a polygon","explanation":"5 equal sides = regular pentagon. All closed figures with straight sides are polygons.","standard_code":"2.G.1","difficulty":3,"options":[{"label":"Regular hexagon; no, it is not a polygon","value":"Regular hexagon; no, it is not a polygon"},{"label":"Square; yes, it is a polygon","value":"Square; yes, it is a polygon"},{"label":"Pentagon; no, it is not a polygon","value":"Pentagon; no, it is not a polygon"},{"label":"Regular pentagon; yes, it is a polygon","value":"Regular pentagon; yes, it is a polygon"}]},{"id":2,"text":"Can a triangle be a quadrilateral?","type":"multiple_choice","correct_answer":"No","explanation":"A triangle has 3 sides; a quadrilateral has 4. They cannot be the same shape.","standard_code":"2.G.1","difficulty":3,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]},{"id":3,"text":"How many vertices (corners) does a cube have?","type":"multiple_choice","correct_answer":"8 vertices","explanation":"A cube has 8 corners: 4 on the top face and 4 on the bottom face.","standard_code":"2.G.1","difficulty":3,"options":[{"label":"12 vertices","value":"12 vertices"},{"label":"8 vertices","value":"8 vertices"},{"label":"6 vertices","value":"6 vertices"},{"label":"4 vertices","value":"4 vertices"}]},{"id":4,"text":"Name two shapes that have all sides equal AND all angles equal.","type":"multiple_choice","correct_answer":"Equilateral triangle and square (also: regular pentagon, regular hexagon)","explanation":"Equilateral triangle: 3 equal sides and angles. Square: 4 equal sides and right angles.","standard_code":"2.G.1","difficulty":3,"options":[{"label":"Equilateral triangle and square (also: regular pentagon, regular hexagon)","value":"Equilateral triangle and square (also: regular pentagon, regular hexagon)"},{"label":"Pentagon and rectangle","value":"Pentagon and rectangle"},{"label":"Square and circle","value":"Square and circle"},{"label":"Triangle and hexagon","value":"Triangle and hexagon"}]},{"id":5,"text":"How is a pentagon different from a hexagon?","type":"multiple_choice","correct_answer":"Pentagon has 5 sides and 5 corners; hexagon has 6 sides and 6 corners.","explanation":"Penta = 5, hexa = 6. They differ in the number of sides and corners.","standard_code":"2.G.1","difficulty":3,"options":[{"label":"Pentagon has 4 sides; hexagon has 6 sides.","value":"Pentagon has 4 sides; hexagon has 6 sides."},{"label":"Pentagon has 6 sides and 6 corners; hexagon has 5 sides and 5 corners.","value":"Pentagon has 6 sides and 6 corners; hexagon has 5 sides and 5 corners."},{"label":"They are the same shape.","value":"They are the same shape."},{"label":"Pentagon has 5 sides and 5 corners; hexagon has 6 sides and 6 corners.","value":"Pentagon has 5 sides and 5 corners; hexagon has 6 sides and 6 corners."}]}]'::jsonb);

VALUES (2,'G','2.G.2','Partition Rectangles into Same-Size Squares; Count Them (Easy)','Students partition a rectangle into rows and columns of same-size unit squares and count to find the total. They write addition equations with equal addends (one per row) to represent the total. This ','practice',1,10,136,'[{"id":1,"text":"A rectangle is divided into 2 rows and 3 columns of squares. How many squares total?","type":"numeric","correct_answer":"6","explanation":"2 rows x 3 columns: 3 + 3 = 6 squares.","standard_code":"2.G.2","difficulty":1},{"id":2,"text":"A rectangle has 4 rows of 2 squares each. How many squares?","type":"numeric","correct_answer":"8","explanation":"4 rows of 2: 2 + 2 + 2 + 2 = 8 squares.","standard_code":"2.G.2","difficulty":1},{"id":3,"text":"A 3 x 3 grid - how many squares?","type":"numeric","correct_answer":"9","explanation":"3 rows of 3: 3 + 3 + 3 = 9 squares.","standard_code":"2.G.2","difficulty":1},{"id":4,"text":"A rectangle has 1 row of 5 squares. How many squares?","type":"numeric","correct_answer":"5","explanation":"1 x 5 = 5 squares.","standard_code":"2.G.2","difficulty":1},{"id":5,"text":"Count the squares in a 2 x 4 grid.","type":"numeric","correct_answer":"8","explanation":"2 rows of 4: 4 + 4 = 8 squares.","standard_code":"2.G.2","difficulty":1}]'::jsonb);

VALUES (2,'G','2.G.2','Partition Rectangles into Same-Size Squares; Count Them (Medium)','Students partition a rectangle into rows and columns of same-size unit squares and count to find the total. They write addition equations with equal addends (one per row) to represent the total. This ','practice',2,15,137,'[{"id":1,"text":"Divide a rectangle into 3 rows and 4 columns. Write the addition equation.","type":"multiple_choice","correct_answer":"4 + 4 + 4 = 12","explanation":"3 rows of 4 squares: 4 + 4 + 4 = 12 squares.","standard_code":"2.G.2","difficulty":2,"options":[{"label":"3 + 3 + 3 + 3 = 12","value":"3 + 3 + 3 + 3 = 12"},{"label":"3 + 4 + 5 = 12","value":"3 + 4 + 5 = 12"},{"label":"4 + 4 + 4 = 12","value":"4 + 4 + 4 = 12"},{"label":"3 + 3 + 3 = 9","value":"3 + 3 + 3 = 9"}]},{"id":2,"text":"A rectangle has 20 squares in 4 equal rows. How many squares are in each row?","type":"numeric","correct_answer":"5","explanation":"20 / 4 = 5 squares per row.","standard_code":"2.G.2","difficulty":2},{"id":3,"text":"How many squares in a 5 x 4 rectangle grid? Write an equation.","type":"multiple_choice","correct_answer":"20; 4 + 4 + 4 + 4 + 4 = 20","explanation":"5 rows of 4 squares each.","standard_code":"2.G.2","difficulty":2,"options":[{"label":"25; 5 + 5 + 5 + 5 + 5 = 25","value":"25; 5 + 5 + 5 + 5 + 5 = 25"},{"label":"20; 4 + 4 + 4 + 4 + 4 = 20","value":"20; 4 + 4 + 4 + 4 + 4 = 20"},{"label":"16; 4 + 4 + 4 + 4 = 16","value":"16; 4 + 4 + 4 + 4 = 16"},{"label":"15; 3 + 3 + 3 + 3 + 3 = 15","value":"15; 3 + 3 + 3 + 3 + 3 = 15"}]},{"id":4,"text":"A 4 x 4 grid - how many squares? How many per row?","type":"multiple_choice","correct_answer":"16 total; 4 per row","explanation":"4 rows of 4: 4 + 4 + 4 + 4 = 16.","standard_code":"2.G.2","difficulty":2,"options":[{"label":"20 total; 5 per row","value":"20 total; 5 per row"},{"label":"16 total; 4 per row","value":"16 total; 4 per row"},{"label":"12 total; 3 per row","value":"12 total; 3 per row"},{"label":"8 total; 2 per row","value":"8 total; 2 per row"}]},{"id":5,"text":"A tile floor is 3 rows by 6 tiles wide. How many tiles?","type":"numeric","correct_answer":"18","explanation":"3 rows of 6: 6 + 6 + 6 = 18 tiles.","standard_code":"2.G.2","difficulty":2}]'::jsonb);

VALUES (2,'G','2.G.2','Partition Rectangles into Same-Size Squares; Count Them (Hard)','Students partition a rectangle into rows and columns of same-size unit squares and count to find the total. They write addition equations with equal addends (one per row) to represent the total. This ','practice',3,20,138,'[{"id":1,"text":"A rectangle has 24 squares in 4 equal rows. How many are in each row?","type":"numeric","correct_answer":"6","explanation":"24 / 4 = 6 squares per row.","standard_code":"2.G.2","difficulty":3},{"id":2,"text":"Two rectangles: one is 3 x 5, the other is 5 x 3. Do they have the same number of squares?","type":"multiple_choice","correct_answer":"Yes, both have 15","explanation":"3 rows of 5 = 15. 5 rows of 3 = 15. Rotating a rectangle does not change the count.","standard_code":"2.G.2","difficulty":3,"options":[{"label":"No, one has 15 and the other has 20","value":"No, one has 15 and the other has 20"},{"label":"Yes, both have 12","value":"Yes, both have 12"},{"label":"Yes, both have 15","value":"Yes, both have 15"},{"label":"No, one has 15 and the other has 8","value":"No, one has 15 and the other has 8"}]},{"id":3,"text":"A grid has 6 rows of 4 squares. How many total? If you add one more row, how many?","type":"multiple_choice","correct_answer":"24; then 28","explanation":"6 x 4 = 24. Adding a row of 4: 24 + 4 = 28.","standard_code":"2.G.2","difficulty":3,"options":[{"label":"24; then 30","value":"24; then 30"},{"label":"24; then 28","value":"24; then 28"},{"label":"24; then 26","value":"24; then 26"},{"label":"20; then 24","value":"20; then 24"}]},{"id":4,"text":"A rectangle is split into 3 rows and some columns. There are 18 squares. How many columns?","type":"multiple_choice","correct_answer":"6 columns","explanation":"18 / 3 = 6 columns.","standard_code":"2.G.2","difficulty":3,"options":[{"label":"4 columns","value":"4 columns"},{"label":"9 columns","value":"9 columns"},{"label":"3 columns","value":"3 columns"},{"label":"6 columns","value":"6 columns"}]},{"id":5,"text":"A floor is 4 squares wide and 7 squares long. How many tiles are needed?","type":"numeric","correct_answer":"28","explanation":"4 rows of 7: 7 + 7 + 7 + 7 = 28 tiles.","standard_code":"2.G.2","difficulty":3}]'::jsonb);

VALUES (2,'G','2.G.3','Partition into Halves, Thirds, Fourths; Equal Shares (Easy)','Students partition circles and rectangles into two, three, or four equal shares and describe them using the vocabulary: halves, thirds, fourths, quarters. They understand that the more equal parts, th','practice',1,10,139,'[{"id":1,"text":"A circle is divided into 3 equal parts. What is each part called?","type":"multiple_choice","correct_answer":"A third","explanation":"3 equal parts = thirds. Each is one-third of the whole.","standard_code":"2.G.3","difficulty":1,"options":[{"label":"A section","value":"A section"},{"label":"A part","value":"A part"},{"label":"A piece","value":"A piece"},{"label":"A third","value":"A third"}]},{"id":2,"text":"A rectangle is divided into 4 equal parts. What is each part called?","type":"multiple_choice","correct_answer":"A fourth or a quarter","explanation":"4 equal parts = fourths or quarters. Each is one-fourth.","standard_code":"2.G.3","difficulty":1,"options":[{"label":"A fifth or a quint","value":"A fifth or a quint"},{"label":"A fourth or a quarter","value":"A fourth or a quarter"},{"label":"A third","value":"A third"},{"label":"A half or a second","value":"A half or a second"}]},{"id":3,"text":"Which is bigger: 1/2 of a pizza or 1/4 of the same pizza?","type":"numeric","correct_answer":"1/2","explanation":"Fewer pieces means each is larger. Half > quarter.","standard_code":"2.G.3","difficulty":1},{"id":4,"text":"3 thirds = how many wholes?","type":"multiple_choice","correct_answer":"1 whole","explanation":"3/3 = 1 whole.","standard_code":"2.G.3","difficulty":1,"options":[{"label":"3 wholes","value":"3 wholes"},{"label":"1 whole","value":"1 whole"},{"label":"One-third","value":"One-third"},{"label":"2 wholes","value":"2 wholes"}]},{"id":5,"text":"A sandwich is cut into thirds. You eat one piece. How much did you eat?","type":"multiple_choice","correct_answer":"One-third (1/3)","explanation":"1 out of 3 equal pieces = one-third.","standard_code":"2.G.3","difficulty":1,"options":[{"label":"One-fourth (1/4)","value":"One-fourth (1/4)"},{"label":"Two-thirds (2/3)","value":"Two-thirds (2/3)"},{"label":"One-half (1/2)","value":"One-half (1/2)"},{"label":"One-third (1/3)","value":"One-third (1/3)"}]}]'::jsonb);

VALUES (2,'G','2.G.3','Partition into Halves, Thirds, Fourths; Equal Shares (Medium)','Students partition circles and rectangles into two, three, or four equal shares and describe them using the vocabulary: halves, thirds, fourths, quarters. They understand that the more equal parts, th','practice',2,15,140,'[{"id":1,"text":"Which is smallest: one-half, one-third, or one-fourth?","type":"multiple_choice","correct_answer":"One-fourth","explanation":"More pieces means each is smaller. 1/4 < 1/3 < 1/2.","standard_code":"2.G.3","difficulty":2,"options":[{"label":"One-third","value":"One-third"},{"label":"One-half","value":"One-half"},{"label":"One-fourth","value":"One-fourth"},{"label":"They are all equal","value":"They are all equal"}]},{"id":2,"text":"A pie is cut into 3 equal pieces. Two pieces are eaten. How much is left?","type":"multiple_choice","correct_answer":"One-third","explanation":"3 pieces - 2 eaten = 1 piece left. 1/3 of the pie remains.","standard_code":"2.G.3","difficulty":2,"options":[{"label":"Two-fifths","value":"Two-fifths"},{"label":"One-third","value":"One-third"},{"label":"One-half","value":"One-half"},{"label":"Two-thirds","value":"Two-thirds"}]},{"id":3,"text":"Kate has 1/4 of a cake. Tom has 1/2. Who has more?","type":"multiple_choice","correct_answer":"Tom","explanation":"1/2 > 1/4. Tom has more cake.","standard_code":"2.G.3","difficulty":2,"options":[{"label":"Kate","value":"Kate"},{"label":"They have the same amount","value":"They have the same amount"},{"label":"Tom","value":"Tom"},{"label":"Not enough information","value":"Not enough information"}]},{"id":4,"text":"A rectangle is cut into thirds horizontally. Each strip is what fraction of the whole?","type":"multiple_choice","correct_answer":"One-third (1/3)","explanation":"Three equal horizontal strips; each is 1/3 of the rectangle.","standard_code":"2.G.3","difficulty":2,"options":[{"label":"One-third (1/3)","value":"One-third (1/3)"},{"label":"One-ninth (1/9)","value":"One-ninth (1/9)"},{"label":"Two-thirds (2/3)","value":"Two-thirds (2/3)"},{"label":"One-half (1/2)","value":"One-half (1/2)"}]},{"id":5,"text":"4 fourths = ___ halves = ___ whole","type":"multiple_choice","correct_answer":"2 halves = 1 whole","explanation":"4/4 = 1. And 2/2 = 1. Both equal 1 whole.","standard_code":"2.G.3","difficulty":2,"options":[{"label":"4 halves = 2 wholes","value":"4 halves = 2 wholes"},{"label":"2 halves = 1 whole","value":"2 halves = 1 whole"},{"label":"2 halves = 2 wholes","value":"2 halves = 2 wholes"},{"label":"3 halves = 2 wholes","value":"3 halves = 2 wholes"}]}]'::jsonb);

VALUES (2,'G','2.G.3','Partition into Halves, Thirds, Fourths; Equal Shares (Hard)','Students partition circles and rectangles into two, three, or four equal shares and describe them using the vocabulary: halves, thirds, fourths, quarters. They understand that the more equal parts, th','practice',3,20,141,'[{"id":1,"text":"Can a circle be divided into thirds? How?","type":"multiple_choice","correct_answer":"Yes, by making 3 equal-sized \"pie slices\" (each 120 degrees)","explanation":"Divide the circle into 3 equal wedges. Each is one-third of the circle.","standard_code":"2.G.3","difficulty":3,"options":[{"label":"No, circles cannot be divided equally","value":"No, circles cannot be divided equally"},{"label":"Yes, by making 3 equal-sized \"pie slices\" (each 120 degrees)","value":"Yes, by making 3 equal-sized \"pie slices\" (each 120 degrees)"},{"label":"Yes, by making 3 equal horizontal lines","value":"Yes, by making 3 equal horizontal lines"},{"label":"Yes, by drawing 3 squares inside it","value":"Yes, by drawing 3 squares inside it"}]},{"id":2,"text":"A shape is divided into 4 equal parts that are not all the same shape. Can these still be called fourths?","type":"multiple_choice","correct_answer":"Yes","explanation":"Equal shares need equal area, not the same shape. They are still fourths.","standard_code":"2.G.3","difficulty":3,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]},{"id":3,"text":"You have 3 cookies. You eat 1/3 of your total. How many did you eat?","type":"multiple_choice","correct_answer":"1 cookie","explanation":"1/3 of 3 = 1 cookie.","standard_code":"2.G.3","difficulty":3,"options":[{"label":"3 cookies","value":"3 cookies"},{"label":"2 cookies","value":"2 cookies"},{"label":"1 cookie","value":"1 cookie"},{"label":"One-third of a cookie","value":"One-third of a cookie"}]},{"id":4,"text":"A rectangle is divided into 8 equal parts (4 rows, 2 columns). What fraction is each part?","type":"multiple_choice","correct_answer":"One-eighth (1/8)","explanation":"8 equal parts = eighths. Each part is 1/8 of the whole.","standard_code":"2.G.3","difficulty":3,"options":[{"label":"One-eighth (1/8)","value":"One-eighth (1/8)"},{"label":"One-tenth (1/10)","value":"One-tenth (1/10)"},{"label":"One-fourth (1/4)","value":"One-fourth (1/4)"},{"label":"One-sixth (1/6)","value":"One-sixth (1/6)"}]},{"id":5,"text":"Which is greater: 2/4 or 1/2? Explain.","type":"multiple_choice","correct_answer":"They are equal","explanation":"2/4 = 1/2. Two fourths equals one half - they represent the same amount.","standard_code":"2.G.3","difficulty":3,"options":[{"label":"They cannot be compared","value":"They cannot be compared"},{"label":"1/2 is greater","value":"1/2 is greater"},{"label":"They are equal","value":"They are equal"},{"label":"2/4 is greater","value":"2/4 is greater"}]}]'::jsonb);

