VALUES (3,'OA','3.OA.1','Interpret Products of Whole Numbers (Easy)','Practice Interpret Products of Whole Numbers','practice',1,10,142,'[{"id":1,"text":"What does 3 x 4 mean?","type":"multiple_choice","correct_answer":"3 groups of 4, which equals 12","explanation":"3 x 4 means 3 groups with 4 in each group: 4 + 4 + 4 = 12.","standard_code":"3.OA.1","difficulty":1,"options":[{"label":"4 groups of 3, which equals 7","value":"4 groups of 3, which equals 7"},{"label":"3 groups of 4, which equals 7","value":"3 groups of 4, which equals 7"},{"label":"12 individual items","value":"12 individual items"},{"label":"3 groups of 4, which equals 12","value":"3 groups of 4, which equals 12"}]},{"id":2,"text":"There are 2 bags with 5 apples each. Write a multiplication equation.","type":"multiple_choice","correct_answer":"2 x 5 = 10","explanation":"2 groups of 5: 2 x 5 = 10 apples.","standard_code":"3.OA.1","difficulty":1,"options":[{"label":"2 x 5 = 12","value":"2 x 5 = 12"},{"label":"2 x 5 = 10","value":"2 x 5 = 10"},{"label":"5 x 2 = 10","value":"5 x 2 = 10"},{"label":"2 + 5 = 7","value":"2 + 5 = 7"}]},{"id":3,"text":"What does 5 x 2 mean?","type":"multiple_choice","correct_answer":"5 groups of 2, which equals 10","explanation":"5 x 2 = 2 + 2 + 2 + 2 + 2 = 10.","standard_code":"3.OA.1","difficulty":1,"options":[{"label":"2 groups of 5, which equals 10","value":"2 groups of 5, which equals 10"},{"label":"10 groups of 2, which equals 20","value":"10 groups of 2, which equals 20"},{"label":"5 groups of 5, which equals 25","value":"5 groups of 5, which equals 25"},{"label":"5 groups of 2, which equals 10","value":"5 groups of 2, which equals 10"}]},{"id":4,"text":"Draw an array for 2 x 3. How many total?","type":"multiple_choice","correct_answer":"6 (2 rows of 3)","explanation":"2 rows with 3 in each row: 3 + 3 = 6.","standard_code":"3.OA.1","difficulty":1,"options":[{"label":"6 (2 rows of 3)","value":"6 (2 rows of 3)"},{"label":"5 (2 rows of 3)","value":"5 (2 rows of 3)"},{"label":"8 (3 rows of 2)","value":"8 (3 rows of 2)"},{"label":"5 (3 rows of 2)","value":"5 (3 rows of 2)"}]},{"id":5,"text":"There are 4 plates with 2 cookies each. How many cookies?","type":"multiple_choice","correct_answer":"8 (4 x 2 = 8)","explanation":"4 groups of 2: 2 + 2 + 2 + 2 = 8.","standard_code":"3.OA.1","difficulty":1,"options":[{"label":"6 (4 x 2 = 6)","value":"6 (4 x 2 = 6)"},{"label":"2 (4 ÷ 2 = 2)","value":"2 (4 ÷ 2 = 2)"},{"label":"10 (4 + 2 = 10)","value":"10 (4 + 2 = 10)"},{"label":"8 (4 x 2 = 8)","value":"8 (4 x 2 = 8)"}]}]'::jsonb);

VALUES (3,'OA','3.OA.1','Interpret Products of Whole Numbers (Medium)','Practice Interpret Products of Whole Numbers','practice',2,15,143,'[{"id":1,"text":"Describe a real-world situation for 6 x 3.","type":"multiple_choice","correct_answer":"Example: 6 baskets with 3 oranges each = 18 oranges","explanation":"6 x 3 = 18. Any situation with 6 equal groups of 3.","standard_code":"3.OA.1","difficulty":2,"options":[{"label":"Example: 3 baskets with 6 oranges each = 18 oranges","value":"Example: 3 baskets with 6 oranges each = 18 oranges"},{"label":"Example: 6 baskets with 3 oranges each = 18 oranges","value":"Example: 6 baskets with 3 oranges each = 18 oranges"},{"label":"Example: 6 oranges divided into 3 groups = 2 oranges each","value":"Example: 6 oranges divided into 3 groups = 2 oranges each"},{"label":"Example: 6 baskets with 6 oranges each = 36 oranges","value":"Example: 6 baskets with 6 oranges each = 36 oranges"}]},{"id":2,"text":"An array shows 4 rows and 5 columns. Write the multiplication.","type":"multiple_choice","correct_answer":"4 x 5 = 20","explanation":"4 rows of 5 = 20 total objects.","standard_code":"3.OA.1","difficulty":2,"options":[{"label":"5 x 4 = 20","value":"5 x 4 = 20"},{"label":"4 + 5 = 9","value":"4 + 5 = 9"},{"label":"4 x 5 = 20","value":"4 x 5 = 20"},{"label":"9 x 20 = 180","value":"9 x 20 = 180"}]},{"id":3,"text":"Write 7 x 3 as repeated addition.","type":"multiple_choice","correct_answer":"3 + 3 + 3 + 3 + 3 + 3 + 3 = 21","explanation":"7 groups of 3 added together = 21.","standard_code":"3.OA.1","difficulty":2,"options":[{"label":"7 + 7 + 7 = 21","value":"7 + 7 + 7 = 21"},{"label":"7 + 3 = 10","value":"7 + 3 = 10"},{"label":"3 + 3 + 3 = 9","value":"3 + 3 + 3 = 9"},{"label":"3 + 3 + 3 + 3 + 3 + 3 + 3 = 21","value":"3 + 3 + 3 + 3 + 3 + 3 + 3 = 21"}]},{"id":4,"text":"There are 8 packs of markers with 3 in each. How many markers?","type":"multiple_choice","correct_answer":"24 (8 x 3 = 24)","explanation":"8 x 3 = 24 markers total.","standard_code":"3.OA.1","difficulty":2,"options":[{"label":"32 (8 x 4 = 32)","value":"32 (8 x 4 = 32)"},{"label":"21 (8 x 3 - 3 = 21)","value":"21 (8 x 3 - 3 = 21)"},{"label":"24 (8 x 3 = 24)","value":"24 (8 x 3 = 24)"},{"label":"11 (8 + 3 = 11)","value":"11 (8 + 3 = 11)"}]},{"id":5,"text":"Is 5 x 4 the same as 4 + 4 + 4 + 4 + 4? Explain.","type":"multiple_choice","correct_answer":"Yes, both equal 20","explanation":"5 x 4 means 5 groups of 4. Adding 4 five times = 20.","standard_code":"3.OA.1","difficulty":2,"options":[{"label":"Yes, both equal 20","value":"Yes, both equal 20"},{"label":"No, 5 x 4 equals 20 but repeated addition is different","value":"No, 5 x 4 equals 20 but repeated addition is different"},{"label":"No, 5 x 4 equals 25","value":"No, 5 x 4 equals 25"},{"label":"Yes, both equal 25","value":"Yes, both equal 25"}]}]'::jsonb);

VALUES (3,'OA','3.OA.1','Interpret Products of Whole Numbers (Hard)','Practice Interpret Products of Whole Numbers','practice',3,20,144,'[{"id":1,"text":"Jake says 3 x 8 means ''3 added 8 times.'' Is he right?","type":"multiple_choice","correct_answer":"Not exactly; it means 3 groups of 8 (or 8 + 8 + 8 = 24)","explanation":"3 x 8 = 3 groups of 8 = 8 + 8 + 8 = 24. It could also be read as 8 groups of 3.","standard_code":"3.OA.1","difficulty":3,"options":[{"label":"Yes, he is correct","value":"Yes, he is correct"},{"label":"Not quite; it means 8 added 3 times (8 + 8 + 8 = 24)","value":"Not quite; it means 8 added 3 times (8 + 8 + 8 = 24)"},{"label":"No, 3 x 8 means 3 + 8","value":"No, 3 x 8 means 3 + 8"},{"label":"Not exactly; it means 3 groups of 8 (or 8 + 8 + 8 = 24)","value":"Not exactly; it means 3 groups of 8 (or 8 + 8 + 8 = 24)"}]},{"id":2,"text":"Write a word problem for 9 x 4.","type":"multiple_choice","correct_answer":"Example: There are 9 rows of desks with 4 desks in each row. How many desks?","explanation":"9 x 4 = 36. Any context with 9 equal groups of 4.","standard_code":"3.OA.1","difficulty":3,"options":[{"label":"Example: There are 9 rows of desks with 4 desks in each row. How many desks?","value":"Example: There are 9 rows of desks with 4 desks in each row. How many desks?"},{"label":"Example: 4 rows with 9 desks in each row. How many desks?","value":"Example: 4 rows with 9 desks in each row. How many desks?"},{"label":"Example: 9 plus 4 equals what?","value":"Example: 9 plus 4 equals what?"},{"label":"Example: There are 9 pencils and 4 children. How many pencils each?","value":"Example: There are 9 pencils and 4 children. How many pencils each?"}]},{"id":3,"text":"Is 6 x 5 the same as 5 x 6? Explain using arrays.","type":"multiple_choice","correct_answer":"Yes, both = 30","explanation":"6 x 5: 6 rows of 5. 5 x 6: 5 rows of 6. Both give 30 (commutative property).","standard_code":"3.OA.1","difficulty":3,"options":[{"label":"No, 6 x 5 = 30 and 5 x 6 = 35","value":"No, 6 x 5 = 30 and 5 x 6 = 35"},{"label":"Yes, both equal 35","value":"Yes, both equal 35"},{"label":"No, they are different because 6 x 5 = 30 but 5 x 6 = 25","value":"No, they are different because 6 x 5 = 30 but 5 x 6 = 25"},{"label":"Yes, both = 30","value":"Yes, both = 30"}]},{"id":4,"text":"A classroom has 7 tables with 4 students at each. Write two multiplication equations.","type":"multiple_choice","correct_answer":"7 x 4 = 28 and 4 x 7 = 28","explanation":"Both describe the same total: 28 students.","standard_code":"3.OA.1","difficulty":3,"options":[{"label":"7 + 4 = 11 and 4 + 7 = 11","value":"7 + 4 = 11 and 4 + 7 = 11"},{"label":"7 x 4 = 28 and 4 x 7 = 28","value":"7 x 4 = 28 and 4 x 7 = 28"},{"label":"7 x 4 = 28 and 7 x 7 = 49","value":"7 x 4 = 28 and 7 x 7 = 49"},{"label":"7 x 4 = 32 and 4 x 7 = 32","value":"7 x 4 = 32 and 4 x 7 = 32"}]},{"id":5,"text":"Write 8 x 5 as repeated addition, then find the product.","type":"multiple_choice","correct_answer":"5+5+5+5+5+5+5+5 = 40","explanation":"8 groups of 5 = 40.","standard_code":"3.OA.1","difficulty":3,"options":[{"label":"8+8+8+8+8+8+8+8 = 64","value":"8+8+8+8+8+8+8+8 = 64"},{"label":"5+5+5+5+5+5+5+5 = 40","value":"5+5+5+5+5+5+5+5 = 40"},{"label":"5+5+5+5+5+5+5 = 35","value":"5+5+5+5+5+5+5 = 35"},{"label":"8+8+8+8+8 = 40","value":"8+8+8+8+8 = 40"}]}]'::jsonb);

VALUES (3,'OA','3.OA.2','Interpret Whole-Number Quotients (Easy)','Practice Interpret Whole-Number Quotients','practice',1,10,145,'[{"id":1,"text":"12 cookies are shared equally among 3 friends. How many does each get?","type":"multiple_choice","correct_answer":"4 cookies (12 / 3 = 4)","explanation":"12 / 3 = 4. Each friend gets 4 cookies.","standard_code":"3.OA.2","difficulty":1,"options":[{"label":"4 cookies (12 / 3 = 4)","value":"4 cookies (12 / 3 = 4)"},{"label":"5 cookies (12 / 3 = 4)","value":"5 cookies (12 / 3 = 4)"},{"label":"6 cookies (12 / 2 = 6)","value":"6 cookies (12 / 2 = 6)"},{"label":"3 cookies (12 / 4 = 3)","value":"3 cookies (12 / 4 = 3)"}]},{"id":2,"text":"What does 10 / 2 mean?","type":"multiple_choice","correct_answer":"10 objects split into 2 equal groups = 5 in each","explanation":"10 / 2 = 5. Two groups of 5.","standard_code":"3.OA.2","difficulty":1,"options":[{"label":"10 minus 2 equals 8","value":"10 minus 2 equals 8"},{"label":"10 plus 2 equals 12","value":"10 plus 2 equals 12"},{"label":"10 objects split into 2 equal groups = 5 in each","value":"10 objects split into 2 equal groups = 5 in each"},{"label":"10 objects split into equal groups of 2 = 10 total","value":"10 objects split into equal groups of 2 = 10 total"}]},{"id":3,"text":"8 stickers are shared equally between 2 children. How many each?","type":"multiple_choice","correct_answer":"4 (8 / 2 = 4)","explanation":"8 / 2 = 4 stickers each.","standard_code":"3.OA.2","difficulty":1,"options":[{"label":"6 (8 - 2 = 6)","value":"6 (8 - 2 = 6)"},{"label":"3 (8 / 2 = 4)","value":"3 (8 / 2 = 4)"},{"label":"4 (8 / 2 = 4)","value":"4 (8 / 2 = 4)"},{"label":"2 (8 / 4 = 2)","value":"2 (8 / 4 = 2)"}]},{"id":4,"text":"15 pencils put into groups of 5. How many groups?","type":"multiple_choice","correct_answer":"3 groups (15 / 5 = 3)","explanation":"15 / 5 = 3. You can make 3 groups of 5.","standard_code":"3.OA.2","difficulty":1,"options":[{"label":"5 groups (15 / 3 = 5)","value":"5 groups (15 / 3 