VALUES (3,'OA','3.OA.2','Interpret Whole-Number Quotients (Medium)','Practice Interpret Whole-Number Quotients','practice',2,15,146,'[{"id":1,"text":"24 students sit in rows of 6. How many rows?","type":"multiple_choice","correct_answer":"4 rows (24 / 6 = 4)","explanation":"24 / 6 = 4 rows.","standard_code":"3.OA.2","difficulty":2,"options":[{"label":"4 rows (24 / 6 = 4)","value":"4 rows (24 / 6 = 4)"},{"label":"6 rows (24 / 4 = 6)","value":"6 rows (24 / 4 = 6)"},{"label":"18 rows (24 - 6 = 18)","value":"18 rows (24 - 6 = 18)"},{"label":"30 rows (24 + 6 = 30)","value":"30 rows (24 + 6 = 30)"}]},{"id":2,"text":"Describe a situation for 36 / 9.","type":"multiple_choice","correct_answer":"Example: 36 books on 9 shelves = 4 books per shelf","explanation":"36 / 9 = 4. 36 objects split into 9 equal groups.","standard_code":"3.OA.2","difficulty":2,"options":[{"label":"Example: 36 books on 9 shelves = 4 books per shelf","value":"Example: 36 books on 9 shelves = 4 books per shelf"},{"label":"Example: 36 stickers on 6 pages = 6 stickers per page","value":"Example: 36 stickers on 6 pages = 6 stickers per page"},{"label":"Example: 36 apples divided among 4 kids = 9 apples each","value":"Example: 36 apples divided among 4 kids = 9 apples each"},{"label":"Example: 36 divided by 6 = 6","value":"Example: 36 divided by 6 = 6"}]},{"id":3,"text":"There are 28 grapes. Each bag holds 7 grapes. How many bags?","type":"multiple_choice","correct_answer":"4 bags (28 / 7 = 4)","explanation":"28 / 7 = 4 bags.","standard_code":"3.OA.2","difficulty":2,"options":[{"label":"7 bags (28 / 4 = 7)","value":"7 bags (28 / 4 = 7)"},{"label":"21 bags (28 - 7 = 21)","value":"21 bags (28 - 7 = 21)"},{"label":"4 bags (28 / 7 = 4)","value":"4 bags (28 / 7 = 4)"},{"label":"3 bags (28 / 7 = 4)","value":"3 bags (28 / 7 = 4)"}]},{"id":4,"text":"40 crayons are shared equally among 8 children. How many each?","type":"multiple_choice","correct_answer":"5 (40 / 8 = 5)","explanation":"40 / 8 = 5 crayons per child.","standard_code":"3.OA.2","difficulty":2,"options":[{"label":"8 (40 / 5 = 8)","value":"8 (40 / 5 = 8)"},{"label":"6 (40 - 8 = 32)","value":"6 (40 - 8 = 32)"},{"label":"5 (40 / 8 = 5)","value":"5 (40 / 8 = 5)"},{"label":"3 (40 / 8 = 5)","value":"3 (40 / 8 = 5)"}]},{"id":5,"text":"What does 42 / 6 mean? Find the answer.","type":"multiple_choice","correct_answer":"7 (42 split into 6 groups or groups of 6)","explanation":"42 / 6 = 7. Either 6 groups of 7 or 7 groups of 6.","standard_code":"3.OA.2","difficulty":2,"options":[{"label":"6 (42 / 7 = 6)","value":"6 (42 / 7 = 6)"},{"label":"7 (42 split into 6 groups or groups of 6)","value":"7 (42 split into 6 groups or groups of 6)"},{"label":"48 (42 + 6 = 48)","value":"48 (42 + 6 = 48)"},{"label":"36 (42 - 6 = 36)","value":"36 (42 - 6 = 36)"}]}]'::jsonb);

VALUES (3,'OA','3.OA.2','Interpret Whole-Number Quotients (Hard)','Practice Interpret Whole-Number Quotients','practice',3,20,147,'[{"id":1,"text":"56 / 8 = ?. Describe two different sharing situations.","type":"numeric","correct_answer":"7","explanation":"Situation 1: 56 items shared among 8 people = 7 each. Situation 2: 56 items in groups of 8 = 7 groups.","standard_code":"3.OA.2","difficulty":3},{"id":2,"text":"A baker has 72 muffins. He puts 9 in each box. How many boxes?","type":"multiple_choice","correct_answer":"8 boxes (72 / 9 = 8)","explanation":"72 / 9 = 8 boxes.","standard_code":"3.OA.2","difficulty":3,"options":[{"label":"63 boxes (72 - 9 = 63)","value":"63 boxes (72 - 9 = 63)"},{"label":"9 boxes (72 / 8 = 9)","value":"9 boxes (72 / 8 = 9)"},{"label":"8 boxes (72 / 9 = 8)","value":"8 boxes (72 / 9 = 8)"},{"label":"6 boxes (72 / 9 = 8)","value":"6 boxes (72 / 9 = 8)"}]},{"id":3,"text":"There are 63 seats in 7 equal rows. How many seats per row?","type":"multiple_choice","correct_answer":"9 (63 / 7 = 9)","explanation":"63 / 7 = 9 seats per row.","standard_code":"3.OA.2","difficulty":3,"options":[{"label":"10 (63 - 7 = 56)","value":"10 (63 - 7 = 56)"},{"label":"8 (63 / 7 = 9)","value":"8 (63 / 7 = 9)"},{"label":"7 (63 / 9 = 7)","value":"7 (63 / 9 = 7)"},{"label":"9 (63 / 7 = 9)","value":"9 (63 / 7 = 9)"}]},{"id":4,"text":"81 / 9 = ?. Check your answer with multiplication.","type":"multiple_choice","correct_answer":"9 (9 x 9 = 81)","explanation":"81 / 9 = 9. Check: 9 x 9 = 81.","standard_code":"3.OA.2","difficulty":3,"options":[{"label":"8 (8 x 9 = 72)","value":"8 (8 x 9 = 72)"},{"label":"10 (10 x 9 = 90)","value":"10 (10 x 9 = 90)"},{"label":"7 (7 x 9 = 63)","value":"7 (7 x 9 = 63)"},{"label":"9 (9 x 9 = 81)","value":"9 (9 x 9 = 81)"}]},{"id":5,"text":"A library has 48 books to put equally on 6 shelves. How many per shelf? Write the equation.","type":"multiple_choice","correct_answer":"48 / 6 = 8","explanation":"48 / 6 = 8 books per shelf.","standard_code":"3.OA.2","difficulty":3,"options":[{"label":"48 - 6 = 42","value":"48 - 6 = 42"},{"label":"6 x 6 = 36","value":"6 x 6 = 36"},{"label":"48 / 8 = 6","value":"48 / 8 = 6"},{"label":"48 / 6 = 8","value":"48 / 6 = 8"}]}]'::jsonb);

VALUES (3,'OA','3.OA.3','Solve Word Problems Using Multiplication and Division Within 100 (Easy)','Practice Solve Word Problems Using Multiplication and Division Within 100','practice',1,10,148,'[{"id":1,"text":"There are 3 fish tanks with 6 fish in each. How many fish in all?","type":"multiple_choice","correct_answer":"18 (3 x 6 = 18)","explanation":"3 x 6 = 18 fish total.","standard_code":"3.OA.3","difficulty":1,"options":[{"label":"21 (3 x 7 = 21)","value":"21 (3 x 7 = 21)"},{"label":"9 (3 x 3 = 9)","value":"9 (3 x 3 = 9)"},{"label":"24 (3 x 8 = 24)","value":"24 (3 x 8 = 24)"},{"label":"18 (3 x 6 = 18)","value":"18 (3 x 6 = 18)"}]},{"id":2,"text":"20 apples are shared equally among 4 baskets. How many in each?","type":"multiple_choice","correct_answer":"5 (20 / 4 = 5)","explanation":"20 / 4 = 5 apples per basket.","standard_code":"3.OA.3","difficulty":1,"options":[{"label":"24 (20 + 4 = 24)","value":"24 (20 + 4 = 24)"},{"label":"4 (20 / 5 = 4)","value":"4 (20 / 5 = 4)"},{"label":"5 (20 / 4 = 5)","value":"5 (20 / 4 = 5)"},{"label":"16 (20 - 4 = 16)","value":"16 (20 - 4 = 16)"}]},{"id":3,"text":"Each kid gets 3 stickers. There are 5 kids. How many stickers in all?","type":"multiple_choice","correct_answer":"15 (5 x 3 = 15)","explanation":"5 x 3 = 15 stickers.","standard_code":"3.OA.3","difficulty":1,"options":[{"label":"20 (5 x 4 = 20)","value":"20 (5 x 4 = 20)"},{"label":"8 (5 + 3 = 8)","value":"8 (5 + 3 = 8)"},{"label":"2 (5 / 3 = 2 remainder 1)","value":"2 (5 / 3 = 2 remainder 1)"},{"label":"15 (5 x 3 = 15)","value":"15 (5 x 3 = 15)"}]},{"id":4,"text":"18 eggs are in cartons of 6. How many cartons?","type":"multiple_choice","correct_answer":"3 (18 / 6 = 3)","explanation":"18 / 6 = 3 cartons.","standard_code":"3.OA.3","difficulty":1,"options":[{"label":"24 (18 + 6 = 24)","value":"24 (18 + 6 = 24)"},{"label":"2 (18 / 9 = 2)","value":"2 (18 / 9 = 2)"},{"label":"12 (18 - 6 = 12)","value":"12 (18 - 6 = 12)"},{"label":"3 (18 / 6 = 3)","value":"3 (18 / 6 = 3)"}]},{"id":5,"text":"A garden has 4 rows with 7 flowers each. How many flowers?","type":"multiple_choice","correct_answer":"28 (4 x 7 = 28)","explanation":"4 x 7 = 28 flowers.","standard_code":"3.OA.3","difficulty":1,"options":[{"label":"35 (5 x 7 = 35)","value":"35 (5 x 7 = 35)"},{"label":"28 (4 x 7 = 28)","value":"28 (4 x 7 = 28)"},{"label":"32 (4 x 8 = 32)","value":"32 (4 x 8 = 32)"},{"label":"11 (4 + 7 = 11)","value":"11 (4 + 7 = 11)"}]}]'::jsonb);

VALUES (3,'OA','3.OA.3','Solve Word Problems Using Multiplication and Division Within 100 (Medium)','Practice Solve Word Problems Using Multiplication and Division Within 100','practice',2,15,149,'[{"id":1,"text":"A farmer has 54 eggs. He puts 9 in each carton. How many cartons does he fill?","type":"multiple_choice","correct_answer":"6 (54 / 9 = 6)","explanation":"54 / 9 = 6 cartons.","standard_code":"3.OA.3","difficulty":2,"options":[{"label":"63 (54 + 9 = 63)","value":"63 (54 + 9 = 63)"},{"label":"6 (54 / 9 = 6)","value":"6 (54 / 9 = 6)"},{"label":"45 (54 - 9 = 45)","value":"45 (54 - 9 = 45)"},{"label":"5 (54 / 9 = 5)","value":"5 (54 / 9 = 5)"}]},{"id":2,"text":"There are 8 teams with 7 players each. How many players in all?","type":"multiple_choice","correct_answer":"56 (8 x 7 = 56)","explanation":"8 x 7 = 56 players.","standard_code":"3.OA.3","difficulty":2,"options":[{"label":"15 (8 + 7 = 15)","value":"15 (8 + 7 = 15)"},{"label":"49 (7 x 7 = 49)","value":"49 (7 x 7 = 49)"},{"label":"64 (8 x 8 = 64)","value":"64 (8 x 8 = 64)"},{"label":"56 (8 x 7 = 56)","value":"56 (8 x 7 = 56)"}]},{"id":3,"text":"A school bought 48 notebooks for 6 classrooms. Each classroom gets the same amount. How many?","type":"multiple_choice","correct_answer":"8 (48 / 6 = 8)","explanation":"48 / 6 = 8 notebooks per classroom.","standard_code":"3.OA.3","difficulty":2,"options":[{"label":"8 (48 / 6 = 8)","value":"8 (48 / 6 = 8)"},{"label":"42 (48 - 6 = 42)","value":"42 (48 - 6 = 42)"},{"label":"6 (48 / 8 = 6)","value":"6 (48 / 8 = 6)"},{"label":"54 (48 + 6 = 54)","value":"54 (48 + 6 = 54)"}]},{"id":4,"text":"A store has 9 shelves with 8 toys on each. How many toys?","type":"multiple_choice","correct_answer":"72 (9 x 8 = 72)","explanation":"9 x 8 = 72 toys.","standard_code":"3.OA.3","difficulty":2,"options":[{"label":"72 (9 x 8 = 72)","value":"72 (9 x 8 = 72)"},{"label":"64 (8 x 8 = 64)","value":"64 (8 x 8 = 64)"},{"label":"17 (9 + 8 = 17)","value":"17 (9 + 8 = 17)"},{"label":"81 (9 x 9 = 81)","value":"81 (9 x 9 = 81)"}]},{"id":5,"text":"A baker made 35 cookies. He puts 5 in each bag. How many bags?","type":"multiple_choice","correct_answer":"7 (35 / 5 = 7)","explanation":"35 / 5 = 7 bags.","standard_code":"3.OA.3","difficulty":2,"options":[{"label":"30 (35 - 5 = 30)","value":"30 (35 - 5 = 30)"},{"label":"7 (35 / 5 = 7)","value":"7 (35 / 5 = 7)"},{"label":"8 (40 / 5 = 8)","value":"8 (40 / 5 = 8)"},{"label":"175 (35 x 5 = 175)","value":"175 (35 x 5 = 175)"}]}]'::jsonb);

VALUES (3,'OA','3.OA.3','Solve Word Problems Using Multiplication and Division Within 100 (Hard)','Practice Solve Word Problems Using Multiplication and Division Within 100','practice',3,20,150,'[{"id":1,"text":"A hall has 6 rows of chairs with 9 chairs in each row. 15 more chairs are added. How many total?","type":"numeric","correct_answer":"69","explanation":"6 x 9 = 54 chairs. 54 + 15 = 69 total chairs.","standard_code":"3.OA.3","difficulty":3},{"id":2,"text":"There are 72 students going on a field trip. Each bus holds 9 students. How many buses are needed?","type":"multiple_choice","correct_answer":"8 buses (72 / 9 = 8)","explanation":"72 / 9 = 8 buses.","standard_code":"3.OA.3","difficulty":3,"options":[{"label":"63 buses (72 - 9 = 63)","value":"63 buses (72 - 9 = 63)"},{"label":"9 buses (72 / 8 = 9)","value":"9 buses (72 / 8 = 9)"},{"label":"81 buses (72 + 9 = 81)","value":"81 buses (72 + 9 = 81)"},{"label":"8 buses (72 / 9 = 8)","value":"8 buses (72 / 9 = 8)"}]},{"id":3,"text":"Amy has 7 packs of cards with 8 cards each. She gives 16 cards away. How many does she have left?","type":"numeric","correct_answer":"40","explanation":"7 x 8 = 56. 56 - 16 = 40 cards left.","standard_code":"3.OA.3","difficulty":3},{"id":4,"text":"A box holds 6 donuts. A bakery needs to box 42 donuts. How many boxes?","type":"multiple_choice","correct_answer":"7 boxes (42 / 6 = 7)","explanation":"42 / 6 = 7 boxes.","standard_code":"3.OA.3","difficulty":3,"options":[{"label":"8 boxes (48 / 6 = 8)","value":"8 boxes (48 / 6 = 8)"},{"label":"36 boxes (42 - 6 = 36)","value":"36 boxes (42 - 6 = 36)"},{"label":"252 boxes (42 x 6 = 252)","value":"252 boxes (42 x 6 = 252)"},{"label":"7 boxes (42 / 6 = 7)","value":"7 boxes (42 / 6 = 7)"}]},{"id":5,"text":"Each table seats 4 people. There are 36 people. How many tables are needed? If 2 more tables are added empty, how many tables total?","type":"multiple_choice","correct_answer":"9 tables needed; 11 total","explanation":"36 / 4 = 9. Then 9 + 2 = 11 tables total.","standard_code":"3.OA.3","difficulty":3,"options":[{"label":"8 tables needed; 10 total","value":"8 tables needed; 10 total"},{"label":"9 tables needed; 11 total","value":"9 tables needed; 11 total"},{"label":"10 tables needed; 12 total","value":"10 tables needed; 12 total"},{"label":"7 tables needed; 9 total","value":"7 tables needed; 9 total"}]}]'::jsonb);

VALUES (3,'OA','3.OA.4','Determine the Unknown in Multiplication/Division Equations (Easy)','Practice Determine the Unknown in Multiplication/Division Equations','practice',1,10,151,'[{"id":1,"text":"Find the unknown: 4 x ? = 12","type":"numeric","correct_answer":"3","explanation":"4 x 3 = 12. Think: how many groups of 4 make 12?","standard_code":"3.OA.4","difficulty":1},{"id":2,"text":"Find the unknown: ? x 5 = 25","type":"numeric","correct_answer":"5","explanation":"5 x 5 = 25.","standard_code":"3.OA.4","difficulty":1},{"id":3,"text":"Find the unknown: 6 x 6 = ?","type":"numeric","correct_answer":"36","explanation":"6 x 6 = 36.","standard_code":"3.OA.4","difficulty":1},{"id":4,"text":"Find the unknown: 18 / ? = 3","type":"numeric","correct_answer":"6","explanation":"18 / 6 = 3. Think: 3 x 6 = 18.","standard_code":"3.OA.4","difficulty":1},{"id":5,"text":"Find the unknown: ? / 4 = 5","type":"numeric","correct_answer":"20","explanation":"20 / 4 = 5. Think: 4 x 5 = 20.","standard_code":"3.OA.4","difficulty":1}]'::jsonb);

VALUES (3,'OA','3.OA.4','Determine the Unknown in Multiplication/Division Equations (Medium)','Practice Determine the Unknown in Multiplication/Division Equations','practice',2,15,152,'[{"id":1,"text":"Find the unknown: 8 x ? = 56","type":"numeric","correct_answer":"7","explanation":"8 x 7 = 56.","standard_code":"3.OA.4","difficulty":2},{"id":2,"text":"Find the unknown: ? x 9 = 63","type":"numeric","correct_answer":"7","explanation":"7 x 9 = 63.","standard_code":"3.OA.4","difficulty":2},{"id":3,"text":"Find the unknown: 48 / ? = 6","type":"numeric","correct_answer":"8","explanation":"48 / 8 = 6. Think: 6 x 8 = 48.","standard_code":"3.OA.4","difficulty":2},{"id":4,"text":"Find the unknown: ? / 7 = 9","type":"numeric","correct_answer":"63","explanation":"63 / 7 = 9. Think: 7 x 9 = 63.","standard_code":"3.OA.4","difficulty":2},{"id":5,"text":"Find the unknown: 7 x ? = 42","type":"numeric","correct_answer":"6","explanation":"7 x 6 = 42.","standard_code":"3.OA.4","difficulty":2}]'::jsonb);

VALUES (3,'OA','3.OA.4','Determine the Unknown in Multiplication/Division Equations (Hard)','Practice Determine the Unknown in Multiplication/Division Equations','practice',3,20,153,'[{"id":1,"text":"Find the unknown: ? x 8 = 72","type":"numeric","correct_answer":"9","explanation":"9 x 8 = 72.","standard_code":"3.OA.4","difficulty":3},{"id":2,"text":"Find the unknown: 81 / ? = 9","type":"numeric","correct_answer":"9","explanation":"81 / 9 = 9.","standard_code":"3.OA.4","difficulty":3},{"id":3,"text":"Find both unknowns: 6 x ? = 54 and 54 / 6 = ?","type":"multiple_choice","correct_answer":"Both are 9","explanation":"6 x 9 = 54 and 54 / 6 = 9. Multiplication and division are related.","standard_code":"3.OA.4","difficulty":3,"options":[{"label":"Both are 9","value":"Both are 9"},{"label":"Both are 8","value":"Both are 8"},{"label":"Both are 324","value":"Both are 324"},{"label":"Both are 10","value":"Both are 10"}]},{"id":4,"text":"If ? x ? = 64 and both numbers are the same, what is ??","type":"numeric","correct_answer":"8","explanation":"8 x 8 = 64.","standard_code":"3.OA.4","difficulty":3},{"id":5,"text":"Find the unknown: ? / 8 = 7. Then check: 8 x 7 = ?","type":"multiple_choice","correct_answer":"56; 8 x 7 = 56","explanation":"? = 56. Check: 8 x 7 = 56 = 56.","standard_code":"3.OA.4","difficulty":3,"options":[{"label":"72; 8 x 9 = 72","value":"72; 8 x 9 = 72"},{"label":"48; 8 x 7 = 48","value":"48; 8 x 7 = 48"},{"label":"56; 8 x 7 = 56","value":"56; 8 x 7 = 56"},{"label":"64; 8 x 8 = 64","value":"64; 8 x 8 = 64"}]}]'::jsonb);

VALUES (3,'OA','3.OA.5','Apply Properties of Operations to Multiply and Divide (Easy)','Practice Apply Properties of Operations to Multiply and Divide','practice',1,10,154,'[{"id":1,"text":"If 3 x 7 = 21, what is 7 x 3?","type":"numeric","correct_answer":"21","explanation":"Commutative property: 3 x 7 = 7 x 3 = 21.","standard_code":"3.OA.5","difficulty":1},{"id":2,"text":"If 4 x 6 = 24, what is 6 x 4?","type":"numeric","correct_answer":"24","explanation":"Switching the order doesn''t change the product.","standard_code":"3.OA.5","difficulty":1},{"id":3,"text":"What is 5 x 1?","type":"numeric","correct_answer":"5","explanation":"Identity property: any number times 1 equals itself.","standard_code":"3.OA.5","difficulty":1},{"id":4,"text":"What is 8 x 0?","type":"numeric","correct_answer":"0","explanation":"Zero property: any number times 0 equals 0.","standard_code":"3.OA.5","difficulty":1},{"id":5,"text":"If 2 x 9 = 18, what is 9 x 2?","type":"numeric","correct_answer":"18","explanation":"Commutative property: order doesn''t matter.","standard_code":"3.OA.5","difficulty":1}]'::jsonb);

VALUES (3,'OA','3.OA.5','Apply Properties of Operations to Multiply and Divide (Medium)','Practice Apply Properties of Operations to Multiply and Divide','practice',2,15,155,'[{"id":1,"text":"Find 3 x 5 x 2 by grouping in two ways.","type":"multiple_choice","correct_answer":"30 both ways","explanation":"(3 x 5) x 2 = 15 x 2 = 30. Also 3 x (5 x 2) = 3 x 10 = 30. Associative property.","standard_code":"3.OA.5","difficulty":2,"options":[{"label":"60 one way, 30 the other way","value":"60 one way, 30 the other way"},{"label":"15 both ways","value":"15 both ways"},{"label":"45 both ways","value":"45 both ways"},{"label":"30 both ways","value":"30 both ways"}]},{"id":2,"text":"Use the distributive property: 7 x 6 = 7 x (5 + 1). Solve.","type":"numeric","correct_answer":"42","explanation":"7 x 5 = 35, 7 x 1 = 7. 35 + 7 = 42.","standard_code":"3.OA.5","difficulty":2},{"id":3,"text":"Find 4 x 8 by breaking 8 into 5 + 3.","type":"numeric","correct_answer":"32","explanation":"4 x (5 + 3) = (4 x 5) + (4 x 3) = 20 + 12 = 32. Distributive property.","standard_code":"3.OA.5","difficulty":2},{"id":4,"text":"Find 2 x 4 x 5. Which grouping makes it easiest?","type":"multiple_choice","correct_answer":"40 (group 4 x 5 first)","explanation":"2 x (4 x 5) = 2 x 20 = 40. Easier than (2 x 4) x 5 = 8 x 5 = 40.","standard_code":"3.OA.5","difficulty":2,"options":[{"label":"40 (group 2 x 4 first)","value":"40 (group 2 x 4 first)"},{"label":"20 (only multiply first two)","value":"20 (only multiply first two)"},{"label":"9 (add instead of multiply)","value":"9 (add instead of multiply)"},{"label":"40 (group 4 x 5 first)","value":"40 (group 4 x 5 first)"}]},{"id":5,"text":"Use the distributive property: 6 x 8 = 6 x (4 + 4). Solve.","type":"numeric","correct_answer":"48","explanation":"6 x 4 = 24, 6 x 4 = 24. 24 + 24 = 48.","standard_code":"3.OA.5","difficulty":2}]'::jsonb);

VALUES (3,'OA','3.OA.5','Apply Properties of Operations to Multiply and Divide (Hard)','Practice Apply Properties of Operations to Multiply and Divide','practice',3,20,156,'[{"id":1,"text":"Use the distributive property to find 8 x 7: 8 x (5 + 2).","type":"numeric","correct_answer":"56","explanation":"8 x 5 = 40. 8 x 2 = 16. 40 + 16 = 56.","standard_code":"3.OA.5","difficulty":3},{"id":2,"text":"Find 9 x 6 by breaking 9 into (10 - 1).","type":"numeric","correct_answer":"54","explanation":"(10 - 1) x 6 = 10 x 6 - 1 x 6 = 60 - 6 = 54.","standard_code":"3.OA.5","difficulty":3},{"id":3,"text":"Show that 5 x 3 x 4 = 4 x 5 x 3.","type":"multiple_choice","correct_answer":"Both = 60","explanation":"Commutative + associative: order and grouping don''t change the product. Both = 60.","standard_code":"3.OA.5","difficulty":3,"options":[{"label":"5 x 3 x 4 = 60 but 4 x 5 x 3 = 40","value":"5 x 3 x 4 = 60 but 4 x 5 x 3 = 40"},{"label":"Both = 60","value":"Both = 60"},{"label":"Both = 120","value":"Both = 120"},{"label":"Both = 30","value":"Both = 30"}]},{"id":4,"text":"Find 7 x 12 using the distributive property: 7 x (10 + 2).","type":"numeric","correct_answer":"84","explanation":"7 x 10 = 70. 7 x 2 = 14. 70 + 14 = 84.","standard_code":"3.OA.5","difficulty":3},{"id":5,"text":"Why does 6 x 0 x 99 = 0?","type":"multiple_choice","correct_answer":"Because any number times 0 equals 0","explanation":"6 x 0 = 0. Then 0 x 99 = 0. Once you multiply by 0, the result is always 0.","standard_code":"3.OA.5","difficulty":3,"options":[{"label":"Because 0 times any number equals that number","value":"Because 0 times any number equals that number"},{"label":"Because 0 is special and makes numbers disappear","value":"Because 0 is special and makes numbers disappear"},{"label":"Because any number times 0 equals 0","value":"Because any number times 0 equals 0"},{"label":"Because multiplying by 6 and 99 cancels out the 0","value":"Because multiplying by 6 and 99 cancels out the 0"}]}]'::jsonb);

VALUES (3,'OA','3.OA.6','Understand Division as an Unknown-Factor Problem (Easy)','Practice Understand Division as an Unknown-Factor Problem','practice',1,10,157,'[{"id":1,"text":"Find 12 / 4 by thinking: 4 x ? = 12","type":"numeric","correct_answer":"3","explanation":"4 x 3 = 12, so 12 / 4 = 3.","standard_code":"3.OA.6","difficulty":1},{"id":2,"text":"Find 15 / 3 by thinking: 3 x ? = 15","type":"numeric","correct_answer":"5","explanation":"3 x 5 = 15, so 15 / 3 = 5.","standard_code":"3.OA.6","difficulty":1},{"id":3,"text":"Find 20 / 5 by thinking: 5 x ? = 20","type":"numeric","correct_answer":"4","explanation":"5 x 4 = 20, so 20 / 5 = 4.","standard_code":"3.OA.6","difficulty":1},{"id":4,"text":"Find 8 / 2 by thinking: 2 x ? = 8","type":"numeric","correct_answer":"4","explanation":"2 x 4 = 8, so 8 / 2 = 4.","standard_code":"3.OA.6","difficulty":1},{"id":5,"text":"Find 18 / 6 by thinking: 6 x ? = 18","type":"numeric","correct_answer":"3","explanation":"6 x 3 = 18, so 18 / 6 = 3.","standard_code":"3.OA.6","difficulty":1}]'::jsonb);

VALUES (3,'OA','3.OA.6','Understand Division as an Unknown-Factor Problem (Medium)','Practice Understand Division as an Unknown-Factor Problem','practice',2,15,158,'[{"id":1,"text":"Find 32 / 8. Think: 8 x ? = 32","type":"numeric","correct_answer":"4","explanation":"8 x 4 = 32, so 32 / 8 = 4.","standard_code":"3.OA.6","difficulty":2},{"id":2,"text":"Find 45 / 9. Think: 9 x ? = 45","type":"numeric","correct_answer":"5","explanation":"9 x 5 = 45, so 45 / 9 = 5.","standard_code":"3.OA.6","difficulty":2},{"id":3,"text":"Find 56 / 7. Think: 7 x ? = 56","type":"numeric","correct_answer":"8","explanation":"7 x 8 = 56, so 56 / 7 = 8.","standard_code":"3.OA.6","difficulty":2},{"id":4,"text":"If 6 x 9 = 54, what are 54 / 6 and 54 / 9?","type":"multiple_choice","correct_answer":"54 / 6 = 9 and 54 / 9 = 6","explanation":"Fact family: 6 x 9 = 54, so 54 / 6 = 9 and 54 / 9 = 6.","standard_code":"3.OA.6","difficulty":2,"options":[{"label":"54 / 6 = 54 and 54 / 9 = 54","value":"54 / 6 = 54 and 54 / 9 = 54"},{"label":"54 / 6 = 6 and 54 / 9 = 9","value":"54 / 6 = 6 and 54 / 9 = 9"},{"label":"54 / 6 = 8 and 54 / 9 = 7","value":"54 / 6 = 8 and 54 / 9 = 7"},{"label":"54 / 6 = 9 and 54 / 9 = 6","value":"54 / 6 = 9 and 54 / 9 = 6"}]},{"id":5,"text":"Find 48 / 8. Think: 8 x ? = 48","type":"numeric","correct_answer":"6","explanation":"8 x 6 = 48, so 48 / 8 = 6.","standard_code":"3.OA.6","difficulty":2}]'::jsonb);

VALUES (3,'OA','3.OA.6','Understand Division as an Unknown-Factor Problem (Hard)','Practice Understand Division as an Unknown-Factor Problem','practice',3,20,159,'[{"id":1,"text":"Find 72 / 8. Think: 8 x ? = 72","type":"numeric","correct_answer":"9","explanation":"8 x 9 = 72, so 72 / 8 = 9.","standard_code":"3.OA.6","difficulty":3},{"id":2,"text":"Write the complete fact family for 7, 8, and 56.","type":"multiple_choice","correct_answer":"7x8=56, 8x7=56, 56/7=8, 56/8=7","explanation":"Four related facts using the same three numbers.","standard_code":"3.OA.6","difficulty":3,"options":[{"label":"7x8=56, 8x7=56, 56/7=8, 56/8=8","value":"7x8=56, 8x7=56, 56/7=8, 56/8=8"},{"label":"8x7=56, 7x8=56, 56/8=7","value":"8x7=56, 7x8=56, 56/8=7"},{"label":"7x8=56, 8x7=56, 56/7=8, 56/8=7","value":"7x8=56, 8x7=56, 56/7=8, 56/8=7"},{"label":"7x8=56, 56/7=8, 56/8=7","value":"7x8=56, 56/7=8, 56/8=7"}]},{"id":3,"text":"Find 63 / 9 by using multiplication. Then find 63 / 7.","type":"multiple_choice","correct_answer":"63/9=7 and 63/7=9","explanation":"9 x 7 = 63. So 63/9 = 7 and 63/7 = 9.","standard_code":"3.OA.6","difficulty":3,"options":[{"label":"63/9=8 and 63/7=8","value":"63/9=8 and 63/7=8"},{"label":"63/9=9 and 63/7=7","value":"63/9=9 and 63/7=7"},{"label":"63/9=7 and 63/7=9","value":"63/9=7 and 63/7=9"},{"label":"63/9=6 and 63/7=8","value":"63/9=6 and 63/7=8"}]},{"id":4,"text":"If you know 8 x 8 = 64, how does that help you find 64 / 8?","type":"multiple_choice","correct_answer":"64 / 8 = 8","explanation":"Division undoes multiplication. Since 8 x 8 = 64, dividing 64 by 8 gives 8.","standard_code":"3.OA.6","difficulty":3,"options":[{"label":"64 / 8 = 64","value":"64 / 8 = 64"},{"label":"It doesn''t help because division is different from multiplication","value":"It doesn''t help because division is different from multiplication"},{"label":"64 / 8 = 8","value":"64 / 8 = 8"},{"label":"64 / 8 = 56","value":"64 / 8 = 56"}]},{"id":5,"text":"Explain why knowing 9 x 6 = 54 helps you solve both 54 / 9 and 54 / 6.","type":"multiple_choice","correct_answer":"Because division is the inverse of multiplication","explanation":"If 9 x 6 = 54, then 54 / 9 = 6 (unknown factor) and 54 / 6 = 9 (unknown factor).","standard_code":"3.OA.6","difficulty":3,"options":[{"label":"Because division is the inverse of multiplication","value":"Because division is the inverse of multiplication"},{"label":"Because multiplication and division use the same facts","value":"Because multiplication and division use the same facts"},{"label":"Because 54 is the product of both pairs of numbers","value":"Because 54 is the product of both pairs of numbers"},{"label":"Because you need to add the two numbers together","value":"Because you need to add the two numbers together"}]}]'::jsonb);

VALUES (3,'OA','3.OA.7','Fluently Multiply and Divide Within 100 (Easy)','Practice Fluently Multiply and Divide Within 100','practice',1,10,160,'[{"id":1,"text":"What is 3 x 5?","type":"numeric","correct_answer":"15","explanation":"3 x 5 = 15.","standard_code":"3.OA.7","difficulty":1},{"id":2,"text":"What is 24 / 6?","type":"numeric","correct_answer":"4","explanation":"24 / 6 = 4. Think: 6 x 4 = 24.","standard_code":"3.OA.7","difficulty":1},{"id":3,"text":"What is 7 x 2?","type":"numeric","correct_answer":"14","explanation":"7 x 2 = 14.","standard_code":"3.OA.7","difficulty":1},{"id":4,"text":"What is 30 / 5?","type":"numeric","correct_answer":"6","explanation":"30 / 5 = 6.","standard_code":"3.OA.7","difficulty":1},{"id":5,"text":"What is 4 x 4?","type":"numeric","correct_answer":"16","explanation":"4 x 4 = 16.","standard_code":"3.OA.7","difficulty":1}]'::jsonb);

VALUES (3,'OA','3.OA.7','Fluently Multiply and Divide Within 100 (Medium)','Practice Fluently Multiply and Divide Within 100','practice',2,15,161,'[{"id":1,"text":"What is 8 x 6?","type":"numeric","correct_answer":"48","explanation":"8 x 6 = 48.","standard_code":"3.OA.7","difficulty":2},{"id":2,"text":"What is 63 / 9?","type":"numeric","correct_answer":"7","explanation":"63 / 9 = 7.","standard_code":"3.OA.7","difficulty":2},{"id":3,"text":"What is 7 x 8?","type":"numeric","correct_answer":"56","explanation":"7 x 8 = 56.","standard_code":"3.OA.7","difficulty":2},{"id":4,"text":"What is 72 / 8?","type":"numeric","correct_answer":"9","explanation":"72 / 8 = 9.","standard_code":"3.OA.7","difficulty":2},{"id":5,"text":"What is 9 x 6?","type":"numeric","correct_answer":"54","explanation":"9 x 6 = 54.","standard_code":"3.OA.7","difficulty":2}]'::jsonb);

VALUES (3,'OA','3.OA.7','Fluently Multiply and Divide Within 100 (Hard)','Practice Fluently Multiply and Divide Within 100','practice',3,20,162,'[{"id":1,"text":"Solve quickly: 8 x 9, 7 x 7, 6 x 8, 81 / 9, 56 / 7.","type":"multiple_choice","correct_answer":"72, 49, 48, 9, 8","explanation":"These are key facts to know from memory by end of Grade 3.","standard_code":"3.OA.7","difficulty":3,"options":[{"label":"72, 49, 48, 9, 8","value":"72, 49, 48, 9, 8"},{"label":"72, 48, 49, 9, 8","value":"72, 48, 49, 9, 8"},{"label":"72, 49, 48, 8, 8","value":"72, 49, 48, 8, 8"},{"label":"81, 49, 48, 9, 7","value":"81, 49, 48, 9, 7"}]},{"id":2,"text":"What is 12 x 5?","type":"numeric","correct_answer":"60","explanation":"12 x 5 = 60. Think: 10 x 5 = 50, 2 x 5 = 10, 50 + 10 = 60.","standard_code":"3.OA.7","difficulty":3},{"id":3,"text":"What is 100 / 10?","type":"numeric","correct_answer":"10","explanation":"100 / 10 = 10.","standard_code":"3.OA.7","difficulty":3},{"id":4,"text":"Complete the fact family: 9 x 7 = 63. Write the other three facts.","type":"multiple_choice","correct_answer":"7x9=63, 63/9=7, 63/7=9","explanation":"All four facts use 7, 9, and 63.","standard_code":"3.OA.7","difficulty":3,"options":[{"label":"9x7=63, 63/7=9","value":"9x7=63, 63/7=9"},{"label":"7x9=63, 63/9=7, 9/7=63","value":"7x9=63, 63/9=7, 9/7=63"},{"label":"7x9=63, 63/7=9, 63/9=7","value":"7x9=63, 63/7=9, 63/9=7"},{"label":"7x9=63, 63/9=7, 63/7=9","value":"7x9=63, 63/9=7, 63/7=9"}]},{"id":5,"text":"What is 11 x 8?","type":"numeric","correct_answer":"88","explanation":"11 x 8 = 88. Think: 10 x 8 = 80, plus 1 x 8 = 8, total 88.","standard_code":"3.OA.7","difficulty":3}]'::jsonb);

VALUES (3,'OA','3.OA.8','Solve Two-Step Word Problems Using Four Operations (Easy)','Practice Solve Two-Step Word Problems Using Four Operations','practice',1,10,163,'[{"id":1,"text":"Sam has 3 bags of 5 marbles. He finds 4 more. How many marbles in all?","type":"numeric","correct_answer":"19","explanation":"3 x 5 = 15 marbles in bags. 15 + 4 = 19 total.","standard_code":"3.OA.8","difficulty":1},{"id":2,"text":"There are 20 apples. 8 are eaten. The rest are shared equally among 4 friends. How many each?","type":"numeric","correct_answer":"3","explanation":"20 - 8 = 12 left. 12 / 4 = 3 each.","standard_code":"3.OA.8","difficulty":1},{"id":3,"text":"Amy buys 4 packs of stickers with 6 each. She gives away 10. How many left?","type":"numeric","correct_answer":"14","explanation":"4 x 6 = 24 stickers. 24 - 10 = 14 left.","standard_code":"3.OA.8","difficulty":1},{"id":4,"text":"A farmer has 12 chickens and buys 18 more. He puts them in coops of 6. How many coops?","type":"numeric","correct_answer":"5","explanation":"12 + 18 = 30 chickens. 30 / 6 = 5 coops.","standard_code":"3.OA.8","difficulty":1},{"id":5,"text":"Jake has $25. He spends $7 and then earns $8. How much does he have?","type":"multiple_choice","correct_answer":"$26","explanation":"$25 - $7 = $18. $18 + $8 = $26.","standard_code":"3.OA.8","difficulty":1,"options":[{"label":"$24","value":"$24"},{"label":"$28","value":"$28"},{"label":"$18","value":"$18"},{"label":"$26","value":"$26"}]}]'::jsonb);

VALUES (3,'OA','3.OA.8','Solve Two-Step Word Problems Using Four Operations (Medium)','Practice Solve Two-Step Word Problems Using Four Operations','practice',2,15,164,'[{"id":1,"text":"A toy costs $8. Maria buys 3 toys and pays with a $50 bill. How much change?","type":"multiple_choice","correct_answer":"$26","explanation":"3 x $8 = $24 spent. $50 - $24 = $26 change.","standard_code":"3.OA.8","difficulty":2,"options":[{"label":"$34","value":"$34"},{"label":"$26","value":"$26"},{"label":"$24","value":"$24"},{"label":"$18","value":"$18"}]},{"id":2,"text":"There are 6 boxes with 9 books each. 15 books are donated. How many books now?","type":"numeric","correct_answer":"69","explanation":"6 x 9 = 54. 54 + 15 = 69 books.","standard_code":"3.OA.8","difficulty":2},{"id":3,"text":"A baker makes 48 cupcakes. He sells 30, then makes 24 more. How many now?","type":"numeric","correct_answer":"42","explanation":"48 - 30 = 18 left. 18 + 24 = 42 cupcakes.","standard_code":"3.OA.8","difficulty":2},{"id":4,"text":"Sara has 45 beads. She uses 9 beads for each bracelet and makes 3 bracelets. How many beads left?","type":"numeric","correct_answer":"18","explanation":"3 x 9 = 27 beads used. 45 - 27 = 18 left.","standard_code":"3.OA.8","difficulty":2},{"id":5,"text":"Round to estimate: 7 x 8 is about ? x 8. Is 52 a reasonable answer for 7 x 8?","type":"multiple_choice","correct_answer":"No, 7 x 8 = 56; 52 is not reasonable","explanation":"7 x 8 = 56, not 52. Estimate: 7 x 8 is close to 7 x 10 = 70 or 8 x 8 = 64. 52 is too low.","standard_code":"3.OA.8","difficulty":2,"options":[{"label":"No, 7 x 8 = 56; 52 is not reasonable","value":"No, 7 x 8 = 56; 52 is not reasonable"},{"label":"Yes, 52 is close to 56 so it is reasonable","value":"Yes, 52 is close to 56 so it is reasonable"},{"label":"Yes, 7 x 8 = 52; the estimate is exact","value":"Yes, 7 x 8 = 52; the estimate is exact"},{"label":"No, 7 x 8 = 54; 52 is not reasonable","value":"No, 7 x 8 = 54; 52 is not reasonable"}]}]'::jsonb);

VALUES (3,'OA','3.OA.8','Solve Two-Step Word Problems Using Four Operations (Hard)','Practice Solve Two-Step Word Problems Using Four Operations','practice',3,20,165,'[{"id":1,"text":"A school orders 8 boxes of pencils with 12 each. They distribute equally to 6 classrooms. How many per classroom?","type":"numeric","correct_answer":"16","explanation":"8 x 12 = 96 pencils. 96 / 6 = 16 per classroom.","standard_code":"3.OA.8","difficulty":3},{"id":2,"text":"Tom earns $9 per hour. He works 5 hours and buys a book for $18. How much money does he have left?","type":"multiple_choice","correct_answer":"$27","explanation":"5 x $9 = $45 earned. $45 - $18 = $27 left.","standard_code":"3.OA.8","difficulty":3,"options":[{"label":"$45","value":"$45"},{"label":"$9","value":"$9"},{"label":"$27","value":"$27"},{"label":"$36","value":"$36"}]},{"id":3,"text":"A parking lot has 4 rows of 8 cars and 3 rows of 6 cars. How many cars total?","type":"numeric","correct_answer":"50","explanation":"4 x 8 = 32. 3 x 6 = 18. 32 + 18 = 50 cars.","standard_code":"3.OA.8","difficulty":3},{"id":4,"text":"Mia has 72 stickers. She gives an equal number to 8 friends and keeps 24 for herself. How many did each friend get?","type":"numeric","correct_answer":"6","explanation":"72 - 24 = 48 given away. 48 / 8 = 6 per friend.","standard_code":"3.OA.8","difficulty":3},{"id":5,"text":"There are 9 packs of 7 erasers. 13 are broken. The rest are shared among 5 boxes. How many per box?","type":"numeric","correct_answer":"10","explanation":"9 x 7 = 63. 63 - 13 = 50 good erasers. 50 / 5 = 10 per box.","standard_code":"3.OA.8","difficulty":3}]'::jsonb);

VALUES (3,'OA','3.OA.9','Identify and Explain Arithmetic Patterns (Easy)','Practice Identify and Explain Arithmetic Patterns','practice',1,10,166,'[{"id":1,"text":"What pattern do you see: 2, 4, 6, 8, 10?","type":"multiple_choice","correct_answer":"Counting by 2s (adding 2 each time)","explanation":"Each number is 2 more than the last. These are even numbers.","standard_code":"3.OA.9","difficulty":1,"options":[{"label":"Counting by 1s","value":"Counting by 1s"},{"label":"Multiplying by 2 each time","value":"Multiplying by 2 each time"},{"label":"Counting by 4s","value":"Counting by 4s"},{"label":"Counting by 2s (adding 2 each time)","value":"Counting by 2s (adding 2 each time)"}]},{"id":2,"text":"What pattern: 5, 10, 15, 20, 25?","type":"multiple_choice","correct_answer":"Counting by 5s (adding 5 each time)","explanation":"Skip-counting by 5. Each number ends in 0 or 5.","standard_code":"3.OA.9","difficulty":1,"options":[{"label":"Counting by 5s (adding 5 each time)","value":"Counting by 5s (adding 5 each time)"},{"label":"Counting by 3s","value":"Counting by 3s"},{"label":"Multiples of 2","value":"Multiples of 2"},{"label":"Counting by 10s","value":"Counting by 10s"}]},{"id":3,"text":"What comes next: 3, 6, 9, 12, ___?","type":"numeric","correct_answer":"15","explanation":"Counting by 3s (multiples of 3). 12 + 3 = 15.","standard_code":"3.OA.9","difficulty":1},{"id":4,"text":"What comes next: 10, 20, 30, 40, ___?","type":"numeric","correct_answer":"50","explanation":"Counting by 10s. 40 + 10 = 50.","standard_code":"3.OA.9","difficulty":1},{"id":5,"text":"What pattern: 4, 8, 12, 16, 20?","type":"multiple_choice","correct_answer":"Multiples of 4 (adding 4 each time)","explanation":"These are multiples of 4: 4x1, 4x2, 4x3, 4x4, 4x5.","standard_code":"3.OA.9","difficulty":1,"options":[{"label":"Odd numbers only","value":"Odd numbers only"},{"label":"Multiples of 8","value":"Multiples of 8"},{"label":"Multiples of 4 (adding 4 each time)","value":"Multiples of 4 (adding 4 each time)"},{"label":"Counting by 5s","value":"Counting by 5s"}]}]'::jsonb);

VALUES (3,'OA','3.OA.9','Identify and Explain Arithmetic Patterns (Medium)','Practice Identify and Explain Arithmetic Patterns','practice',2,15,167,'[{"id":1,"text":"Look at the multiplication table: 4x1=4, 4x2=8, 4x3=12. Are the products always even?","type":"multiple_choice","correct_answer":"Yes","explanation":"4 times any number is always even. 4 = 2 x 2, so the product always has 2 as a factor.","standard_code":"3.OA.9","difficulty":2,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]},{"id":2,"text":"What pattern do you see in multiples of 9: 9, 18, 27, 36, 45?","type":"multiple_choice","correct_answer":"The digits add up to 9","explanation":"9: 9, 18: 1+8=9, 27: 2+7=9, 36: 3+6=9, 45: 4+5=9.","standard_code":"3.OA.9","difficulty":2,"options":[{"label":"Each number is 9 more than the last","value":"Each number is 9 more than the last"},{"label":"The digits are all different","value":"The digits are all different"},{"label":"The digits add up to 9","value":"The digits add up to 9"},{"label":"The digits multiply to equal 9","value":"The digits multiply to equal 9"}]},{"id":3,"text":"In the addition table, what happens when you add 0 to any number?","type":"multiple_choice","correct_answer":"You get the same number","explanation":"Adding 0 doesn''t change the number. This is the identity property of addition.","standard_code":"3.OA.9","difficulty":2,"options":[{"label":"You get 0","value":"You get 0"},{"label":"You get double the number","value":"You get double the number"},{"label":"You get a larger number","value":"You get a larger number"},{"label":"You get the same number","value":"You get the same number"}]},{"id":4,"text":"Odd + odd = ? (Try 3+5, 7+9, 1+3)","type":"multiple_choice","correct_answer":"Always even","explanation":"3+5=8, 7+9=16, 1+3=4. Odd + odd always equals an even number.","standard_code":"3.OA.9","difficulty":2,"options":[{"label":"Sometimes even and sometimes odd","value":"Sometimes even and sometimes odd"},{"label":"Never a whole number","value":"Never a whole number"},{"label":"Always even","value":"Always even"},{"label":"Always odd","value":"Always odd"}]},{"id":5,"text":"What pattern: 0x5=0, 1x5=5, 2x5=10, 3x5=15? What comes next?","type":"multiple_choice","correct_answer":"4 x 5 = 20","explanation":"Multiples of 5 go up by 5 each time. They always end in 0 or 5.","standard_code":"3.OA.9","difficulty":2,"options":[{"label":"5 x 4 = 25","value":"5 x 4 = 25"},{"label":"3 x 5 = 15","value":"3 x 5 = 15"},{"label":"4 x 5 = 20","value":"4 x 5 = 20"},{"label":"5 x 5 = 25","value":"5 x 5 = 25"}]}]'::jsonb);

VALUES (3,'OA','3.OA.9','Identify and Explain Arithmetic Patterns (Hard)','Practice Identify and Explain Arithmetic Patterns','practice',3,20,168,'[{"id":1,"text":"Why is 4 times any number always even? Explain.","type":"multiple_choice","correct_answer":"Because 4 = 2 x 2, so the product always contains 2 as a factor, making it even","explanation":"4 x n = 2 x 2 x n. Since there''s a factor of 2, the result is always even.","standard_code":"3.OA.9","difficulty":3,"options":[{"label":"Because 4 is an even number and stays even","value":"Because 4 is an even number and stays even"},{"label":"Because 4 = 2 x 2, so the product always contains 2 as a factor, making it even","value":"Because 4 = 2 x 2, so the product always contains 2 as a factor, making it even"},{"label":"Because multiplication always makes numbers bigger and bigger numbers are even","value":"Because multiplication always makes numbers bigger and bigger numbers are even"},{"label":"Because even times anything is always even","value":"Because even times anything is always even"}]},{"id":2,"text":"In the multiplication table, is the product of two odd numbers odd or even? Test with examples.","type":"multiple_choice","correct_answer":"Always odd","explanation":"3x5=15 (odd), 7x3=21 (odd), 9x7=63 (odd). Odd x odd = odd.","standard_code":"3.OA.9","difficulty":3,"options":[{"label":"Always even","value":"Always even"},{"label":"Never odd","value":"Never odd"},{"label":"Always odd","value":"Always odd"},{"label":"Sometimes odd, sometimes even","value":"Sometimes odd, sometimes even"}]},{"id":3,"text":"What pattern do you notice about squares: 1x1=1, 2x2=4, 3x3=9, 4x4=16, 5x5=25?","type":"multiple_choice","correct_answer":"The differences increase by 2: 3, 5, 7, 9","explanation":"4-1=3, 9-4=5, 16-9=7, 25-16=9. Consecutive odd numbers!","standard_code":"3.OA.9","difficulty":3,"options":[{"label":"The differences stay the same at 3","value":"The differences stay the same at 3"},{"label":"The differences increase by 2: 3, 5, 7, 9","value":"The differences increase by 2: 3, 5, 7, 9"},{"label":"The differences are all odd numbers","value":"The differences are all odd numbers"},{"label":"The differences decrease by 1: 2, 1, 0","value":"The differences decrease by 1: 2, 1, 0"}]},{"id":4,"text":"Even x even = ? Even x odd = ? Test and explain.","type":"multiple_choice","correct_answer":"Even x even = even; even x odd = even","explanation":"4x6=24 (even), 6x3=18 (even). Any product with an even factor is even.","standard_code":"3.OA.9","difficulty":3,"options":[{"label":"Even x even = odd; even x odd = odd","value":"Even x even = odd; even x odd = odd"},{"label":"Even x even = odd; even x odd = even","value":"Even x even = odd; even x odd = even"},{"label":"Even x even = even; even x odd = odd","value":"Even x even = even; even x odd = odd"},{"label":"Even x even = even; even x odd = even","value":"Even x even = even; even x odd = even"}]},{"id":5,"text":"Look at multiples of 3: 3,6,9,12,15,18. Which are also multiples of 6?","type":"multiple_choice","correct_answer":"6, 12, 18","explanation":"Every other multiple of 3 is a multiple of 6, because 6 = 2 x 3.","standard_code":"3.OA.9","difficulty":3,"options":[{"label":"12, 18","value":"12, 18"},{"label":"6, 9, 12, 18","value":"6, 9, 12, 18"},{"label":"6, 12, 18","value":"6, 12, 18"},{"label":"3, 9, 15","value":"3, 9, 15"}]}]'::jsonb);

VALUES (3,'NBT','3.NBT.1','Round Whole Numbers to the Nearest 10 or 100 (Easy)','Practice Round Whole Numbers to the Nearest 10 or 100','practice',1,10,169,'[{"id":1,"text":"Round 23 to the nearest 10.","type":"numeric","correct_answer":"20","explanation":"23 is between 20 and 30. Since 3 < 5, round down to 20.","standard_code":"3.NBT.1","difficulty":1},{"id":2,"text":"Round 67 to the nearest 10.","type":"numeric","correct_answer":"70","explanation":"67 is between 60 and 70. Since 7 >= 5, round up to 70.","standard_code":"3.NBT.1","difficulty":1},{"id":3,"text":"Round 45 to the nearest 10.","type":"numeric","correct_answer":"50","explanation":"45 is exactly halfway. The rule is to round up: 50.","standard_code":"3.NBT.1","difficulty":1},{"id":4,"text":"Round 150 to the nearest 100.","type":"numeric","correct_answer":"200","explanation":"150 is halfway between 100 and 200. Round up to 200.","standard_code":"3.NBT.1","difficulty":1},{"id":5,"text":"Round 82 to the nearest 10.","type":"numeric","correct_answer":"80","explanation":"82 is between 80 and 90. Since 2 < 5, round down to 80.","standard_code":"3.NBT.1","difficulty":1}]'::jsonb);

VALUES (3,'NBT','3.NBT.1','Round Whole Numbers to the Nearest 10 or 100 (Medium)','Practice Round Whole Numbers to the Nearest 10 or 100','practice',2,15,170,'[{"id":1,"text":"Round 345 to the nearest 10.","type":"numeric","correct_answer":"350","explanation":"345: look at ones digit (5). 5 = 5, round up to 350.","standard_code":"3.NBT.1","difficulty":2},{"id":2,"text":"Round 345 to the nearest 100.","type":"numeric","correct_answer":"300","explanation":"345: look at tens digit (4). 4 < 5, round down to 300.","standard_code":"3.NBT.1","difficulty":2},{"id":3,"text":"Round 678 to the nearest 100.","type":"numeric","correct_answer":"700","explanation":"678: tens digit is 7. 7 >= 5, round up to 700.","standard_code":"3.NBT.1","difficulty":2},{"id":4,"text":"Round 251 to the nearest 10 and the nearest 100.","type":"multiple_choice","correct_answer":"250 (nearest 10); 300 (nearest 100)","explanation":"Nearest 10: ones digit 1 < 5, round to 250. Nearest 100: tens digit 5, round up to 300.","standard_code":"3.NBT.1","difficulty":2,"options":[{"label":"260 (nearest 10); 250 (nearest 100)","value":"260 (nearest 10); 250 (nearest 100)"},{"label":"250 (nearest 10); 250 (nearest 100)","value":"250 (nearest 10); 250 (nearest 100)"},{"label":"260 (nearest 10); 200 (nearest 100)","value":"260 (nearest 10); 200 (nearest 100)"},{"label":"250 (nearest 10); 300 (nearest 100)","value":"250 (nearest 10); 300 (nearest 100)"}]},{"id":5,"text":"Round 495 to the nearest 10.","type":"numeric","correct_answer":"500","explanation":"495: ones digit 5, round up from 490 to 500.","standard_code":"3.NBT.1","difficulty":2}]'::jsonb);

VALUES (3,'NBT','3.NBT.1','Round Whole Numbers to the Nearest 10 or 100 (Hard)','Practice Round Whole Numbers to the Nearest 10 or 100','practice',3,20,171,'[{"id":1,"text":"A school has 467 students. About how many is that, rounded to the nearest hundred?","type":"numeric","correct_answer":"500","explanation":"467: tens digit is 6. 6 >= 5, round up to 500.","standard_code":"3.NBT.1","difficulty":3},{"id":2,"text":"Round 555 to the nearest 10 and to the nearest 100.","type":"multiple_choice","correct_answer":"560 (nearest 10); 600 (nearest 100)","explanation":"Nearest 10: 5 rounds up to 560. Nearest 100: tens digit 5 rounds up to 600.","standard_code":"3.NBT.1","difficulty":3,"options":[{"label":"550 (nearest 10); 600 (nearest 100)","value":"550 (nearest 10); 600 (nearest 100)"},{"label":"560 (nearest 10); 600 (nearest 100)","value":"560 (nearest 10); 600 (nearest 100)"},{"label":"550 (nearest 10); 500 (nearest 100)","value":"550 (nearest 10); 500 (nearest 100)"},{"label":"560 (nearest 10); 500 (nearest 100)","value":"560 (nearest 10); 500 (nearest 100)"}]},{"id":3,"text":"Which numbers round to 400 when rounded to the nearest hundred?","type":"multiple_choice","correct_answer":"350 to 449","explanation":"Numbers from 350 to 449 round to 400. Below 350 rounds to 300; 450+ rounds to 500.","standard_code":"3.NBT.1","difficulty":3,"options":[{"label":"350 to 449","value":"350 to 449"},{"label":"400 to 450","value":"400 to 450"},{"label":"300 to 499","value":"300 to 499"},{"label":"375 to 425","value":"375 to 425"}]},{"id":4,"text":"Sara says 348 rounds to 400. Jake says it rounds to 350. Who is correct and why?","type":"multiple_choice","correct_answer":"Both could be correct depending on whether rounding to nearest 100 or 10","explanation":"To nearest 100: 300 (Jake is wrong). To nearest 10: 350 (Jake is right). Sara is wrong for both.","standard_code":"3.NBT.1","difficulty":3,"options":[{"label":"Both could be correct depending on whether rounding to nearest 100 or 10","value":"Both could be correct depending on whether rounding to nearest 100 or 10"},{"label":"Sara is correct because it rounds to 400","value":"Sara is correct because it rounds to 400"},{"label":"Neither is correct; it rounds to 300","value":"Neither is correct; it rounds to 300"},{"label":"Jake is correct because it rounds to 350","value":"Jake is correct because it rounds to 350"}]},{"id":5,"text":"Use rounding to estimate 489 + 312.","type":"multiple_choice","correct_answer":"About 800","explanation":"489 rounds to 500. 312 rounds to 300. 500 + 300 = 800.","standard_code":"3.NBT.1","difficulty":3,"options":[{"label":"About 750","value":"About 750"},{"label":"About 700","value":"About 700"},{"label":"About 800","value":"About 800"},{"label":"About 900","value":"About 900"}]}]'::jsonb);

VALUES (3,'NBT','3.NBT.2','Fluently Add and Subtract Within 1000 (Easy)','Practice Fluently Add and Subtract Within 1000','practice',1,10,172,'[{"id":1,"text":"What is 342 + 215?","type":"numeric","correct_answer":"557","explanation":"Ones: 2+5=7. Tens: 4+1=5. Hundreds: 3+2=5. Total: 557.","standard_code":"3.NBT.2","difficulty":1},{"id":2,"text":"What is 689 - 234?","type":"numeric","correct_answer":"455","explanation":"Ones: 9-4=5. Tens: 8-3=5. Hundreds: 6-2=4. Total: 455.","standard_code":"3.NBT.2","difficulty":1},{"id":3,"text":"What is 500 + 300?","type":"numeric","correct_answer":"800","explanation":"5 hundreds + 3 hundreds = 8 hundreds.","standard_code":"3.NBT.2","difficulty":1},{"id":4,"text":"What is 746 - 200?","type":"numeric","correct_answer":"546","explanation":"746 - 200: subtract 2 from hundreds. 546.","standard_code":"3.NBT.2","difficulty":1},{"id":5,"text":"What is 123 + 456?","type":"numeric","correct_answer":"579","explanation":"Ones: 3+6=9. Tens: 2+5=7. Hundreds: 1+4=5. Total: 579.","standard_code":"3.NBT.2","difficulty":1}]'::jsonb);

VALUES (3,'NBT','3.NBT.2','Fluently Add and Subtract Within 1000 (Medium)','Practice Fluently Add and Subtract Within 1000','practice',2,15,173,'[{"id":1,"text":"What is 475 + 368?","type":"numeric","correct_answer":"843","explanation":"Ones: 5+8=13, write 3 carry 1. Tens: 7+6+1=14, write 4 carry 1. Hundreds: 4+3+1=8. Total: 843.","standard_code":"3.NBT.2","difficulty":2},{"id":2,"text":"What is 800 - 347?","type":"numeric","correct_answer":"453","explanation":"Decompose: 800 = 799 + 1. Or use standard algorithm with regrouping.","standard_code":"3.NBT.2","difficulty":2},{"id":3,"text":"What is 562 + 279?","type":"numeric","correct_answer":"841","explanation":"Ones: 2+9=11. Tens: 6+7+1=14. Hundreds: 5+2+1=8. Total: 841.","standard_code":"3.NBT.2","difficulty":2},{"id":4,"text":"What is 604 - 258?","type":"numeric","correct_answer":"346","explanation":"Need to regroup from hundreds. 604 = 5 hundreds + 10 tens + 4 ones, etc.","standard_code":"3.NBT.2","difficulty":2},{"id":5,"text":"What is 999 - 456?","type":"numeric","correct_answer":"543","explanation":"Ones: 9-6=3. Tens: 9-5=4. Hundreds: 9-4=5. Total: 543.","standard_code":"3.NBT.2","difficulty":2}]'::jsonb);

VALUES (3,'NBT','3.NBT.2','Fluently Add and Subtract Within 1000 (Hard)','Practice Fluently Add and Subtract Within 1000','practice',3,20,174,'[{"id":1,"text":"What is 783 + 217?","type":"numeric","correct_answer":"1000","explanation":"Ones: 3+7=10. Tens: 8+1+1=10. Hundreds: 7+2+1=10. Total: 1000.","standard_code":"3.NBT.2","difficulty":3},{"id":2,"text":"What is 1000 - 463?","type":"numeric","correct_answer":"537","explanation":"1000 - 463: regroup from thousands. 999 - 463 = 536, plus 1 = 537.","standard_code":"3.NBT.2","difficulty":3},{"id":3,"text":"A store had 856 items. It sold 478 and received 235 new ones. How many now?","type":"numeric","correct_answer":"613","explanation":"856 - 478 = 378. 378 + 235 = 613.","standard_code":"3.NBT.2","difficulty":3},{"id":4,"text":"What is 567 + 433 - 291?","type":"numeric","correct_answer":"709","explanation":"567 + 433 = 1000. 1000 - 291 = 709.","standard_code":"3.NBT.2","difficulty":3},{"id":5,"text":"Estimate 687 + 295 by rounding, then find the exact answer.","type":"multiple_choice","correct_answer":"Estimate: 700+300=1000; Exact: 982","explanation":"Estimate: 700 + 300 = 1000. Exact: 687 + 295 = 982.","standard_code":"3.NBT.2","difficulty":3,"options":[{"label":"Estimate: 700+300=1000; Exact: 982","value":"Estimate: 700+300=1000; Exact: 982"},{"label":"Estimate: 700+300=1000; Exact: 992","value":"Estimate: 700+300=1000; Exact: 992"},{"label":"Estimate: 690+290=980; Exact: 982","value":"Estimate: 690+290=980; Exact: 982"},{"label":"Estimate: 800+300=1100; Exact: 982","value":"Estimate: 800+300=1100; Exact: 982"}]}]'::jsonb);

VALUES (3,'NBT','3.NBT.3','Multiply One-Digit Numbers by Multiples of 10 (Easy)','Practice Multiply One-Digit Numbers by Multiples of 10','practice',1,10,175,'[{"id":1,"text":"What is 2 x 10?","type":"numeric","correct_answer":"20","explanation":"2 groups of 10 = 20.","standard_code":"3.NBT.3","difficulty":1},{"id":2,"text":"What is 5 x 10?","type":"numeric","correct_answer":"50","explanation":"5 groups of 10 = 50.","standard_code":"3.NBT.3","difficulty":1},{"id":3,"text":"What is 3 x 20?","type":"numeric","correct_answer":"60","explanation":"3 x 20 = 3 x 2 tens = 6 tens = 60.","standard_code":"3.NBT.3","difficulty":1},{"id":4,"text":"What is 4 x 10?","type":"numeric","correct_answer":"40","explanation":"4 x 10 = 40.","standard_code":"3.NBT.3","difficulty":1},{"id":5,"text":"What is 2 x 30?","type":"numeric","correct_answer":"60","explanation":"2 x 30 = 2 x 3 tens = 6 tens = 60.","standard_code":"3.NBT.3","difficulty":1}]'::jsonb);

VALUES (3,'NBT','3.NBT.3','Multiply One-Digit Numbers by Multiples of 10 (Medium)','Practice Multiply One-Digit Numbers by Multiples of 10','practice',2,15,176,'[{"id":1,"text":"What is 5 x 60?","type":"numeric","correct_answer":"300","explanation":"5 x 6 = 30, then 30 x 10 = 300. Or: 5 x 6 tens = 30 tens = 300.","standard_code":"3.NBT.3","difficulty":2},{"id":2,"text":"What is 7 x 40?","type":"numeric","correct_answer":"280","explanation":"7 x 4 = 28, then 28 x 10 = 280.","standard_code":"3.NBT.3","difficulty":2},{"id":3,"text":"What is 8 x 30?","type":"numeric","correct_answer":"240","explanation":"8 x 3 = 24, then times 10 = 240.","standard_code":"3.NBT.3","difficulty":2},{"id":4,"text":"What is 6 x 50?","type":"numeric","correct_answer":"300","explanation":"6 x 5 = 30, times 10 = 300.","standard_code":"3.NBT.3","difficulty":2},{"id":5,"text":"What is 9 x 20?","type":"numeric","correct_answer":"180","explanation":"9 x 2 = 18, times 10 = 180.","standard_code":"3.NBT.3","difficulty":2}]'::jsonb);

VALUES (3,'NBT','3.NBT.3','Multiply One-Digit Numbers by Multiples of 10 (Hard)','Practice Multiply One-Digit Numbers by Multiples of 10','practice',3,20,177,'[{"id":1,"text":"What is 9 x 80?","type":"numeric","correct_answer":"720","explanation":"9 x 8 = 72, times 10 = 720.","standard_code":"3.NBT.3","difficulty":3},{"id":2,"text":"What is 7 x 90?","type":"numeric","correct_answer":"630","explanation":"7 x 9 = 63, times 10 = 630.","standard_code":"3.NBT.3","difficulty":3},{"id":3,"text":"What is 8 x 70?","type":"numeric","correct_answer":"560","explanation":"8 x 7 = 56, times 10 = 560.","standard_code":"3.NBT.3","difficulty":3},{"id":4,"text":"Each classroom has 30 desks. There are 8 classrooms. How many desks total?","type":"numeric","correct_answer":"240","explanation":"8 x 30 = 240 desks.","standard_code":"3.NBT.3","difficulty":3},{"id":5,"text":"Explain why 6 x 70 = 420 using place value.","type":"numeric","correct_answer":"420","explanation":"6 x 70 = 6 x 7 tens = 42 tens = 420. Multiply the non-zero digits (6 x 7 = 42), then append the zero.","standard_code":"3.NBT.3","difficulty":3}]'::jsonb);

VALUES (3,'NF','3.NF.1','Understand Unit Fractions and Fractions a/b (Easy)','Practice Understand Unit Fractions and Fractions a/b','practice',1,10,178,'[{"id":1,"text":"A pizza is cut into 4 equal slices. What fraction is one slice?","type":"numeric","correct_answer":"1/4","explanation":"1 part out of 4 equal parts = 1/4 (one fourth).","standard_code":"3.NF.1","difficulty":1},{"id":2,"text":"A pie is cut into 2 equal pieces. What fraction is one piece?","type":"numeric","correct_answer":"1/2","explanation":"1 out of 2 equal parts = 1/2 (one half).","standard_code":"3.NF.1","difficulty":1},{"id":3,"text":"A chocolate bar has 3 equal parts. You eat 1 part. What fraction did you eat?","type":"numeric","correct_answer":"1/3","explanation":"1 out of 3 equal parts = 1/3 (one third).","standard_code":"3.NF.1","difficulty":1},{"id":4,"text":"A rectangle is divided into 8 equal parts. What fraction is one part?","type":"numeric","correct_answer":"1/8","explanation":"1 out of 8 equal parts = 1/8 (one eighth).","standard_code":"3.NF.1","difficulty":1},{"id":5,"text":"What does the 4 in 3/4 tell you?","type":"multiple_choice","correct_answer":"The whole is divided into 4 equal parts","explanation":"The denominator (bottom number) tells how many equal parts the whole is divided into.","standard_code":"3.NF.1","difficulty":1,"options":[{"label":"You have 4 parts","value":"You have 4 parts"},{"label":"The whole is divided into 3 equal parts","value":"The whole is divided into 3 equal parts"},{"label":"There are 4 equal parts total","value":"There are 4 equal parts total"},{"label":"The whole is divided into 4 equal parts","value":"The whole is divided into 4 equal parts"}]}]'::jsonb);

VALUES (3,'NF','3.NF.1','Understand Unit Fractions and Fractions a/b (Medium)','Practice Understand Unit Fractions and Fractions a/b','practice',2,15,179,'[{"id":1,"text":"A pie is cut into 6 equal pieces. You eat 2 pieces. What fraction did you eat?","type":"numeric","correct_answer":"2/6","explanation":"2 out of 6 equal parts = 2/6. Each piece is 1/6, and you ate 2 of them.","standard_code":"3.NF.1","difficulty":2},{"id":2,"text":"A strip of paper is divided into 4 equal parts. You color 3 parts. What fraction is colored?","type":"numeric","correct_answer":"3/4","explanation":"3 out of 4 equal parts = 3/4.","standard_code":"3.NF.1","difficulty":2},{"id":3,"text":"What does 5/8 mean?","type":"multiple_choice","correct_answer":"5 parts out of 8 equal parts","explanation":"The whole is divided into 8 equal parts, and we have 5 of them.","standard_code":"3.NF.1","difficulty":2,"options":[{"label":"5 parts out of 8 equal parts","value":"5 parts out of 8 equal parts"},{"label":"5 equal parts divided into 8","value":"5 equal parts divided into 8"},{"label":"8 parts out of 5 equal parts","value":"8 parts out of 5 equal parts"},{"label":"8 out of 5 parts used","value":"8 out of 5 parts used"}]},{"id":4,"text":"A cake is divided into 3 equal parts. All 3 parts are eaten. What fraction was eaten?","type":"multiple_choice","correct_answer":"3/3 = 1 whole","explanation":"3/3 = 1. All parts of the whole were eaten.","standard_code":"3.NF.1","difficulty":2,"options":[{"label":"3/3 = 3 parts","value":"3/3 = 3 parts"},{"label":"3/3 = 1 whole","value":"3/3 = 1 whole"},{"label":"1/3 is left","value":"1/3 is left"},{"label":"2/3 = 1 whole","value":"2/3 = 1 whole"}]},{"id":5,"text":"Write the fraction: two sixths.","type":"numeric","correct_answer":"2/6","explanation":"Two sixths: numerator 2, denominator 6 = 2/6.","standard_code":"3.NF.1","difficulty":2}]'::jsonb);

VALUES (3,'NF','3.NF.1','Understand Unit Fractions and Fractions a/b (Hard)','Practice Understand Unit Fractions and Fractions a/b','practice',3,20,180,'[{"id":1,"text":"A ribbon is divided into 8 equal parts. You use 5 parts. What fraction is used? What fraction is left?","type":"multiple_choice","correct_answer":"5/8 used; 3/8 left","explanation":"Used: 5/8. Left: 8/8 - 5/8 = 3/8.","standard_code":"3.NF.1","difficulty":3,"options":[{"label":"5/8 used; 3/8 left","value":"5/8 used; 3/8 left"},{"label":"3/8 used; 5/8 left","value":"3/8 used; 5/8 left"},{"label":"6/8 used; 2/8 left","value":"6/8 used; 2/8 left"},{"label":"4/8 used; 4/8 left","value":"4/8 used; 4/8 left"}]},{"id":2,"text":"What fraction is greater: 3/4 or 3/8? Explain.","type":"multiple_choice","correct_answer":"3/4 is greater","explanation":"Same numerator (3), but fourths are larger than eighths. So 3/4 > 3/8.","standard_code":"3.NF.1","difficulty":3,"options":[{"label":"3/4 is greater","value":"3/4 is greater"},{"label":"3/4 is less","value":"3/4 is less"},{"label":"3/8 is greater","value":"3/8 is greater"},{"label":"They are equal","value":"They are equal"}]},{"id":3,"text":"A shape is divided into 6 equal parts. 6 parts are shaded. What fraction? What does this equal?","type":"multiple_choice","correct_answer":"6/6 = 1 whole","explanation":"6/6 means all parts are shaded = 1 whole.","standard_code":"3.NF.1","difficulty":3,"options":[{"label":"6/6 = 1 whole","value":"6/6 = 1 whole"},{"label":"6/6 = 6 parts","value":"6/6 = 6 parts"},{"label":"1/6 = 1 whole","value":"1/6 = 1 whole"},{"label":"5/6 = 1 whole","value":"5/6 = 1 whole"}]},{"id":4,"text":"If 1/4 of a rope is 3 feet long, how long is the whole rope?","type":"multiple_choice","correct_answer":"12 feet","explanation":"If 1/4 = 3 feet, then the whole = 4 x 3 = 12 feet.","standard_code":"3.NF.1","difficulty":3,"options":[{"label":"12 feet","value":"12 feet"},{"label":"9 feet","value":"9 feet"},{"label":"3 feet","value":"3 feet"},{"label":"15 feet","value":"15 feet"}]},{"id":5,"text":"Write a fraction with denominator 8 that is more than 1/2 of the whole.","type":"multiple_choice","correct_answer":"5/8, 6/8, 7/8 (any works)","explanation":"1/2 of 8 parts = 4 parts. More than 4/8 means 5/8 or greater.","standard_code":"3.NF.1","difficulty":3,"options":[{"label":"1/8, 2/8, 3/8 (any works)","value":"1/8, 2/8, 3/8 (any works)"},{"label":"4/8 only","value":"4/8 only"},{"label":"1/2 only","value":"1/2 only"},{"label":"5/8, 6/8, 7/8 (any works)","value":"5/8, 6/8, 7/8 (any works)"}]}]'::jsonb);

VALUES (3,'NF','3.NF.2','Represent Fractions on a Number Line (Easy)','Practice Represent Fractions on a Number Line','practice',1,10,181,'[{"id":1,"text":"On a number line from 0 to 1, where is 1/2?","type":"multiple_choice","correct_answer":"Halfway between 0 and 1","explanation":"Divide the segment into 2 equal parts. The first mark is 1/2.","standard_code":"3.NF.2","difficulty":1,"options":[{"label":"Three quarters of the way between 0 and 1","value":"Three quarters of the way between 0 and 1"},{"label":"At the mark labeled 2","value":"At the mark labeled 2"},{"label":"Halfway between 0 and 1","value":"Halfway between 0 and 1"},{"label":"One quarter of the way between 0 and 1","value":"One quarter of the way between 0 and 1"}]},{"id":2,"text":"On a number line from 0 to 1 divided into 4 equal parts, where is 1/4?","type":"multiple_choice","correct_answer":"At the first mark (one quarter of the way)","explanation":"4 equal parts: the first mark from 0 is 1/4.","standard_code":"3.NF.2","difficulty":1,"options":[{"label":"Halfway between 0 and 1","value":"Halfway between 0 and 1"},{"label":"At the mark labeled 3","value":"At the mark labeled 3"},{"label":"Three quarters of the way between 0 and 1","value":"Three quarters of the way between 0 and 1"},{"label":"At the first mark (one quarter of the way)","value":"At the first mark (one quarter of the way)"}]},{"id":3,"text":"On a number line from 0 to 1 divided into 3 parts, where is 1/3?","type":"multiple_choice","correct_answer":"At the first mark","explanation":"3 equal parts: the first mark is at 1/3.","standard_code":"3.NF.2","difficulty":1,"options":[{"label":"At the first mark","value":"At the first mark"},{"label":"Halfway between 0 and 1","value":"Halfway between 0 and 1"},{"label":"At the second mark","value":"At the second mark"},{"label":"At the third mark","value":"At the third mark"}]},{"id":4,"text":"On a number line, where is 0/4?","type":"multiple_choice","correct_answer":"At 0","explanation":"0/4 = 0. Zero parts out of 4 means you''re at the start.","standard_code":"3.NF.2","difficulty":1,"options":[{"label":"At 0","value":"At 0"},{"label":"At 1","value":"At 1"},{"label":"Halfway between 0 and 1","value":"Halfway between 0 and 1"},{"label":"At 1/4","value":"At 1/4"}]},{"id":5,"text":"On a number line, where is 4/4?","type":"multiple_choice","correct_answer":"At 1","explanation":"4/4 = 1 whole. All 4 parts = the whole.","standard_code":"3.NF.2","difficulty":1,"options":[{"label":"At 3/4","value":"At 3/4"},{"label":"At 1/2","value":"At 1/2"},{"label":"At 1","value":"At 1"},{"label":"Halfway between 0 and 1","value":"Halfway between 0 and 1"}]}]'::jsonb);

VALUES (3,'NF','3.NF.2','Represent Fractions on a Number Line (Medium)','Practice Represent Fractions on a Number Line','practice',2,15,182,'[{"id":1,"text":"On a number line from 0 to 1 with 4 equal parts, where is 3/4?","type":"multiple_choice","correct_answer":"At the third mark from 0","explanation":"Count 3 parts of size 1/4 from 0. That''s 3/4.","standard_code":"3.NF.2","difficulty":2,"options":[{"label":"Halfway between 0 and 1","value":"Halfway between 0 and 1"},{"label":"At the second mark from 0","value":"At the second mark from 0"},{"label":"At the third mark from 0","value":"At the third mark from 0"},{"label":"At the fourth mark from 0","value":"At the fourth mark from 0"}]},{"id":2,"text":"Place 2/3 on a number line from 0 to 1.","type":"multiple_choice","correct_answer":"At the second mark when divided into 3 equal parts","explanation":"Divide into 3 parts. The second mark = 2/3.","standard_code":"3.NF.2","difficulty":2,"options":[{"label":"At the second mark when divided into 3 equal parts","value":"At the second mark when divided into 3 equal parts"},{"label":"At the first mark when divided into 3 equal parts","value":"At the first mark when divided into 3 equal parts"},{"label":"Halfway between 0 and 1","value":"Halfway between 0 and 1"},{"label":"At the third mark when divided into 3 equal parts","value":"At the third mark when divided into 3 equal parts"}]},{"id":3,"text":"What fraction is at the point halfway between 0 and 1/2 on the number line?","type":"numeric","correct_answer":"1/4","explanation":"Half of 1/2 is 1/4. It''s at the 1/4 mark.","standard_code":"3.NF.2","difficulty":2},{"id":4,"text":"On a number line with eighths marked, what fraction is at the 5th mark?","type":"numeric","correct_answer":"5/8","explanation":"Count 5 parts of size 1/8 from 0 = 5/8.","standard_code":"3.NF.2","difficulty":2},{"id":5,"text":"On a number line, is 2/6 to the left or right of 1/2?","type":"multiple_choice","correct_answer":"To the left (2/6 < 1/2)","explanation":"2/6 = 1/3, and 1/3 < 1/2. So it''s to the left of 1/2.","standard_code":"3.NF.2","difficulty":2,"options":[{"label":"At the same place as 1/2","value":"At the same place as 1/2"},{"label":"To the left (2/6 > 1/3)","value":"To the left (2/6 > 1/3)"},{"label":"To the right (2/6 > 1/2)","value":"To the right (2/6 > 1/2)"},{"label":"To the left (2/6 < 1/2)","value":"To the left (2/6 < 1/2)"}]}]'::jsonb);

VALUES (3,'NF','3.NF.2','Represent Fractions on a Number Line (Hard)','Practice Represent Fractions on a Number Line','practice',3,20,183,'[{"id":1,"text":"On a number line from 0 to 2, where is 5/4?","type":"multiple_choice","correct_answer":"Between 1 and 2, at 1 and 1/4","explanation":"5/4 = 1 whole + 1/4. One and one quarter, between 1 and 2.","standard_code":"3.NF.2","difficulty":3,"options":[{"label":"Between 0 and 1, at 1/4","value":"Between 0 and 1, at 1/4"},{"label":"At 1","value":"At 1"},{"label":"Between 1 and 2, at 1 and 1/2","value":"Between 1 and 2, at 1 and 1/2"},{"label":"Between 1 and 2, at 1 and 1/4","value":"Between 1 and 2, at 1 and 1/4"}]},{"id":2,"text":"Place both 1/3 and 2/3 on a number line. Which is closer to 1?","type":"multiple_choice","correct_answer":"2/3 is closer to 1","explanation":"1/3 is 1 part from 0. 2/3 is 2 parts from 0 (only 1/3 from 1).","standard_code":"3.NF.2","difficulty":3,"options":[{"label":"They are the same distance from 1","value":"They are the same distance from 1"},{"label":"1/3 is closer to 1","value":"1/3 is closer to 1"},{"label":"1/3 is closer to 0","value":"1/3 is closer to 0"},{"label":"2/3 is closer to 1","value":"2/3 is closer to 1"}]},{"id":3,"text":"On a number line with sixths, what fraction is at the same point as 1/2?","type":"numeric","correct_answer":"3/6","explanation":"1/2 = 3/6. They occupy the same point on the number line.","standard_code":"3.NF.2","difficulty":3},{"id":4,"text":"On a number line from 0 to 1, is 3/8 closer to 0 or to 1/2?","type":"multiple_choice","correct_answer":"Closer to 1/2","explanation":"1/2 = 4/8. 3/8 is 1/8 from 4/8 but 3/8 from 0. Closer to 1/2.","standard_code":"3.NF.2","difficulty":3,"options":[{"label":"Closer to 1","value":"Closer to 1"},{"label":"Closer to 1/2","value":"Closer to 1/2"},{"label":"Exactly at 1/2","value":"Exactly at 1/2"},{"label":"Closer to 0","value":"Closer to 0"}]},{"id":5,"text":"Place 6/4 on a number line. Is it greater or less than 1?","type":"multiple_choice","correct_answer":"Greater than 1 (6/4 = 1 and 2/4 = 1 1/2)","explanation":"6/4 = 1 2/4 = 1 1/2, which is past 1 on the number line.","standard_code":"3.NF.2","difficulty":3,"options":[{"label":"Less than 1 (6/4 = 1/2)","value":"Less than 1 (6/4 = 1/2)"},{"label":"Equal to 1","value":"Equal to 1"},{"label":"Greater than 1 (6/4 = 1 and 2/4 = 1 1/2)","value":"Greater than 1 (6/4 = 1 and 2/4 = 1 1/2)"},{"label":"Less than 1 (6/4 = 1 and 1/4)","value":"Less than 1 (6/4 = 1 and 1/4)"}]}]'::jsonb);

VALUES (3,'NF','3.NF.3','Equivalent Fractions and Comparing Fractions (Easy)','Practice Equivalent Fractions and Comparing Fractions','practice',1,10,184,'[{"id":1,"text":"Are 1/2 and 2/4 the same amount?","type":"multiple_choice","correct_answer":"Yes, they are equivalent","explanation":"1/2 = 2/4. If you cut a half in half, you get two fourths.","standard_code":"3.NF.3","difficulty":1,"options":[{"label":"1/2 is bigger","value":"1/2 is bigger"},{"label":"2/4 is bigger","value":"2/4 is bigger"},{"label":"No, they are not equivalent","value":"No, they are not equivalent"},{"label":"Yes, they are equivalent","value":"Yes, they are equivalent"}]},{"id":2,"text":"Compare 1/3 and 1/6. Which is larger?","type":"numeric","correct_answer":"1/3","explanation":"Same numerator: thirds are bigger pieces than sixths. 1/3 > 1/6.","standard_code":"3.NF.3","difficulty":1},{"id":3,"text":"Compare 2/4 and 3/4. Which is larger?","type":"numeric","correct_answer":"3/4","explanation":"Same denominator: more parts = larger fraction. 3/4 > 2/4.","standard_code":"3.NF.3","difficulty":1},{"id":4,"text":"What is 3/3 equal to?","type":"multiple_choice","correct_answer":"1 (one whole)","explanation":"3/3 means all 3 parts of 3 = 1 whole.","standard_code":"3.NF.3","difficulty":1,"options":[{"label":"2 (two wholes)","value":"2 (two wholes)"},{"label":"0","value":"0"},{"label":"1 (one whole)","value":"1 (one whole)"},{"label":"1/3","value":"1/3"}]},{"id":5,"text":"What whole number equals 6/6?","type":"numeric","correct_answer":"1","explanation":"6/6 = 1 whole.","standard_code":"3.NF.3","difficulty":1}]'::jsonb);

VALUES (3,'NF','3.NF.3','Equivalent Fractions and Comparing Fractions (Medium)','Practice Equivalent Fractions and Comparing Fractions','practice',2,15,185,'[{"id":1,"text":"Write a fraction equivalent to 1/2 with denominator 6.","type":"numeric","correct_answer":"3/6","explanation":"1/2 = 3/6. Multiply top and bottom by 3.","standard_code":"3.NF.3","difficulty":2},{"id":2,"text":"Compare 3/8 and 3/4. Which is greater?","type":"numeric","correct_answer":"3/4","explanation":"Same numerator (3). Fourths > eighths in size. 3/4 > 3/8.","standard_code":"3.NF.3","difficulty":2},{"id":3,"text":"Express the number 3 as a fraction with denominator 1.","type":"numeric","correct_answer":"3/1","explanation":"3 = 3/1. Any whole number n = n/1.","standard_code":"3.NF.3","difficulty":2},{"id":4,"text":"Is 2/3 greater than, less than, or equal to 4/6?","type":"multiple_choice","correct_answer":"Equal (2/3 = 4/6)","explanation":"2/3 = 4/6. Multiply 2/3 by 2/2 = 4/6.","standard_code":"3.NF.3","difficulty":2,"options":[{"label":"Equal (2/3 = 4/6)","value":"Equal (2/3 = 4/6)"},{"label":"Cannot be compared","value":"Cannot be compared"},{"label":"Greater than (2/3 > 4/6)","value":"Greater than (2/3 > 4/6)"},{"label":"Less than (2/3 < 4/6)","value":"Less than (2/3 < 4/6)"}]},{"id":5,"text":"Compare 1/4 and 1/3. Which is greater?","type":"numeric","correct_answer":"1/3","explanation":"Same numerator. Fewer parts means bigger pieces: 1/3 > 1/4.","standard_code":"3.NF.3","difficulty":2}]'::jsonb);

VALUES (3,'NF','3.NF.3','Equivalent Fractions and Comparing Fractions (Hard)','Practice Equivalent Fractions and Comparing Fractions','practice',3,20,186,'[{"id":1,"text":"Compare 5/6 and 7/8. Which is closer to 1?","type":"multiple_choice","correct_answer":"7/8 is closer to 1","explanation":"5/6 is 1/6 away from 1. 7/8 is 1/8 away from 1. 1/8 < 1/6, so 7/8 is closer.","standard_code":"3.NF.3","difficulty":3,"options":[{"label":"5/6 is closer to 1","value":"5/6 is closer to 1"},{"label":"They are equally close to 1","value":"They are equally close to 1"},{"label":"7/8 is closer to 1","value":"7/8 is closer to 1"},{"label":"Neither is close to 1","value":"Neither is close to 1"}]},{"id":2,"text":"Write two fractions equivalent to 2/4.","type":"multiple_choice","correct_answer":"1/2 and 4/8","explanation":"2/4 = 1/2 (simplify). 2/4 = 4/8 (multiply by 2/2).","standard_code":"3.NF.3","difficulty":3,"options":[{"label":"3/6 and 2/8","value":"3/6 and 2/8"},{"label":"2/8 and 3/6","value":"2/8 and 3/6"},{"label":"1/2 and 4/8","value":"1/2 and 4/8"},{"label":"1/4 and 3/12","value":"1/4 and 3/12"}]},{"id":3,"text":"Express 4 as a fraction with denominator 4.","type":"numeric","correct_answer":"16/4","explanation":"4 = 16/4, because 16 / 4 = 4.","standard_code":"3.NF.3","difficulty":3},{"id":4,"text":"Where does 8/8 sit on the number line? What about 8/4?","type":"multiple_choice","correct_answer":"8/8 = 1; 8/4 = 2","explanation":"8/8 = 1 (one whole). 8/4 = 2 (two wholes).","standard_code":"3.NF.3","difficulty":3,"options":[{"label":"8/8 = 1; 8/4 = 2","value":"8/8 = 1; 8/4 = 2"},{"label":"8/8 = 2; 8/4 = 1","value":"8/8 = 2; 8/4 = 1"},{"label":"8/8 = 4; 8/4 = 2","value":"8/8 = 4; 8/4 = 2"},{"label":"8/8 = 1/2; 8/4 = 4","value":"8/8 = 1/2; 8/4 = 4"}]},{"id":5,"text":"Compare 2/3 and 3/4. Which is greater? (Hint: find common denominators or use benchmarks.)","type":"multiple_choice","correct_answer":"3/4 > 2/3","explanation":"2/3 = 8/12. 3/4 = 9/12. Since 9/12 > 8/12, 3/4 > 2/3.","standard_code":"3.NF.3","difficulty":3,"options":[{"label":"2/3 > 3/4","value":"2/3 > 3/4"},{"label":"They are equal","value":"They are equal"},{"label":"3/4 > 2/3","value":"3/4 > 2/3"},{"label":"Cannot be compared without a calculator","value":"Cannot be compared without a calculator"}]}]'::jsonb);

VALUES (3,'MD','3.MD.1','Tell Time to the Nearest Minute; Solve Time Interval Problems (Easy)','Practice Tell Time to the Nearest Minute; Solve Time Interval Problems','practice',1,10,187,'[{"id":1,"text":"What time does a clock show when the hour hand is on 3 and the minute hand is on 4?","type":"multiple_choice","correct_answer":"3:20","explanation":"Minute hand on 4 = 4 x 5 = 20 minutes. Time is 3:20.","standard_code":"3.MD.1","difficulty":1,"options":[{"label":"3:04","value":"3:04"},{"label":"3:20","value":"3:20"},{"label":"12:20","value":"12:20"},{"label":"3:40","value":"3:40"}]},{"id":2,"text":"It is 2:00. What time will it be in 30 minutes?","type":"multiple_choice","correct_answer":"2:30","explanation":"2:00 + 30 minutes = 2:30.","standard_code":"3.MD.1","difficulty":1,"options":[{"label":"2:20","value":"2:20"},{"label":"2:50","value":"2:50"},{"label":"3:00","value":"3:00"},{"label":"2:30","value":"2:30"}]},{"id":3,"text":"A class starts at 9:00 and ends at 10:00. How long is the class?","type":"multiple_choice","correct_answer":"60 minutes (1 hour)","explanation":"From 9:00 to 10:00 = 1 hour = 60 minutes.","standard_code":"3.MD.1","difficulty":1,"options":[{"label":"2 hours","value":"2 hours"},{"label":"30 minutes","value":"30 minutes"},{"label":"60 minutes (1 hour)","value":"60 minutes (1 hour)"},{"label":"30 seconds","value":"30 seconds"}]},{"id":4,"text":"The minute hand is on the 6. How many minutes past the hour?","type":"multiple_choice","correct_answer":"30 minutes","explanation":"6 x 5 = 30 minutes.","standard_code":"3.MD.1","difficulty":1,"options":[{"label":"40 minutes","value":"40 minutes"},{"label":"25 minutes","value":"25 minutes"},{"label":"30 minutes","value":"30 minutes"},{"label":"35 minutes","value":"35 minutes"}]},{"id":5,"text":"The minute hand is on the 12. The hour hand is between 7 and 8. What time is it?","type":"multiple_choice","correct_answer":"7:00","explanation":"When the minute hand is exactly on 12, it''s the start of the hour.","standard_code":"3.MD.1","difficulty":1,"options":[{"label":"8:00","value":"8:00"},{"label":"7:30","value":"7:30"},{"label":"7:00","value":"7:00"},{"label":"6:00","value":"6:00"}]}]'::jsonb);

VALUES (3,'MD','3.MD.1','Tell Time to the Nearest Minute; Solve Time Interval Problems (Medium)','Practice Tell Time to the Nearest Minute; Solve Time Interval Problems','practice',2,15,188,'[{"id":1,"text":"A movie starts at 4:15 and is 90 minutes long. What time does it end?","type":"multiple_choice","correct_answer":"5:45","explanation":"4:15 + 60 min = 5:15. 5:15 + 30 min = 5:45.","standard_code":"3.MD.1","difficulty":2,"options":[{"label":"5:30","value":"5:30"},{"label":"6:15","value":"6:15"},{"label":"6:45","value":"6:45"},{"label":"5:45","value":"5:45"}]},{"id":2,"text":"School starts at 8:05 and lunch is at 11:35. How many minutes between?","type":"multiple_choice","correct_answer":"210 minutes (3 hours 30 minutes)","explanation":"8:05 to 11:05 = 3 hours = 180 min. 11:05 to 11:35 = 30 min. Total: 210 min.","standard_code":"3.MD.1","difficulty":2,"options":[{"label":"210 minutes (3 hours 30 minutes)","value":"210 minutes (3 hours 30 minutes)"},{"label":"240 minutes (4 hours)","value":"240 minutes (4 hours)"},{"label":"200 minutes (3 hours 20 minutes)","value":"200 minutes (3 hours 20 minutes)"},{"label":"180 minutes (3 hours)","value":"180 minutes (3 hours)"}]},{"id":3,"text":"A train leaves at 6:47 a.m. It arrives at 7:23 a.m. How long was the trip?","type":"multiple_choice","correct_answer":"36 minutes","explanation":"6:47 to 7:00 = 13 min. 7:00 to 7:23 = 23 min. Total: 36 min.","standard_code":"3.MD.1","difficulty":2,"options":[{"label":"45 minutes","value":"45 minutes"},{"label":"36 minutes","value":"36 minutes"},{"label":"30 minutes","value":"30 minutes"},{"label":"40 minutes","value":"40 minutes"}]},{"id":4,"text":"It is 3:42. What time was it 25 minutes ago?","type":"multiple_choice","correct_answer":"3:17","explanation":"3:42 - 25 = 3:17.","standard_code":"3.MD.1","difficulty":2,"options":[{"label":"3:17","value":"3:17"},{"label":"2:42","value":"2:42"},{"label":"3:07","value":"3:07"},{"label":"3:25","value":"3:25"}]},{"id":5,"text":"If the minute hand points at the 7, what is the exact minute?","type":"multiple_choice","correct_answer":"35 minutes past the hour","explanation":"7 x 5 = 35 minutes.","standard_code":"3.MD.1","difficulty":2,"options":[{"label":"30 minutes past the hour","value":"30 minutes past the hour"},{"label":"40 minutes past the hour","value":"40 minutes past the hour"},{"label":"25 minutes past the hour","value":"25 minutes past the hour"},{"label":"35 minutes past the hour","value":"35 minutes past the hour"}]}]'::jsonb);

VALUES (3,'MD','3.MD.1','Tell Time to the Nearest Minute; Solve Time Interval Problems (Hard)','Practice Tell Time to the Nearest Minute; Solve Time Interval Problems','practice',3,20,189,'[{"id":1,"text":"A show starts at 7:48 p.m. and lasts 1 hour 25 minutes. What time does it end?","type":"multiple_choice","correct_answer":"9:13 p.m.","explanation":"7:48 + 1 hour = 8:48. 8:48 + 25 min = 9:13 p.m.","standard_code":"3.MD.1","difficulty":3,"options":[{"label":"9:23 p.m.","value":"9:23 p.m."},{"label":"8:13 p.m.","value":"8:13 p.m."},{"label":"9:02 p.m.","value":"9:02 p.m."},{"label":"9:13 p.m.","value":"9:13 p.m."}]},{"id":2,"text":"Recess starts at 10:15 and lasts 20 minutes. Math class is 45 minutes after recess. When does math start?","type":"multiple_choice","correct_answer":"10:35 + 0 = 10:35 is when recess ends; but 45 min after = trick","explanation":"Recess ends at 10:35. Math starts 45 min later: 10:35 + 45 = 11:20.","standard_code":"3.MD.1","difficulty":3,"options":[{"label":"11:00","value":"11:00"},{"label":"10:55","value":"10:55"},{"label":"10:20","value":"10:20"},{"label":"10:35 + 0 = 10:35 is when recess ends; but 45 min after = trick","value":"10:35 + 0 = 10:35 is when recess ends; but 45 min after = trick"}]},{"id":3,"text":"A bus ride takes 1 hour 15 minutes. If you need to arrive by 9:00, what is the latest you can leave?","type":"multiple_choice","correct_answer":"7:45","explanation":"9:00 - 1 hour = 8:00. 8:00 - 15 min = 7:45.","standard_code":"3.MD.1","difficulty":3,"options":[{"label":"8:30","value":"8:30"},{"label":"8:00","value":"8:00"},{"label":"7:30","value":"7:30"},{"label":"7:45","value":"7:45"}]},{"id":4,"text":"Sam starts homework at 4:23 and finishes at 5:08. How long did it take?","type":"multiple_choice","correct_answer":"45 minutes","explanation":"4:23 to 5:00 = 37 min. 5:00 to 5:08 = 8 min. Total: 45 min.","standard_code":"3.MD.1","difficulty":3,"options":[{"label":"50 minutes","value":"50 minutes"},{"label":"40 minutes","value":"40 minutes"},{"label":"35 minutes","value":"35 minutes"},{"label":"45 minutes","value":"45 minutes"}]},{"id":5,"text":"Two events: Event A from 1:30 to 2:15, Event B from 3:00 to 4:10. Which lasts longer and by how much?","type":"multiple_choice","correct_answer":"Event B (70 min vs 45 min); 25 min longer","explanation":"A: 45 min. B: 70 min. Difference: 70 - 45 = 25 min.","standard_code":"3.MD.1","difficulty":3,"options":[{"label":"Event B (70 min vs 45 min); 25 min longer","value":"Event B (70 min vs 45 min); 25 min longer"},{"label":"Both events are equal length","value":"Both events are equal length"},{"label":"Event A (70 min vs 45 min); 25 min longer","value":"Event A (70 min vs 45 min); 25 min longer"},{"label":"Event B (50 min vs 45 min); 5 min longer","value":"Event B (50 min vs 45 min); 5 min longer"}]}]'::jsonb);

VALUES (3,'MD','3.MD.2','Measure and Estimate Liquid Volumes and Masses (g, kg, L) (Easy)','Practice Measure and Estimate Liquid Volumes and Masses (g, kg, L)','practice',1,10,190,'[{"id":1,"text":"Would you measure a paperclip in grams or kilograms?","type":"multiple_choice","correct_answer":"Grams","explanation":"A paperclip is very light. Grams are used for small masses.","standard_code":"3.MD.2","difficulty":1,"options":[{"label":"Kilograms","value":"Kilograms"},{"label":"Liters","value":"Liters"},{"label":"Grams","value":"Grams"},{"label":"Meters","value":"Meters"}]},{"id":2,"text":"Would you measure a watermelon in grams or kilograms?","type":"multiple_choice","correct_answer":"Kilograms","explanation":"A watermelon is heavy. Kilograms are used for heavier objects.","standard_code":"3.MD.2","difficulty":1,"options":[{"label":"Kilograms","value":"Kilograms"},{"label":"Liters","value":"Liters"},{"label":"Grams","value":"Grams"},{"label":"Centimeters","value":"Centimeters"}]},{"id":3,"text":"A bottle holds 1 liter of water. If you pour out half, how much is left?","type":"multiple_choice","correct_answer":"About half a liter","explanation":"1 liter - half a liter = half a liter remaining.","standard_code":"3.MD.2","difficulty":1,"options":[{"label":"About half a liter","value":"About half a liter"},{"label":"A full liter","value":"A full liter"},{"label":"A quarter liter","value":"A quarter liter"},{"label":"Two liters","value":"Two liters"}]},{"id":4,"text":"A bag of flour weighs 2 kilograms. What is its mass?","type":"numeric","correct_answer":"2","explanation":"The mass is 2 kilograms.","standard_code":"3.MD.2","difficulty":1},{"id":5,"text":"Would you measure a bathtub of water in liters or grams?","type":"multiple_choice","correct_answer":"Liters","explanation":"Liters measure liquid volume. A bathtub holds many liters.","standard_code":"3.MD.2","difficulty":1,"options":[{"label":"Grams","value":"Grams"},{"label":"Kilograms","value":"Kilograms"},{"label":"Liters","value":"Liters"},{"label":"Milliliters","value":"Milliliters"}]}]'::jsonb);

VALUES (3,'MD','3.MD.2','Measure and Estimate Liquid Volumes and Masses (g, kg, L) (Medium)','Practice Measure and Estimate Liquid Volumes and Masses (g, kg, L)','practice',2,15,191,'[{"id":1,"text":"An apple has a mass of 150 grams. 4 apples weigh how many grams?","type":"multiple_choice","correct_answer":"600 grams","explanation":"4 x 150 = 600 grams.","standard_code":"3.MD.2","difficulty":2,"options":[{"label":"750 grams","value":"750 grams"},{"label":"600 grams","value":"600 grams"},{"label":"400 grams","value":"400 grams"},{"label":"500 grams","value":"500 grams"}]},{"id":2,"text":"A bucket holds 8 liters. You fill 3 buckets. How many liters total?","type":"multiple_choice","correct_answer":"24 liters","explanation":"3 x 8 = 24 liters.","standard_code":"3.MD.2","difficulty":2,"options":[{"label":"24 liters","value":"24 liters"},{"label":"20 liters","value":"20 liters"},{"label":"32 liters","value":"32 liters"},{"label":"16 liters","value":"16 liters"}]},{"id":3,"text":"A book has a mass of 300 g. You have 3 books. What is the total mass?","type":"numeric","correct_answer":"900","explanation":"3 x 300 = 900 grams.","standard_code":"3.MD.2","difficulty":2},{"id":4,"text":"A jug has 5 liters of juice. You pour out 2 liters. How much is left?","type":"multiple_choice","correct_answer":"3 liters","explanation":"5 - 2 = 3 liters.","standard_code":"3.MD.2","difficulty":2,"options":[{"label":"6 liters","value":"6 liters"},{"label":"3 liters","value":"3 liters"},{"label":"2 liters","value":"2 liters"},{"label":"4 liters","value":"4 liters"}]},{"id":5,"text":"A cat weighs 4 kg. A dog weighs 9 kg. How much more does the dog weigh?","type":"numeric","correct_answer":"5","explanation":"9 - 4 = 5 kg.","standard_code":"3.MD.2","difficulty":2}]'::jsonb);

VALUES (3,'MD','3.MD.2','Measure and Estimate Liquid Volumes and Masses (g, kg, L) (Hard)','Practice Measure and Estimate Liquid Volumes and Masses (g, kg, L)','practice',3,20,192,'[{"id":1,"text":"A recipe needs 250 mL of milk. You have 1 liter. How much is left after the recipe?","type":"multiple_choice","correct_answer":"750 mL","explanation":"1 liter = 1000 mL. 1000 - 250 = 750 mL.","standard_code":"3.MD.2","difficulty":3,"options":[{"label":"500 mL","value":"500 mL"},{"label":"750 mL","value":"750 mL"},{"label":"250 mL","value":"250 mL"},{"label":"1000 mL","value":"1000 mL"}]},{"id":2,"text":"A bag of rice is 2 kg. How many grams is that?","type":"multiple_choice","correct_answer":"2000 grams","explanation":"1 kg = 1000 g. 2 kg = 2000 g.","standard_code":"3.MD.2","difficulty":3,"options":[{"label":"20000 grams","value":"20000 grams"},{"label":"20 grams","value":"20 grams"},{"label":"2000 grams","value":"2000 grams"},{"label":"200 grams","value":"200 grams"}]},{"id":3,"text":"Three boxes weigh 350 g, 425 g, and 225 g. What is the total mass?","type":"multiple_choice","correct_answer":"1000 g (or 1 kg)","explanation":"350 + 425 + 225 = 1000 g = 1 kg.","standard_code":"3.MD.2","difficulty":3,"options":[{"label":"1100 g","value":"1100 g"},{"label":"900 g","value":"900 g"},{"label":"1200 g","value":"1200 g"},{"label":"1000 g (or 1 kg)","value":"1000 g (or 1 kg)"}]},{"id":4,"text":"A fish tank holds 20 liters. It has 12 liters. How much more water is needed to fill it?","type":"multiple_choice","correct_answer":"8 liters","explanation":"20 - 12 = 8 liters needed.","standard_code":"3.MD.2","difficulty":3,"options":[{"label":"12 liters","value":"12 liters"},{"label":"10 liters","value":"10 liters"},{"label":"8 liters","value":"8 liters"},{"label":"6 liters","value":"6 liters"}]},{"id":5,"text":"5 oranges each weigh 200 g. A basket weighs 300 g. What is the total mass?","type":"numeric","correct_answer":"1300","explanation":"5 x 200 = 1000 g oranges. 1000 + 300 = 1300 g.","standard_code":"3.MD.2","difficulty":3}]'::jsonb);

VALUES (3,'MD','3.MD.3','Scaled Picture Graphs and Bar Graphs (Easy)','Practice Scaled Picture Graphs and Bar Graphs','practice',1,10,193,'[{"id":1,"text":"A bar graph shows: Red=6, Blue=10, Green=4. Which color has the most votes?","type":"multiple_choice","correct_answer":"Blue (10)","explanation":"10 is the highest value.","standard_code":"3.MD.3","difficulty":1,"options":[{"label":"Green (4)","value":"Green (4)"},{"label":"Blue (10)","value":"Blue (10)"},{"label":"They are all equal","value":"They are all equal"},{"label":"Red (6)","value":"Red (6)"}]},{"id":2,"text":"In a picture graph, each picture = 2 votes. A category has 5 pictures. How many votes?","type":"numeric","correct_answer":"10","explanation":"5 x 2 = 10 votes.","standard_code":"3.MD.3","difficulty":1},{"id":3,"text":"A bar graph shows: Dogs=8, Cats=5. How many more votes for dogs?","type":"multiple_choice","correct_answer":"3 more","explanation":"8 - 5 = 3 more for dogs.","standard_code":"3.MD.3","difficulty":1,"options":[{"label":"3 more","value":"3 more"},{"label":"13 more","value":"13 more"},{"label":"2 more","value":"2 more"},{"label":"5 more","value":"5 more"}]},{"id":4,"text":"In a picture graph, each picture = 5. There are 3 pictures for apples. How many for apples?","type":"numeric","correct_answer":"15","explanation":"3 x 5 = 15.","standard_code":"3.MD.3","difficulty":1},{"id":5,"text":"A bar graph shows: Spring=12, Summer=18, Fall=9, Winter=6. Which season is least popular?","type":"multiple_choice","correct_answer":"Winter (6)","explanation":"6 is the lowest value.","standard_code":"3.MD.3","difficulty":1,"options":[{"label":"Fall (9)","value":"Fall (9)"},{"label":"Spring (12)","value":"Spring (12)"},{"label":"Winter (6)","value":"Winter (6)"},{"label":"Summer (18)","value":"Summer (18)"}]}]'::jsonb);

VALUES (3,'MD','3.MD.3','Scaled Picture Graphs and Bar Graphs (Medium)','Practice Scaled Picture Graphs and Bar Graphs','practice',2,15,194,'[{"id":1,"text":"A picture graph uses a scale of 2. Pizza has 7 pictures. Tacos have 5 pictures. How many total votes?","type":"numeric","correct_answer":"24","explanation":"Pizza: 7 x 2 = 14. Tacos: 5 x 2 = 10. Total: 24.","standard_code":"3.MD.3","difficulty":2},{"id":2,"text":"A bar graph: Soccer=20, Basketball=15, Baseball=25, Tennis=10. How many more for baseball than tennis?","type":"multiple_choice","correct_answer":"15 more","explanation":"25 - 10 = 15 more.","standard_code":"3.MD.3","difficulty":2,"options":[{"label":"5 more","value":"5 more"},{"label":"15 more","value":"15 more"},{"label":"10 more","value":"10 more"},{"label":"35 more","value":"35 more"}]},{"id":3,"text":"In a picture graph (scale=5): Cats have 4 pictures, Dogs have 6. How many more dog votes?","type":"multiple_choice","correct_answer":"10 more","explanation":"Dogs: 6 x 5 = 30. Cats: 4 x 5 = 20. 30 - 20 = 10 more.","standard_code":"3.MD.3","difficulty":2,"options":[{"label":"5 more","value":"5 more"},{"label":"20 more","value":"20 more"},{"label":"10 more","value":"10 more"},{"label":"2 more","value":"2 more"}]},{"id":4,"text":"A bar graph shows scores: Team A=45, Team B=38. How many total points were scored?","type":"numeric","correct_answer":"83","explanation":"45 + 38 = 83.","standard_code":"3.MD.3","difficulty":2},{"id":5,"text":"In a scaled graph (scale=10), how many pictures show 60?","type":"multiple_choice","correct_answer":"6 pictures","explanation":"60 / 10 = 6 pictures.","standard_code":"3.MD.3","difficulty":2,"options":[{"label":"4 pictures","value":"4 pictures"},{"label":"6 pictures","value":"6 pictures"},{"label":"10 pictures","value":"10 pictures"},{"label":"60 pictures","value":"60 pictures"}]}]'::jsonb);

VALUES (3,'MD','3.MD.3','Scaled Picture Graphs and Bar Graphs (Hard)','Practice Scaled Picture Graphs and Bar Graphs','practice',3,20,195,'[{"id":1,"text":"A picture graph (scale=5) shows: Mon=3, Tue=5, Wed=4, Thu=6, Fri=2. Total for the week?","type":"numeric","correct_answer":"100","explanation":"(3+5+4+6+2) x 5 = 20 x 5 = 100.","standard_code":"3.MD.3","difficulty":3},{"id":2,"text":"A bar graph: Grade 3=45, Grade 4=60, Grade 5=55. How many fewer in Grade 3 than Grades 4 and 5 combined?","type":"multiple_choice","correct_answer":"70 fewer","explanation":"Grade 4+5 = 60+55 = 115. 115 - 45 = 70 fewer.","standard_code":"3.MD.3","difficulty":3,"options":[{"label":"60 fewer","value":"60 fewer"},{"label":"70 fewer","value":"70 fewer"},{"label":"50 fewer","value":"50 fewer"},{"label":"70 more","value":"70 more"}]},{"id":3,"text":"In a picture graph with scale=2, if you need to show 15, how many full pictures and half pictures?","type":"multiple_choice","correct_answer":"7 full pictures and 1 half picture","explanation":"7 x 2 = 14. 15 - 14 = 1, which is half of 2. So 7.5 pictures.","standard_code":"3.MD.3","difficulty":3,"options":[{"label":"7 full pictures and 1 half picture","value":"7 full pictures and 1 half picture"},{"label":"6 full pictures and 1 half picture","value":"6 full pictures and 1 half picture"},{"label":"15 half pictures","value":"15 half pictures"},{"label":"8 full pictures","value":"8 full pictures"}]},{"id":4,"text":"A bar graph: Red=24, Blue=18, Green=30, Yellow=12. Which two colors total closest to 50?","type":"multiple_choice","correct_answer":"Red + Blue = 42 or Blue + Green = 48 (Blue+Green is closest)","explanation":"24+18=42, 18+30=48, 24+12=36, 30+12=42. 48 is closest to 50.","standard_code":"3.MD.3","difficulty":3,"options":[{"label":"Red + Yellow = 36","value":"Red + Yellow = 36"},{"label":"Red + Green = 54","value":"Red + Green = 54"},{"label":"Red + Blue = 42 or Blue + Green = 48 (Blue+Green is closest)","value":"Red + Blue = 42 or Blue + Green = 48 (Blue+Green is closest)"},{"label":"Blue + Yellow = 30","value":"Blue + Yellow = 30"}]},{"id":5,"text":"Design a scale for a picture graph showing: Apples=35, Bananas=20, Oranges=15. What scale works well?","type":"multiple_choice","correct_answer":"Scale of 5","explanation":"All values are multiples of 5. Scale=5: Apples=7 pictures, Bananas=4, Oranges=3.","standard_code":"3.MD.3","difficulty":3,"options":[{"label":"Scale of 2","value":"Scale of 2"},{"label":"Scale of 3","value":"Scale of 3"},{"label":"Scale of 10","value":"Scale of 10"},{"label":"Scale of 5","value":"Scale of 5"}]}]'::jsonb);

VALUES (3,'MD','3.MD.4','Measure Lengths to Halves/Fourths of an Inch; Line Plots (Easy)','Practice Measure Lengths to Halves/Fourths of an Inch; Line Plots','practice',1,10,196,'[{"id":1,"text":"A pencil is 5 and 1/2 inches long. Write this as a number.","type":"multiple_choice","correct_answer":"5 1/2 inches","explanation":"Five and one half inches, or 5.5 inches.","standard_code":"3.MD.4","difficulty":1,"options":[{"label":"5.5 inches","value":"5.5 inches"},{"label":"5 1/2 inches","value":"5 1/2 inches"},{"label":"5 2/4 inches","value":"5 2/4 inches"},{"label":"6 inches","value":"6 inches"}]},{"id":2,"text":"How many quarter inches are in 1 inch?","type":"numeric","correct_answer":"4","explanation":"1 inch = 4 quarter inches (4 x 1/4 = 1).","standard_code":"3.MD.4","difficulty":1},{"id":3,"text":"A crayon measures between 3 inches and 4 inches, right at the halfway mark. How long?","type":"multiple_choice","correct_answer":"3 1/2 inches","explanation":"Halfway between 3 and 4 = 3 1/2 inches.","standard_code":"3.MD.4","difficulty":1,"options":[{"label":"3 1/4 inches","value":"3 1/4 inches"},{"label":"3 1/2 inches","value":"3 1/2 inches"},{"label":"3 3/4 inches","value":"3 3/4 inches"},{"label":"4 inches","value":"4 inches"}]},{"id":4,"text":"On a line plot, 3 X''s are above 4 inches. What does that mean?","type":"multiple_choice","correct_answer":"3 objects measured 4 inches","explanation":"Each X represents one measurement of that length.","standard_code":"3.MD.4","difficulty":1,"options":[{"label":"The total is 4 inches","value":"The total is 4 inches"},{"label":"3 objects are above the 4 inch mark","value":"3 objects are above the 4 inch mark"},{"label":"3 objects measured 4 inches","value":"3 objects measured 4 inches"},{"label":"No objects measured 4 inches","value":"No objects measured 4 inches"}]},{"id":5,"text":"How many half inches are in 1 inch?","type":"numeric","correct_answer":"2","explanation":"1 inch = 2 half inches.","standard_code":"3.MD.4","difficulty":1}]'::jsonb);

VALUES (3,'MD','3.MD.4','Measure Lengths to Halves/Fourths of an Inch; Line Plots (Medium)','Practice Measure Lengths to Halves/Fourths of an Inch; Line Plots','practice',2,15,197,'[{"id":1,"text":"Lengths: 3, 3 1/2, 4, 3 1/2, 4, 4 1/2, 3 (inches). How many are 3 1/2 inches?","type":"numeric","correct_answer":"2","explanation":"Count the 3 1/2 values: there are 2.","standard_code":"3.MD.4","difficulty":2},{"id":2,"text":"A ribbon is 6 3/4 inches long. Is it closer to 6 or 7 inches?","type":"multiple_choice","correct_answer":"Closer to 7","explanation":"6 3/4 is 3/4 past 6, which is more than halfway to 7.","standard_code":"3.MD.4","difficulty":2,"options":[{"label":"Exactly between 6 and 7","value":"Exactly between 6 and 7"},{"label":"Closer to 6","value":"Closer to 6"},{"label":"Closer to 8","value":"Closer to 8"},{"label":"Closer to 7","value":"Closer to 7"}]},{"id":3,"text":"On a line plot: 2 in.(1), 2 1/4(3), 2 1/2(2), 2 3/4(1), 3 in.(1). How many objects were measured?","type":"numeric","correct_answer":"8","explanation":"1 + 3 + 2 + 1 + 1 = 8 objects.","standard_code":"3.MD.4","difficulty":2},{"id":4,"text":"A stick is 4 1/4 inches. Another is 4 3/4 inches. What is the difference?","type":"multiple_choice","correct_answer":"1/2 inch","explanation":"4 3/4 - 4 1/4 = 2/4 = 1/2 inch.","standard_code":"3.MD.4","difficulty":2,"options":[{"label":"1/2 inch","value":"1/2 inch"},{"label":"2 inches","value":"2 inches"},{"label":"1/4 inch","value":"1/4 inch"},{"label":"1 inch","value":"1 inch"}]},{"id":5,"text":"What is the length if the ruler shows 3 marks past the 5 inch line (marked in quarters)?","type":"multiple_choice","correct_answer":"5 3/4 inches","explanation":"3 quarter-inch marks past 5 = 5 + 3/4 = 5 3/4 inches.","standard_code":"3.MD.4","difficulty":2,"options":[{"label":"5 3/4 inches","value":"5 3/4 inches"},{"label":"5 1/2 inches","value":"5 1/2 inches"},{"label":"5 1/4 inches","value":"5 1/4 inches"},{"label":"6 inches","value":"6 inches"}]}]'::jsonb);

VALUES (3,'MD','3.MD.4','Measure Lengths to Halves/Fourths of an Inch; Line Plots (Hard)','Practice Measure Lengths to Halves/Fourths of an Inch; Line Plots','practice',3,20,198,'[{"id":1,"text":"Lengths measured: 2 1/4, 2 3/4, 2 1/2, 2 1/4, 3, 2 1/2, 2 3/4, 2 1/4 inches. What length is most common?","type":"multiple_choice","correct_answer":"2 1/4 inches (3 times)","explanation":"2 1/4: 3 times, 2 1/2: 2 times, 2 3/4: 2 times, 3: 1 time.","standard_code":"3.MD.4","difficulty":3,"options":[{"label":"2 3/4 inches (2 times)","value":"2 3/4 inches (2 times)"},{"label":"2 1/2 inches (2 times)","value":"2 1/2 inches (2 times)"},{"label":"3 inches (1 time)","value":"3 inches (1 time)"},{"label":"2 1/4 inches (3 times)","value":"2 1/4 inches (3 times)"}]},{"id":2,"text":"On a line plot, the shortest measurement is 4 1/4 inches and the longest is 6 inches. What is the range?","type":"multiple_choice","correct_answer":"1 3/4 inches","explanation":"6 - 4 1/4 = 1 3/4 inches.","standard_code":"3.MD.4","difficulty":3,"options":[{"label":"1 1/2 inches","value":"1 1/2 inches"},{"label":"1 3/4 inches","value":"1 3/4 inches"},{"label":"10 1/4 inches","value":"10 1/4 inches"},{"label":"2 1/4 inches","value":"2 1/4 inches"}]},{"id":3,"text":"A caterpillar is 1 3/4 inches. A beetle is 1 1/4 inches. How much longer is the caterpillar?","type":"multiple_choice","correct_answer":"1/2 inch (2/4 inch)","explanation":"1 3/4 - 1 1/4 = 2/4 = 1/2 inch.","standard_code":"3.MD.4","difficulty":3,"options":[{"label":"1/4 inch","value":"1/4 inch"},{"label":"1 inch","value":"1 inch"},{"label":"1/2 inch (2/4 inch)","value":"1/2 inch (2/4 inch)"},{"label":"3 inches","value":"3 inches"}]},{"id":4,"text":"Five worms measured: 3 1/2, 4, 3 3/4, 4 1/4, 3 1/2 inches. If you add another worm at 3 3/4, which lengths now tie?","type":"multiple_choice","correct_answer":"3 1/2 and 3 3/4 (both appear twice)","explanation":"3 1/2: 2, 3 3/4: 2, 4: 1, 4 1/4: 1.","standard_code":"3.MD.4","difficulty":3,"options":[{"label":"No lengths tie","value":"No lengths tie"},{"label":"4 and 3 3/4","value":"4 and 3 3/4"},{"label":"3 1/2 and 3 3/4 (both appear twice)","value":"3 1/2 and 3 3/4 (both appear twice)"},{"label":"3 1/2 appears three times","value":"3 1/2 appears three times"}]},{"id":5,"text":"A line plot shows measurements from 5 to 7 inches in half-inch intervals. Most X''s (4) are at 6 inches. What can you conclude?","type":"multiple_choice","correct_answer":"6 inches was the most frequent measurement","explanation":"The mode is 6 inches with 4 occurrences, more than any other length.","standard_code":"3.MD.4","difficulty":3,"options":[{"label":"The measurements range from 5 to 7 inches","value":"The measurements range from 5 to 7 inches"},{"label":"Half-inch intervals are the best way to measure","value":"Half-inch intervals are the best way to measure"},{"label":"6 inches was the most frequent measurement","value":"6 inches was the most frequent measurement"},{"label":"Most worms are 6 inches long","value":"Most worms are 6 inches long"}]}]'::jsonb);

VALUES (3,'MD','3.MD.5','Recognize Area as an Attribute; Understand Area Measurement (Easy)','Practice Recognize Area as an Attribute; Understand Area Measurement','practice',1,10,199,'[{"id":1,"text":"What is area?","type":"multiple_choice","correct_answer":"The amount of space inside a flat shape","explanation":"Area measures how much surface a 2D shape covers.","standard_code":"3.MD.5","difficulty":1,"options":[{"label":"The perimeter of a rectangle","value":"The perimeter of a rectangle"},{"label":"How many unit squares fit on a line","value":"How many unit squares fit on a line"},{"label":"The distance around a flat shape","value":"The distance around a flat shape"},{"label":"The amount of space inside a flat shape","value":"The amount of space inside a flat shape"}]},{"id":2,"text":"A square has side length 1 unit. What is its area?","type":"multiple_choice","correct_answer":"1 square unit","explanation":"A unit square (1 x 1) has an area of 1 square unit.","standard_code":"3.MD.5","difficulty":1,"options":[{"label":"4 square units","value":"4 square units"},{"label":"1 square unit","value":"1 square unit"},{"label":"2 square units","value":"2 square units"},{"label":"1 unit","value":"1 unit"}]},{"id":3,"text":"If a shape is covered by 6 unit squares with no gaps, what is its area?","type":"multiple_choice","correct_answer":"6 square units","explanation":"Count the unit squares: 6 squares = 6 square units.","standard_code":"3.MD.5","difficulty":1,"options":[{"label":"36 square units","value":"36 square units"},{"label":"3 square units","value":"3 square units"},{"label":"6 square units","value":"6 square units"},{"label":"12 square units","value":"12 square units"}]},{"id":4,"text":"Which has more area: a shape covered by 4 squares or one covered by 7 squares?","type":"multiple_choice","correct_answer":"The shape covered by 7 squares","explanation":"7 square units > 4 square units.","standard_code":"3.MD.5","difficulty":1,"options":[{"label":"They have equal area","value":"They have equal area"},{"label":"You need more information to tell","value":"You need more information to tell"},{"label":"The shape covered by 7 squares","value":"The shape covered by 7 squares"},{"label":"The shape covered by 4 squares","value":"The shape covered by 4 squares"}]},{"id":5,"text":"Can you measure area with circles? Why or why not?","type":"multiple_choice","correct_answer":"No, circles leave gaps","explanation":"Circles can''t cover a surface without gaps or overlaps. We use squares.","standard_code":"3.MD.5","difficulty":1,"options":[{"label":"No, you must count the gaps","value":"No, you must count the gaps"},{"label":"Yes, circles are the best units","value":"Yes, circles are the best units"},{"label":"No, circles leave gaps","value":"No, circles leave gaps"},{"label":"Yes, circles fit perfectly together","value":"Yes, circles fit perfectly together"}]}]'::jsonb);

VALUES (3,'MD','3.MD.5','Recognize Area as an Attribute; Understand Area Measurement (Medium)','Practice Recognize Area as an Attribute; Understand Area Measurement','practice',2,15,200,'[{"id":1,"text":"A shape is covered by 12 unit squares. What is the area?","type":"multiple_choice","correct_answer":"12 square units","explanation":"Count all squares with no gaps or overlaps = 12 sq units.","standard_code":"3.MD.5","difficulty":2,"options":[{"label":"144 square units","value":"144 square units"},{"label":"12 square units","value":"12 square units"},{"label":"24 units","value":"24 units"},{"label":"6 square units","value":"6 square units"}]},{"id":2,"text":"Two shapes: Shape A = 15 square cm, Shape B = 11 square cm. Which is larger?","type":"multiple_choice","correct_answer":"Shape A","explanation":"15 > 11. Shape A has more area.","standard_code":"3.MD.5","difficulty":2,"options":[{"label":"Shape B","value":"Shape B"},{"label":"Shape A","value":"Shape A"},{"label":"You cannot compare them","value":"You cannot compare them"},{"label":"They are the same size","value":"They are the same size"}]},{"id":3,"text":"Why must unit squares have no gaps or overlaps when measuring area?","type":"multiple_choice","correct_answer":"Gaps would undercount and overlaps would overcount the area","explanation":"No gaps/overlaps ensures an accurate measurement of the space inside.","standard_code":"3.MD.5","difficulty":2,"options":[{"label":"Unit squares must be the same color","value":"Unit squares must be the same color"},{"label":"Overlaps would only overcount the area","value":"Overlaps would only overcount the area"},{"label":"Gaps would only undercount the area","value":"Gaps would only undercount the area"},{"label":"Gaps would undercount and overlaps would overcount the area","value":"Gaps would undercount and overlaps would overcount the area"}]},{"id":4,"text":"A rectangle is filled with square-inch tiles: 3 rows of 5. What is the area?","type":"multiple_choice","correct_answer":"15 square inches","explanation":"3 x 5 = 15 square inches.","standard_code":"3.MD.5","difficulty":2,"options":[{"label":"15 square inches","value":"15 square inches"},{"label":"30 square inches","value":"30 square inches"},{"label":"20 square inches","value":"20 square inches"},{"label":"8 square inches","value":"8 square inches"}]},{"id":5,"text":"If you use larger unit squares, do you need more or fewer to cover the same shape?","type":"multiple_choice","correct_answer":"Fewer","explanation":"Larger units cover more space each, so you need fewer of them.","standard_code":"3.MD.5","difficulty":2,"options":[{"label":"It depends on the shape","value":"It depends on the shape"},{"label":"More","value":"More"},{"label":"The same number","value":"The same number"},{"label":"Fewer","value":"Fewer"}]}]'::jsonb);

VALUES (3,'MD','3.MD.5','Recognize Area as an Attribute; Understand Area Measurement (Hard)','Practice Recognize Area as an Attribute; Understand Area Measurement','practice',3,20,201,'[{"id":1,"text":"A floor is covered by square-foot tiles. It takes 24 tiles. What is the floor area?","type":"multiple_choice","correct_answer":"24 square feet","explanation":"24 tiles of 1 sq ft each = 24 square feet.","standard_code":"3.MD.5","difficulty":3,"options":[{"label":"6 square feet","value":"6 square feet"},{"label":"24 square feet","value":"24 square feet"},{"label":"48 square feet","value":"48 square feet"},{"label":"12 square feet","value":"12 square feet"}]},{"id":2,"text":"Shape A is 20 square cm. Shape B is 20 square inches. Are their areas the same?","type":"multiple_choice","correct_answer":"No, because the units are different","explanation":"Square cm and square inches are different sizes. You can only compare when units match.","standard_code":"3.MD.5","difficulty":3,"options":[{"label":"Cannot be determined","value":"Cannot be determined"},{"label":"Yes, they are the same","value":"Yes, they are the same"},{"label":"Yes, because they are both measured","value":"Yes, because they are both measured"},{"label":"No, because the units are different","value":"No, because the units are different"}]},{"id":3,"text":"A shape is covered by 8 large squares or 32 small squares. If each large square = 4 small squares, does this make sense?","type":"multiple_choice","correct_answer":"Yes, 8 x 4 = 32","explanation":"Each large square = 4 small squares. 8 x 4 = 32 small squares.","standard_code":"3.MD.5","difficulty":3,"options":[{"label":"Yes, but the units don''t match","value":"Yes, but the units don''t match"},{"label":"No, because the squares are different sizes","value":"No, because the squares are different sizes"},{"label":"Yes, 8 x 4 = 32","value":"Yes, 8 x 4 = 32"},{"label":"No, because 8 x 4 = 12","value":"No, because 8 x 4 = 12"}]},{"id":4,"text":"Can two different shapes have the same area? Give an example.","type":"multiple_choice","correct_answer":"Yes","explanation":"A 2x6 rectangle and a 3x4 rectangle both have area 12, but look different.","standard_code":"3.MD.5","difficulty":3,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]},{"id":5,"text":"Explain why area is measured in ''square units'' rather than just ''units.''","type":"multiple_choice","correct_answer":"Because area measures 2D space, which is covered by squares, not lines","explanation":"Length is 1D (units). Area is 2D (square units). The ''square'' indicates two dimensions.","standard_code":"3.MD.5","difficulty":3,"options":[{"label":"Because area measures 2D space, which is covered by squares, not lines","value":"Because area measures 2D space, which is covered by squares, not lines"},{"label":"Because area always uses the word square","value":"Because area always uses the word square"},{"label":"Because you multiply two measurements together","value":"Because you multiply two measurements together"},{"label":"Because squares are easier to count than rectangles","value":"Because squares are easier to count than rectangles"}]}]'::jsonb);

VALUES (3,'MD','3.MD.6','Measure Areas by Counting Unit Squares (Easy)','Practice Measure Areas by Counting Unit Squares','practice',1,10,202,'[{"id":1,"text":"Count the squares: a shape made of 5 unit squares. What is the area?","type":"multiple_choice","correct_answer":"5 square units","explanation":"Count each unit square: 5 squares = 5 square units.","standard_code":"3.MD.6","difficulty":1,"options":[{"label":"3 square units","value":"3 square units"},{"label":"10 square units","value":"10 square units"},{"label":"5 square units","value":"5 square units"},{"label":"25 square units","value":"25 square units"}]},{"id":2,"text":"A shape has 3 rows of 4 squares. What is the area?","type":"multiple_choice","correct_answer":"12 square units","explanation":"3 x 4 = 12 square units.","standard_code":"3.MD.6","difficulty":1,"options":[{"label":"7 units","value":"7 units"},{"label":"7 square units","value":"7 square units"},{"label":"12 square units","value":"12 square units"},{"label":"24 square units","value":"24 square units"}]},{"id":3,"text":"A small rug covers 8 square feet. What is its area?","type":"multiple_choice","correct_answer":"8 square feet","explanation":"The rug covers 8 square foot tiles.","standard_code":"3.MD.6","difficulty":1,"options":[{"label":"8 square feet","value":"8 square feet"},{"label":"16 square feet","value":"16 square feet"},{"label":"8 feet","value":"8 feet"},{"label":"4 square feet","value":"4 square feet"}]},{"id":4,"text":"A rectangle is 2 squares wide and 6 squares long. What is the area?","type":"multiple_choice","correct_answer":"12 square units","explanation":"2 x 6 = 12 square units.","standard_code":"3.MD.6","difficulty":1,"options":[{"label":"12 square units","value":"12 square units"},{"label":"18 square units","value":"18 square units"},{"label":"8 square units","value":"8 square units"},{"label":"16 square units","value":"16 square units"}]},{"id":5,"text":"Count: a shape has 10 unit squares. What is the area?","type":"multiple_choice","correct_answer":"10 square units","explanation":"10 non-overlapping unit squares = 10 square units.","standard_code":"3.MD.6","difficulty":1,"options":[{"label":"20 square units","value":"20 square units"},{"label":"10 square units","value":"10 square units"},{"label":"100 square units","value":"100 square units"},{"label":"5 square units","value":"5 square units"}]}]'::jsonb);

VALUES (3,'MD','3.MD.6','Measure Areas by Counting Unit Squares (Medium)','Practice Measure Areas by Counting Unit Squares','practice',2,15,203,'[{"id":1,"text":"An L-shaped figure is made of a 3x2 rectangle and a 2x1 rectangle. What is the total area?","type":"multiple_choice","correct_answer":"8 square units","explanation":"3x2 = 6. 2x1 = 2. Total: 6 + 2 = 8 square units.","standard_code":"3.MD.6","difficulty":2,"options":[{"label":"10 square units","value":"10 square units"},{"label":"12 square units","value":"12 square units"},{"label":"6 square units","value":"6 square units"},{"label":"8 square units","value":"8 square units"}]},{"id":2,"text":"A rectangle is 5 cm by 4 cm. How many square centimeters?","type":"multiple_choice","correct_answer":"20 square cm","explanation":"5 x 4 = 20 square centimeters.","standard_code":"3.MD.6","difficulty":2,"options":[{"label":"20 square cm","value":"20 square cm"},{"label":"24 square cm","value":"24 square cm"},{"label":"18 square cm","value":"18 square cm"},{"label":"9 square cm","value":"9 square cm"}]},{"id":3,"text":"A room has 7 rows of 8 square-foot tiles. What is the area?","type":"multiple_choice","correct_answer":"56 square feet","explanation":"7 x 8 = 56 square feet.","standard_code":"3.MD.6","difficulty":2,"options":[{"label":"64 square feet","value":"64 square feet"},{"label":"56 square feet","value":"56 square feet"},{"label":"15 square feet","value":"15 square feet"},{"label":"56 square tiles","value":"56 square tiles"}]},{"id":4,"text":"A garden plot is 6 m by 3 m. What is the area?","type":"multiple_choice","correct_answer":"18 square meters","explanation":"6 x 3 = 18 square meters.","standard_code":"3.MD.6","difficulty":2,"options":[{"label":"18 meters","value":"18 meters"},{"label":"36 square meters","value":"36 square meters"},{"label":"9 square meters","value":"9 square meters"},{"label":"18 square meters","value":"18 square meters"}]},{"id":5,"text":"A T-shaped figure: top part 4x1, bottom part 2x3. Total area?","type":"multiple_choice","correct_answer":"10 square units","explanation":"Top: 4x1 = 4. Bottom: 2x3 = 6. Total: 4 + 6 = 10.","standard_code":"3.MD.6","difficulty":2,"options":[{"label":"10 square units","value":"10 square units"},{"label":"14 square units","value":"14 square units"},{"label":"12 square units","value":"12 square units"},{"label":"7 square units","value":"7 square units"}]}]'::jsonb);

VALUES (3,'MD','3.MD.6','Measure Areas by Counting Unit Squares (Hard)','Practice Measure Areas by Counting Unit Squares','practice',3,20,204,'[{"id":1,"text":"An irregular shape on grid paper covers 23 full squares and 0 partial squares. What is the area?","type":"multiple_choice","correct_answer":"23 square units","explanation":"Count only full squares (no gaps/overlaps): 23 square units.","standard_code":"3.MD.6","difficulty":3,"options":[{"label":"23 square units","value":"23 square units"},{"label":"46 square units","value":"46 square units"},{"label":"11 square units","value":"11 square units"},{"label":"34 square units","value":"34 square units"}]},{"id":2,"text":"A U-shaped pool: outer rectangle 8x5, inner rectangle 4x3 removed. What is the pool area?","type":"multiple_choice","correct_answer":"28 square units","explanation":"Outer: 8x5 = 40. Inner removed: 4x3 = 12. Pool: 40 - 12 = 28.","standard_code":"3.MD.6","difficulty":3,"options":[{"label":"32 square units","value":"32 square units"},{"label":"20 square units","value":"20 square units"},{"label":"28 square units","value":"28 square units"},{"label":"40 square units","value":"40 square units"}]},{"id":3,"text":"A floor is 9 m by 7 m. Each tile is 1 sq m. How many tiles are needed?","type":"multiple_choice","correct_answer":"63 tiles","explanation":"9 x 7 = 63 square meters = 63 tiles.","standard_code":"3.MD.6","difficulty":3,"options":[{"label":"2 tiles","value":"2 tiles"},{"label":"16 tiles","value":"16 tiles"},{"label":"63 square meters","value":"63 square meters"},{"label":"63 tiles","value":"63 tiles"}]},{"id":4,"text":"Two rooms: Room A is 4x5, Room B is 3x7. Which has more area? By how much?","type":"multiple_choice","correct_answer":"Room B (21 vs 20); 1 square unit more","explanation":"A: 20. B: 21. Room B is 1 sq unit larger.","standard_code":"3.MD.6","difficulty":3,"options":[{"label":"They are equal; 0 square units difference","value":"They are equal; 0 square units difference"},{"label":"Room A (20 vs 21); 1 square unit more","value":"Room A (20 vs 21); 1 square unit more"},{"label":"Room A (21 vs 20); 1 square unit more","value":"Room A (21 vs 20); 1 square unit more"},{"label":"Room B (21 vs 20); 1 square unit more","value":"Room B (21 vs 20); 1 square unit more"}]},{"id":5,"text":"A figure is made of 3 non-overlapping rectangles: 2x3, 4x2, and 1x5. Total area?","type":"multiple_choice","correct_answer":"19 square units","explanation":"6 + 8 + 5 = 19 square units.","standard_code":"3.MD.6","difficulty":3,"options":[{"label":"15 square units","value":"15 square units"},{"label":"24 square units","value":"24 square units"},{"label":"22 square units","value":"22 square units"},{"label":"19 square units","value":"19 square units"}]}]'::jsonb);

VALUES (3,'MD','3.MD.7','Relate Area to Multiplication and Addition (Easy)','Practice Relate Area to Multiplication and Addition','practice',1,10,205,'[{"id":1,"text":"A rectangle is 3 units by 5 units. What is the area?","type":"multiple_choice","correct_answer":"15 square units (3 x 5 = 15)","explanation":"Area = length x width = 3 x 5 = 15 square units.","standard_code":"3.MD.7","difficulty":1,"options":[{"label":"18 square units","value":"18 square units"},{"label":"15 square units (3 x 5 = 15)","value":"15 square units (3 x 5 = 15)"},{"label":"8 square units","value":"8 square units"},{"label":"20 square units","value":"20 square units"}]},{"id":2,"text":"A rectangle is 4 by 6. Find the area by multiplying.","type":"multiple_choice","correct_answer":"24 square units","explanation":"4 x 6 = 24 square units.","standard_code":"3.MD.7","difficulty":1,"options":[{"label":"20 square units","value":"20 square units"},{"label":"24 square units","value":"24 square units"},{"label":"10 square units","value":"10 square units"},{"label":"28 square units","value":"28 square units"}]},{"id":3,"text":"A rug is 2 feet by 8 feet. What is the area?","type":"multiple_choice","correct_answer":"16 square feet","explanation":"2 x 8 = 16 square feet.","standard_code":"3.MD.7","difficulty":1,"options":[{"label":"64 square feet","value":"64 square feet"},{"label":"20 square feet","value":"20 square feet"},{"label":"16 square feet","value":"16 square feet"},{"label":"10 square feet","value":"10 square feet"}]},{"id":4,"text":"A rectangle is 7 by 3. Area?","type":"multiple_choice","correct_answer":"21 square units","explanation":"7 x 3 = 21.","standard_code":"3.MD.7","difficulty":1,"options":[{"label":"28 square units","value":"28 square units"},{"label":"21 square units","value":"21 square units"},{"label":"10 square units","value":"10 square units"},{"label":"14 square units","value":"14 square units"}]},{"id":5,"text":"A poster is 5 inches by 5 inches. Area?","type":"multiple_choice","correct_answer":"25 square inches","explanation":"5 x 5 = 25 square inches.","standard_code":"3.MD.7","difficulty":1,"options":[{"label":"25 square inches","value":"25 square inches"},{"label":"20 square inches","value":"20 square inches"},{"label":"30 square inches","value":"30 square inches"},{"label":"10 square inches","value":"10 square inches"}]}]'::jsonb);

VALUES (3,'MD','3.MD.7','Relate Area to Multiplication and Addition (Medium)','Practice Relate Area to Multiplication and Addition','practice',2,15,206,'[{"id":1,"text":"Use the distributive property: A rectangle is 7 by 8. Break 8 into 5+3 and find the area.","type":"numeric","correct_answer":"56","explanation":"7 x (5+3) = 7x5 + 7x3 = 35 + 21 = 56 square units.","standard_code":"3.MD.7","difficulty":2},{"id":2,"text":"A rectangle is 6 by 9. Break 9 into 10-1. Find the area.","type":"numeric","correct_answer":"54","explanation":"6 x (10-1) = 60 - 6 = 54.","standard_code":"3.MD.7","difficulty":2},{"id":3,"text":"An L-shaped room: one part is 3x4, the other is 5x2. Total area?","type":"multiple_choice","correct_answer":"22 square units","explanation":"3x4 = 12. 5x2 = 10. Total: 12 + 10 = 22.","standard_code":"3.MD.7","difficulty":2,"options":[{"label":"22 square units","value":"22 square units"},{"label":"32 square units","value":"32 square units"},{"label":"20 square units","value":"20 square units"},{"label":"12 square units","value":"12 square units"}]},{"id":4,"text":"A rectangle is 8 by 7. Show it equals 8 x (4+3).","type":"numeric","correct_answer":"56","explanation":"8 x 4 = 32. 8 x 3 = 24. 32 + 24 = 56.","standard_code":"3.MD.7","difficulty":2},{"id":5,"text":"A garden is 9 m by 6 m. What is the area? If you add a 3x6 section, what is the new total?","type":"multiple_choice","correct_answer":"54 sq m; new total 72 sq m","explanation":"9x6 = 54. Additional: 3x6 = 18. Total: 54 + 18 = 72.","standard_code":"3.MD.7","difficulty":2,"options":[{"label":"54 sq m; new total 57 sq m","value":"54 sq m; new total 57 sq m"},{"label":"27 sq m; new total 45 sq m","value":"27 sq m; new total 45 sq m"},{"label":"54 sq m; new total 72 sq m","value":"54 sq m; new total 72 sq m"},{"label":"54 sq m; new total 108 sq m","value":"54 sq m; new total 108 sq m"}]}]'::jsonb);

VALUES (3,'MD','3.MD.7','Relate Area to Multiplication and Addition (Hard)','Practice Relate Area to Multiplication and Addition','practice',3,20,207,'[{"id":1,"text":"A room is shaped like an L: a 10x8 rectangle with a 4x3 corner cut out. What is the area?","type":"multiple_choice","correct_answer":"68 square units","explanation":"10x8 = 80. Cut: 4x3 = 12. Area: 80 - 12 = 68.","standard_code":"3.MD.7","difficulty":3,"options":[{"label":"68 square units","value":"68 square units"},{"label":"72 square units","value":"72 square units"},{"label":"64 square units","value":"64 square units"},{"label":"80 square units","value":"80 square units"}]},{"id":2,"text":"Show that a 6 by (4+5) rectangle has the same area as 6x4 + 6x5.","type":"multiple_choice","correct_answer":"54 = 24 + 30 = 54","explanation":"6 x 9 = 54. Also 6x4=24, 6x5=30, 24+30=54. Distributive property.","standard_code":"3.MD.7","difficulty":3,"options":[{"label":"54 = 30 + 24 = 54","value":"54 = 30 + 24 = 54"},{"label":"54 = 24 + 30 = 54","value":"54 = 24 + 30 = 54"},{"label":"48 = 24 + 30 = 54","value":"48 = 24 + 30 = 54"},{"label":"54 = 20 + 34 = 54","value":"54 = 20 + 34 = 54"}]},{"id":3,"text":"Two rectangles share a side: Rectangle A is 5x3, Rectangle B is 5x7. What is the combined area? What single rectangle has the same area?","type":"multiple_choice","correct_answer":"50 square units; a 5x10 rectangle","explanation":"5x3 = 15, 5x7 = 35. Total: 50. Combined: 5 x (3+7) = 5x10 = 50.","standard_code":"3.MD.7","difficulty":3,"options":[{"label":"50 square units; a 10x5 rectangle","value":"50 square units; a 10x5 rectangle"},{"label":"50 square units; a 5x10 rectangle","value":"50 square units; a 5x10 rectangle"},{"label":"60 square units; a 6x10 rectangle","value":"60 square units; a 6x10 rectangle"},{"label":"35 square units; a 5x7 rectangle","value":"35 square units; a 5x7 rectangle"}]},{"id":4,"text":"A playground is 12 by 8. A sandbox (3x4) is inside it. What is the playground area NOT covered by the sandbox?","type":"multiple_choice","correct_answer":"84 square units","explanation":"12x8 = 96. Sandbox: 3x4 = 12. Uncovered: 96 - 12 = 84.","standard_code":"3.MD.7","difficulty":3,"options":[{"label":"96 square units","value":"96 square units"},{"label":"88 square units","value":"88 square units"},{"label":"76 square units","value":"76 square units"},{"label":"84 square units","value":"84 square units"}]},{"id":5,"text":"Find the area of a figure made of a 4x6 rectangle on top of a 8x3 rectangle (sharing the 4-unit side... well, just add the areas).","type":"multiple_choice","correct_answer":"48 square units","explanation":"4x6 = 24. 8x3 = 24. Total: 24 + 24 = 48.","standard_code":"3.MD.7","difficulty":3,"options":[{"label":"48 square units","value":"48 square units"},{"label":"42 square units","value":"42 square units"},{"label":"54 square units","value":"54 square units"},{"label":"50 square units","value":"50 square units"}]}]'::jsonb);

VALUES (3,'MD','3.MD.8','Solve Problems Involving Perimeter (Easy)','Practice Solve Problems Involving Perimeter','practice',1,10,208,'[{"id":1,"text":"A square has sides of 4 cm. What is the perimeter?","type":"numeric","correct_answer":"16","explanation":"4 + 4 + 4 + 4 = 16 cm. Or 4 x 4 = 16 cm.","standard_code":"3.MD.8","difficulty":1},{"id":2,"text":"A rectangle is 5 inches long and 3 inches wide. What is the perimeter?","type":"multiple_choice","correct_answer":"16 inches","explanation":"5 + 3 + 5 + 3 = 16 inches. Or 2x(5+3) = 16.","standard_code":"3.MD.8","difficulty":1,"options":[{"label":"16 inches","value":"16 inches"},{"label":"15 inches","value":"15 inches"},{"label":"14 inches","value":"14 inches"},{"label":"18 inches","value":"18 inches"}]},{"id":3,"text":"A triangle has sides 3, 4, and 5 cm. What is the perimeter?","type":"numeric","correct_answer":"12","explanation":"3 + 4 + 5 = 12 cm.","standard_code":"3.MD.8","difficulty":1},{"id":4,"text":"What is perimeter?","type":"multiple_choice","correct_answer":"The distance around the outside of a shape","explanation":"Perimeter = total length of all sides added together.","standard_code":"3.MD.8","difficulty":1,"options":[{"label":"The amount of space inside a shape","value":"The amount of space inside a shape"},{"label":"The distance around the outside of a shape","value":"The distance around the outside of a shape"},{"label":"Half the distance around a shape","value":"Half the distance around a shape"},{"label":"The total length of all sides added together","value":"The total length of all sides added together"}]},{"id":5,"text":"A rectangle has sides 6 and 2. What is the perimeter?","type":"numeric","correct_answer":"16","explanation":"6 + 2 + 6 + 2 = 16.","standard_code":"3.MD.8","difficulty":1}]'::jsonb);

VALUES (3,'MD','3.MD.8','Solve Problems Involving Perimeter (Medium)','Practice Solve Problems Involving Perimeter','practice',2,15,209,'[{"id":1,"text":"A rectangle has a perimeter of 20 cm. One side is 6 cm. What is the other side?","type":"numeric","correct_answer":"4","explanation":"20 = 2(6 + w). 10 = 6 + w. w = 4 cm.","standard_code":"3.MD.8","difficulty":2},{"id":2,"text":"A square has a perimeter of 36 inches. What is the side length?","type":"multiple_choice","correct_answer":"9 inches","explanation":"36 / 4 = 9 inches per side.","standard_code":"3.MD.8","difficulty":2,"options":[{"label":"9 inches","value":"9 inches"},{"label":"6 inches","value":"6 inches"},{"label":"12 inches","value":"12 inches"},{"label":"18 inches","value":"18 inches"}]},{"id":3,"text":"A garden is 8 m by 5 m. How much fencing is needed to go around it?","type":"multiple_choice","correct_answer":"26 meters","explanation":"Perimeter = 2(8+5) = 2(13) = 26 m.","standard_code":"3.MD.8","difficulty":2,"options":[{"label":"25 meters","value":"25 meters"},{"label":"26 meters","value":"26 meters"},{"label":"40 meters","value":"40 meters"},{"label":"30 meters","value":"30 meters"}]},{"id":4,"text":"Can two rectangles have the same perimeter but different areas?","type":"multiple_choice","correct_answer":"Yes","explanation":"Example: 1x9 (perimeter 20, area 9) and 4x6 (perimeter 20, area 24).","standard_code":"3.MD.8","difficulty":2,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]},{"id":5,"text":"A rectangle is 7 by 3. Another is 5 by 5. Which has the larger perimeter?","type":"multiple_choice","correct_answer":"7 by 3 (perimeter 20 vs 20) - they''re equal!","explanation":"7x3: 2(7+3)=20. 5x5: 2(5+5)=20. Same perimeter!","standard_code":"3.MD.8","difficulty":2,"options":[{"label":"They have equal perimeters of 20","value":"They have equal perimeters of 20"},{"label":"7 by 3 (perimeter 20 vs 20) - they''re equal!","value":"7 by 3 (perimeter 20 vs 20) - they''re equal!"},{"label":"5 by 5 (perimeter 20 vs 20) - they''re equal!","value":"5 by 5 (perimeter 20 vs 20) - they''re equal!"},{"label":"7 by 3 has a larger perimeter of 20","value":"7 by 3 has a larger perimeter of 20"}]}]'::jsonb);

VALUES (3,'MD','3.MD.8','Solve Problems Involving Perimeter (Hard)','Practice Solve Problems Involving Perimeter','practice',3,20,210,'[{"id":1,"text":"Draw two rectangles with perimeter 24 cm. What are their areas?","type":"multiple_choice","correct_answer":"Example: 1x11 (area 11) and 6x6 (area 36)","explanation":"Many options: 2x10 (area 20), 3x9 (area 27), 4x8 (area 32), 5x7 (area 35), 6x6 (area 36).","standard_code":"3.MD.8","difficulty":3,"options":[{"label":"Example: 2x10 (area 20) and 4x8 (area 32)","value":"Example: 2x10 (area 20) and 4x8 (area 32)"},{"label":"Example: 3x9 (area 27) and 5x7 (area 35)","value":"Example: 3x9 (area 27) and 5x7 (area 35)"},{"label":"Example: 1x11 (area 11) and 6x6 (area 36)","value":"Example: 1x11 (area 11) and 6x6 (area 36)"},{"label":"Example: 1x12 (area 12) and 8x4 (area 32)","value":"Example: 1x12 (area 12) and 8x4 (area 32)"}]},{"id":2,"text":"A rectangle has area 24 sq cm and one side is 8 cm. What is the perimeter?","type":"numeric","correct_answer":"22","explanation":"Width = 24/8 = 3. Perimeter = 2(8+3) = 22 cm.","standard_code":"3.MD.8","difficulty":3},{"id":3,"text":"Two rectangles both have area 36. Rectangle A is 4x9. Rectangle B is 6x6. Which has the smaller perimeter?","type":"multiple_choice","correct_answer":"Rectangle B (24 vs 26)","explanation":"A: 2(4+9)=26. B: 2(6+6)=24. B has the smaller perimeter.","standard_code":"3.MD.8","difficulty":3,"options":[{"label":"Rectangle B (24 vs 26)","value":"Rectangle B (24 vs 26)"},{"label":"They have the same perimeter of 25","value":"They have the same perimeter of 25"},{"label":"Rectangle A (26 vs 24)","value":"Rectangle A (26 vs 24)"},{"label":"Rectangle A (25 vs 24)","value":"Rectangle A (25 vs 24)"}]},{"id":4,"text":"A rectangular garden has perimeter 30 m. If the length is twice the width, what are the dimensions?","type":"multiple_choice","correct_answer":"Length = 10 m, Width = 5 m","explanation":"2(L+W) = 30, L+W = 15. If L = 2W: 2W+W = 15, 3W = 15, W = 5, L = 10.","standard_code":"3.MD.8","difficulty":3,"options":[{"label":"Length = 12 m, Width = 6 m","value":"Length = 12 m, Width = 6 m"},{"label":"Length = 15 m, Width = 7.5 m","value":"Length = 15 m, Width = 7.5 m"},{"label":"Length = 10 m, Width = 5 m","value":"Length = 10 m, Width = 5 m"},{"label":"Length = 20 m, Width = 10 m","value":"Length = 20 m, Width = 10 m"}]},{"id":5,"text":"An L-shaped figure: outer dimensions 8x6, with a 3x2 notch cut from one corner. What is the perimeter?","type":"multiple_choice","correct_answer":"28 units","explanation":"The perimeter = 8+6+8+6 = 28 (cutting a notch adds the same length it removes from the outside).","standard_code":"3.MD.8","difficulty":3,"options":[{"label":"32 units","value":"32 units"},{"label":"30 units","value":"30 units"},{"label":"28 units","value":"28 units"},{"label":"24 units","value":"24 units"}]}]'::jsonb);

VALUES (3,'G','3.G.1','Understand Shape Categories; Quadrilateral Subcategories (Easy)','Practice Understand Shape Categories; Quadrilateral Subcategories','practice',1,10,211,'[{"id":1,"text":"Is a square a quadrilateral?","type":"multiple_choice","correct_answer":"Yes","explanation":"A square has 4 sides, so it is a quadrilateral.","standard_code":"3.G.1","difficulty":1,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]},{"id":2,"text":"Is a rectangle a quadrilateral?","type":"multiple_choice","correct_answer":"Yes","explanation":"A rectangle has 4 sides = quadrilateral.","standard_code":"3.G.1","difficulty":1,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]},{"id":3,"text":"Name a shape that is NOT a quadrilateral.","type":"multiple_choice","correct_answer":"A triangle (3 sides) or circle","explanation":"Quadrilaterals must have exactly 4 sides.","standard_code":"3.G.1","difficulty":1,"options":[{"label":"A pentagon (5 sides)","value":"A pentagon (5 sides)"},{"label":"A rectangle (4 sides)","value":"A rectangle (4 sides)"},{"label":"A square (4 sides)","value":"A square (4 sides)"},{"label":"A triangle (3 sides) or circle","value":"A triangle (3 sides) or circle"}]},{"id":4,"text":"What do all quadrilaterals have in common?","type":"multiple_choice","correct_answer":"4 sides and 4 angles","explanation":"Every quadrilateral has exactly 4 sides and 4 angles.","standard_code":"3.G.1","difficulty":1,"options":[{"label":"4 equal sides","value":"4 equal sides"},{"label":"4 sides and 4 angles","value":"4 sides and 4 angles"},{"label":"Right angles and equal sides","value":"Right angles and equal sides"},{"label":"Opposite sides that are parallel","value":"Opposite sides that are parallel"}]},{"id":5,"text":"Is a rhombus a quadrilateral?","type":"multiple_choice","correct_answer":"Yes","explanation":"A rhombus has 4 sides, so it is a quadrilateral.","standard_code":"3.G.1","difficulty":1,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]}]'::jsonb);

VALUES (3,'G','3.G.1','Understand Shape Categories; Quadrilateral Subcategories (Medium)','Practice Understand Shape Categories; Quadrilateral Subcategories','practice',2,15,212,'[{"id":1,"text":"What makes a rectangle special compared to other quadrilaterals?","type":"multiple_choice","correct_answer":"It has 4 right angles","explanation":"All rectangles are quadrilaterals with 4 right (square) angles.","standard_code":"3.G.1","difficulty":2,"options":[{"label":"All 4 sides are equal length","value":"All 4 sides are equal length"},{"label":"All interior angles are equal","value":"All interior angles are equal"},{"label":"It has 4 right angles","value":"It has 4 right angles"},{"label":"It has two pairs of parallel sides","value":"It has two pairs of parallel sides"}]},{"id":2,"text":"What makes a rhombus special?","type":"multiple_choice","correct_answer":"All 4 sides are equal length","explanation":"A rhombus has 4 equal sides (but angles may not be right angles).","standard_code":"3.G.1","difficulty":2,"options":[{"label":"It has two pairs of equal sides","value":"It has two pairs of equal sides"},{"label":"All 4 sides are equal length","value":"All 4 sides are equal length"},{"label":"It has 4 right angles","value":"It has 4 right angles"},{"label":"All sides and angles are equal","value":"All sides and angles are equal"}]},{"id":3,"text":"Is a square a rectangle? Is it a rhombus?","type":"multiple_choice","correct_answer":"Yes to both","explanation":"A square has 4 right angles (rectangle) AND 4 equal sides (rhombus).","standard_code":"3.G.1","difficulty":2,"options":[{"label":"No to the first, yes to the second","value":"No to the first, yes to the second"},{"label":"Yes to both","value":"Yes to both"},{"label":"Yes to the first, no to the second","value":"Yes to the first, no to the second"},{"label":"No to both","value":"No to both"}]},{"id":4,"text":"Draw (describe) a quadrilateral that is NOT a rectangle, square, or rhombus.","type":"multiple_choice","correct_answer":"Example: a trapezoid or any irregular 4-sided shape","explanation":"A shape with 4 sides, unequal side lengths, and no right angles.","standard_code":"3.G.1","difficulty":2,"options":[{"label":"Example: a triangle or a hexagon","value":"Example: a triangle or a hexagon"},{"label":"Example: a parallelogram or a rectangle","value":"Example: a parallelogram or a rectangle"},{"label":"Example: a trapezoid or any irregular 4-sided shape","value":"Example: a trapezoid or any irregular 4-sided shape"},{"label":"Example: a square or a kite","value":"Example: a square or a kite"}]},{"id":5,"text":"Can a quadrilateral have no right angles? Give an example.","type":"multiple_choice","correct_answer":"Yes, a parallelogram (non-rectangle) or a general quadrilateral","explanation":"Many quadrilaterals have no right angles, like a tilted diamond.","standard_code":"3.G.1","difficulty":2,"options":[{"label":"No, quadrilaterals must have 4 right angles","value":"No, quadrilaterals must have 4 right angles"},{"label":"Yes, only a trapezoid","value":"Yes, only a trapezoid"},{"label":"No, all quadrilaterals have at least one right angle","value":"No, all quadrilaterals have at least one right angle"},{"label":"Yes, a parallelogram (non-rectangle) or a general quadrilateral","value":"Yes, a parallelogram (non-rectangle) or a general quadrilateral"}]}]'::jsonb);

VALUES (3,'G','3.G.1','Understand Shape Categories; Quadrilateral Subcategories (Hard)','Practice Understand Shape Categories; Quadrilateral Subcategories','practice',3,20,213,'[{"id":1,"text":"Explain how squares, rectangles, and rhombuses are all related.","type":"multiple_choice","correct_answer":"All are quadrilaterals. A square is both a rectangle and a rhombus.","explanation":"Quadrilateral > rectangle (4 right angles) and rhombus (4 equal sides). Square = both.","standard_code":"3.G.1","difficulty":3,"options":[{"label":"A rectangle is a type of square, and all rhombuses are rectangles","value":"A rectangle is a type of square, and all rhombuses are rectangles"},{"label":"They all have 4 sides, but squares cannot be rectangles","value":"They all have 4 sides, but squares cannot be rectangles"},{"label":"All are quadrilaterals. A square is both a rectangle and a rhombus.","value":"All are quadrilaterals. A square is both a rectangle and a rhombus."},{"label":"They are all different shapes with no connections","value":"They are all different shapes with no connections"}]},{"id":2,"text":"True or false: All rectangles are squares.","type":"multiple_choice","correct_answer":"False","explanation":"All squares are rectangles, but not all rectangles are squares. Squares need equal sides.","standard_code":"3.G.1","difficulty":3,"options":[{"label":"True","value":"True"},{"label":"False","value":"False"}]},{"id":3,"text":"True or false: All rhombuses are quadrilaterals.","type":"multiple_choice","correct_answer":"True","explanation":"Every rhombus has 4 sides, making it a quadrilateral.","standard_code":"3.G.1","difficulty":3,"options":[{"label":"True","value":"True"},{"label":"False","value":"False"}]},{"id":4,"text":"A shape has 4 sides, 2 pairs of parallel sides, but no right angles. What could it be?","type":"multiple_choice","correct_answer":"A parallelogram (non-rectangle type) or rhombus","explanation":"A parallelogram with no right angles, like a tilted rectangle.","standard_code":"3.G.1","difficulty":3,"options":[{"label":"A triangle","value":"A triangle"},{"label":"A rectangle","value":"A rectangle"},{"label":"A parallelogram (non-rectangle type) or rhombus","value":"A parallelogram (non-rectangle type) or rhombus"},{"label":"A trapezoid","value":"A trapezoid"}]},{"id":5,"text":"Sort: square, triangle, rhombus, pentagon, rectangle. Which are quadrilaterals?","type":"multiple_choice","correct_answer":"Square, rhombus, rectangle","explanation":"These all have 4 sides. Triangle has 3, pentagon has 5.","standard_code":"3.G.1","difficulty":3,"options":[{"label":"Square, rhombus, rectangle","value":"Square, rhombus, rectangle"},{"label":"Rhombus, pentagon, rectangle","value":"Rhombus, pentagon, rectangle"},{"label":"Square, triangle, rectangle","value":"Square, triangle, rectangle"},{"label":"Triangle, pentagon, square","value":"Triangle, pentagon, square"}]}]'::jsonb);

VALUES (3,'G','3.G.2','Partition Shapes into Equal Areas; Express as Unit Fractions (Easy)','Practice Partition Shapes into Equal Areas; Express as Unit Fractions','practice',1,10,214,'[{"id":1,"text":"A rectangle is divided into 4 equal parts. What fraction is each part?","type":"numeric","correct_answer":"1/4","explanation":"4 equal parts: each is 1/4 of the total area.","standard_code":"3.G.2","difficulty":1},{"id":2,"text":"A circle is divided into 3 equal parts. What fraction is each?","type":"numeric","correct_answer":"1/3","explanation":"3 equal parts: each is 1/3.","standard_code":"3.G.2","difficulty":1},{"id":3,"text":"A square is cut in half. What fraction is each piece?","type":"numeric","correct_answer":"1/2","explanation":"2 equal parts: each is 1/2.","standard_code":"3.G.2","difficulty":1},{"id":4,"text":"A rectangle is divided into 8 equal parts. You shade 1. What fraction is shaded?","type":"numeric","correct_answer":"1/8","explanation":"1 out of 8 equal parts = 1/8.","standard_code":"3.G.2","difficulty":1},{"id":5,"text":"A shape is divided into 6 equal parts. What fraction is one part?","type":"numeric","correct_answer":"1/6","explanation":"Each part is 1/6 of the whole.","standard_code":"3.G.2","difficulty":1}]'::jsonb);

VALUES (3,'G','3.G.2','Partition Shapes into Equal Areas; Express as Unit Fractions (Medium)','Practice Partition Shapes into Equal Areas; Express as Unit Fractions','practice',2,15,215,'[{"id":1,"text":"A rectangle has area 12 sq units. It is divided into 4 equal parts. What is the area of each part?","type":"multiple_choice","correct_answer":"3 square units","explanation":"12 / 4 = 3 sq units each. Each is 1/4 of 12.","standard_code":"3.G.2","difficulty":2,"options":[{"label":"2 square units","value":"2 square units"},{"label":"6 square units","value":"6 square units"},{"label":"4 square units","value":"4 square units"},{"label":"3 square units","value":"3 square units"}]},{"id":2,"text":"A square has area 16 sq cm. It is divided into 4 equal parts. Each part = what fraction? What area?","type":"multiple_choice","correct_answer":"1/4 of the whole; 4 sq cm each","explanation":"16 / 4 = 4 sq cm. Each is 1/4.","standard_code":"3.G.2","difficulty":2,"options":[{"label":"1/4 of the whole; 4 sq cm each","value":"1/4 of the whole; 4 sq cm each"},{"label":"1/3 of the whole; 5 sq cm each","value":"1/3 of the whole; 5 sq cm each"},{"label":"1/8 of the whole; 2 sq cm each","value":"1/8 of the whole; 2 sq cm each"},{"label":"1/2 of the whole; 8 sq cm each","value":"1/2 of the whole; 8 sq cm each"}]},{"id":3,"text":"A circle is divided into 6 equal parts. You shade 2. What fraction is shaded?","type":"multiple_choice","correct_answer":"2/6 (or 1/3)","explanation":"2 out of 6 = 2/6 = 1/3.","standard_code":"3.G.2","difficulty":2,"options":[{"label":"4/6","value":"4/6"},{"label":"2/8","value":"2/8"},{"label":"6/2","value":"6/2"},{"label":"2/6 (or 1/3)","value":"2/6 (or 1/3)"}]},{"id":4,"text":"A rectangle (area 24) is divided into 3 equal rows. What is the area of each row?","type":"multiple_choice","correct_answer":"8 square units (1/3 of 24)","explanation":"24 / 3 = 8. Each row is 1/3 of the total.","standard_code":"3.G.2","difficulty":2,"options":[{"label":"4 square units","value":"4 square units"},{"label":"8 square units (1/3 of 24)","value":"8 square units (1/3 of 24)"},{"label":"12 square units","value":"12 square units"},{"label":"6 square units","value":"6 square units"}]},{"id":5,"text":"If 1/4 of a shape''s area is 5 sq cm, what is the total area?","type":"multiple_choice","correct_answer":"20 sq cm","explanation":"1/4 = 5, so whole = 4 x 5 = 20 sq cm.","standard_code":"3.G.2","difficulty":2,"options":[{"label":"10 sq cm","value":"10 sq cm"},{"label":"25 sq cm","value":"25 sq cm"},{"label":"20 sq cm","value":"20 sq cm"},{"label":"15 sq cm","value":"15 sq cm"}]}]'::jsonb);

VALUES (3,'G','3.G.2','Partition Shapes into Equal Areas; Express as Unit Fractions (Hard)','Practice Partition Shapes into Equal Areas; Express as Unit Fractions','practice',3,20,216,'[{"id":1,"text":"A rectangle has area 36 sq units. It is divided into 6 equal parts. What fraction and area is each part?","type":"multiple_choice","correct_answer":"1/6 of the whole; 6 sq units each","explanation":"36 / 6 = 6 sq units per part. Each is 1/6.","standard_code":"3.G.2","difficulty":3,"options":[{"label":"1/5 of the whole; 7 sq units each","value":"1/5 of the whole; 7 sq units each"},{"label":"1/3 of the whole; 12 sq units each","value":"1/3 of the whole; 12 sq units each"},{"label":"1/4 of the whole; 9 sq units each","value":"1/4 of the whole; 9 sq units each"},{"label":"1/6 of the whole; 6 sq units each","value":"1/6 of the whole; 6 sq units each"}]},{"id":2,"text":"A square (area 64 sq in) is divided into 8 equal strips. What is the area of 3 strips?","type":"multiple_choice","correct_answer":"24 sq in (3/8 of 64)","explanation":"Each strip: 64/8 = 8 sq in. Three strips: 3 x 8 = 24 sq in = 3/8 of the whole.","standard_code":"3.G.2","difficulty":3,"options":[{"label":"28 sq in","value":"28 sq in"},{"label":"24 sq in (3/8 of 64)","value":"24 sq in (3/8 of 64)"},{"label":"16 sq in","value":"16 sq in"},{"label":"32 sq in","value":"32 sq in"}]},{"id":3,"text":"Can you divide a rectangle into 4 equal parts in more than one way?","type":"multiple_choice","correct_answer":"Yes","explanation":"4 horizontal strips, 4 vertical strips, a 2x2 grid, or diagonal cuts can all make 4 equal parts.","standard_code":"3.G.2","difficulty":3,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]},{"id":4,"text":"A shape is divided into 3 unequal parts. Can you call each part 1/3?","type":"multiple_choice","correct_answer":"No","explanation":"Fractions require EQUAL parts. Unequal parts are not thirds.","standard_code":"3.G.2","difficulty":3,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]},{"id":5,"text":"A rectangular garden (area 30 sq m) is divided into 6 equal plots. Each plot is what fraction? What area?","type":"multiple_choice","correct_answer":"1/6 of the garden; 5 sq m each","explanation":"30 / 6 = 5 sq m. Each is 1/6.","standard_code":"3.G.2","difficulty":3,"options":[{"label":"1/3 of the garden; 10 sq m each","value":"1/3 of the garden; 10 sq m each"},{"label":"1/6 of the garden; 5 sq m each","value":"1/6 of the garden; 5 sq m each"},{"label":"1/4 of the garden; 7.5 sq m each","value":"1/4 of the garden; 7.5 sq m each"},{"label":"1/5 of the garden; 6 sq m each","value":"1/5 of the garden; 6 sq m each"}]}]'::jsonb);

