VALUES (4,'OA','4.OA.1','Interpret a multiplication equation as a comparison (Easy)','Practice Interpret a multiplication equation as a comparison','practice',1,10,217,'[{"id":1,"text":"Interpret this equation as a comparison: 3 × 6 = 18. Which statement is correct?","type":"multiple_choice","correct_answer":"18 is 3 times as many as 6","explanation":"A multiplication equation a × b = c means c is a times as many as b.","standard_code":"4.OA.1","difficulty":1,"options":[{"label":"18 is 3 times as many as 6","value":"18 is 3 times as many as 6"},{"label":"18 is 6 times as many as 3","value":"18 is 6 times as many as 3"},{"label":"6 is 3 times as many as 18","value":"6 is 3 times as many as 18"},{"label":"3 is 6 times as many as 18","value":"3 is 6 times as many as 18"}]},{"id":2,"text":"Write a comparison statement for 5 × 4 = 20.","type":"multiple_choice","correct_answer":"20 is 5 times as many as 4","explanation":"5 × 4 = 20 means 20 is 5 times as many as 4, or equivalently, 4 times as many as 5.","standard_code":"4.OA.1","difficulty":1,"options":[{"label":"20 is 4 times as many as 5","value":"20 is 4 times as many as 5"},{"label":"4 is 5 times as many as 20","value":"4 is 5 times as many as 20"},{"label":"5 is 4 times as many as 20","value":"5 is 4 times as many as 20"},{"label":"20 is 5 times as many as 4","value":"20 is 5 times as many as 4"}]},{"id":3,"text":"If 7 is 7 times as many as 1, write a multiplication equation.","type":"multiple_choice","correct_answer":"7 × 1 = 7","explanation":"''7 times as many as 1'' translates to 7 × 1 = 7.","standard_code":"4.OA.1","difficulty":1,"options":[{"label":"7 + 1 = 8","value":"7 + 1 = 8"},{"label":"7 × 1 = 7","value":"7 × 1 = 7"},{"label":"1 × 7 = 7","value":"1 × 7 = 7"},{"label":"7 ÷ 1 = 7","value":"7 ÷ 1 = 7"}]},{"id":4,"text":"Sara has 2 stickers. Tom has 4 times as many stickers as Sara. How many stickers does Tom have?","type":"multiple_choice","correct_answer":"8 stickers","explanation":"4 times as many as 2 is 4 × 2 = 8.","standard_code":"4.OA.1","difficulty":1,"options":[{"label":"6 stickers","value":"6 stickers"},{"label":"10 stickers","value":"10 stickers"},{"label":"8 stickers","value":"8 stickers"},{"label":"12 stickers","value":"12 stickers"}]},{"id":5,"text":"Which equation matches: ''24 is 8 times as many as 3''?","type":"multiple_choice","correct_answer":"8 × 3 = 24","explanation":"The phrase ''a times as many as b'' translates to a × b = the total.","standard_code":"4.OA.1","difficulty":1,"options":[{"label":"8 × 3 = 24","value":"8 × 3 = 24"},{"label":"24 ÷ 8 = 3","value":"24 ÷ 8 = 3"},{"label":"3 × 8 = 24","value":"3 × 8 = 24"},{"label":"24 × 3 = 8","value":"24 × 3 = 8"}]}]'::jsonb);

VALUES (4,'OA','4.OA.1','Interpret a multiplication equation as a comparison (Medium)','Practice Interpret a multiplication equation as a comparison','practice',2,15,218,'[{"id":1,"text":"A dog weighs 9 pounds. A cat weighs 3 times as much. Write a comparison equation.","type":"multiple_choice","correct_answer":"3 × 9 = 27","explanation":"3 times as much as 9 pounds is 3 × 9 = 27 pounds.","standard_code":"4.OA.1","difficulty":2,"options":[{"label":"3 × 9 = 27","value":"3 × 9 = 27"},{"label":"9 + 3 = 12","value":"9 + 3 = 12"},{"label":"27 × 9 = 3","value":"27 × 9 = 3"},{"label":"9 × 3 = 27","value":"9 × 3 = 27"}]},{"id":2,"text":"Maya has 6 marbles. Jake has 42 marbles. Jake has how many times as many marbles as Maya?","type":"multiple_choice","correct_answer":"7 times as many","explanation":"42 ÷ 6 = 7, so Jake has 7 times as many as Maya.","standard_code":"4.OA.1","difficulty":2,"options":[{"label":"36 times as many","value":"36 times as many"},{"label":"6 times as many","value":"6 times as many"},{"label":"7 times as many","value":"7 times as many"},{"label":"48 times as many","value":"48 times as many"}]},{"id":3,"text":"Complete the comparison: 56 is ___ times as many as 8.","type":"numeric","correct_answer":"7","explanation":"56 ÷ 8 = 7, so 56 is 7 times as many as 8.","standard_code":"4.OA.1","difficulty":2},{"id":4,"text":"A book costs $5. A game costs 9 times as much. How much does the game cost? Write the equation.","type":"multiple_choice","correct_answer":"9 × $5 = $45","explanation":"9 times as much as $5 is 9 × 5 = $45.","standard_code":"4.OA.1","difficulty":2,"options":[{"label":"9 + $5 = $14","value":"9 + $5 = $14"},{"label":"9 × $9 = $81","value":"9 × $9 = $81"},{"label":"5 × $5 = $25","value":"5 × $5 = $25"},{"label":"9 × $5 = $45","value":"9 × $5 = $45"}]},{"id":5,"text":"If 48 is 6 times as many as a number, what is that number?","type":"numeric","correct_answer":"8","explanation":"48 ÷ 6 = 8. So 48 is 6 times as many as 8.","standard_code":"4.OA.1","difficulty":2}]'::jsonb);

VALUES (4,'OA','4.OA.1','Interpret a multiplication equation as a comparison (Hard)','Practice Interpret a multiplication equation as a comparison','practice',3,20,219,'[{"id":1,"text":"Liam ran 4 miles. His dad ran 7 times as far. How far did his dad run? Write both a comparison statement and equation.","type":"multiple_choice","correct_answer":"His dad ran 28 miles; 7 × 4 = 28","explanation":"7 times as far as 4 miles = 7 × 4 = 28 miles.","standard_code":"4.OA.1","difficulty":3,"options":[{"label":"His dad ran 28 miles; 7 × 4 = 28","value":"His dad ran 28 miles; 7 × 4 = 28"},{"label":"His dad ran 32 miles; 4 × 8 = 32","value":"His dad ran 32 miles; 4 × 8 = 32"},{"label":"His dad ran 24 miles; 6 × 4 = 24","value":"His dad ran 24 miles; 6 × 4 = 24"},{"label":"His dad ran 11 miles; 4 + 7 = 11","value":"His dad ran 11 miles; 4 + 7 = 11"}]},{"id":2,"text":"A shelf has 8 books. Another shelf has 72 books. Write two different comparison statements.","type":"multiple_choice","correct_answer":"72 is 9 times as many as 8; 8 is 1/9 of 72","explanation":"72 ÷ 8 = 9, so 72 is 9 times as many as 8. Conversely, 8 is the smaller amount.","standard_code":"4.OA.1","difficulty":3,"options":[{"label":"72 is 10 times as many as 8; 8 is 1/10 of 72","value":"72 is 10 times as many as 8; 8 is 1/10 of 72"},{"label":"72 is 8 times as many as 8; 8 is 1/8 of 72","value":"72 is 8 times as many as 8; 8 is 1/8 of 72"},{"label":"72 is 64 times as many as 8; 8 is 1/64 of 72","value":"72 is 64 times as many as 8; 8 is 1/64 of 72"},{"label":"72 is 9 times as many as 8; 8 is 1/9 of 72","value":"72 is 9 times as many as 8; 8 is 1/9 of 72"}]},{"id":3,"text":"If n × 6 = 54, interpret the equation as a comparison statement.","type":"multiple_choice","correct_answer":"54 is n times as many as 6, where n = 9","explanation":"54 ÷ 6 = 9, so 54 is 9 times as many as 6.","standard_code":"4.OA.1","difficulty":3,"options":[{"label":"54 is n times as many as 6, where n = 9","value":"54 is n times as many as 6, where n = 9"},{"label":"n is 6 times as many as 54, where n = 9","value":"n is 6 times as many as 54, where n = 9"},{"label":"54 is 6 times as many as 9, where n = 9","value":"54 is 6 times as many as 9, where n = 9"},{"label":"54 is 8 times as many as 6, where n = 8","value":"54 is 8 times as many as 6, where n = 8"}]},{"id":4,"text":"Emma has 3 times as many cards as Lily. Together they have 48 cards. How many does each girl have?","type":"multiple_choice","correct_answer":"Lily has 12, Emma has 36","explanation":"Let Lily = x. Emma = 3x. x + 3x = 48, so 4x = 48, x = 12. Emma has 36.","standard_code":"4.OA.1","difficulty":3,"options":[{"label":"Lily has 12, Emma has 35","value":"Lily has 12, Emma has 35"},{"label":"Lily has 15, Emma has 36","value":"Lily has 15, Emma has 36"},{"label":"Lily has 16, Emma has 32","value":"Lily has 16, Emma has 32"},{"label":"Lily has 12, Emma has 36","value":"Lily has 12, Emma has 36"}]},{"id":5,"text":"Tom''s age is 4 times Kim''s age. Tom is 36. How old is Kim? Write the comparison equation.","type":"multiple_choice","correct_answer":"Kim is 9; 4 × 9 = 36","explanation":"36 ÷ 4 = 9. Kim is 9 years old. 4 × 9 = 36.","standard_code":"4.OA.1","difficulty":3,"options":[{"label":"Kim is 8; 4 × 8 = 32","value":"Kim is 8; 4 × 8 = 32"},{"label":"Kim is 9; 4 × 9 = 36","value":"Kim is 9; 4 × 9 = 36"},{"label":"Kim is 9; 9 + 4 = 13","value":"Kim is 9; 9 + 4 = 13"},{"label":"Kim is 32; 4 × 32 = 128","value":"Kim is 32; 4 × 32 = 128"}]}]'::jsonb);

VALUES (4,'OA','4.OA.2','Multiply or divide to solve word problems involving multiplicative comparison (Easy)','Practice Multiply or divide to solve word problems involving multiplicative comparison','practice',1,10,220,'[{"id":1,"text":"A cat weighs 6 pounds. A dog weighs 5 times as much. How much does the dog weigh?","type":"multiple_choice","correct_answer":"30 pounds","explanation":"5 × 6 = 30 pounds.","standard_code":"4.OA.2","difficulty":1,"options":[{"label":"25 pounds","value":"25 pounds"},{"label":"30 pounds","value":"30 pounds"},{"label":"36 pounds","value":"36 pounds"},{"label":"35 pounds","value":"35 pounds"}]},{"id":2,"text":"Ben has 3 toy cars. Alex has 4 times as many. How many toy cars does Alex have?","type":"multiple_choice","correct_answer":"12 toy cars","explanation":"4 × 3 = 12 toy cars.","standard_code":"4.OA.2","difficulty":1,"options":[{"label":"15 toy cars","value":"15 toy cars"},{"label":"12 toy cars total","value":"12 toy cars total"},{"label":"12 toy cars","value":"12 toy cars"},{"label":"7 toy cars","value":"7 toy cars"}]},{"id":3,"text":"A rope is 8 feet long. A ribbon is 2 times as long. How long is the ribbon?","type":"multiple_choice","correct_answer":"16 feet","explanation":"2 × 8 = 16 feet.","standard_code":"4.OA.2","difficulty":1,"options":[{"label":"24 feet","value":"24 feet"},{"label":"10 feet","value":"10 feet"},{"label":"6 feet","value":"6 feet"},{"label":"16 feet","value":"16 feet"}]},{"id":4,"text":"There are 7 red apples and 3 times as many green apples. How many green apples are there?","type":"multiple_choice","correct_answer":"21 green apples","explanation":"3 × 7 = 21 green apples.","standard_code":"4.OA.2","difficulty":1,"options":[{"label":"20 green apples","value":"20 green apples"},{"label":"21 green apples","value":"21 green apples"},{"label":"10 green apples","value":"10 green apples"},{"label":"24 green apples","value":"24 green apples"}]},{"id":5,"text":"A pencil costs 9 cents. An eraser costs 2 times as much. How much does the eraser cost?","type":"numeric","correct_answer":"18","explanation":"2 × 9 = 18 cents.","standard_code":"4.OA.2","difficulty":1}]'::jsonb);

VALUES (4,'OA','4.OA.2','Multiply or divide to solve word problems involving multiplicative comparison (Medium)','Practice Multiply or divide to solve word problems involving multiplicative comparison','practice',2,15,221,'[{"id":1,"text":"Maria scored 48 points. She scored 6 times as many points as Juan. How many points did Juan score?","type":"multiple_choice","correct_answer":"8 points","explanation":"48 ÷ 6 = 8 points.","standard_code":"4.OA.2","difficulty":2,"options":[{"label":"8 points","value":"8 points"},{"label":"6 points","value":"6 points"},{"label":"42 points","value":"42 points"},{"label":"12 points","value":"12 points"}]},{"id":2,"text":"A garden has 35 flowers. That is 5 times as many as a small pot. How many flowers are in the small pot?","type":"multiple_choice","correct_answer":"7 flowers","explanation":"35 ÷ 5 = 7 flowers.","standard_code":"4.OA.2","difficulty":2,"options":[{"label":"30 flowers","value":"30 flowers"},{"label":"10 flowers","value":"10 flowers"},{"label":"40 flowers","value":"40 flowers"},{"label":"7 flowers","value":"7 flowers"}]},{"id":3,"text":"Dad drove 63 miles, which is 9 times as far as Mom drove. How far did Mom drive?","type":"multiple_choice","correct_answer":"7 miles","explanation":"63 ÷ 9 = 7 miles.","standard_code":"4.OA.2","difficulty":2,"options":[{"label":"9 miles","value":"9 miles"},{"label":"56 miles","value":"56 miles"},{"label":"7 miles","value":"7 miles"},{"label":"54 miles","value":"54 miles"}]},{"id":4,"text":"Amy read 8 books this month. That is 4 times as many as last month. How many books did she read last month?","type":"multiple_choice","correct_answer":"2 books","explanation":"8 ÷ 4 = 2 books.","standard_code":"4.OA.2","difficulty":2,"options":[{"label":"4 books","value":"4 books"},{"label":"12 books","value":"12 books"},{"label":"32 books","value":"32 books"},{"label":"2 books","value":"2 books"}]},{"id":5,"text":"A large box holds 72 crayons, which is 8 times as many as a small box. How many crayons in the small box?","type":"multiple_choice","correct_answer":"9 crayons","explanation":"72 ÷ 8 = 9 crayons.","standard_code":"4.OA.2","difficulty":2,"options":[{"label":"64 crayons","value":"64 crayons"},{"label":"8 crayons","value":"8 crayons"},{"label":"9 crayons","value":"9 crayons"},{"label":"10 crayons","value":"10 crayons"}]}]'::jsonb);

VALUES (4,'OA','4.OA.2','Multiply or divide to solve word problems involving multiplicative comparison (Hard)','Practice Multiply or divide to solve word problems involving multiplicative comparison','practice',3,20,222,'[{"id":1,"text":"Sam collected 3 times as many shells as Mia. Together they collected 56 shells. How many did each collect?","type":"multiple_choice","correct_answer":"Mia: 14, Sam: 42","explanation":"Let Mia = x, Sam = 3x. x + 3x = 56 → 4x = 56 → x = 14. Sam = 42.","standard_code":"4.OA.2","difficulty":3,"options":[{"label":"Mia: 12, Sam: 44","value":"Mia: 12, Sam: 44"},{"label":"Mia: 14, Sam: 42","value":"Mia: 14, Sam: 42"},{"label":"Mia: 18, Sam: 38","value":"Mia: 18, Sam: 38"},{"label":"Mia: 14, Sam: 42 total","value":"Mia: 14, Sam: 42 total"}]},{"id":2,"text":"A truck weighs 5 times as much as a car. Together they weigh 5,400 pounds. How much does each weigh?","type":"multiple_choice","correct_answer":"Car: 900 lbs, Truck: 4,500 lbs","explanation":"Let car = x. 5x + x = 5400 → 6x = 5400 → x = 900. Truck = 4500.","standard_code":"4.OA.2","difficulty":3,"options":[{"label":"Car: 1,080 lbs, Truck: 4,320 lbs","value":"Car: 1,080 lbs, Truck: 4,320 lbs"},{"label":"Car: 800 lbs, Truck: 4,600 lbs","value":"Car: 800 lbs, Truck: 4,600 lbs"},{"label":"Car: 900 lbs, Truck: 4,500 lbs","value":"Car: 900 lbs, Truck: 4,500 lbs"},{"label":"Car: 1,000 lbs, Truck: 4,400 lbs","value":"Car: 1,000 lbs, Truck: 4,400 lbs"}]},{"id":3,"text":"There are 3 times as many girls as boys in a class. There are 32 students total. How many boys and girls?","type":"multiple_choice","correct_answer":"8 boys, 24 girls","explanation":"Let boys = b. Girls = 3b. b + 3b = 32 → 4b = 32 → b = 8, girls = 24.","standard_code":"4.OA.2","difficulty":3,"options":[{"label":"6 boys, 26 girls","value":"6 boys, 26 girls"},{"label":"8 boys, 25 girls","value":"8 boys, 25 girls"},{"label":"8 boys, 24 girls","value":"8 boys, 24 girls"},{"label":"10 boys, 22 girls","value":"10 boys, 22 girls"}]},{"id":4,"text":"The length of a rectangle is 6 times its width. The perimeter is 56 cm. Find the length and width.","type":"multiple_choice","correct_answer":"Width: 4 cm, Length: 24 cm","explanation":"Let w = width. Length = 6w. 2(6w + w) = 56 → 14w = 56 → w = 4. Length = 24.","standard_code":"4.OA.2","difficulty":3,"options":[{"label":"Width: 5 cm, Length: 23 cm","value":"Width: 5 cm, Length: 23 cm"},{"label":"Width: 4 cm, Length: 20 cm","value":"Width: 4 cm, Length: 20 cm"},{"label":"Width: 3 cm, Length: 18 cm","value":"Width: 3 cm, Length: 18 cm"},{"label":"Width: 4 cm, Length: 24 cm","value":"Width: 4 cm, Length: 24 cm"}]},{"id":5,"text":"Ella has 4 times as many stickers as Nora. If Ella gives 15 stickers to Nora, they have the same amount. How many did each start with?","type":"multiple_choice","correct_answer":"Nora: 10, Ella: 40","explanation":"Let Nora = n, Ella = 4n. 4n − 15 = n + 15 → 3n = 30 → n = 10. Ella = 40.","standard_code":"4.OA.2","difficulty":3,"options":[{"label":"Nora: 10, Ella: 40","value":"Nora: 10, Ella: 40"},{"label":"Nora: 12, Ella: 38","value":"Nora: 12, Ella: 38"},{"label":"Nora: 5, Ella: 20","value":"Nora: 5, Ella: 20"},{"label":"Nora: 15, Ella: 45","value":"Nora: 15, Ella: 45"}]}]'::jsonb);

VALUES (4,'OA','4.OA.3','Solve multistep word problems using the four operations (Easy)','Practice Solve multistep word problems using the four operations','practice',1,10,223,'[{"id":1,"text":"A store sold 24 apples in the morning and 36 in the afternoon. They packed them in bags of 6. How many bags?","type":"multiple_choice","correct_answer":"10 bags","explanation":"24 + 36 = 60. 60 ÷ 6 = 10 bags.","standard_code":"4.OA.3","difficulty":1,"options":[{"label":"10 bags","value":"10 bags"},{"label":"12 bags","value":"12 bags"},{"label":"9 bags","value":"9 bags"},{"label":"11 bags","value":"11 bags"}]},{"id":2,"text":"Tom had 50 stickers. He gave 12 to Sam and 8 to Lily. How many does he have left?","type":"multiple_choice","correct_answer":"30 stickers","explanation":"50 − 12 − 8 = 30 stickers.","standard_code":"4.OA.3","difficulty":1,"options":[{"label":"32 stickers","value":"32 stickers"},{"label":"30 stickers","value":"30 stickers"},{"label":"20 stickers","value":"20 stickers"},{"label":"40 stickers","value":"40 stickers"}]},{"id":3,"text":"Each box has 8 cookies. There are 5 boxes. If 10 cookies are eaten, how many are left?","type":"multiple_choice","correct_answer":"30 cookies","explanation":"8 × 5 = 40. 40 − 10 = 30.","standard_code":"4.OA.3","difficulty":1,"options":[{"label":"40 cookies","value":"40 cookies"},{"label":"35 cookies","value":"35 cookies"},{"label":"30 cookies","value":"30 cookies"},{"label":"28 cookies","value":"28 cookies"}]},{"id":4,"text":"A class has 4 rows of 7 desks plus 3 extra desks. How many desks total?","type":"multiple_choice","correct_answer":"31 desks","explanation":"4 × 7 = 28. 28 + 3 = 31.","standard_code":"4.OA.3","difficulty":1,"options":[{"label":"35 desks","value":"35 desks"},{"label":"28 desks","value":"28 desks"},{"label":"31 desks","value":"31 desks"},{"label":"32 desks","value":"32 desks"}]},{"id":5,"text":"Maria earned $9 each day for 5 days. She spent $15. How much does she have?","type":"multiple_choice","correct_answer":"$30","explanation":"9 × 5 = 45. 45 − 15 = 30.","standard_code":"4.OA.3","difficulty":1,"options":[{"label":"$40","value":"$40"},{"label":"$30","value":"$30"},{"label":"$45","value":"$45"},{"label":"$35","value":"$35"}]}]'::jsonb);

VALUES (4,'OA','4.OA.3','Solve multistep word problems using the four operations (Medium)','Practice Solve multistep word problems using the four operations','practice',2,15,224,'[{"id":1,"text":"A school ordered 6 boxes of pencils with 24 pencils each. They divided them equally among 8 classrooms. How many pencils per classroom?","type":"multiple_choice","correct_answer":"18 pencils","explanation":"6 × 24 = 144. 144 ÷ 8 = 18.","standard_code":"4.OA.3","difficulty":2,"options":[{"label":"20 pencils","value":"20 pencils"},{"label":"16 pencils","value":"16 pencils"},{"label":"24 pencils","value":"24 pencils"},{"label":"18 pencils","value":"18 pencils"}]},{"id":2,"text":"Sam has $100. He buys 3 books at $12 each and 2 notebooks at $7 each. How much money is left?","type":"multiple_choice","correct_answer":"$50","explanation":"3 × 12 = 36. 2 × 7 = 14. 36 + 14 = 50. 100 − 50 = 50.","standard_code":"4.OA.3","difficulty":2,"options":[{"label":"$58","value":"$58"},{"label":"$64","value":"$64"},{"label":"$42","value":"$42"},{"label":"$50","value":"$50"}]},{"id":3,"text":"A baker made 240 muffins. He sold 185 and gave away 30. He wants to pack the rest in boxes of 5. How many boxes?","type":"multiple_choice","correct_answer":"5 boxes","explanation":"240 − 185 − 30 = 25. 25 ÷ 5 = 5.","standard_code":"4.OA.3","difficulty":2,"options":[{"label":"10 boxes","value":"10 boxes"},{"label":"8 boxes","value":"8 boxes"},{"label":"7 boxes","value":"7 boxes"},{"label":"5 boxes","value":"5 boxes"}]},{"id":4,"text":"There are 156 students going on a field trip. Each bus holds 48 students. How many buses are needed?","type":"multiple_choice","correct_answer":"4 buses","explanation":"156 ÷ 48 = 3 remainder 12. You need 4 buses to seat everyone.","standard_code":"4.OA.3","difficulty":2,"options":[{"label":"6 buses","value":"6 buses"},{"label":"5 buses","value":"5 buses"},{"label":"3 buses","value":"3 buses"},{"label":"4 buses","value":"4 buses"}]},{"id":5,"text":"A farmer picks 35 oranges per hour for 8 hours. He packs them in bags of 7. How many bags?","type":"multiple_choice","correct_answer":"40 bags","explanation":"35 × 8 = 280. 280 ÷ 7 = 40.","standard_code":"4.OA.3","difficulty":2,"options":[{"label":"40 bags","value":"40 bags"},{"label":"45 bags","value":"45 bags"},{"label":"50 bags","value":"50 bags"},{"label":"35 bags","value":"35 bags"}]}]'::jsonb);

VALUES (4,'OA','4.OA.3','Solve multistep word problems using the four operations (Hard)','Practice Solve multistep word problems using the four operations','practice',3,20,225,'[{"id":1,"text":"A theater has 12 rows of 15 seats plus 8 rows of 20 seats. If 245 tickets are sold, how many empty seats?","type":"multiple_choice","correct_answer":"95 empty seats","explanation":"12 × 15 = 180. 8 × 20 = 160. 180 + 160 = 340. 340 − 245 = 95.","standard_code":"4.OA.3","difficulty":3,"options":[{"label":"115 empty seats","value":"115 empty seats"},{"label":"95 empty seats","value":"95 empty seats"},{"label":"105 empty seats","value":"105 empty seats"},{"label":"75 empty seats","value":"75 empty seats"}]},{"id":2,"text":"A store received 1,500 bottles of water. They sold 847 on Monday and 398 on Tuesday. They need to order more if fewer than 100 are left. Should they order more?","type":"multiple_choice","correct_answer":"Yes, only 255 are left","explanation":"1500 − 847 − 398 = 255. 255 > 100, actually they should NOT order more.","standard_code":"4.OA.3","difficulty":3,"options":[{"label":"Yes, only 150 are left","value":"Yes, only 150 are left"},{"label":"No, 398 are left","value":"No, 398 are left"},{"label":"No, 255 are left","value":"No, 255 are left"},{"label":"Yes, only 255 are left","value":"Yes, only 255 are left"}]},{"id":3,"text":"Mia saves $8 per week. After 9 weeks, she buys a book for $23 and a game for $34. How much is left?","type":"multiple_choice","correct_answer":"$15","explanation":"8 × 9 = 72. 23 + 34 = 57. 72 − 57 = 15.","standard_code":"4.OA.3","difficulty":3,"options":[{"label":"$25","value":"$25"},{"label":"$22","value":"$22"},{"label":"$18","value":"$18"},{"label":"$15","value":"$15"}]},{"id":4,"text":"A factory makes 1,200 toys. They ship 48 toys per box. After filling as many boxes as possible, how many toys are left over?","type":"multiple_choice","correct_answer":"0 toys left over","explanation":"1200 ÷ 48 = 25 exactly. No remainder.","standard_code":"4.OA.3","difficulty":3,"options":[{"label":"24 toys left over","value":"24 toys left over"},{"label":"48 toys left over","value":"48 toys left over"},{"label":"12 toys left over","value":"12 toys left over"},{"label":"0 toys left over","value":"0 toys left over"}]},{"id":5,"text":"A garden has 4 sections. Each section has 6 rows with 9 plants per row. If 50 plants die, how many are alive?","type":"multiple_choice","correct_answer":"166 plants","explanation":"4 × 6 × 9 = 216. 216 − 50 = 166.","standard_code":"4.OA.3","difficulty":3,"options":[{"label":"200 plants","value":"200 plants"},{"label":"154 plants","value":"154 plants"},{"label":"166 plants","value":"166 plants"},{"label":"176 plants","value":"176 plants"}]}]'::jsonb);

VALUES (4,'OA','4.OA.4','Find all factor pairs and determine prime or composite (Easy)','Practice Find all factor pairs and determine prime or composite','practice',1,10,226,'[{"id":1,"text":"List all the factors of 12.","type":"multiple_choice","correct_answer":"1, 2, 3, 4, 6, 12","explanation":"Check each number 1–12: 12÷1=12, 12÷2=6, 12÷3=4. Factor pairs: (1,12), (2,6), (3,4).","standard_code":"4.OA.4","difficulty":1,"options":[{"label":"2, 3, 4, 6, 12","value":"2, 3, 4, 6, 12"},{"label":"1, 2, 4, 6, 12","value":"1, 2, 4, 6, 12"},{"label":"1, 2, 3, 6, 12","value":"1, 2, 3, 6, 12"},{"label":"1, 2, 3, 4, 6, 12","value":"1, 2, 3, 4, 6, 12"}]},{"id":2,"text":"Is 7 prime or composite?","type":"multiple_choice","correct_answer":"Prime","explanation":"7 has only two factors: 1 and 7. That makes it prime.","standard_code":"4.OA.4","difficulty":1,"options":[{"label":"Neither","value":"Neither"},{"label":"Composite","value":"Composite"},{"label":"Prime","value":"Prime"},{"label":"Even","value":"Even"}]},{"id":3,"text":"List all the factors of 18.","type":"multiple_choice","correct_answer":"1, 2, 3, 6, 9, 18","explanation":"Factor pairs: (1,18), (2,9), (3,6).","standard_code":"4.OA.4","difficulty":1,"options":[{"label":"2, 3, 6, 9, 18","value":"2, 3, 6, 9, 18"},{"label":"1, 2, 3, 6, 9, 18","value":"1, 2, 3, 6, 9, 18"},{"label":"1, 3, 6, 9, 18","value":"1, 3, 6, 9, 18"},{"label":"1, 2, 3, 9, 18","value":"1, 2, 3, 9, 18"}]},{"id":4,"text":"Is 9 prime or composite?","type":"multiple_choice","correct_answer":"Composite","explanation":"9 = 3 × 3, so it has more than two factors (1, 3, 9).","standard_code":"4.OA.4","difficulty":1,"options":[{"label":"Even","value":"Even"},{"label":"Neither","value":"Neither"},{"label":"Composite","value":"Composite"},{"label":"Prime","value":"Prime"}]},{"id":5,"text":"What are all the factor pairs of 10?","type":"multiple_choice","correct_answer":"(1, 10) and (2, 5)","explanation":"1×10=10 and 2×5=10. Those are all factor pairs.","standard_code":"4.OA.4","difficulty":1,"options":[{"label":"(1, 5) and (2, 10)","value":"(1, 5) and (2, 10)"},{"label":"(2, 5) only","value":"(2, 5) only"},{"label":"(1, 10) and (2, 5)","value":"(1, 10) and (2, 5)"},{"label":"(1, 10) and (5, 2)","value":"(1, 10) and (5, 2)"}]}]'::jsonb);

VALUES (4,'OA','4.OA.4','Find all factor pairs and determine prime or composite (Medium)','Practice Find all factor pairs and determine prime or composite','practice',2,15,227,'[{"id":1,"text":"Find all factor pairs of 36.","type":"multiple_choice","correct_answer":"(1,36), (2,18), (3,12), (4,9), (6,6)","explanation":"Check divisibility: 36÷1, 36÷2, 36÷3, 36÷4, 36÷6 all give whole numbers.","standard_code":"4.OA.4","difficulty":2,"options":[{"label":"(1,36), (2,18), (3,12), (4,9), (6,6)","value":"(1,36), (2,18), (3,12), (4,9), (6,6)"},{"label":"(1,36), (2,18), (3,12), (6,6)","value":"(1,36), (2,18), (3,12), (6,6)"},{"label":"(2,18), (3,12), (4,9), (6,6)","value":"(2,18), (3,12), (4,9), (6,6)"},{"label":"(1,36), (2,18), (4,9), (6,6)","value":"(1,36), (2,18), (4,9), (6,6)"}]},{"id":2,"text":"Is 51 prime or composite? Explain.","type":"multiple_choice","correct_answer":"Composite (51 = 3 × 17)","explanation":"51 ÷ 3 = 17. Since 51 has factors other than 1 and itself, it''s composite.","standard_code":"4.OA.4","difficulty":2,"options":[{"label":"Prime (51 is only divisible by 1 and 51)","value":"Prime (51 is only divisible by 1 and 51)"},{"label":"Composite (51 = 3 × 17)","value":"Composite (51 = 3 × 17)"},{"label":"Prime (51 cannot be divided evenly by 2)","value":"Prime (51 cannot be divided evenly by 2)"},{"label":"Composite (51 = 6 × 8.5)","value":"Composite (51 = 6 × 8.5)"}]},{"id":3,"text":"Which numbers between 20 and 30 are prime?","type":"multiple_choice","correct_answer":"23 and 29","explanation":"Check each: 20(comp), 21(comp), 22(comp), 23(prime), 24(comp), 25(comp), 26(comp), 27(comp), 28(comp), 29(prime), 30(comp).","standard_code":"4.OA.4","difficulty":2,"options":[{"label":"25 and 29","value":"25 and 29"},{"label":"23 and 29","value":"23 and 29"},{"label":"21 and 29","value":"21 and 29"},{"label":"23 and 27","value":"23 and 27"}]},{"id":4,"text":"How many factors does 24 have?","type":"multiple_choice","correct_answer":"8 factors","explanation":"Factors: 1, 2, 3, 4, 6, 8, 12, 24. That''s 8 factors.","standard_code":"4.OA.4","difficulty":2,"options":[{"label":"8 factors","value":"8 factors"},{"label":"12 factors","value":"12 factors"},{"label":"10 factors","value":"10 factors"},{"label":"6 factors","value":"6 factors"}]},{"id":5,"text":"Is 1 prime, composite, or neither?","type":"multiple_choice","correct_answer":"Neither","explanation":"1 has only one factor (itself). Prime numbers must have exactly two factors.","standard_code":"4.OA.4","difficulty":2,"options":[{"label":"Composite","value":"Composite"},{"label":"Both prime and composite","value":"Both prime and composite"},{"label":"Prime","value":"Prime"},{"label":"Neither","value":"Neither"}]}]'::jsonb);

VALUES (4,'OA','4.OA.4','Find all factor pairs and determine prime or composite (Hard)','Practice Find all factor pairs and determine prime or composite','practice',3,20,228,'[{"id":1,"text":"Find all the factors of 48. How many factor pairs are there?","type":"multiple_choice","correct_answer":"Factors: 1,2,3,4,6,8,12,16,24,48 - 5 factor pairs","explanation":"Pairs: (1,48),(2,24),(3,16),(4,12),(6,8). That''s 5 pairs, 10 factors.","standard_code":"4.OA.4","difficulty":3,"options":[{"label":"Factors: 1,2,3,4,6,8,12,16,24,48 - 6 factor pairs","value":"Factors: 1,2,3,4,6,8,12,16,24,48 - 6 factor pairs"},{"label":"Factors: 1,2,3,4,6,8,12,16,24,48 - 5 factor pairs","value":"Factors: 1,2,3,4,6,8,12,16,24,48 - 5 factor pairs"},{"label":"Factors: 1,2,3,4,6,8,12,16,24,48 - 8 factor pairs","value":"Factors: 1,2,3,4,6,8,12,16,24,48 - 8 factor pairs"},{"label":"Factors: 1,2,3,4,6,8,12,24,48 - 4 factor pairs","value":"Factors: 1,2,3,4,6,8,12,24,48 - 4 factor pairs"}]},{"id":2,"text":"What is the smallest number that has exactly 6 factors?","type":"numeric","correct_answer":"12","explanation":"12 has factors: 1,2,3,4,6,12 - exactly 6. Numbers before 12 have fewer.","standard_code":"4.OA.4","difficulty":3},{"id":3,"text":"A number between 60 and 70 is prime. What is it?","type":"multiple_choice","correct_answer":"61 and 67","explanation":"Check: 61 is prime (not divisible by 2,3,5,7). 67 is prime. Others are composite.","standard_code":"4.OA.4","difficulty":3,"options":[{"label":"59 and 61","value":"59 and 61"},{"label":"61 and 67","value":"61 and 67"},{"label":"67 only","value":"67 only"},{"label":"61 only","value":"61 only"}]},{"id":4,"text":"Can an even number greater than 2 be prime? Explain.","type":"multiple_choice","correct_answer":"No","explanation":"Every even number > 2 is divisible by 2 and itself, giving at least 3 factors, so it''s composite.","standard_code":"4.OA.4","difficulty":3,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]},{"id":5,"text":"Find a number less than 50 that has exactly 3 factors.","type":"multiple_choice","correct_answer":"4, 9, 25, or 49","explanation":"Numbers with exactly 3 factors are squares of primes: 2²=4(1,2,4), 3²=9(1,3,9), 5²=25(1,5,25), 7²=49(1,7,49).","standard_code":"4.OA.4","difficulty":3,"options":[{"label":"9 and 25","value":"9 and 25"},{"label":"16 and 36","value":"16 and 36"},{"label":"4, 9, 25, or 49","value":"4, 9, 25, or 49"},{"label":"16, 25, and 36","value":"16, 25, and 36"}]}]'::jsonb);

VALUES (4,'OA','4.OA.5','Generate and analyze a number or shape pattern (Easy)','Practice Generate and analyze a number or shape pattern','practice',1,10,229,'[{"id":1,"text":"What is the rule for this pattern? 2, 4, 6, 8, 10, …","type":"multiple_choice","correct_answer":"Add 2","explanation":"Each number is 2 more than the previous: 2+2=4, 4+2=6, etc.","standard_code":"4.OA.5","difficulty":1,"options":[{"label":"Add 2","value":"Add 2"},{"label":"Add 1","value":"Add 1"},{"label":"Multiply by 2","value":"Multiply by 2"},{"label":"Subtract 2","value":"Subtract 2"}]},{"id":2,"text":"Continue the pattern: 5, 10, 15, 20, ___","type":"numeric","correct_answer":"25","explanation":"The rule is add 5. 20 + 5 = 25.","standard_code":"4.OA.5","difficulty":1},{"id":3,"text":"What is the rule? 3, 6, 9, 12, 15, …","type":"multiple_choice","correct_answer":"Add 3","explanation":"Each term increases by 3.","standard_code":"4.OA.5","difficulty":1,"options":[{"label":"Multiply by 2","value":"Multiply by 2"},{"label":"Multiply by 3","value":"Multiply by 3"},{"label":"Add 4","value":"Add 4"},{"label":"Add 3","value":"Add 3"}]},{"id":4,"text":"Continue: 1, 4, 7, 10, ___","type":"numeric","correct_answer":"13","explanation":"The rule is add 3. 10 + 3 = 13.","standard_code":"4.OA.5","difficulty":1},{"id":5,"text":"What comes next? 100, 90, 80, 70, ___","type":"numeric","correct_answer":"60","explanation":"The rule is subtract 10. 70 − 10 = 60.","standard_code":"4.OA.5","difficulty":1}]'::jsonb);

VALUES (4,'OA','4.OA.5','Generate and analyze a number or shape pattern (Medium)','Practice Generate and analyze a number or shape pattern','practice',2,15,230,'[{"id":1,"text":"The rule is ''start at 1, add 5.'' Generate the first 6 terms. Are all the terms odd?","type":"multiple_choice","correct_answer":"1, 6, 11, 16, 21, 26. No, they alternate odd/even.","explanation":"1(odd), 6(even), 11(odd), 16(even), 21(odd), 26(even). They alternate.","standard_code":"4.OA.5","difficulty":2,"options":[{"label":"1, 6, 11, 16, 21, 26. No, they alternate odd/even.","value":"1, 6, 11, 16, 21, 26. No, they alternate odd/even."},{"label":"1, 6, 11, 16, 21, 26. Yes, all are odd.","value":"1, 6, 11, 16, 21, 26. Yes, all are odd."},{"label":"1, 6, 11, 16, 21, 26. Yes, most are odd.","value":"1, 6, 11, 16, 21, 26. Yes, most are odd."},{"label":"1, 6, 11, 16, 21, 26. No, all are even.","value":"1, 6, 11, 16, 21, 26. No, all are even."}]},{"id":2,"text":"Pattern: 2, 6, 18, 54, ___. What is the rule?","type":"multiple_choice","correct_answer":"Multiply by 3. Next term is 162.","explanation":"2×3=6, 6×3=18, 18×3=54, 54×3=162.","standard_code":"4.OA.5","difficulty":2,"options":[{"label":"Multiply by 4. Next term is 216.","value":"Multiply by 4. Next term is 216."},{"label":"Multiply by 2. Next term is 108.","value":"Multiply by 2. Next term is 108."},{"label":"Add 3. Next term is 57.","value":"Add 3. Next term is 57."},{"label":"Multiply by 3. Next term is 162.","value":"Multiply by 3. Next term is 162."}]},{"id":3,"text":"Start at 3, add 4 each time. What is the 8th number in the pattern?","type":"numeric","correct_answer":"31","explanation":"3, 7, 11, 15, 19, 23, 27, 31. The 8th term is 31.","standard_code":"4.OA.5","difficulty":2},{"id":4,"text":"A pattern starts at 0 and adds 7 each time. Will the number 50 appear in this pattern?","type":"multiple_choice","correct_answer":"No","explanation":"0, 7, 14, 21, 28, 35, 42, 49, 56… It skips from 49 to 56. 50 is not a multiple of 7.","standard_code":"4.OA.5","difficulty":2,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]},{"id":5,"text":"In the pattern 4, 8, 12, 16, 20…, what do you notice about whether the numbers are odd or even?","type":"multiple_choice","correct_answer":"All numbers are even","explanation":"Adding 4 (even) to an even number always gives an even number.","standard_code":"4.OA.5","difficulty":2,"options":[{"label":"All numbers are even","value":"All numbers are even"},{"label":"Some numbers are odd and some are even","value":"Some numbers are odd and some are even"},{"label":"Numbers alternate between odd and even","value":"Numbers alternate between odd and even"},{"label":"All numbers are odd","value":"All numbers are odd"}]}]'::jsonb);

VALUES (4,'OA','4.OA.5','Generate and analyze a number or shape pattern (Hard)','Practice Generate and analyze a number or shape pattern','practice',3,20,231,'[{"id":1,"text":"Start at 1, multiply by 2 each time. What are the first 8 terms? What do you notice about odd/even?","type":"multiple_choice","correct_answer":"1, 2, 4, 8, 16, 32, 64, 128. After the first term, all are even.","explanation":"1 is odd; multiplying by 2 produces all even numbers from the 2nd term on.","standard_code":"4.OA.5","difficulty":3,"options":[{"label":"1, 2, 4, 8, 16, 32, 64, 128. After the first term, all are even.","value":"1, 2, 4, 8, 16, 32, 64, 128. After the first term, all are even."},{"label":"2, 4, 8, 16, 32, 64, 128, 256. All are even.","value":"2, 4, 8, 16, 32, 64, 128, 256. All are even."},{"label":"1, 2, 4, 8, 16, 32, 64, 128. All are even.","value":"1, 2, 4, 8, 16, 32, 64, 128. All are even."},{"label":"1, 2, 4, 8, 16, 32, 64, 128. All are odd.","value":"1, 2, 4, 8, 16, 32, 64, 128. All are odd."}]},{"id":2,"text":"Two patterns start at 0. Pattern A adds 3. Pattern B adds 6. Compare the 5th terms of each.","type":"multiple_choice","correct_answer":"A: 12, B: 24. B is always twice A.","explanation":"A: 0,3,6,9,12. B: 0,6,12,18,24. Each term in B is exactly 2 times the corresponding term in A.","standard_code":"4.OA.5","difficulty":3,"options":[{"label":"A: 12, B: 24. B is always twice A.","value":"A: 12, B: 24. B is always twice A."},{"label":"A: 12, B: 24. A is always twice B.","value":"A: 12, B: 24. A is always twice B."},{"label":"A: 12, B: 24. A and B are equal.","value":"A: 12, B: 24. A and B are equal."},{"label":"A: 15, B: 30. B is always twice A.","value":"A: 15, B: 30. B is always twice A."}]},{"id":3,"text":"A shape pattern repeats: triangle, square, circle. What is the 47th shape?","type":"multiple_choice","correct_answer":"Square","explanation":"47 ÷ 3 = 15 remainder 2. The 2nd shape in the cycle is square.","standard_code":"4.OA.5","difficulty":3,"options":[{"label":"Square","value":"Square"},{"label":"Circle","value":"Circle"},{"label":"Triangle","value":"Triangle"},{"label":"Pentagon","value":"Pentagon"}]},{"id":4,"text":"Start at 5 and add 3 each time. Will any numbers in the pattern be divisible by 6? Find the first one.","type":"multiple_choice","correct_answer":"Yes, suffered: the 3rd term (11)… No - actually checking: 5,8,11,14,17,20. 20 is not div by 6. Continuing: 23,26,29,32,35,38. 38 not div by 6. Actually none of 5+3n are divisible by 6 until 5+3(7)=26, no. Let me recalculate: 5,8,11,14,17,20,23,26,29,32,35,38,41,44,47,50,53,56. Actually terms are 5+3n. For divisibility by 6: 5+3n≡0 mod 6 → 3n≡1 mod 6, which has no solution since 3n is always 0 or 3 mod 6. So NO.","explanation":"Numbers in this pattern have the form 5+3n. Since 5+3n is never divisible by 6 (checking mod 6: always remainder 2 or 5), no term is divisible by 6.","standard_code":"4.OA.5","difficulty":3,"options":[{"label":"Yes, the 5th term (20)","value":"Yes, the 5th term (20)"},{"label":"Yes, the 10th term (32)","value":"Yes, the 10th term (32)"},{"label":"Yes, suffered: the 3rd term (11)… No - actually checking: 5,8,11,14,17,20. 20 is not div by 6. Continuing: 23,26,29,32,35,38. 38 not div by 6. Actually none of 5+3n are divisible by 6 until 5+3(7)=26, no. Let me recalculate: 5,8,11,14,17,20,23,26,29,32,35,38,41,44,47,50,53,56. Actually terms are 5+3n. For divisibility by 6: 5+3n≡0 mod 6 → 3n≡1 mod 6, which has no solution since 3n is always 0 or 3 mod 6. So NO.","value":"Yes, suffered: the 3rd term (11)… No - actually checking: 5,8,11,14,17,20. 20 is not div by 6. Continuing: 23,26,29,32,35,38. 38 not div by 6. Actually none of 5+3n are divisible by 6 until 5+3(7)=26, no. Let me recalculate: 5,8,11,14,17,20,23,26,29,32,35,38,41,44,47,50,53,56. Actually terms are 5+3n. For divisibility by 6: 5+3n≡0 mod 6 → 3n≡1 mod 6, which has no solution since 3n is always 0 or 3 mod 6. So NO."},{"label":"Yes, the 8th term (26)","value":"Yes, the 8th term (26)"}]},{"id":5,"text":"Pattern A: start at 0, add 4. Pattern B: start at 0, add 12. The 6th term of Pattern B equals which term of Pattern A?","type":"multiple_choice","correct_answer":"The 16th term","explanation":"B''s 6th term: 0+12×5=60. In A: 0+4×(n-1)=60 → n-1=15 → n=16. So A''s 16th term.","standard_code":"4.OA.5","difficulty":3,"options":[{"label":"The 12th term","value":"The 12th term"},{"label":"The 20th term","value":"The 20th term"},{"label":"The 16th term","value":"The 16th term"},{"label":"The 18th term","value":"The 18th term"}]}]'::jsonb);

VALUES (4,'NBT','4.NBT.1','Recognize that a digit in one place represents ten times what it represents in the place to its right (Easy)','Practice Recognize that a digit in one place represents ten times what it represents in the place to its right','practice',1,10,232,'[{"id":1,"text":"In the number 440, how many times greater is the 4 in the hundreds place than the 4 in the tens place?","type":"multiple_choice","correct_answer":"10 times greater","explanation":"The hundreds place is one place to the left of tens, so the digit represents 10 times as much.","standard_code":"4.NBT.1","difficulty":1,"options":[{"label":"20 times greater","value":"20 times greater"},{"label":"5 times greater","value":"5 times greater"},{"label":"10 times greater","value":"10 times greater"},{"label":"100 times greater","value":"100 times greater"}]},{"id":2,"text":"What is the value of the 3 in 3,000?","type":"multiple_choice","correct_answer":"3,000","explanation":"The 3 is in the thousands place, so its value is 3 × 1,000 = 3,000.","standard_code":"4.NBT.1","difficulty":1,"options":[{"label":"3,000","value":"3,000"},{"label":"30","value":"30"},{"label":"3","value":"3"},{"label":"300","value":"300"}]},{"id":3,"text":"In 550, what is the value of the 5 in the hundreds place?","type":"numeric","correct_answer":"500","explanation":"5 in the hundreds place = 5 × 100 = 500.","standard_code":"4.NBT.1","difficulty":1},{"id":4,"text":"In 660, the 6 in the tens place has a value of 60. What is the value of the 6 in the hundreds place?","type":"numeric","correct_answer":"600","explanation":"600 is 10 times 60, because the hundreds place is one position to the left.","standard_code":"4.NBT.1","difficulty":1},{"id":5,"text":"What place value is 10 times greater than the ones place?","type":"multiple_choice","correct_answer":"Tens place","explanation":"Each place value is 10 times the place to its right: ones → tens (×10).","standard_code":"4.NBT.1","difficulty":1,"options":[{"label":"Hundreds place","value":"Hundreds place"},{"label":"Tens place","value":"Tens place"},{"label":"Hundreds place","value":"Hundreds place"},{"label":"Ones place","value":"Ones place"}]}]'::jsonb);

VALUES (4,'NBT','4.NBT.1','Recognize that a digit in one place represents ten times what it represents in the place to its right (Medium)','Practice Recognize that a digit in one place represents ten times what it represents in the place to its right','practice',2,15,233,'[{"id":1,"text":"In 7,700, the 7 appears in two places. How many times greater is the thousands-place 7 than the hundreds-place 7?","type":"multiple_choice","correct_answer":"10 times greater","explanation":"7,000 ÷ 700 = 10. The thousands place is 10× the hundreds place.","standard_code":"4.NBT.1","difficulty":2,"options":[{"label":"7 times greater","value":"7 times greater"},{"label":"10 times greater","value":"10 times greater"},{"label":"1,000 times greater","value":"1,000 times greater"},{"label":"100 times greater","value":"100 times greater"}]},{"id":2,"text":"How many times greater is the value of 5 in 50,000 compared to the 5 in 5,000?","type":"multiple_choice","correct_answer":"10 times greater","explanation":"50,000 ÷ 5,000 = 10. Ten-thousands is 10× thousands.","standard_code":"4.NBT.1","difficulty":2,"options":[{"label":"1,000 times greater","value":"1,000 times greater"},{"label":"10 times greater","value":"10 times greater"},{"label":"100 times greater","value":"100 times greater"},{"label":"5 times greater","value":"5 times greater"}]},{"id":3,"text":"In 88,888, how many times greater is the leftmost 8 than the rightmost 8?","type":"multiple_choice","correct_answer":"10,000 times greater","explanation":"80,000 ÷ 8 = 10,000. Moving 4 places left = 10⁴ = 10,000 times.","standard_code":"4.NBT.1","difficulty":2,"options":[{"label":"100 times greater","value":"100 times greater"},{"label":"10,000 times greater","value":"10,000 times greater"},{"label":"1,000 times greater","value":"1,000 times greater"},{"label":"100,000 times greater","value":"100,000 times greater"}]},{"id":4,"text":"A digit in the thousands place has a value of 6,000. What would the same digit''s value be in the ten-thousands place?","type":"multiple_choice","correct_answer":"60,000","explanation":"One place to the left is 10 times greater: 6,000 × 10 = 60,000.","standard_code":"4.NBT.1","difficulty":2,"options":[{"label":"6,000","value":"6,000"},{"label":"600,000","value":"600,000"},{"label":"60,000","value":"60,000"},{"label":"6","value":"6"}]},{"id":5,"text":"The 2 in 2,200 appears in two places. What are the values of each 2?","type":"multiple_choice","correct_answer":"2,000 and 200","explanation":"The 2 in thousands = 2,000. The 2 in hundreds = 200.","standard_code":"4.NBT.1","difficulty":2,"options":[{"label":"2,000 and 200","value":"2,000 and 200"},{"label":"2,000 and 20","value":"2,000 and 20"},{"label":"200 and 20","value":"200 and 20"},{"label":"20 and 2","value":"20 and 2"}]}]'::jsonb);

VALUES (4,'NBT','4.NBT.1','Recognize that a digit in one place represents ten times what it represents in the place to its right (Hard)','Practice Recognize that a digit in one place represents ten times what it represents in the place to its right','practice',3,20,234,'[{"id":1,"text":"In 333,333, how many times greater is the hundred-thousands digit than the hundreds digit?","type":"multiple_choice","correct_answer":"1,000 times greater","explanation":"300,000 ÷ 300 = 1,000. Three places apart = 10³ = 1,000 times.","standard_code":"4.NBT.1","difficulty":3,"options":[{"label":"1,000 times greater","value":"1,000 times greater"},{"label":"100 times greater","value":"100 times greater"},{"label":"10,000 times greater","value":"10,000 times greater"},{"label":"10 times greater","value":"10 times greater"}]},{"id":2,"text":"A number has a 4 in the ten-thousands place. If you move it two places to the right, what is its new value?","type":"numeric","correct_answer":"400","explanation":"Ten-thousands = 40,000. Two places right = ÷10÷10 = ÷100. 40,000 ÷ 100 = 400 (hundreds place).","standard_code":"4.NBT.1","difficulty":3},{"id":3,"text":"In 505,050, compare the value of each 5. List them from greatest to least.","type":"multiple_choice","correct_answer":"500,000; 5,000; 50","explanation":"5 in hundred-thousands = 500,000; 5 in thousands = 5,000; 5 in tens = 50.","standard_code":"4.NBT.1","difficulty":3,"options":[{"label":"5,000; 50; 500,000","value":"5,000; 50; 500,000"},{"label":"5,000; 500,000; 50","value":"5,000; 500,000; 50"},{"label":"500,000; 50; 5,000","value":"500,000; 50; 5,000"},{"label":"500,000; 5,000; 50","value":"500,000; 5,000; 50"}]},{"id":4,"text":"If you multiply a digit''s value by 10 three times, you move it how many places to the left?","type":"multiple_choice","correct_answer":"3 places","explanation":"Each ×10 moves one place left. Three multiplications = 3 places left.","standard_code":"4.NBT.1","difficulty":3,"options":[{"label":"30 places","value":"30 places"},{"label":"10 places","value":"10 places"},{"label":"1 place","value":"1 place"},{"label":"3 places","value":"3 places"}]},{"id":5,"text":"The digit 9 in a number has a value of 90,000. In another number, the same digit has a value of 9. How many times greater is the first value?","type":"multiple_choice","correct_answer":"10,000 times greater","explanation":"90,000 ÷ 9 = 10,000. This is 10⁴, or 4 place-value positions apart.","standard_code":"4.NBT.1","difficulty":3,"options":[{"label":"100 times greater","value":"100 times greater"},{"label":"100,000 times greater","value":"100,000 times greater"},{"label":"10,000 times greater","value":"10,000 times greater"},{"label":"1,000 times greater","value":"1,000 times greater"}]}]'::jsonb);

VALUES (4,'NBT','4.NBT.2','Read and write multi-digit whole numbers using numerals, number names, and expanded form (Easy)','Practice Read and write multi-digit whole numbers using numerals, number names, and expanded form','practice',1,10,235,'[{"id":1,"text":"Write 4,523 in expanded form.","type":"multiple_choice","correct_answer":"4,000 + 500 + 20 + 3","explanation":"Break each digit by place value: 4 thousands + 5 hundreds + 2 tens + 3 ones.","standard_code":"4.NBT.2","difficulty":1,"options":[{"label":"4,000 + 500 + 2 + 3","value":"4,000 + 500 + 2 + 3"},{"label":"4,000 + 500 + 20 + 3","value":"4,000 + 500 + 20 + 3"},{"label":"4 + 5 + 2 + 3","value":"4 + 5 + 2 + 3"},{"label":"4,000 + 50 + 20 + 3","value":"4,000 + 50 + 20 + 3"}]},{"id":2,"text":"Write the number name for 7,081.","type":"multiple_choice","correct_answer":"Seven thousand, eighty-one","explanation":"7 thousands = seven thousand, 0 hundreds (skip), 8 tens + 1 one = eighty-one.","standard_code":"4.NBT.2","difficulty":1,"options":[{"label":"Seven thousand, eighteen","value":"Seven thousand, eighteen"},{"label":"Seven thousand, eighty-one","value":"Seven thousand, eighty-one"},{"label":"Seventy thousand, eighty-one","value":"Seventy thousand, eighty-one"},{"label":"Seven thousand, eight hundred one","value":"Seven thousand, eight hundred one"}]},{"id":3,"text":"Write three thousand, two hundred five as a numeral.","type":"multiple_choice","correct_answer":"3,205","explanation":"Three thousand = 3,000, two hundred = 200, five = 5. Total: 3,205.","standard_code":"4.NBT.2","difficulty":1,"options":[{"label":"3,025","value":"3,025"},{"label":"3,205","value":"3,205"},{"label":"3,225","value":"3,225"},{"label":"3,250","value":"3,250"}]},{"id":4,"text":"What is 6,000 + 300 + 40 + 9 in standard form?","type":"multiple_choice","correct_answer":"6,349","explanation":"Add the values: 6,000 + 300 + 40 + 9 = 6,349.","standard_code":"4.NBT.2","difficulty":1,"options":[{"label":"6,349","value":"6,349"},{"label":"6,439","value":"6,439"},{"label":"6,394","value":"6,394"},{"label":"6,349","value":"6,349"}]},{"id":5,"text":"Write 1,600 in expanded form.","type":"multiple_choice","correct_answer":"1,000 + 600","explanation":"1 thousand + 6 hundreds + 0 tens + 0 ones = 1,000 + 600.","standard_code":"4.NBT.2","difficulty":1,"options":[{"label":"10,000 + 600","value":"10,000 + 600"},{"label":"1,000 + 600","value":"1,000 + 600"},{"label":"1,600 + 0","value":"1,600 + 0"},{"label":"1,000 + 60","value":"1,000 + 60"}]}]'::jsonb);

VALUES (4,'NBT','4.NBT.2','Read and write multi-digit whole numbers using numerals, number names, and expanded form (Medium)','Practice Read and write multi-digit whole numbers using numerals, number names, and expanded form','practice',2,15,236,'[{"id":1,"text":"Write 52,407 in expanded form.","type":"multiple_choice","correct_answer":"50,000 + 2,000 + 400 + 7","explanation":"5 ten-thousands + 2 thousands + 4 hundreds + 0 tens + 7 ones.","standard_code":"4.NBT.2","difficulty":2,"options":[{"label":"50,000 + 200 + 400 + 7","value":"50,000 + 200 + 400 + 7"},{"label":"50,000 + 2,000 + 40 + 7","value":"50,000 + 2,000 + 40 + 7"},{"label":"5,000 + 2,000 + 400 + 7","value":"5,000 + 2,000 + 400 + 7"},{"label":"50,000 + 2,000 + 400 + 7","value":"50,000 + 2,000 + 400 + 7"}]},{"id":2,"text":"Write the number name for 305,018.","type":"multiple_choice","correct_answer":"Three hundred five thousand, eighteen","explanation":"305 thousand = three hundred five thousand. 018 = eighteen.","standard_code":"4.NBT.2","difficulty":2,"options":[{"label":"Thirty-five thousand, eighteen","value":"Thirty-five thousand, eighteen"},{"label":"Three hundred five thousand, eighteen","value":"Three hundred five thousand, eighteen"},{"label":"Three hundred fifty thousand, eighteen","value":"Three hundred fifty thousand, eighteen"},{"label":"Three hundred five thousand, eighty","value":"Three hundred five thousand, eighty"}]},{"id":3,"text":"Compare: 45,672 ___ 45,762. Use <, >, or =.","type":"multiple_choice","correct_answer":"45,672 < 45,762","explanation":"Same ten-thousands and thousands. Hundreds: 6 < 7, so 45,672 < 45,762.","standard_code":"4.NBT.2","difficulty":2,"options":[{"label":"45,672 < 45,762","value":"45,672 < 45,762"},{"label":"45,672 = 45,762","value":"45,672 = 45,762"},{"label":"45,672 ≤ 45,762","value":"45,672 ≤ 45,762"},{"label":"45,672 > 45,762","value":"45,672 > 45,762"}]},{"id":4,"text":"Write nine hundred twelve thousand, sixty in standard form.","type":"multiple_choice","correct_answer":"912,060","explanation":"912 thousand = 912,000. Sixty = 60. Total: 912,060.","standard_code":"4.NBT.2","difficulty":2,"options":[{"label":"921,060","value":"921,060"},{"label":"912,006","value":"912,006"},{"label":"912,060","value":"912,060"},{"label":"912,600","value":"912,600"}]},{"id":5,"text":"Which is greater: 80,000 + 4,000 + 300 + 20 + 1 or 84,231?","type":"multiple_choice","correct_answer":"84,321 > 84,231","explanation":"The expanded form equals 84,321. Comparing hundreds: 3 > 2, so 84,321 > 84,231.","standard_code":"4.NBT.2","difficulty":2,"options":[{"label":"84,321 > 84,231","value":"84,321 > 84,231"},{"label":"84,321 = 84,231","value":"84,321 = 84,231"},{"label":"84,321 < 84,231","value":"84,321 < 84,231"},{"label":"84,231 > 84,321","value":"84,231 > 84,321"}]}]'::jsonb);

VALUES (4,'NBT','4.NBT.2','Read and write multi-digit whole numbers using numerals, number names, and expanded form (Hard)','Practice Read and write multi-digit whole numbers using numerals, number names, and expanded form','practice',3,20,237,'[{"id":1,"text":"Write 600,000 + 50,000 + 70 + 8 in standard form and number name.","type":"multiple_choice","correct_answer":"650,078; six hundred fifty thousand, seventy-eight","explanation":"Add values: 650,078. Note the 0 in hundreds and thousands places.","standard_code":"4.NBT.2","difficulty":3,"options":[{"label":"650,087; six hundred fifty thousand, eighty-seven","value":"650,087; six hundred fifty thousand, eighty-seven"},{"label":"650,078; six hundred fifty thousand, seventy-eight","value":"650,078; six hundred fifty thousand, seventy-eight"},{"label":"650,708; six hundred fifty thousand, seven hundred eight","value":"650,708; six hundred fifty thousand, seven hundred eight"},{"label":"605,078; six hundred five thousand, seventy-eight","value":"605,078; six hundred five thousand, seventy-eight"}]},{"id":2,"text":"Arrange from least to greatest: 409,100; 410,900; 409,010; 401,900.","type":"multiple_choice","correct_answer":"401,900; 409,010; 409,100; 410,900","explanation":"Compare hundred-thousands (all 4), then ten-thousands: 01<09<09<10, then thousands to break 409 ties.","standard_code":"4.NBT.2","difficulty":3,"options":[{"label":"409,010; 401,900; 409,100; 410,900","value":"409,010; 401,900; 409,100; 410,900"},{"label":"401,900; 409,010; 409,100; 410,900","value":"401,900; 409,010; 409,100; 410,900"},{"label":"401,900; 409,100; 409,010; 410,900","value":"401,900; 409,100; 409,010; 410,900"},{"label":"409,010; 409,100; 401,900; 410,900","value":"409,010; 409,100; 401,900; 410,900"}]},{"id":3,"text":"A number has 8 hundred-thousands, 0 ten-thousands, 6 thousands, 0 hundreds, 4 tens, and 3 ones. Write it.","type":"multiple_choice","correct_answer":"806,043","explanation":"800,000 + 0 + 6,000 + 0 + 40 + 3 = 806,043.","standard_code":"4.NBT.2","difficulty":3,"options":[{"label":"860,043","value":"860,043"},{"label":"806,043","value":"806,043"},{"label":"806,403","value":"806,403"},{"label":"806,340","value":"806,340"}]},{"id":4,"text":"What number is 10,000 more than 594,999?","type":"multiple_choice","correct_answer":"604,999","explanation":"594,999 + 10,000 = 604,999.","standard_code":"4.NBT.2","difficulty":3,"options":[{"label":"604,999","value":"604,999"},{"label":"605,999","value":"605,999"},{"label":"594,999","value":"594,999"},{"label":"614,999","value":"614,999"}]},{"id":5,"text":"Compare using <, >, or =: 700,000 + 8,000 + 90 ___ 708,900.","type":"multiple_choice","correct_answer":"708,090 < 708,900","explanation":"Left side = 708,090. 708,090 < 708,900 (compare hundreds: 0 < 9).","standard_code":"4.NBT.2","difficulty":3,"options":[{"label":"708,090 > 708,900","value":"708,090 > 708,900"},{"label":"708,090 < 708,900","value":"708,090 < 708,900"},{"label":"708,090 = 708,900","value":"708,090 = 708,900"},{"label":"708,090 < 708,090","value":"708,090 < 708,090"}]}]'::jsonb);

VALUES (4,'NBT','4.NBT.3','Use place value understanding to round multi-digit whole numbers to any place (Easy)','Practice Use place value understanding to round multi-digit whole numbers to any place','practice',1,10,238,'[{"id":1,"text":"Round 463 to the nearest hundred.","type":"numeric","correct_answer":"500","explanation":"Look at tens digit (6 ≥ 5), so round up: 463 → 500.","standard_code":"4.NBT.3","difficulty":1},{"id":2,"text":"Round 3,821 to the nearest thousand.","type":"multiple_choice","correct_answer":"4,000","explanation":"Hundreds digit is 8 (≥5), so round up: 3,821 → 4,000.","standard_code":"4.NBT.3","difficulty":1,"options":[{"label":"4,000","value":"4,000"},{"label":"3,000","value":"3,000"},{"label":"3,800","value":"3,800"},{"label":"3,500","value":"3,500"}]},{"id":3,"text":"Round 749 to the nearest ten.","type":"numeric","correct_answer":"750","explanation":"Ones digit is 9 (≥5), round up: 749 → 750.","standard_code":"4.NBT.3","difficulty":1},{"id":4,"text":"Round 1,250 to the nearest hundred.","type":"multiple_choice","correct_answer":"1,300","explanation":"Tens digit is 5 (≥5), round up: 1,250 → 1,300.","standard_code":"4.NBT.3","difficulty":1,"options":[{"label":"1,250","value":"1,250"},{"label":"1,300","value":"1,300"},{"label":"1,400","value":"1,400"},{"label":"1,200","value":"1,200"}]},{"id":5,"text":"Round 6,500 to the nearest thousand.","type":"multiple_choice","correct_answer":"7,000","explanation":"Hundreds digit is 5 (≥5), round up: 6,500 → 7,000.","standard_code":"4.NBT.3","difficulty":1,"options":[{"label":"7,000","value":"7,000"},{"label":"6,400","value":"6,400"},{"label":"6,600","value":"6,600"},{"label":"6,000","value":"6,000"}]}]'::jsonb);

VALUES (4,'NBT','4.NBT.3','Use place value understanding to round multi-digit whole numbers to any place (Medium)','Practice Use place value understanding to round multi-digit whole numbers to any place','practice',2,15,239,'[{"id":1,"text":"Round 45,678 to the nearest ten-thousand.","type":"multiple_choice","correct_answer":"50,000","explanation":"Thousands digit is 5 (≥5), round up: 45,678 → 50,000.","standard_code":"4.NBT.3","difficulty":2,"options":[{"label":"50,000","value":"50,000"},{"label":"45,000","value":"45,000"},{"label":"46,000","value":"46,000"},{"label":"40,000","value":"40,000"}]},{"id":2,"text":"Round 82,439 to the nearest thousand.","type":"multiple_choice","correct_answer":"82,000","explanation":"Hundreds digit is 4 (<5), round down: 82,439 → 82,000.","standard_code":"4.NBT.3","difficulty":2,"options":[{"label":"82,500","value":"82,500"},{"label":"82,000","value":"82,000"},{"label":"82,400","value":"82,400"},{"label":"83,000","value":"83,000"}]},{"id":3,"text":"A stadium holds 67,248 people. Round to the nearest thousand.","type":"multiple_choice","correct_answer":"67,000","explanation":"Hundreds digit is 2 (<5), round down: 67,248 → 67,000.","standard_code":"4.NBT.3","difficulty":2,"options":[{"label":"68,000","value":"68,000"},{"label":"66,000","value":"66,000"},{"label":"67,200","value":"67,200"},{"label":"67,000","value":"67,000"}]},{"id":4,"text":"Round 504,500 to the nearest thousand.","type":"multiple_choice","correct_answer":"505,000","explanation":"Hundreds digit is 5 (≥5), round up: 504,500 → 505,000.","standard_code":"4.NBT.3","difficulty":2,"options":[{"label":"504,000","value":"504,000"},{"label":"505,000","value":"505,000"},{"label":"506,000","value":"506,000"},{"label":"505,500","value":"505,500"}]},{"id":5,"text":"Round 395,001 to the nearest ten-thousand.","type":"multiple_choice","correct_answer":"400,000","explanation":"Thousands digit is 5 (≥5), round up: 395,001 → 400,000.","standard_code":"4.NBT.3","difficulty":2,"options":[{"label":"400,000","value":"400,000"},{"label":"395,000","value":"395,000"},{"label":"390,000","value":"390,000"},{"label":"405,000","value":"405,000"}]}]'::jsonb);

VALUES (4,'NBT','4.NBT.3','Use place value understanding to round multi-digit whole numbers to any place (Hard)','Practice Use place value understanding to round multi-digit whole numbers to any place','practice',3,20,240,'[{"id":1,"text":"Round 549,999 to the nearest hundred-thousand.","type":"multiple_choice","correct_answer":"500,000","explanation":"Ten-thousands digit is 4 (<5), round down: 549,999 → 500,000.","standard_code":"4.NBT.3","difficulty":3,"options":[{"label":"600,000","value":"600,000"},{"label":"500,000","value":"500,000"},{"label":"550,000","value":"550,000"},{"label":"400,000","value":"400,000"}]},{"id":2,"text":"A city''s population is 847,562. Round to the nearest ten-thousand and hundred-thousand.","type":"multiple_choice","correct_answer":"850,000 and 800,000","explanation":"Nearest ten-thousand: thousands=7≥5 → 850,000. Nearest hundred-thousand: ten-thousands=4<5 → 800,000.","standard_code":"4.NBT.3","difficulty":3,"options":[{"label":"850,000 and 900,000","value":"850,000 and 900,000"},{"label":"840,000 and 800,000","value":"840,000 and 800,000"},{"label":"850,000 and 800,000","value":"850,000 and 800,000"},{"label":"847,000 and 850,000","value":"847,000 and 850,000"}]},{"id":3,"text":"What is the smallest number that rounds to 500,000 when rounded to the nearest hundred-thousand?","type":"multiple_choice","correct_answer":"450,000","explanation":"Numbers from 450,000 to 549,999 round to 500,000. The smallest is 450,000.","standard_code":"4.NBT.3","difficulty":3,"options":[{"label":"500,000","value":"500,000"},{"label":"400,000","value":"400,000"},{"label":"450,000","value":"450,000"},{"label":"460,000","value":"460,000"}]},{"id":4,"text":"Round 995,500 to the nearest thousand.","type":"multiple_choice","correct_answer":"996,000","explanation":"Hundreds digit is 5 (≥5), round up: 995,500 → 996,000.","standard_code":"4.NBT.3","difficulty":3,"options":[{"label":"995,000","value":"995,000"},{"label":"996,000","value":"996,000"},{"label":"997,000","value":"997,000"},{"label":"996,500","value":"996,500"}]},{"id":5,"text":"A number rounded to the nearest thousand is 47,000 and to the nearest hundred is 46,500. What could the number be?","type":"multiple_choice","correct_answer":"Any number from 46,500 to 46,549","explanation":"To round to 46,500 at hundreds, number is 46,450–46,549. Of these, 46,500–46,549 also round to 47,000 at thousands.","standard_code":"4.NBT.3","difficulty":3,"options":[{"label":"Any number from 46,501 to 46,599","value":"Any number from 46,501 to 46,599"},{"label":"Any number from 46,550 to 47,049","value":"Any number from 46,550 to 47,049"},{"label":"Any number from 46,500 to 46,549","value":"Any number from 46,500 to 46,549"},{"label":"Any number from 46,450 to 46,549","value":"Any number from 46,450 to 46,549"}]}]'::jsonb);

VALUES (4,'NBT','4.NBT.4','Fluently add and subtract multi-digit whole numbers using the standard algorithm (Easy)','Practice Fluently add and subtract multi-digit whole numbers using the standard algorithm','practice',1,10,241,'[{"id":1,"text":"3,456 + 2,341 = ?","type":"multiple_choice","correct_answer":"5,797","explanation":"Add column by column: 6+1=7, 5+4=9, 4+3=7, 3+2=5. Answer: 5,797.","standard_code":"4.NBT.4","difficulty":1,"options":[{"label":"5,897","value":"5,897"},{"label":"5,797","value":"5,797"},{"label":"5,797","value":"5,797"},{"label":"5,677","value":"5,677"}]},{"id":2,"text":"8,000 − 3,500 = ?","type":"multiple_choice","correct_answer":"4,500","explanation":"8,000 − 3,500 = 4,500.","standard_code":"4.NBT.4","difficulty":1,"options":[{"label":"4,500","value":"4,500"},{"label":"4,600","value":"4,600"},{"label":"4,400","value":"4,400"},{"label":"4,000","value":"4,000"}]},{"id":3,"text":"5,274 + 1,603 = ?","type":"multiple_choice","correct_answer":"6,877","explanation":"4+3=7, 7+0=7, 2+6=8, 5+1=6. Answer: 6,877.","standard_code":"4.NBT.4","difficulty":1,"options":[{"label":"6,877","value":"6,877"},{"label":"6,977","value":"6,977"},{"label":"6,777","value":"6,777"},{"label":"6,877","value":"6,877"}]},{"id":4,"text":"9,450 − 6,230 = ?","type":"multiple_choice","correct_answer":"3,220","explanation":"0−0=0, 5−3=2, 4−2=2, 9−6=3. Answer: 3,220.","standard_code":"4.NBT.4","difficulty":1,"options":[{"label":"3,120","value":"3,120"},{"label":"3,220","value":"3,220"},{"label":"3,210","value":"3,210"},{"label":"3,320","value":"3,320"}]},{"id":5,"text":"4,125 + 3,874 = ?","type":"multiple_choice","correct_answer":"7,999","explanation":"5+4=9, 2+7=9, 1+8=9, 4+3=7. Answer: 7,999.","standard_code":"4.NBT.4","difficulty":1,"options":[{"label":"7,999","value":"7,999"},{"label":"8,999","value":"8,999"},{"label":"7,909","value":"7,909"},{"label":"7,989","value":"7,989"}]}]'::jsonb);

VALUES (4,'NBT','4.NBT.4','Fluently add and subtract multi-digit whole numbers using the standard algorithm (Medium)','Practice Fluently add and subtract multi-digit whole numbers using the standard algorithm','practice',2,15,242,'[{"id":1,"text":"47,856 + 35,678 = ?","type":"multiple_choice","correct_answer":"83,534","explanation":"Add with regrouping: 6+8=14, carry 1; 5+7+1=13, carry 1; 8+6+1=15, carry 1; 7+5+1=13, carry 1; 4+3+1=8. Answer: 83,534.","standard_code":"4.NBT.4","difficulty":2,"options":[{"label":"84,534","value":"84,534"},{"label":"83,524","value":"83,524"},{"label":"83,534","value":"83,534"},{"label":"83,544","value":"83,544"}]},{"id":2,"text":"90,000 − 45,327 = ?","type":"multiple_choice","correct_answer":"44,673","explanation":"Subtract with borrowing from 90,000. 90,000 − 45,327 = 44,673.","standard_code":"4.NBT.4","difficulty":2,"options":[{"label":"45,673","value":"45,673"},{"label":"44,673","value":"44,673"},{"label":"44,763","value":"44,763"},{"label":"44,673","value":"44,673"}]},{"id":3,"text":"62,408 + 27,594 = ?","type":"multiple_choice","correct_answer":"90,002","explanation":"8+4=12 carry 1; 0+9+1=10 carry 1; 4+5+1=10 carry 1; 2+7+1=10 carry 1; 6+2+1=9. Answer: 90,002.","standard_code":"4.NBT.4","difficulty":2,"options":[{"label":"90,000","value":"90,000"},{"label":"90,012","value":"90,012"},{"label":"90,002","value":"90,002"},{"label":"89,002","value":"89,002"}]},{"id":4,"text":"80,503 − 47,865 = ?","type":"multiple_choice","correct_answer":"32,638","explanation":"Borrow across zeros: 80,503 − 47,865 = 32,638.","standard_code":"4.NBT.4","difficulty":2,"options":[{"label":"33,638","value":"33,638"},{"label":"32,638","value":"32,638"},{"label":"32,738","value":"32,738"},{"label":"32,528","value":"32,528"}]},{"id":5,"text":"A school raised $34,578 in fall and $28,963 in spring. What is the total?","type":"multiple_choice","correct_answer":"$63,541","explanation":"34,578 + 28,963 = 63,541.","standard_code":"4.NBT.4","difficulty":2,"options":[{"label":"$63,541","value":"$63,541"},{"label":"$63,541","value":"$63,541"},{"label":"$62,541","value":"$62,541"},{"label":"$64,541","value":"$64,541"}]}]'::jsonb);

VALUES (4,'NBT','4.NBT.4','Fluently add and subtract multi-digit whole numbers using the standard algorithm (Hard)','Practice Fluently add and subtract multi-digit whole numbers using the standard algorithm','practice',3,20,243,'[{"id":1,"text":"456,789 + 345,678 = ?","type":"multiple_choice","correct_answer":"802,467","explanation":"Add with multiple regroupings: 9+8=17, 8+7+1=16, 7+6+1=14, 6+5+1=12, 5+4+1=10, 4+3+1=8. Answer: 802,467.","standard_code":"4.NBT.4","difficulty":3,"options":[{"label":"802,467","value":"802,467"},{"label":"802,467","value":"802,467"},{"label":"801,467","value":"801,467"},{"label":"802,357","value":"802,357"}]},{"id":2,"text":"1,000,000 − 567,891 = ?","type":"multiple_choice","correct_answer":"432,109","explanation":"Borrow from 1,000,000. 1,000,000 − 567,891 = 432,109.","standard_code":"4.NBT.4","difficulty":3,"options":[{"label":"432,109","value":"432,109"},{"label":"432,109","value":"432,109"},{"label":"432,019","value":"432,019"},{"label":"433,109","value":"433,109"}]},{"id":3,"text":"A city had 284,506 residents in 2020 and gained 37,894 by 2024. How many residents in 2024?","type":"multiple_choice","correct_answer":"322,400 residents","explanation":"284,506 + 37,894 = 322,400.","standard_code":"4.NBT.4","difficulty":3,"options":[{"label":"322,400 residents","value":"322,400 residents"},{"label":"321,400 residents","value":"321,400 residents"},{"label":"323,400 residents","value":"323,400 residents"},{"label":"322,400 residents","value":"322,400 residents"}]},{"id":4,"text":"Find the missing number: 456,_23 + 234,567 = 691,290.","type":"multiple_choice","correct_answer":"7 (456,723)","explanation":"691,290 − 234,567 = 456,723. The missing digit is 7.","standard_code":"4.NBT.4","difficulty":3,"options":[{"label":"6 (456,623)","value":"6 (456,623)"},{"label":"8 (456,823)","value":"8 (456,823)"},{"label":"7 (456,723)","value":"7 (456,723)"},{"label":"9 (456,923)","value":"9 (456,923)"}]},{"id":5,"text":"A warehouse had 500,000 items. They shipped 168,475 on Monday and 243,890 on Tuesday. How many remain?","type":"multiple_choice","correct_answer":"87,635 items","explanation":"500,000 − 168,475 = 331,525. 331,525 − 243,890 = 87,635.","standard_code":"4.NBT.4","difficulty":3,"options":[{"label":"87,635 items","value":"87,635 items"},{"label":"88,635 items","value":"88,635 items"},{"label":"87,625 items","value":"87,625 items"},{"label":"87,735 items","value":"87,735 items"}]}]'::jsonb);

VALUES (4,'NBT','4.NBT.5','Multiply a whole number of up to four digits by a one-digit number, and two two-digit numbers (Easy)','Practice Multiply a whole number of up to four digits by a one-digit number, and two two-digit numbers','practice',1,10,244,'[{"id":1,"text":"34 × 2 = ?","type":"numeric","correct_answer":"68","explanation":"30×2=60, 4×2=8, 60+8=68.","standard_code":"4.NBT.5","difficulty":1},{"id":2,"text":"123 × 3 = ?","type":"numeric","correct_answer":"369","explanation":"100×3=300, 20×3=60, 3×3=9. 300+60+9=369.","standard_code":"4.NBT.5","difficulty":1},{"id":3,"text":"45 × 5 = ?","type":"numeric","correct_answer":"225","explanation":"40×5=200, 5×5=25. 200+25=225.","standard_code":"4.NBT.5","difficulty":1},{"id":4,"text":"201 × 4 = ?","type":"numeric","correct_answer":"804","explanation":"200×4=800, 1×4=4. 800+4=804.","standard_code":"4.NBT.5","difficulty":1},{"id":5,"text":"12 × 11 = ?","type":"numeric","correct_answer":"132","explanation":"12×10=120, 12×1=12. 120+12=132.","standard_code":"4.NBT.5","difficulty":1}]'::jsonb);

VALUES (4,'NBT','4.NBT.5','Multiply a whole number of up to four digits by a one-digit number, and two two-digit numbers (Medium)','Practice Multiply a whole number of up to four digits by a one-digit number, and two two-digit numbers','practice',2,15,245,'[{"id":1,"text":"2,345 × 6 = ?","type":"multiple_choice","correct_answer":"14,070","explanation":"2000×6=12000, 300×6=1800, 40×6=240, 5×6=30. Total: 14,070.","standard_code":"4.NBT.5","difficulty":2,"options":[{"label":"14,170","value":"14,170"},{"label":"13,070","value":"13,070"},{"label":"14,070","value":"14,070"},{"label":"14,070","value":"14,070"}]},{"id":2,"text":"56 × 34 = ?","type":"multiple_choice","correct_answer":"1,904","explanation":"56×30=1680, 56×4=224. 1680+224=1,904.","standard_code":"4.NBT.5","difficulty":2,"options":[{"label":"1,904","value":"1,904"},{"label":"1,914","value":"1,914"},{"label":"1,804","value":"1,804"},{"label":"1,994","value":"1,994"}]},{"id":3,"text":"78 × 45 = ?","type":"multiple_choice","correct_answer":"3,510","explanation":"78×40=3120, 78×5=390. 3120+390=3,510.","standard_code":"4.NBT.5","difficulty":2,"options":[{"label":"3,610","value":"3,610"},{"label":"3,410","value":"3,410"},{"label":"3,520","value":"3,520"},{"label":"3,510","value":"3,510"}]},{"id":4,"text":"1,508 × 7 = ?","type":"multiple_choice","correct_answer":"10,556","explanation":"1000×7=7000, 500×7=3500, 8×7=56. 7000+3500+56=10,556.","standard_code":"4.NBT.5","difficulty":2,"options":[{"label":"10,556","value":"10,556"},{"label":"10,456","value":"10,456"},{"label":"11,556","value":"11,556"},{"label":"10,556","value":"10,556"}]},{"id":5,"text":"63 × 27 = ?","type":"multiple_choice","correct_answer":"1,701","explanation":"63×20=1260, 63×7=441. 1260+441=1,701.","standard_code":"4.NBT.5","difficulty":2,"options":[{"label":"1,711","value":"1,711"},{"label":"1,701","value":"1,701"},{"label":"1,601","value":"1,601"},{"label":"1,801","value":"1,801"}]}]'::jsonb);

VALUES (4,'NBT','4.NBT.5','Multiply a whole number of up to four digits by a one-digit number, and two two-digit numbers (Hard)','Practice Multiply a whole number of up to four digits by a one-digit number, and two two-digit numbers','practice',3,20,246,'[{"id":1,"text":"4,567 × 8 = ?","type":"multiple_choice","correct_answer":"36,536","explanation":"4000×8=32000, 500×8=4000, 60×8=480, 7×8=56. Total: 36,536.","standard_code":"4.NBT.5","difficulty":3,"options":[{"label":"36,426","value":"36,426"},{"label":"36,536","value":"36,536"},{"label":"37,536","value":"37,536"},{"label":"36,536","value":"36,536"}]},{"id":2,"text":"93 × 86 = ?","type":"multiple_choice","correct_answer":"7,998","explanation":"93×80=7440, 93×6=558. 7440+558=7,998.","standard_code":"4.NBT.5","difficulty":3,"options":[{"label":"7,998","value":"7,998"},{"label":"7,888","value":"7,888"},{"label":"7,998","value":"7,998"},{"label":"8,098","value":"8,098"}]},{"id":3,"text":"A factory produces 1,875 items per day. How many in 9 days?","type":"multiple_choice","correct_answer":"16,875 items","explanation":"1,875 × 9 = 16,875.","standard_code":"4.NBT.5","difficulty":3,"options":[{"label":"16,875 items","value":"16,875 items"},{"label":"16,775 items","value":"16,775 items"},{"label":"16,875 items","value":"16,875 items"},{"label":"16,975 items","value":"16,975 items"}]},{"id":4,"text":"67 × 89 = ?","type":"multiple_choice","correct_answer":"5,963","explanation":"67×80=5360, 67×9=603. 5360+603=5,963.","standard_code":"4.NBT.5","difficulty":3,"options":[{"label":"5,973","value":"5,973"},{"label":"5,863","value":"5,863"},{"label":"6,063","value":"6,063"},{"label":"5,963","value":"5,963"}]},{"id":5,"text":"A school orders 48 boxes with 36 pencils each. How many pencils total?","type":"multiple_choice","correct_answer":"1,728 pencils","explanation":"48 × 36: 48×30=1440, 48×6=288. 1440+288=1,728.","standard_code":"4.NBT.5","difficulty":3,"options":[{"label":"1,836 pencils","value":"1,836 pencils"},{"label":"1,638 pencils","value":"1,638 pencils"},{"label":"1,728 pencils","value":"1,728 pencils"},{"label":"1,728 pencils","value":"1,728 pencils"}]}]'::jsonb);

VALUES (4,'NBT','4.NBT.6','Find whole-number quotients and remainders with up to four-digit dividends and one-digit divisors (Easy)','Practice Find whole-number quotients and remainders with up to four-digit dividends and one-digit divisors','practice',1,10,247,'[{"id":1,"text":"84 ÷ 4 = ?","type":"numeric","correct_answer":"21","explanation":"4 × 21 = 84. Or: 80÷4=20, 4÷4=1, 20+1=21.","standard_code":"4.NBT.6","difficulty":1},{"id":2,"text":"96 ÷ 3 = ?","type":"numeric","correct_answer":"32","explanation":"3 × 32 = 96. 90÷3=30, 6÷3=2, 30+2=32.","standard_code":"4.NBT.6","difficulty":1},{"id":3,"text":"75 ÷ 5 = ?","type":"numeric","correct_answer":"15","explanation":"5 × 15 = 75.","standard_code":"4.NBT.6","difficulty":1},{"id":4,"text":"56 ÷ 8 = ?","type":"numeric","correct_answer":"7","explanation":"8 × 7 = 56.","standard_code":"4.NBT.6","difficulty":1},{"id":5,"text":"63 ÷ 7 = ?","type":"numeric","correct_answer":"9","explanation":"7 × 9 = 63.","standard_code":"4.NBT.6","difficulty":1}]'::jsonb);

VALUES (4,'NBT','4.NBT.6','Find whole-number quotients and remainders with up to four-digit dividends and one-digit divisors (Medium)','Practice Find whole-number quotients and remainders with up to four-digit dividends and one-digit divisors','practice',2,15,248,'[{"id":1,"text":"435 ÷ 5 = ?","type":"numeric","correct_answer":"87","explanation":"400÷5=80, 35÷5=7. 80+7=87.","standard_code":"4.NBT.6","difficulty":2},{"id":2,"text":"637 ÷ 7 = ?","type":"numeric","correct_answer":"91","explanation":"630÷7=90, 7÷7=1. 90+1=91.","standard_code":"4.NBT.6","difficulty":2},{"id":3,"text":"529 ÷ 6 = ?","type":"multiple_choice","correct_answer":"88 R1","explanation":"6 × 88 = 528. 529 − 528 = 1. Answer: 88 remainder 1.","standard_code":"4.NBT.6","difficulty":2,"options":[{"label":"88 R1","value":"88 R1"},{"label":"89 R1","value":"89 R1"},{"label":"87 R5","value":"87 R5"},{"label":"88 R2","value":"88 R2"}]},{"id":4,"text":"1,248 ÷ 4 = ?","type":"numeric","correct_answer":"312","explanation":"1200÷4=300, 48÷4=12. 300+12=312.","standard_code":"4.NBT.6","difficulty":2},{"id":5,"text":"845 ÷ 3 = ?","type":"multiple_choice","correct_answer":"281 R2","explanation":"3 × 281 = 843. 845 − 843 = 2. Answer: 281 R2.","standard_code":"4.NBT.6","difficulty":2,"options":[{"label":"281 R2","value":"281 R2"},{"label":"280 R2","value":"280 R2"},{"label":"282 R2","value":"282 R2"},{"label":"281 R1","value":"281 R1"}]}]'::jsonb);

VALUES (4,'NBT','4.NBT.6','Find whole-number quotients and remainders with up to four-digit dividends and one-digit divisors (Hard)','Practice Find whole-number quotients and remainders with up to four-digit dividends and one-digit divisors','practice',3,20,249,'[{"id":1,"text":"4,536 ÷ 8 = ?","type":"numeric","correct_answer":"567","explanation":"8 × 567 = 4,536. Divide step by step: 45÷8=5R5, 53÷8=6R5, 56÷8=7.","standard_code":"4.NBT.6","difficulty":3},{"id":2,"text":"7,259 ÷ 6 = ?","type":"multiple_choice","correct_answer":"1,209 R5","explanation":"6 × 1,209 = 7,254. 7,259 − 7,254 = 5. Answer: 1,209 R5.","standard_code":"4.NBT.6","difficulty":3,"options":[{"label":"1,210 R5","value":"1,210 R5"},{"label":"1,208 R5","value":"1,208 R5"},{"label":"1,209 R5","value":"1,209 R5"},{"label":"1,209 R4","value":"1,209 R4"}]},{"id":3,"text":"A factory packs 2,847 toys into boxes of 9. How many full boxes and how many left over?","type":"multiple_choice","correct_answer":"316 full boxes, 3 left over","explanation":"9 × 316 = 2,844. 2,847 − 2,844 = 3.","standard_code":"4.NBT.6","difficulty":3,"options":[{"label":"317 full boxes, 3 left over","value":"317 full boxes, 3 left over"},{"label":"315 full boxes, 3 left over","value":"315 full boxes, 3 left over"},{"label":"316 full boxes, 3 left over","value":"316 full boxes, 3 left over"},{"label":"316 full boxes, 2 left over","value":"316 full boxes, 2 left over"}]},{"id":4,"text":"5,000 ÷ 7 = ?","type":"multiple_choice","correct_answer":"714 R2","explanation":"7 × 714 = 4,998. 5,000 − 4,998 = 2.","standard_code":"4.NBT.6","difficulty":3,"options":[{"label":"714 R2","value":"714 R2"},{"label":"713 R2","value":"713 R2"},{"label":"714 R3","value":"714 R3"},{"label":"715 R2","value":"715 R2"}]},{"id":5,"text":"If 3,672 stickers are shared equally among 8 students, how many does each get and how many are left?","type":"multiple_choice","correct_answer":"459 each, 0 left over","explanation":"8 × 459 = 3,672. It divides evenly.","standard_code":"4.NBT.6","difficulty":3,"options":[{"label":"459 each, 1 left over","value":"459 each, 1 left over"},{"label":"459 each, 0 left over","value":"459 each, 0 left over"},{"label":"460 each, 0 left over","value":"460 each, 0 left over"},{"label":"458 each, 0 left over","value":"458 each, 0 left over"}]}]'::jsonb);

VALUES (4,'NF','4.NF.1','Explain why a fraction a/b is equivalent to (n×a)/(n×b) using visual models (Easy)','Practice Explain why a fraction a/b is equivalent to (n×a)/(n×b) using visual models','practice',1,10,250,'[{"id":1,"text":"Find a fraction equivalent to 1/2 by multiplying numerator and denominator by 2.","type":"numeric","correct_answer":"2/4","explanation":"(1×2)/(2×2) = 2/4. Both represent the same amount.","standard_code":"4.NF.1","difficulty":1},{"id":2,"text":"Find a fraction equivalent to 1/3 by multiplying by 3.","type":"numeric","correct_answer":"3/9","explanation":"(1×3)/(3×3) = 3/9.","standard_code":"4.NF.1","difficulty":1},{"id":3,"text":"Are 2/4 and 1/2 equivalent? Explain.","type":"multiple_choice","correct_answer":"Yes","explanation":"2/4 simplifies to 1/2 (divide both by 2). They name the same amount.","standard_code":"4.NF.1","difficulty":1,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]},{"id":4,"text":"Find a fraction equivalent to 3/4 with denominator 8.","type":"numeric","correct_answer":"6/8","explanation":"(3×2)/(4×2) = 6/8.","standard_code":"4.NF.1","difficulty":1},{"id":5,"text":"Write an equivalent fraction for 2/3 with denominator 6.","type":"numeric","correct_answer":"4/6","explanation":"(2×2)/(3×2) = 4/6.","standard_code":"4.NF.1","difficulty":1}]'::jsonb);

VALUES (4,'NF','4.NF.1','Explain why a fraction a/b is equivalent to (n×a)/(n×b) using visual models (Medium)','Practice Explain why a fraction a/b is equivalent to (n×a)/(n×b) using visual models','practice',2,15,251,'[{"id":1,"text":"Find two fractions equivalent to 3/5.","type":"multiple_choice","correct_answer":"6/10 and 9/15","explanation":"(3×2)/(5×2)=6/10 and (3×3)/(5×3)=9/15.","standard_code":"4.NF.1","difficulty":2,"options":[{"label":"6/10 and 9/15","value":"6/10 and 9/15"},{"label":"9/15 and 12/20","value":"9/15 and 12/20"},{"label":"12/20 and 15/25","value":"12/20 and 15/25"},{"label":"3/10 and 3/15","value":"3/10 and 3/15"}]},{"id":2,"text":"Simplify 8/12 to its simplest form.","type":"numeric","correct_answer":"2/3","explanation":"GCF of 8 and 12 is 4. 8÷4=2, 12÷4=3. So 8/12 = 2/3.","standard_code":"4.NF.1","difficulty":2},{"id":3,"text":"Are 4/6 and 6/9 equivalent?","type":"multiple_choice","correct_answer":"Yes","explanation":"4/6 = 2/3 (÷2). 6/9 = 2/3 (÷3). Both equal 2/3.","standard_code":"4.NF.1","difficulty":2,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]},{"id":4,"text":"Find an equivalent fraction for 5/8 with denominator 24.","type":"numeric","correct_answer":"15/24","explanation":"(5×3)/(8×3) = 15/24.","standard_code":"4.NF.1","difficulty":2},{"id":5,"text":"Simplify 6/10.","type":"numeric","correct_answer":"3/5","explanation":"GCF of 6 and 10 is 2. 6÷2=3, 10÷2=5.","standard_code":"4.NF.1","difficulty":2}]'::jsonb);

VALUES (4,'NF','4.NF.1','Explain why a fraction a/b is equivalent to (n×a)/(n×b) using visual models (Hard)','Practice Explain why a fraction a/b is equivalent to (n×a)/(n×b) using visual models','practice',3,20,252,'[{"id":1,"text":"Find three equivalent fractions for 2/5.","type":"multiple_choice","correct_answer":"4/10, 6/15, 8/20","explanation":"Multiply by 2, 3, and 4: (2×2)/(5×2)=4/10, (2×3)/(5×3)=6/15, (2×4)/(5×4)=8/20.","standard_code":"4.NF.1","difficulty":3,"options":[{"label":"6/15, 8/20, 10/25","value":"6/15, 8/20, 10/25"},{"label":"4/10, 6/20, 8/30","value":"4/10, 6/20, 8/30"},{"label":"4/10, 6/15, 10/20","value":"4/10, 6/15, 10/20"},{"label":"4/10, 6/15, 8/20","value":"4/10, 6/15, 8/20"}]},{"id":2,"text":"Is 12/18 equivalent to 8/12? Explain how you know.","type":"multiple_choice","correct_answer":"Yes","explanation":"12/18 = 2/3 (÷6). 8/12 = 2/3 (÷4). Both simplify to 2/3.","standard_code":"4.NF.1","difficulty":3,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]},{"id":3,"text":"What number makes this true? 3/7 = __/21","type":"numeric","correct_answer":"9","explanation":"7 × 3 = 21, so multiply numerator by 3 too: 3 × 3 = 9.","standard_code":"4.NF.1","difficulty":3},{"id":4,"text":"Simplify 24/36 to lowest terms.","type":"numeric","correct_answer":"2/3","explanation":"GCF of 24 and 36 is 12. 24÷12=2, 36÷12=3.","standard_code":"4.NF.1","difficulty":3},{"id":5,"text":"Find the missing number: __/8 = 15/24","type":"numeric","correct_answer":"5","explanation":"24 ÷ 8 = 3. So 15 ÷ 3 = 5. The fraction is 5/8.","standard_code":"4.NF.1","difficulty":3}]'::jsonb);

VALUES (4,'NF','4.NF.2','Compare two fractions with different numerators and denominators (Easy)','Practice Compare two fractions with different numerators and denominators','practice',1,10,253,'[{"id":1,"text":"Compare 1/3 and 1/4 using <, >, or =.","type":"multiple_choice","correct_answer":"1/3 > 1/4","explanation":"With the same numerator, the fraction with the smaller denominator is larger.","standard_code":"4.NF.2","difficulty":1,"options":[{"label":"1/3 < 1/4","value":"1/3 < 1/4"},{"label":"1/3 = 1/4","value":"1/3 = 1/4"},{"label":"1/3 > 1/4","value":"1/3 > 1/4"},{"label":"1/4 > 1/3","value":"1/4 > 1/3"}]},{"id":2,"text":"Compare 2/5 and 4/5.","type":"multiple_choice","correct_answer":"2/5 < 4/5","explanation":"Same denominator: 2 < 4, so 2/5 < 4/5.","standard_code":"4.NF.2","difficulty":1,"options":[{"label":"2/5 < 4/5","value":"2/5 < 4/5"},{"label":"4/5 < 2/5","value":"4/5 < 2/5"},{"label":"2/5 = 4/5","value":"2/5 = 4/5"},{"label":"2/5 > 4/5","value":"2/5 > 4/5"}]},{"id":3,"text":"Compare 3/8 and 5/8.","type":"multiple_choice","correct_answer":"3/8 < 5/8","explanation":"Same denominator: 3 < 5.","standard_code":"4.NF.2","difficulty":1,"options":[{"label":"5/8 < 3/8","value":"5/8 < 3/8"},{"label":"3/8 > 5/8","value":"3/8 > 5/8"},{"label":"3/8 = 5/8","value":"3/8 = 5/8"},{"label":"3/8 < 5/8","value":"3/8 < 5/8"}]},{"id":4,"text":"Which is larger: 1/2 or 1/6?","type":"numeric","correct_answer":"1/2","explanation":"Same numerator: smaller denominator = larger fraction.","standard_code":"4.NF.2","difficulty":1},{"id":5,"text":"Compare 3/4 and 3/6.","type":"multiple_choice","correct_answer":"3/4 > 3/6","explanation":"Same numerator (3): 4ths are larger pieces than 6ths.","standard_code":"4.NF.2","difficulty":1,"options":[{"label":"3/4 < 3/6","value":"3/4 < 3/6"},{"label":"3/4 > 3/6","value":"3/4 > 3/6"},{"label":"3/4 = 3/6","value":"3/4 = 3/6"},{"label":"3/6 > 3/4","value":"3/6 > 3/4"}]}]'::jsonb);

VALUES (4,'NF','4.NF.2','Compare two fractions with different numerators and denominators (Medium)','Practice Compare two fractions with different numerators and denominators','practice',2,15,254,'[{"id":1,"text":"Compare 3/4 and 5/8. Use a common denominator.","type":"multiple_choice","correct_answer":"3/4 > 5/8","explanation":"3/4 = 6/8. Since 6/8 > 5/8, we know 3/4 > 5/8.","standard_code":"4.NF.2","difficulty":2,"options":[{"label":"5/8 > 3/4","value":"5/8 > 3/4"},{"label":"3/4 > 5/8","value":"3/4 > 5/8"},{"label":"3/4 < 5/8","value":"3/4 < 5/8"},{"label":"3/4 = 5/8","value":"3/4 = 5/8"}]},{"id":2,"text":"Compare 2/3 and 3/5.","type":"multiple_choice","correct_answer":"2/3 > 3/5","explanation":"Common denom 15: 2/3=10/15, 3/5=9/15. 10>9 so 2/3 > 3/5.","standard_code":"4.NF.2","difficulty":2,"options":[{"label":"2/3 < 3/5","value":"2/3 < 3/5"},{"label":"2/3 = 3/5","value":"2/3 = 3/5"},{"label":"2/3 > 3/5","value":"2/3 > 3/5"},{"label":"3/5 > 2/3","value":"3/5 > 2/3"}]},{"id":3,"text":"Order from least to greatest: 1/2, 2/5, 3/4.","type":"multiple_choice","correct_answer":"2/5, 1/2, 3/4","explanation":"Common denom 20: 1/2=10/20, 2/5=8/20, 3/4=15/20. Order: 8,10,15.","standard_code":"4.NF.2","difficulty":2,"options":[{"label":"3/4, 1/2, 2/5","value":"3/4, 1/2, 2/5"},{"label":"1/2, 2/5, 3/4","value":"1/2, 2/5, 3/4"},{"label":"2/5, 1/2, 3/4","value":"2/5, 1/2, 3/4"},{"label":"2/5, 3/4, 1/2","value":"2/5, 3/4, 1/2"}]},{"id":4,"text":"Compare 5/6 and 7/8.","type":"multiple_choice","correct_answer":"5/6 < 7/8","explanation":"Common denom 24: 5/6=20/24, 7/8=21/24. 20<21.","standard_code":"4.NF.2","difficulty":2,"options":[{"label":"5/6 = 7/8","value":"5/6 = 7/8"},{"label":"5/6 > 7/8","value":"5/6 > 7/8"},{"label":"5/6 < 7/8","value":"5/6 < 7/8"},{"label":"7/8 < 5/6","value":"7/8 < 5/6"}]},{"id":5,"text":"Compare 4/10 and 2/5.","type":"multiple_choice","correct_answer":"4/10 = 2/5","explanation":"2/5 = 4/10 (multiply by 2). They are equal.","standard_code":"4.NF.2","difficulty":2,"options":[{"label":"4/10 = 2/5","value":"4/10 = 2/5"},{"label":"4/10 > 2/5","value":"4/10 > 2/5"},{"label":"2/5 ≠ 4/10","value":"2/5 ≠ 4/10"},{"label":"4/10 < 2/5","value":"4/10 < 2/5"}]}]'::jsonb);

VALUES (4,'NF','4.NF.2','Compare two fractions with different numerators and denominators (Hard)','Practice Compare two fractions with different numerators and denominators','practice',3,20,255,'[{"id":1,"text":"Order from greatest to least: 2/3, 5/8, 7/12.","type":"multiple_choice","correct_answer":"2/3, 5/8, 7/12","explanation":"Common denom 24: 2/3=16/24, 5/8=15/24, 7/12=14/24. Order: 16,15,14.","standard_code":"4.NF.2","difficulty":3,"options":[{"label":"2/3, 5/8, 7/12","value":"2/3, 5/8, 7/12"},{"label":"7/12, 5/8, 2/3","value":"7/12, 5/8, 2/3"},{"label":"2/3, 7/12, 5/8","value":"2/3, 7/12, 5/8"},{"label":"5/8, 2/3, 7/12","value":"5/8, 2/3, 7/12"}]},{"id":2,"text":"Compare 7/9 and 5/6. Which is closer to 1?","type":"multiple_choice","correct_answer":"5/6 is closer to 1","explanation":"7/9 = 14/18, 5/6 = 15/18. 15/18 > 14/18 and is closer to 18/18 = 1.","standard_code":"4.NF.2","difficulty":3,"options":[{"label":"5/6 is closer to 1","value":"5/6 is closer to 1"},{"label":"Neither is close to 1","value":"Neither is close to 1"},{"label":"They are equally close to 1","value":"They are equally close to 1"},{"label":"7/9 is closer to 1","value":"7/9 is closer to 1"}]},{"id":3,"text":"Find a fraction between 1/3 and 1/2.","type":"multiple_choice","correct_answer":"5/12 (or other valid answer)","explanation":"1/3=4/12, 1/2=6/12. 5/12 is between them.","standard_code":"4.NF.2","difficulty":3,"options":[{"label":"5/12 (or other valid answer)","value":"5/12 (or other valid answer)"},{"label":"1/4","value":"1/4"},{"label":"2/5","value":"2/5"},{"label":"7/12","value":"7/12"}]},{"id":4,"text":"Compare 11/12 and 8/9.","type":"multiple_choice","correct_answer":"11/12 > 8/9","explanation":"Common denom 36: 11/12=33/36, 8/9=32/36. 33>32.","standard_code":"4.NF.2","difficulty":3,"options":[{"label":"They are equal","value":"They are equal"},{"label":"11/12 > 8/9","value":"11/12 > 8/9"},{"label":"8/9 > 11/12","value":"8/9 > 11/12"},{"label":"11/12 < 8/9","value":"11/12 < 8/9"}]},{"id":5,"text":"Is 3/7 greater or less than 1/2? Explain without finding a common denominator.","type":"multiple_choice","correct_answer":"Less than 1/2","explanation":"Half of 7 is 3.5. Since 3 < 3.5, the fraction 3/7 < 1/2.","standard_code":"4.NF.2","difficulty":3,"options":[{"label":"Cannot be compared","value":"Cannot be compared"},{"label":"Greater than 1/2","value":"Greater than 1/2"},{"label":"Equal to 1/2","value":"Equal to 1/2"},{"label":"Less than 1/2","value":"Less than 1/2"}]}]'::jsonb);

VALUES (4,'NF','4.NF.3','Understand a fraction a/b with a > 1 as a sum of fractions 1/b; add and subtract fractions with like denominators (Easy)','Practice Understand a fraction a/b with a > 1 as a sum of fractions 1/b; add and subtract fractions with like denominators','practice',1,10,256,'[{"id":1,"text":"Write 3/4 as a sum of unit fractions.","type":"multiple_choice","correct_answer":"1/4 + 1/4 + 1/4","explanation":"3/4 = three copies of 1/4.","standard_code":"4.NF.3","difficulty":1,"options":[{"label":"1/3 + 1/3 + 1/3","value":"1/3 + 1/3 + 1/3"},{"label":"1/2 + 1/4","value":"1/2 + 1/4"},{"label":"1/2 + 1/2","value":"1/2 + 1/2"},{"label":"1/4 + 1/4 + 1/4","value":"1/4 + 1/4 + 1/4"}]},{"id":2,"text":"1/5 + 2/5 = ?","type":"numeric","correct_answer":"3/5","explanation":"Same denominator: 1+2=3, keep denominator 5.","standard_code":"4.NF.3","difficulty":1},{"id":3,"text":"4/6 − 1/6 = ?","type":"multiple_choice","correct_answer":"3/6 = 1/2","explanation":"4−1=3, keep 6. 3/6 simplifies to 1/2.","standard_code":"4.NF.3","difficulty":1,"options":[{"label":"3/6 = 1/2","value":"3/6 = 1/2"},{"label":"2/6","value":"2/6"},{"label":"5/6 = 1/1","value":"5/6 = 1/1"},{"label":"4/6 = 2/3","value":"4/6 = 2/3"}]},{"id":4,"text":"2/8 + 3/8 = ?","type":"numeric","correct_answer":"5/8","explanation":"2+3=5, denominator stays 8.","standard_code":"4.NF.3","difficulty":1},{"id":5,"text":"Write 5/3 as a mixed number.","type":"multiple_choice","correct_answer":"1 2/3","explanation":"5÷3 = 1 remainder 2, so 5/3 = 1 2/3.","standard_code":"4.NF.3","difficulty":1,"options":[{"label":"1 1/3","value":"1 1/3"},{"label":"1 2/3","value":"1 2/3"},{"label":"2 2/3","value":"2 2/3"},{"label":"2 1/3","value":"2 1/3"}]}]'::jsonb);

VALUES (4,'NF','4.NF.3','Understand a fraction a/b with a > 1 as a sum of fractions 1/b; add and subtract fractions with like denominators (Medium)','Practice Understand a fraction a/b with a > 1 as a sum of fractions 1/b; add and subtract fractions with like denominators','practice',2,15,257,'[{"id":1,"text":"3/10 + 4/10 + 2/10 = ?","type":"numeric","correct_answer":"9/10","explanation":"3+4+2=9, denominator stays 10.","standard_code":"4.NF.3","difficulty":2},{"id":2,"text":"7/8 − 3/8 = ?","type":"multiple_choice","correct_answer":"4/8 = 1/2","explanation":"7−3=4, keep 8. 4/8 simplifies to 1/2.","standard_code":"4.NF.3","difficulty":2,"options":[{"label":"11/8 = 1 3/8","value":"11/8 = 1 3/8"},{"label":"4/8 = 1/2","value":"4/8 = 1/2"},{"label":"5/8 = 1/2","value":"5/8 = 1/2"},{"label":"3/8","value":"3/8"}]},{"id":3,"text":"2 3/5 + 1 1/5 = ?","type":"multiple_choice","correct_answer":"3 4/5","explanation":"Add wholes: 2+1=3. Add fractions: 3/5+1/5=4/5. Total: 3 4/5.","standard_code":"4.NF.3","difficulty":2,"options":[{"label":"3 3/5","value":"3 3/5"},{"label":"3 4/5","value":"3 4/5"},{"label":"4 1/5","value":"4 1/5"},{"label":"4 4/5","value":"4 4/5"}]},{"id":4,"text":"4 2/6 − 1 5/6 = ?","type":"multiple_choice","correct_answer":"2 3/6 = 2 1/2","explanation":"Borrow: 4 2/6 = 3 8/6. 3 8/6 − 1 5/6 = 2 3/6 = 2 1/2.","standard_code":"4.NF.3","difficulty":2,"options":[{"label":"1 3/6 = 1 1/2","value":"1 3/6 = 1 1/2"},{"label":"3 3/6 = 3 1/2","value":"3 3/6 = 3 1/2"},{"label":"2 3/6 = 2 1/2","value":"2 3/6 = 2 1/2"},{"label":"2 4/6","value":"2 4/6"}]},{"id":5,"text":"Write 11/4 as a mixed number.","type":"multiple_choice","correct_answer":"2 3/4","explanation":"11÷4=2 R3, so 11/4 = 2 3/4.","standard_code":"4.NF.3","difficulty":2,"options":[{"label":"2 3/4","value":"2 3/4"},{"label":"3 3/4","value":"3 3/4"},{"label":"2 1/2","value":"2 1/2"},{"label":"2 1/4","value":"2 1/4"}]}]'::jsonb);

VALUES (4,'NF','4.NF.3','Understand a fraction a/b with a > 1 as a sum of fractions 1/b; add and subtract fractions with like denominators (Hard)','Practice Understand a fraction a/b with a > 1 as a sum of fractions 1/b; add and subtract fractions with like denominators','practice',3,20,258,'[{"id":1,"text":"5 1/8 − 2 5/8 = ?","type":"multiple_choice","correct_answer":"2 4/8 = 2 1/2","explanation":"Borrow: 5 1/8 = 4 9/8. 4 9/8 − 2 5/8 = 2 4/8 = 2 1/2.","standard_code":"4.NF.3","difficulty":3,"options":[{"label":"2 3/8","value":"2 3/8"},{"label":"3 4/8 = 3 1/2","value":"3 4/8 = 3 1/2"},{"label":"3 1/8","value":"3 1/8"},{"label":"2 4/8 = 2 1/2","value":"2 4/8 = 2 1/2"}]},{"id":2,"text":"A recipe needs 3/4 cup of flour. You already added 1/4 cup. How much more do you need?","type":"multiple_choice","correct_answer":"2/4 = 1/2 cup","explanation":"3/4 − 1/4 = 2/4 = 1/2 cup.","standard_code":"4.NF.3","difficulty":3,"options":[{"label":"2/4 = 1/2 cup","value":"2/4 = 1/2 cup"},{"label":"1/4 cup","value":"1/4 cup"},{"label":"1 cup","value":"1 cup"},{"label":"3/4 cup","value":"3/4 cup"}]},{"id":3,"text":"Write 3 2/5 as an improper fraction.","type":"numeric","correct_answer":"17/5","explanation":"3 × 5 + 2 = 17. So 3 2/5 = 17/5.","standard_code":"4.NF.3","difficulty":3},{"id":4,"text":"7 3/12 + 2 11/12 = ?","type":"multiple_choice","correct_answer":"10 2/12 = 10 1/6","explanation":"7+2=9. 3/12+11/12=14/12=1 2/12. 9+1 2/12=10 2/12=10 1/6.","standard_code":"4.NF.3","difficulty":3,"options":[{"label":"10 2/12 = 10 1/6","value":"10 2/12 = 10 1/6"},{"label":"10 3/12","value":"10 3/12"},{"label":"9 14/12","value":"9 14/12"},{"label":"11 2/12","value":"11 2/12"}]},{"id":5,"text":"Sam ran 2 5/6 miles Monday and 3 4/6 miles Tuesday. How far total?","type":"multiple_choice","correct_answer":"6 3/6 = 6 1/2 miles","explanation":"2+3=5. 5/6+4/6=9/6=1 3/6. 5+1 3/6=6 3/6=6 1/2.","standard_code":"4.NF.3","difficulty":3,"options":[{"label":"5 9/6 = 5 1/2 miles","value":"5 9/6 = 5 1/2 miles"},{"label":"7 3/6 miles","value":"7 3/6 miles"},{"label":"6 3/6 = 6 1/2 miles","value":"6 3/6 = 6 1/2 miles"},{"label":"6 1/6 miles","value":"6 1/6 miles"}]}]'::jsonb);

VALUES (4,'NF','4.NF.4','Apply and extend understanding of multiplication to multiply a fraction by a whole number (Easy)','Practice Apply and extend understanding of multiplication to multiply a fraction by a whole number','practice',1,10,259,'[{"id":1,"text":"3 × 1/4 = ?","type":"numeric","correct_answer":"3/4","explanation":"3 × 1/4 = 1/4 + 1/4 + 1/4 = 3/4.","standard_code":"4.NF.4","difficulty":1},{"id":2,"text":"2 × 2/5 = ?","type":"numeric","correct_answer":"4/5","explanation":"2 × 2/5 = 2/5 + 2/5 = 4/5.","standard_code":"4.NF.4","difficulty":1},{"id":3,"text":"4 × 1/3 = ?","type":"multiple_choice","correct_answer":"4/3 = 1 1/3","explanation":"4 × 1/3 = 4/3 = 1 1/3.","standard_code":"4.NF.4","difficulty":1,"options":[{"label":"1/3","value":"1/3"},{"label":"4/3","value":"4/3"},{"label":"5/3 = 1 2/3","value":"5/3 = 1 2/3"},{"label":"4/3 = 1 1/3","value":"4/3 = 1 1/3"}]},{"id":4,"text":"5 × 1/2 = ?","type":"multiple_choice","correct_answer":"5/2 = 2 1/2","explanation":"5 × 1/2 = 5/2 = 2 1/2.","standard_code":"4.NF.4","difficulty":1,"options":[{"label":"5/2 = 2 1/2","value":"5/2 = 2 1/2"},{"label":"2/2 = 1","value":"2/2 = 1"},{"label":"5/4 = 1 1/4","value":"5/4 = 1 1/4"},{"label":"7/2 = 3 1/2","value":"7/2 = 3 1/2"}]},{"id":5,"text":"2 × 3/8 = ?","type":"multiple_choice","correct_answer":"6/8 = 3/4","explanation":"2 × 3 = 6, keep 8. 6/8 = 3/4.","standard_code":"4.NF.4","difficulty":1,"options":[{"label":"6/8 = 3/4","value":"6/8 = 3/4"},{"label":"9/8 = 1 1/8","value":"9/8 = 1 1/8"},{"label":"8/8 = 1","value":"8/8 = 1"},{"label":"5/8","value":"5/8"}]}]'::jsonb);

VALUES (4,'NF','4.NF.4','Apply and extend understanding of multiplication to multiply a fraction by a whole number (Medium)','Practice Apply and extend understanding of multiplication to multiply a fraction by a whole number','practice',2,15,260,'[{"id":1,"text":"6 × 2/3 = ?","type":"multiple_choice","correct_answer":"12/3 = 4","explanation":"6 × 2 = 12, keep 3. 12/3 = 4.","standard_code":"4.NF.4","difficulty":2,"options":[{"label":"8/3 = 2 2/3","value":"8/3 = 2 2/3"},{"label":"18/3 = 6","value":"18/3 = 6"},{"label":"6/3 = 2","value":"6/3 = 2"},{"label":"12/3 = 4","value":"12/3 = 4"}]},{"id":2,"text":"4 × 3/5 = ?","type":"multiple_choice","correct_answer":"12/5 = 2 2/5","explanation":"4 × 3 = 12, keep 5. 12/5 = 2 2/5.","standard_code":"4.NF.4","difficulty":2,"options":[{"label":"11/5 = 2 1/5","value":"11/5 = 2 1/5"},{"label":"7/5 = 1 2/5","value":"7/5 = 1 2/5"},{"label":"12/5 = 2 2/5","value":"12/5 = 2 2/5"},{"label":"15/5 = 3","value":"15/5 = 3"}]},{"id":3,"text":"A recipe uses 2/3 cup of sugar. If you triple the recipe, how much sugar?","type":"multiple_choice","correct_answer":"6/3 = 2 cups","explanation":"3 × 2/3 = 6/3 = 2 cups.","standard_code":"4.NF.4","difficulty":2,"options":[{"label":"4/3 = 1 1/3 cups","value":"4/3 = 1 1/3 cups"},{"label":"9/3 = 3 cups","value":"9/3 = 3 cups"},{"label":"6/3 = 2 cups","value":"6/3 = 2 cups"},{"label":"8/3 = 2 2/3 cups","value":"8/3 = 2 2/3 cups"}]},{"id":4,"text":"7 × 3/4 = ?","type":"multiple_choice","correct_answer":"21/4 = 5 1/4","explanation":"7 × 3 = 21, keep 4. 21/4 = 5 1/4.","standard_code":"4.NF.4","difficulty":2,"options":[{"label":"24/4 = 6","value":"24/4 = 6"},{"label":"14/4 = 3 1/2","value":"14/4 = 3 1/2"},{"label":"28/4 = 7","value":"28/4 = 7"},{"label":"21/4 = 5 1/4","value":"21/4 = 5 1/4"}]},{"id":5,"text":"5 × 4/6 = ?","type":"multiple_choice","correct_answer":"20/6 = 3 2/6 = 3 1/3","explanation":"5 × 4 = 20, keep 6. 20/6 = 3 2/6 = 3 1/3.","standard_code":"4.NF.4","difficulty":2,"options":[{"label":"15/6 = 2 3/6 = 2 1/2","value":"15/6 = 2 3/6 = 2 1/2"},{"label":"24/6 = 4","value":"24/6 = 4"},{"label":"20/6 = 3 2/6 = 3 1/3","value":"20/6 = 3 2/6 = 3 1/3"},{"label":"25/6 = 4 1/6","value":"25/6 = 4 1/6"}]}]'::jsonb);

VALUES (4,'NF','4.NF.4','Apply and extend understanding of multiplication to multiply a fraction by a whole number (Hard)','Practice Apply and extend understanding of multiplication to multiply a fraction by a whole number','practice',3,20,261,'[{"id":1,"text":"8 × 5/6 = ?","type":"multiple_choice","correct_answer":"40/6 = 6 4/6 = 6 2/3","explanation":"8×5=40, keep 6. 40/6 = 6 R4, so 6 4/6 = 6 2/3.","standard_code":"4.NF.4","difficulty":3,"options":[{"label":"45/6 = 7 3/6 = 7 1/2","value":"45/6 = 7 3/6 = 7 1/2"},{"label":"48/6 = 8","value":"48/6 = 8"},{"label":"40/6 = 6 4/6 = 6 2/3","value":"40/6 = 6 4/6 = 6 2/3"},{"label":"35/6 = 5 5/6","value":"35/6 = 5 5/6"}]},{"id":2,"text":"Each serving of juice is 3/4 cup. How many cups for 12 servings?","type":"multiple_choice","correct_answer":"36/4 = 9 cups","explanation":"12 × 3/4 = 36/4 = 9 cups.","standard_code":"4.NF.4","difficulty":3,"options":[{"label":"36/4 = 9 cups","value":"36/4 = 9 cups"},{"label":"48/4 = 12 cups","value":"48/4 = 12 cups"},{"label":"40/4 = 10 cups","value":"40/4 = 10 cups"},{"label":"28/4 = 7 cups","value":"28/4 = 7 cups"}]},{"id":3,"text":"9 × 2/3 = ? Write as a mixed number.","type":"multiple_choice","correct_answer":"18/3 = 6","explanation":"9 × 2 = 18, keep 3. 18/3 = 6 (whole number).","standard_code":"4.NF.4","difficulty":3,"options":[{"label":"12/3 = 4","value":"12/3 = 4"},{"label":"27/3 = 9","value":"27/3 = 9"},{"label":"18/3 = 5 1/3","value":"18/3 = 5 1/3"},{"label":"18/3 = 6","value":"18/3 = 6"}]},{"id":4,"text":"A hiker walks 7/8 mile each day. How far in 6 days?","type":"multiple_choice","correct_answer":"42/8 = 5 2/8 = 5 1/4 miles","explanation":"6 × 7/8 = 42/8 = 5 2/8 = 5 1/4 miles.","standard_code":"4.NF.4","difficulty":3,"options":[{"label":"42/8 = 5 3/8 miles","value":"42/8 = 5 3/8 miles"},{"label":"56/8 = 7 miles","value":"56/8 = 7 miles"},{"label":"42/8 = 5 2/8 = 5 1/4 miles","value":"42/8 = 5 2/8 = 5 1/4 miles"},{"label":"48/8 = 6 miles","value":"48/8 = 6 miles"}]},{"id":5,"text":"If 4 × n/5 = 3 1/5, what is n?","type":"multiple_choice","correct_answer":"n = 4","explanation":"3 1/5 = 16/5. 4n/5 = 16/5, so 4n = 16, n = 4.","standard_code":"4.NF.4","difficulty":3,"options":[{"label":"n = 4","value":"n = 4"},{"label":"n = 3","value":"n = 3"},{"label":"n = 8","value":"n = 8"},{"label":"n = 5","value":"n = 5"}]}]'::jsonb);

VALUES (4,'NF','4.NF.5','Express a fraction with denominator 10 as an equivalent fraction with denominator 100 (Easy)','Practice Express a fraction with denominator 10 as an equivalent fraction with denominator 100','practice',1,10,262,'[{"id":1,"text":"Write 3/10 as a fraction with denominator 100.","type":"numeric","correct_answer":"30/100","explanation":"(3×10)/(10×10) = 30/100.","standard_code":"4.NF.5","difficulty":1},{"id":2,"text":"Write 7/10 as a fraction with denominator 100.","type":"numeric","correct_answer":"70/100","explanation":"(7×10)/(10×10) = 70/100.","standard_code":"4.NF.5","difficulty":1},{"id":3,"text":"Add: 3/10 + 4/100 = ?","type":"numeric","correct_answer":"34/100","explanation":"3/10 = 30/100. 30/100 + 4/100 = 34/100.","standard_code":"4.NF.5","difficulty":1},{"id":4,"text":"Write 1/10 with denominator 100.","type":"numeric","correct_answer":"10/100","explanation":"(1×10)/(10×10) = 10/100.","standard_code":"4.NF.5","difficulty":1},{"id":5,"text":"Add: 5/10 + 20/100 = ?","type":"numeric","correct_answer":"70/100","explanation":"5/10 = 50/100. 50/100 + 20/100 = 70/100.","standard_code":"4.NF.5","difficulty":1}]'::jsonb);

VALUES (4,'NF','4.NF.5','Express a fraction with denominator 10 as an equivalent fraction with denominator 100 (Medium)','Practice Express a fraction with denominator 10 as an equivalent fraction with denominator 100','practice',2,15,263,'[{"id":1,"text":"Add: 6/10 + 35/100 = ?","type":"numeric","correct_answer":"95/100","explanation":"6/10 = 60/100. 60/100 + 35/100 = 95/100.","standard_code":"4.NF.5","difficulty":2},{"id":2,"text":"Add: 2/10 + 8/100 = ?","type":"numeric","correct_answer":"28/100","explanation":"2/10 = 20/100. 20/100 + 8/100 = 28/100.","standard_code":"4.NF.5","difficulty":2},{"id":3,"text":"Which is greater: 4/10 or 39/100?","type":"multiple_choice","correct_answer":"4/10 > 39/100","explanation":"4/10 = 40/100. 40/100 > 39/100.","standard_code":"4.NF.5","difficulty":2,"options":[{"label":"39/100 > 4/10","value":"39/100 > 4/10"},{"label":"4/10 = 39/100","value":"4/10 = 39/100"},{"label":"4/10 < 39/100","value":"4/10 < 39/100"},{"label":"4/10 > 39/100","value":"4/10 > 39/100"}]},{"id":4,"text":"Add: 9/10 + 5/100 = ?","type":"numeric","correct_answer":"95/100","explanation":"9/10 = 90/100. 90/100 + 5/100 = 95/100.","standard_code":"4.NF.5","difficulty":2},{"id":5,"text":"Is 50/100 the same as 5/10?","type":"multiple_choice","correct_answer":"Yes","explanation":"5/10 = 50/100 (multiply by 10). They are equivalent.","standard_code":"4.NF.5","difficulty":2,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]}]'::jsonb);

VALUES (4,'NF','4.NF.5','Express a fraction with denominator 10 as an equivalent fraction with denominator 100 (Hard)','Practice Express a fraction with denominator 10 as an equivalent fraction with denominator 100','practice',3,20,264,'[{"id":1,"text":"Add: 8/10 + 25/100 = ? Write as a fraction and simplify if possible.","type":"multiple_choice","correct_answer":"105/100 = 1 5/100 = 1 1/20","explanation":"8/10=80/100. 80+25=105/100=1 5/100. 5/100=1/20.","standard_code":"4.NF.5","difficulty":3,"options":[{"label":"103/100 = 1 3/100","value":"103/100 = 1 3/100"},{"label":"33/100 = 33/100","value":"33/100 = 33/100"},{"label":"105/100 = 1 5/100 = 1 1/20","value":"105/100 = 1 5/100 = 1 1/20"},{"label":"110/100 = 1 1/10","value":"110/100 = 1 1/10"}]},{"id":2,"text":"Express 47/100 as a sum of a tenths fraction and a hundredths fraction.","type":"multiple_choice","correct_answer":"4/10 + 7/100","explanation":"47/100 = 40/100 + 7/100 = 4/10 + 7/100.","standard_code":"4.NF.5","difficulty":3,"options":[{"label":"3/10 + 5/100","value":"3/10 + 5/100"},{"label":"4/10 + 7/100","value":"4/10 + 7/100"},{"label":"5/10 + 7/100","value":"5/10 + 7/100"},{"label":"4/10 + 17/100","value":"4/10 + 17/100"}]},{"id":3,"text":"Which is greater: 6/10 + 3/100 or 7/10 − 8/100?","type":"multiple_choice","correct_answer":"6/10 + 3/100 = 63/100; 7/10 − 8/100 = 62/100. The first is greater.","explanation":"63/100 > 62/100.","standard_code":"4.NF.5","difficulty":3,"options":[{"label":"7/10 − 8/100 is greater","value":"7/10 − 8/100 is greater"},{"label":"6/10 + 3/100 = 64/100; 7/10 − 8/100 = 61/100","value":"6/10 + 3/100 = 64/100; 7/10 − 8/100 = 61/100"},{"label":"They are equal","value":"They are equal"},{"label":"6/10 + 3/100 = 63/100; 7/10 − 8/100 = 62/100. The first is greater.","value":"6/10 + 3/100 = 63/100; 7/10 − 8/100 = 62/100. The first is greater."}]},{"id":4,"text":"A jar is 3/10 full. Then 15/100 more is added. What fraction is full now?","type":"multiple_choice","correct_answer":"45/100 = 9/20","explanation":"3/10=30/100. 30+15=45/100. Simplify: 45÷5=9, 100÷5=20.","standard_code":"4.NF.5","difficulty":3,"options":[{"label":"45/100 = 9/20","value":"45/100 = 9/20"},{"label":"30/100 = 3/10","value":"30/100 = 3/10"},{"label":"50/100 = 1/2","value":"50/100 = 1/2"},{"label":"48/100 = 12/25","value":"48/100 = 12/25"}]},{"id":5,"text":"Add: 7/10 + 7/100. Then subtract 1/10. What''s the result?","type":"numeric","correct_answer":"67/100","explanation":"7/10+7/100=77/100. 77/100−10/100=67/100.","standard_code":"4.NF.5","difficulty":3}]'::jsonb);

VALUES (4,'NF','4.NF.6','Use decimal notation for fractions with denominators 10 or 100 (Easy)','Practice Use decimal notation for fractions with denominators 10 or 100','practice',1,10,265,'[{"id":1,"text":"Write 3/10 as a decimal.","type":"numeric","correct_answer":"0.3","explanation":"3/10 = 0.3 (3 in the tenths place).","standard_code":"4.NF.6","difficulty":1},{"id":2,"text":"Write 47/100 as a decimal.","type":"numeric","correct_answer":"0.47","explanation":"47/100 = 0.47 (4 tenths, 7 hundredths).","standard_code":"4.NF.6","difficulty":1},{"id":3,"text":"Write 0.8 as a fraction.","type":"numeric","correct_answer":"8/10","explanation":"0.8 has 8 in the tenths place = 8/10.","standard_code":"4.NF.6","difficulty":1},{"id":4,"text":"Write 0.25 as a fraction.","type":"numeric","correct_answer":"25/100","explanation":"0.25 = 25 hundredths = 25/100.","standard_code":"4.NF.6","difficulty":1},{"id":5,"text":"Write 9/10 as a decimal.","type":"numeric","correct_answer":"0.9","explanation":"9/10 = 0.9.","standard_code":"4.NF.6","difficulty":1}]'::jsonb);

VALUES (4,'NF','4.NF.6','Use decimal notation for fractions with denominators 10 or 100 (Medium)','Practice Use decimal notation for fractions with denominators 10 or 100','practice',2,15,266,'[{"id":1,"text":"Write 1 3/10 as a decimal.","type":"numeric","correct_answer":"1.3","explanation":"1 whole and 3 tenths = 1.3.","standard_code":"4.NF.6","difficulty":2},{"id":2,"text":"Write 5.07 as a fraction.","type":"multiple_choice","correct_answer":"5 7/100","explanation":"5.07 = 5 and 7 hundredths = 5 7/100.","standard_code":"4.NF.6","difficulty":2,"options":[{"label":"5 17/100","value":"5 17/100"},{"label":"5 70/100","value":"5 70/100"},{"label":"57/100","value":"57/100"},{"label":"5 7/100","value":"5 7/100"}]},{"id":3,"text":"Write 62/100 as a decimal.","type":"numeric","correct_answer":"0.62","explanation":"62/100 = 0.62.","standard_code":"4.NF.6","difficulty":2},{"id":4,"text":"Write 2.50 as a mixed number.","type":"multiple_choice","correct_answer":"2 50/100 = 2 1/2","explanation":"2.50 = 2 and 50/100 = 2 1/2.","standard_code":"4.NF.6","difficulty":2,"options":[{"label":"2 40/100 = 2 2/5","value":"2 40/100 = 2 2/5"},{"label":"2 25/100 = 2 1/4","value":"2 25/100 = 2 1/4"},{"label":"2 5/100 = 2 1/20","value":"2 5/100 = 2 1/20"},{"label":"2 50/100 = 2 1/2","value":"2 50/100 = 2 1/2"}]},{"id":5,"text":"Write 4/10 as a decimal and as hundredths.","type":"multiple_choice","correct_answer":"0.4 = 0.40 = 40/100","explanation":"4/10 = 40/100 = 0.40.","standard_code":"4.NF.6","difficulty":2,"options":[{"label":"4.0 = 4.00 = 400/100","value":"4.0 = 4.00 = 400/100"},{"label":"0.04 = 0.040 = 4/100","value":"0.04 = 0.040 = 4/100"},{"label":"0.4 = 0.04 = 4/100","value":"0.4 = 0.04 = 4/100"},{"label":"0.4 = 0.40 = 40/100","value":"0.4 = 0.40 = 40/100"}]}]'::jsonb);

VALUES (4,'NF','4.NF.6','Use decimal notation for fractions with denominators 10 or 100 (Hard)','Practice Use decimal notation for fractions with denominators 10 or 100','practice',3,20,267,'[{"id":1,"text":"Write 3 8/10 + 15/100 as a single decimal.","type":"numeric","correct_answer":"3.95","explanation":"3 8/10 = 3.80. 15/100 = 0.15. 3.80 + 0.15 = 3.95.","standard_code":"4.NF.6","difficulty":3},{"id":2,"text":"A pencil costs $0.75. Write this as a fraction of a dollar.","type":"multiple_choice","correct_answer":"75/100 = 3/4 of a dollar","explanation":"$0.75 = 75/100 = 3/4.","standard_code":"4.NF.6","difficulty":3,"options":[{"label":"50/100 = 1/2 of a dollar","value":"50/100 = 1/2 of a dollar"},{"label":"70/100 = 7/10 of a dollar","value":"70/100 = 7/10 of a dollar"},{"label":"75/100 = 3/4 of a dollar","value":"75/100 = 3/4 of a dollar"},{"label":"80/100 = 4/5 of a dollar","value":"80/100 = 4/5 of a dollar"}]},{"id":3,"text":"Order from least to greatest: 0.5, 0.05, 0.55, 0.50.","type":"multiple_choice","correct_answer":"0.05, 0.5, 0.50, 0.55 (note: 0.5 = 0.50)","explanation":"0.05=5/100, 0.5=50/100=0.50, 0.55=55/100. Order: 0.05, 0.5=0.50, 0.55.","standard_code":"4.NF.6","difficulty":3,"options":[{"label":"0.05, 0.50, 0.5, 0.55","value":"0.05, 0.50, 0.5, 0.55"},{"label":"0.05, 0.5, 0.50, 0.55 (note: 0.5 = 0.50)","value":"0.05, 0.5, 0.50, 0.55 (note: 0.5 = 0.50)"},{"label":"0.5, 0.50, 0.05, 0.55","value":"0.5, 0.50, 0.05, 0.55"},{"label":"0.05, 0.55, 0.5, 0.50","value":"0.05, 0.55, 0.5, 0.50"}]},{"id":4,"text":"Write the decimal for: 6 ones + 0 tenths + 4 hundredths.","type":"numeric","correct_answer":"6.04","explanation":"6 + 0/10 + 4/100 = 6.04.","standard_code":"4.NF.6","difficulty":3},{"id":5,"text":"If you add 3/10 and 0.45, what decimal do you get?","type":"numeric","correct_answer":"0.75","explanation":"3/10 = 0.30. 0.30 + 0.45 = 0.75.","standard_code":"4.NF.6","difficulty":3}]'::jsonb);

VALUES (4,'NF','4.NF.7','Compare two decimals to hundredths by reasoning about their size (Easy)','Practice Compare two decimals to hundredths by reasoning about their size','practice',1,10,268,'[{"id":1,"text":"Compare 0.3 and 0.5 using <, >, or =.","type":"multiple_choice","correct_answer":"0.3 < 0.5","explanation":"3 tenths < 5 tenths.","standard_code":"4.NF.7","difficulty":1,"options":[{"label":"0.3 > 0.5","value":"0.3 > 0.5"},{"label":"0.3 < 0.5","value":"0.3 < 0.5"},{"label":"0.5 < 0.3","value":"0.5 < 0.3"},{"label":"0.3 = 0.5","value":"0.3 = 0.5"}]},{"id":2,"text":"Compare 0.72 and 0.27.","type":"multiple_choice","correct_answer":"0.72 > 0.27","explanation":"7 tenths > 2 tenths, so 0.72 > 0.27.","standard_code":"4.NF.7","difficulty":1,"options":[{"label":"0.72 > 0.27","value":"0.72 > 0.27"},{"label":"0.72 < 0.27","value":"0.72 < 0.27"},{"label":"0.27 > 0.72","value":"0.27 > 0.72"},{"label":"0.72 = 0.27","value":"0.72 = 0.27"}]},{"id":3,"text":"Compare 0.40 and 0.4.","type":"multiple_choice","correct_answer":"0.40 = 0.4","explanation":"0.40 and 0.4 are the same: 4 tenths.","standard_code":"4.NF.7","difficulty":1,"options":[{"label":"0.40 ≠ 0.4","value":"0.40 ≠ 0.4"},{"label":"0.40 = 0.4","value":"0.40 = 0.4"},{"label":"0.40 < 0.4","value":"0.40 < 0.4"},{"label":"0.40 > 0.4","value":"0.40 > 0.4"}]},{"id":4,"text":"Which is greater: 0.9 or 0.85?","type":"numeric","correct_answer":"0.9","explanation":"0.9 = 0.90. 0.90 > 0.85.","standard_code":"4.NF.7","difficulty":1},{"id":5,"text":"Compare 0.6 and 0.60.","type":"multiple_choice","correct_answer":"0.6 = 0.60","explanation":"They are equal. The trailing zero doesn''t change value.","standard_code":"4.NF.7","difficulty":1,"options":[{"label":"0.6 > 0.60","value":"0.6 > 0.60"},{"label":"0.6 < 0.60","value":"0.6 < 0.60"},{"label":"0.6 ≠ 0.60","value":"0.6 ≠ 0.60"},{"label":"0.6 = 0.60","value":"0.6 = 0.60"}]}]'::jsonb);

VALUES (4,'NF','4.NF.7','Compare two decimals to hundredths by reasoning about their size (Medium)','Practice Compare two decimals to hundredths by reasoning about their size','practice',2,15,269,'[{"id":1,"text":"Order from least to greatest: 0.45, 0.54, 0.4, 0.5.","type":"multiple_choice","correct_answer":"0.4, 0.45, 0.5, 0.54","explanation":"0.4=0.40, 0.45, 0.5=0.50, 0.54. Compare hundredths in order.","standard_code":"4.NF.7","difficulty":2,"options":[{"label":"0.4, 0.5, 0.45, 0.54","value":"0.4, 0.5, 0.45, 0.54"},{"label":"0.45, 0.4, 0.5, 0.54","value":"0.45, 0.4, 0.5, 0.54"},{"label":"0.4, 0.45, 0.5, 0.54","value":"0.4, 0.45, 0.5, 0.54"},{"label":"0.54, 0.5, 0.45, 0.4","value":"0.54, 0.5, 0.45, 0.4"}]},{"id":2,"text":"Compare 0.08 and 0.8.","type":"multiple_choice","correct_answer":"0.08 < 0.8","explanation":"0.08 = 8 hundredths. 0.8 = 80 hundredths. 8 < 80.","standard_code":"4.NF.7","difficulty":2,"options":[{"label":"0.08 = 0.8","value":"0.08 = 0.8"},{"label":"0.08 > 0.8","value":"0.08 > 0.8"},{"label":"0.08 < 0.8","value":"0.08 < 0.8"},{"label":"0.08 > 0.8","value":"0.08 > 0.8"}]},{"id":3,"text":"Which is closest to 1: 0.89, 0.98, or 0.9?","type":"numeric","correct_answer":"0.98","explanation":"0.98 is only 0.02 from 1. 0.9 is 0.1 away. 0.89 is 0.11 away.","standard_code":"4.NF.7","difficulty":2},{"id":4,"text":"Order from greatest to least: 3.5, 3.05, 3.55, 3.50.","type":"multiple_choice","correct_answer":"3.55, 3.5 = 3.50, 3.05","explanation":"3.55 > 3.50 = 3.5 > 3.05.","standard_code":"4.NF.7","difficulty":2,"options":[{"label":"3.55, 3.50, 3.5 = 3.05","value":"3.55, 3.50, 3.5 = 3.05"},{"label":"3.55, 3.5, 3.50, 3.05","value":"3.55, 3.5, 3.50, 3.05"},{"label":"3.50 = 3.5, 3.55, 3.05","value":"3.50 = 3.5, 3.55, 3.05"},{"label":"3.55, 3.5 = 3.50, 3.05","value":"3.55, 3.5 = 3.50, 3.05"}]},{"id":5,"text":"Compare 1.2 and 1.19.","type":"multiple_choice","correct_answer":"1.2 > 1.19","explanation":"1.2 = 1.20. 1.20 > 1.19.","standard_code":"4.NF.7","difficulty":2,"options":[{"label":"1.2 < 1.19","value":"1.2 < 1.19"},{"label":"1.2 < 1.19","value":"1.2 < 1.19"},{"label":"1.2 > 1.19","value":"1.2 > 1.19"},{"label":"1.2 = 1.19","value":"1.2 = 1.19"}]}]'::jsonb);

VALUES (4,'NF','4.NF.7','Compare two decimals to hundredths by reasoning about their size (Hard)','Practice Compare two decimals to hundredths by reasoning about their size','practice',3,20,270,'[{"id":1,"text":"Order from least to greatest: 4.04, 4.40, 4.44, 4.4.","type":"multiple_choice","correct_answer":"4.04, 4.4 = 4.40, 4.44","explanation":"4.04 < 4.40 = 4.4 < 4.44.","standard_code":"4.NF.7","difficulty":3,"options":[{"label":"4.4 = 4.40, 4.04, 4.44","value":"4.4 = 4.40, 4.04, 4.44"},{"label":"4.04, 4.44, 4.4 = 4.40","value":"4.04, 4.44, 4.4 = 4.40"},{"label":"4.04, 4.4 = 4.40, 4.44","value":"4.04, 4.4 = 4.40, 4.44"},{"label":"4.40 = 4.4, 4.04, 4.44","value":"4.40 = 4.4, 4.04, 4.44"}]},{"id":2,"text":"Find a decimal between 0.6 and 0.7.","type":"multiple_choice","correct_answer":"0.65 (or any value like 0.61–0.69)","explanation":"0.6 = 0.60. Any decimal from 0.61 to 0.69 is between them.","standard_code":"4.NF.7","difficulty":3,"options":[{"label":"0.60","value":"0.60"},{"label":"0.75","value":"0.75"},{"label":"0.50","value":"0.50"},{"label":"0.65 (or any value like 0.61–0.69)","value":"0.65 (or any value like 0.61–0.69)"}]},{"id":3,"text":"Are 0.30 and 0.3 and 3/10 all equal? Explain.","type":"multiple_choice","correct_answer":"Yes, all equal","explanation":"0.30 = 0.3 (trailing zero). 0.3 = 3/10. All represent three tenths.","standard_code":"4.NF.7","difficulty":3,"options":[{"label":"Only 0.3 and 3/10 are equal","value":"Only 0.3 and 3/10 are equal"},{"label":"No, they are different values","value":"No, they are different values"},{"label":"Yes, but only approximately equal","value":"Yes, but only approximately equal"},{"label":"Yes, all equal","value":"Yes, all equal"}]},{"id":4,"text":"Sam ran 2.5 miles. Kim ran 2.48 miles. Who ran farther and by how much?","type":"multiple_choice","correct_answer":"Sam ran farther by 0.02 miles","explanation":"2.5 = 2.50. 2.50 − 2.48 = 0.02 miles.","standard_code":"4.NF.7","difficulty":3,"options":[{"label":"Sam ran farther by 0.02 miles","value":"Sam ran farther by 0.02 miles"},{"label":"Kim ran farther by 0.08 miles","value":"Kim ran farther by 0.08 miles"},{"label":"Kim ran farther by 0.02 miles","value":"Kim ran farther by 0.02 miles"},{"label":"Sam ran farther by 0.08 miles","value":"Sam ran farther by 0.08 miles"}]},{"id":5,"text":"Place these on a number line in order: 0.7, 0.07, 7.0, 0.77.","type":"multiple_choice","correct_answer":"0.07, 0.7, 0.77, 7.0","explanation":"7 hundredths, 70 hundredths, 77 hundredths, 7 wholes.","standard_code":"4.NF.7","difficulty":3,"options":[{"label":"0.07, 0.7, 0.77, 7.0","value":"0.07, 0.7, 0.77, 7.0"},{"label":"7.0, 0.77, 0.7, 0.07","value":"7.0, 0.77, 0.7, 0.07"},{"label":"0.7, 0.07, 0.77, 7.0","value":"0.7, 0.07, 0.77, 7.0"},{"label":"0.07, 0.77, 0.7, 7.0","value":"0.07, 0.77, 0.7, 7.0"}]}]'::jsonb);

VALUES (4,'MD','4.MD.1','Know relative sizes of measurement units; express measurements of a larger unit in terms of a smaller unit (Easy)','Practice Know relative sizes of measurement units; express measurements of a larger unit in terms of a smaller unit','practice',1,10,271,'[{"id":1,"text":"How many inches are in 1 foot?","type":"multiple_choice","correct_answer":"12 inches","explanation":"1 foot = 12 inches.","standard_code":"4.MD.1","difficulty":1,"options":[{"label":"12 inches","value":"12 inches"},{"label":"10 inches","value":"10 inches"},{"label":"13 inches","value":"13 inches"},{"label":"11 inches","value":"11 inches"}]},{"id":2,"text":"How many centimeters are in 1 meter?","type":"multiple_choice","correct_answer":"100 centimeters","explanation":"1 meter = 100 centimeters.","standard_code":"4.MD.1","difficulty":1,"options":[{"label":"1,000 centimeters","value":"1,000 centimeters"},{"label":"50 centimeters","value":"50 centimeters"},{"label":"10 centimeters","value":"10 centimeters"},{"label":"100 centimeters","value":"100 centimeters"}]},{"id":3,"text":"Convert 3 feet to inches.","type":"multiple_choice","correct_answer":"36 inches","explanation":"3 × 12 = 36 inches.","standard_code":"4.MD.1","difficulty":1,"options":[{"label":"36 inches","value":"36 inches"},{"label":"12 inches","value":"12 inches"},{"label":"48 inches","value":"48 inches"},{"label":"9 inches","value":"9 inches"}]},{"id":4,"text":"How many minutes are in 1 hour?","type":"multiple_choice","correct_answer":"60 minutes","explanation":"1 hour = 60 minutes.","standard_code":"4.MD.1","difficulty":1,"options":[{"label":"60 minutes","value":"60 minutes"},{"label":"90 minutes","value":"90 minutes"},{"label":"120 minutes","value":"120 minutes"},{"label":"30 minutes","value":"30 minutes"}]},{"id":5,"text":"Convert 2 meters to centimeters.","type":"multiple_choice","correct_answer":"200 centimeters","explanation":"2 × 100 = 200 cm.","standard_code":"4.MD.1","difficulty":1,"options":[{"label":"2,000 centimeters","value":"2,000 centimeters"},{"label":"200 centimeters","value":"200 centimeters"},{"label":"20 meters","value":"20 meters"},{"label":"20 centimeters","value":"20 centimeters"}]}]'::jsonb);

VALUES (4,'MD','4.MD.1','Know relative sizes of measurement units; express measurements of a larger unit in terms of a smaller unit (Medium)','Practice Know relative sizes of measurement units; express measurements of a larger unit in terms of a smaller unit','practice',2,15,272,'[{"id":1,"text":"Convert 5 yards to feet.","type":"multiple_choice","correct_answer":"15 feet","explanation":"1 yard = 3 feet. 5 × 3 = 15 feet.","standard_code":"4.MD.1","difficulty":2,"options":[{"label":"15 feet","value":"15 feet"},{"label":"12 feet","value":"12 feet"},{"label":"20 feet","value":"20 feet"},{"label":"10 feet","value":"10 feet"}]},{"id":2,"text":"How many ounces are in 3 pounds?","type":"multiple_choice","correct_answer":"48 ounces","explanation":"1 pound = 16 ounces. 3 × 16 = 48.","standard_code":"4.MD.1","difficulty":2,"options":[{"label":"48 ounces","value":"48 ounces"},{"label":"64 ounces","value":"64 ounces"},{"label":"36 ounces","value":"36 ounces"},{"label":"24 ounces","value":"24 ounces"}]},{"id":3,"text":"Convert 4 kilometers to meters.","type":"multiple_choice","correct_answer":"4,000 meters","explanation":"1 km = 1,000 m. 4 × 1,000 = 4,000.","standard_code":"4.MD.1","difficulty":2,"options":[{"label":"40,000 meters","value":"40,000 meters"},{"label":"400 meters","value":"400 meters"},{"label":"40 meters","value":"40 meters"},{"label":"4,000 meters","value":"4,000 meters"}]},{"id":4,"text":"How many cups are in 3 quarts?","type":"multiple_choice","correct_answer":"12 cups","explanation":"1 quart = 4 cups. 3 × 4 = 12 cups.","standard_code":"4.MD.1","difficulty":2,"options":[{"label":"3 cups","value":"3 cups"},{"label":"16 cups","value":"16 cups"},{"label":"12 cups","value":"12 cups"},{"label":"9 cups","value":"9 cups"}]},{"id":5,"text":"Convert 2 hours 30 minutes to minutes.","type":"multiple_choice","correct_answer":"150 minutes","explanation":"2 × 60 = 120. 120 + 30 = 150 minutes.","standard_code":"4.MD.1","difficulty":2,"options":[{"label":"90 minutes","value":"90 minutes"},{"label":"180 minutes","value":"180 minutes"},{"label":"150 minutes","value":"150 minutes"},{"label":"120 minutes","value":"120 minutes"}]}]'::jsonb);

VALUES (4,'MD','4.MD.1','Know relative sizes of measurement units; express measurements of a larger unit in terms of a smaller unit (Hard)','Practice Know relative sizes of measurement units; express measurements of a larger unit in terms of a smaller unit','practice',3,20,273,'[{"id":1,"text":"A table is 6 feet long. How many inches is that? How many yards?","type":"multiple_choice","correct_answer":"72 inches; 2 yards","explanation":"6 × 12 = 72 inches. 6 ÷ 3 = 2 yards.","standard_code":"4.MD.1","difficulty":3,"options":[{"label":"84 inches; 2 yards","value":"84 inches; 2 yards"},{"label":"72 inches; 3 yards","value":"72 inches; 3 yards"},{"label":"72 inches; 2 yards","value":"72 inches; 2 yards"},{"label":"60 inches; 3 yards","value":"60 inches; 3 yards"}]},{"id":2,"text":"A recipe needs 2 pounds 5 ounces of flour. How many ounces total?","type":"multiple_choice","correct_answer":"37 ounces","explanation":"2 × 16 = 32. 32 + 5 = 37 ounces.","standard_code":"4.MD.1","difficulty":3,"options":[{"label":"32 ounces","value":"32 ounces"},{"label":"40 ounces","value":"40 ounces"},{"label":"37 ounces","value":"37 ounces"},{"label":"29 ounces","value":"29 ounces"}]},{"id":3,"text":"Convert 3 gallons 2 quarts to quarts.","type":"multiple_choice","correct_answer":"14 quarts","explanation":"1 gallon = 4 quarts. 3 × 4 = 12. 12 + 2 = 14 quarts.","standard_code":"4.MD.1","difficulty":3,"options":[{"label":"11 quarts","value":"11 quarts"},{"label":"16 quarts","value":"16 quarts"},{"label":"14 quarts","value":"14 quarts"},{"label":"12 quarts","value":"12 quarts"}]},{"id":4,"text":"A race is 5 kilometers 200 meters. How many meters total?","type":"multiple_choice","correct_answer":"5,200 meters","explanation":"5 × 1,000 = 5,000. 5,000 + 200 = 5,200.","standard_code":"4.MD.1","difficulty":3,"options":[{"label":"5,200 meters","value":"5,200 meters"},{"label":"5,200 kilometers","value":"5,200 kilometers"},{"label":"5,002 meters","value":"5,002 meters"},{"label":"5,020 meters","value":"5,020 meters"}]},{"id":5,"text":"A movie is 2 hours 15 minutes. A second movie is 145 minutes. Which is longer?","type":"multiple_choice","correct_answer":"The second movie (145 > 135)","explanation":"2 hr 15 min = 135 min. 145 > 135.","standard_code":"4.MD.1","difficulty":3,"options":[{"label":"They are the same length","value":"They are the same length"},{"label":"The second movie (145 > 135)","value":"The second movie (145 > 135)"},{"label":"The first movie (135 > 145)","value":"The first movie (135 > 145)"},{"label":"The second movie (135 > 145)","value":"The second movie (135 > 145)"}]}]'::jsonb);

VALUES (4,'MD','4.MD.2','Use the four operations to solve word problems involving distances, intervals of time, money, and liquid volumes (Easy)','Practice Use the four operations to solve word problems involving distances, intervals of time, money, and liquid volumes','practice',1,10,274,'[{"id":1,"text":"A bottle holds 2 liters. How many milliliters is that?","type":"multiple_choice","correct_answer":"2,000 mL","explanation":"1 L = 1,000 mL. 2 × 1,000 = 2,000 mL.","standard_code":"4.MD.2","difficulty":1,"options":[{"label":"2,000 mL","value":"2,000 mL"},{"label":"200,000 mL","value":"200,000 mL"},{"label":"20,000 mL","value":"20,000 mL"},{"label":"200 mL","value":"200 mL"}]},{"id":2,"text":"Sam walked 3 km 400 m. Write this in meters.","type":"multiple_choice","correct_answer":"3,400 m","explanation":"3 × 1,000 = 3,000. 3,000 + 400 = 3,400 m.","standard_code":"4.MD.2","difficulty":1,"options":[{"label":"340 m","value":"340 m"},{"label":"3,004 m","value":"3,004 m"},{"label":"3,400 m","value":"3,400 m"},{"label":"3,040 m","value":"3,040 m"}]},{"id":3,"text":"A movie starts at 2:15 PM and ends at 4:00 PM. How long is it?","type":"multiple_choice","correct_answer":"1 hour 45 minutes","explanation":"From 2:15 to 4:00 = 1 hr 45 min.","standard_code":"4.MD.2","difficulty":1,"options":[{"label":"1 hour 45 minutes","value":"1 hour 45 minutes"},{"label":"1 hour 50 minutes","value":"1 hour 50 minutes"},{"label":"1 hour 30 minutes","value":"1 hour 30 minutes"},{"label":"2 hours 15 minutes","value":"2 hours 15 minutes"}]},{"id":4,"text":"You have $5.00 and buy a toy for $3.25. How much change?","type":"multiple_choice","correct_answer":"$1.75","explanation":"$5.00 − $3.25 = $1.75.","standard_code":"4.MD.2","difficulty":1,"options":[{"label":"$1.25","value":"$1.25"},{"label":"$1.50","value":"$1.50"},{"label":"$1.75","value":"$1.75"},{"label":"$2.25","value":"$2.25"}]},{"id":5,"text":"A pitcher has 4 liters of juice. 1 liter 500 mL is poured out. How much remains?","type":"multiple_choice","correct_answer":"2 liters 500 mL","explanation":"4 L − 1 L 500 mL = 2 L 500 mL.","standard_code":"4.MD.2","difficulty":1,"options":[{"label":"3 liters 500 mL","value":"3 liters 500 mL"},{"label":"2 liters 400 mL","value":"2 liters 400 mL"},{"label":"2 liters 800 mL","value":"2 liters 800 mL"},{"label":"2 liters 500 mL","value":"2 liters 500 mL"}]}]'::jsonb);

VALUES (4,'MD','4.MD.2','Use the four operations to solve word problems involving distances, intervals of time, money, and liquid volumes (Medium)','Practice Use the four operations to solve word problems involving distances, intervals of time, money, and liquid volumes','practice',2,15,275,'[{"id":1,"text":"A runner completes a race in 12 minutes 45 seconds. Another finishes in 11 minutes 58 seconds. What is the difference?","type":"multiple_choice","correct_answer":"47 seconds","explanation":"12:45 − 11:58 = 47 seconds.","standard_code":"4.MD.2","difficulty":2,"options":[{"label":"37 seconds","value":"37 seconds"},{"label":"57 seconds","value":"57 seconds"},{"label":"47 seconds","value":"47 seconds"},{"label":"1 minute 47 seconds","value":"1 minute 47 seconds"}]},{"id":2,"text":"Three containers hold 750 mL, 1 L 200 mL, and 500 mL. What is the total in liters and mL?","type":"multiple_choice","correct_answer":"2 L 450 mL","explanation":"750 + 1200 + 500 = 2,450 mL = 2 L 450 mL.","standard_code":"4.MD.2","difficulty":2,"options":[{"label":"2 L 450 mL","value":"2 L 450 mL"},{"label":"2 L 350 mL","value":"2 L 350 mL"},{"label":"3 L 450 mL","value":"3 L 450 mL"},{"label":"2 L 500 mL","value":"2 L 500 mL"}]},{"id":3,"text":"You earn $8.50 per hour and work 4 hours. How much do you earn?","type":"multiple_choice","correct_answer":"$34.00","explanation":"$8.50 × 4 = $34.00.","standard_code":"4.MD.2","difficulty":2,"options":[{"label":"$34.00","value":"$34.00"},{"label":"$36.00","value":"$36.00"},{"label":"$35.50","value":"$35.50"},{"label":"$32.00","value":"$32.00"}]},{"id":4,"text":"A trip is 15 km 600 m. You''ve driven 8 km 900 m. How far is left?","type":"multiple_choice","correct_answer":"6 km 700 m","explanation":"15,600 − 8,900 = 6,700 m = 6 km 700 m.","standard_code":"4.MD.2","difficulty":2,"options":[{"label":"6 km 700 m","value":"6 km 700 m"},{"label":"7 km 300 m","value":"7 km 300 m"},{"label":"6 km 200 m","value":"6 km 200 m"},{"label":"7 km 700 m","value":"7 km 700 m"}]},{"id":5,"text":"School starts at 8:30 AM and ends at 3:15 PM. How long is the school day?","type":"multiple_choice","correct_answer":"6 hours 45 minutes","explanation":"8:30 to 3:15: 8:30→3:30 = 7 hrs, minus 15 min = 6 hr 45 min.","standard_code":"4.MD.2","difficulty":2,"options":[{"label":"6 hours 45 minutes","value":"6 hours 45 minutes"},{"label":"7 hours 45 minutes","value":"7 hours 45 minutes"},{"label":"5 hours 45 minutes","value":"5 hours 45 minutes"},{"label":"6 hours 30 minutes","value":"6 hours 30 minutes"}]}]'::jsonb);

VALUES (4,'MD','4.MD.2','Use the four operations to solve word problems involving distances, intervals of time, money, and liquid volumes (Hard)','Practice Use the four operations to solve word problems involving distances, intervals of time, money, and liquid volumes','practice',3,20,276,'[{"id":1,"text":"You buy 3 items at $4.75, $6.50, and $2.25. You pay with a $20 bill. What''s your change?","type":"multiple_choice","correct_answer":"$6.50","explanation":"4.75+6.50+2.25 = $13.50. $20 − $13.50 = $6.50.","standard_code":"4.MD.2","difficulty":3,"options":[{"label":"$6.50","value":"$6.50"},{"label":"$6.00","value":"$6.00"},{"label":"$13.50","value":"$13.50"},{"label":"$7.00","value":"$7.00"}]},{"id":2,"text":"A tank holds 50 liters. Water flows in at 3 liters per minute. How long to fill?","type":"multiple_choice","correct_answer":"16 minutes 40 seconds","explanation":"50 ÷ 3 = 16 R2. 2/3 minute = 40 seconds. Total: 16 min 40 sec.","standard_code":"4.MD.2","difficulty":3,"options":[{"label":"15 minutes 50 seconds","value":"15 minutes 50 seconds"},{"label":"17 minutes 30 seconds","value":"17 minutes 30 seconds"},{"label":"16 minutes 20 seconds","value":"16 minutes 20 seconds"},{"label":"16 minutes 40 seconds","value":"16 minutes 40 seconds"}]},{"id":3,"text":"A family drives 234 km in the morning and 178 km 500 m in the afternoon. Total distance?","type":"multiple_choice","correct_answer":"412 km 500 m","explanation":"234,000 + 178,500 = 412,500 m = 412 km 500 m.","standard_code":"4.MD.2","difficulty":3,"options":[{"label":"412 km 400 m","value":"412 km 400 m"},{"label":"413 km 500 m","value":"413 km 500 m"},{"label":"411 km 500 m","value":"411 km 500 m"},{"label":"412 km 500 m","value":"412 km 500 m"}]},{"id":4,"text":"A plumber charges $45 per hour plus $25 for the visit. A job takes 3 hours. What''s the total cost?","type":"multiple_choice","correct_answer":"$160","explanation":"3 × $45 = $135. $135 + $25 = $160.","standard_code":"4.MD.2","difficulty":3,"options":[{"label":"$180","value":"$180"},{"label":"$160","value":"$160"},{"label":"$155","value":"$155"},{"label":"$150","value":"$150"}]},{"id":5,"text":"A train departs at 9:47 AM and arrives at 1:23 PM. How long is the trip?","type":"multiple_choice","correct_answer":"3 hours 36 minutes","explanation":"9:47→12:47 = 3 hrs. 12:47→1:23 = 36 min. Total: 3 hr 36 min.","standard_code":"4.MD.2","difficulty":3,"options":[{"label":"3 hours 23 minutes","value":"3 hours 23 minutes"},{"label":"3 hours 36 minutes","value":"3 hours 36 minutes"},{"label":"2 hours 36 minutes","value":"2 hours 36 minutes"},{"label":"4 hours 36 minutes","value":"4 hours 36 minutes"}]}]'::jsonb);

VALUES (4,'MD','4.MD.3','Apply the area and perimeter formulas for rectangles in real-world problems (Easy)','Practice Apply the area and perimeter formulas for rectangles in real-world problems','practice',1,10,277,'[{"id":1,"text":"Find the perimeter of a rectangle with length 8 cm and width 5 cm.","type":"numeric","correct_answer":"26","explanation":"P = 2(8+5) = 2×13 = 26 cm.","standard_code":"4.MD.3","difficulty":1},{"id":2,"text":"Find the area of a rectangle with length 6 m and width 4 m.","type":"multiple_choice","correct_answer":"24 sq m","explanation":"A = 6 × 4 = 24 square meters.","standard_code":"4.MD.3","difficulty":1,"options":[{"label":"24 sq m","value":"24 sq m"},{"label":"28 sq m","value":"28 sq m"},{"label":"20 sq m","value":"20 sq m"},{"label":"10 sq m","value":"10 sq m"}]},{"id":3,"text":"A square has sides of 7 inches. What is its perimeter?","type":"multiple_choice","correct_answer":"28 inches","explanation":"P = 4 × 7 = 28 inches.","standard_code":"4.MD.3","difficulty":1,"options":[{"label":"21 inches","value":"21 inches"},{"label":"49 inches","value":"49 inches"},{"label":"14 inches","value":"14 inches"},{"label":"28 inches","value":"28 inches"}]},{"id":4,"text":"A square has sides of 9 cm. What is its area?","type":"multiple_choice","correct_answer":"81 sq cm","explanation":"A = 9 × 9 = 81 square centimeters.","standard_code":"4.MD.3","difficulty":1,"options":[{"label":"36 sq cm","value":"36 sq cm"},{"label":"63 sq cm","value":"63 sq cm"},{"label":"81 sq cm","value":"81 sq cm"},{"label":"18 sq cm","value":"18 sq cm"}]},{"id":5,"text":"A garden is 10 feet long and 3 feet wide. What is its area?","type":"multiple_choice","correct_answer":"30 sq ft","explanation":"A = 10 × 3 = 30 square feet.","standard_code":"4.MD.3","difficulty":1,"options":[{"label":"26 sq ft","value":"26 sq ft"},{"label":"13 sq ft","value":"13 sq ft"},{"label":"40 sq ft","value":"40 sq ft"},{"label":"30 sq ft","value":"30 sq ft"}]}]'::jsonb);

VALUES (4,'MD','4.MD.3','Apply the area and perimeter formulas for rectangles in real-world problems (Medium)','Practice Apply the area and perimeter formulas for rectangles in real-world problems','practice',2,15,278,'[{"id":1,"text":"A room is 12 feet by 15 feet. How many square feet of carpet are needed?","type":"multiple_choice","correct_answer":"180 sq ft","explanation":"A = 12 × 15 = 180 square feet.","standard_code":"4.MD.3","difficulty":2,"options":[{"label":"54 sq ft","value":"54 sq ft"},{"label":"180 sq ft","value":"180 sq ft"},{"label":"108 sq ft","value":"108 sq ft"},{"label":"27 sq ft","value":"27 sq ft"}]},{"id":2,"text":"A rectangle has a perimeter of 30 m and a length of 10 m. What is the width?","type":"numeric","correct_answer":"5","explanation":"P = 2(L+W). 30 = 2(10+W). 15 = 10+W. W = 5.","standard_code":"4.MD.3","difficulty":2},{"id":3,"text":"A rectangle has an area of 48 sq cm and a width of 6 cm. What is the length?","type":"numeric","correct_answer":"8","explanation":"A = L×W. 48 = L×6. L = 8.","standard_code":"4.MD.3","difficulty":2},{"id":4,"text":"How much fencing is needed for a 25 m by 18 m rectangular field?","type":"numeric","correct_answer":"86","explanation":"P = 2(25+18) = 2×43 = 86 m.","standard_code":"4.MD.3","difficulty":2},{"id":5,"text":"A rectangle has sides 7 cm and 11 cm. Find both area and perimeter.","type":"multiple_choice","correct_answer":"Area: 77 sq cm, Perimeter: 36 cm","explanation":"A = 7×11 = 77. P = 2(7+11) = 36.","standard_code":"4.MD.3","difficulty":2,"options":[{"label":"Area: 78 sq cm, Perimeter: 36 cm","value":"Area: 78 sq cm, Perimeter: 36 cm"},{"label":"Area: 77 sq cm, Perimeter: 36 cm","value":"Area: 77 sq cm, Perimeter: 36 cm"},{"label":"Area: 77 sq cm, Perimeter: 18 cm","value":"Area: 77 sq cm, Perimeter: 18 cm"},{"label":"Area: 39 sq cm, Perimeter: 36 cm","value":"Area: 39 sq cm, Perimeter: 36 cm"}]}]'::jsonb);

VALUES (4,'MD','4.MD.3','Apply the area and perimeter formulas for rectangles in real-world problems (Hard)','Practice Apply the area and perimeter formulas for rectangles in real-world problems','practice',3,20,279,'[{"id":1,"text":"A rectangle has a perimeter of 50 cm. Its length is 3 times its width. Find the dimensions.","type":"multiple_choice","correct_answer":"Width: 6.25 cm, Length: 18.75 cm","explanation":"2(3w+w)=50. 8w=50. w=6.25. L=18.75.","standard_code":"4.MD.3","difficulty":3,"options":[{"label":"Width: 8.33 cm, Length: 25 cm","value":"Width: 8.33 cm, Length: 25 cm"},{"label":"Width: 5 cm, Length: 20 cm","value":"Width: 5 cm, Length: 20 cm"},{"label":"Width: 12.5 cm, Length: 12.5 cm","value":"Width: 12.5 cm, Length: 12.5 cm"},{"label":"Width: 6.25 cm, Length: 18.75 cm","value":"Width: 6.25 cm, Length: 18.75 cm"}]},{"id":2,"text":"Two rooms are 15×12 ft and 10×8 ft. What is the total area of carpet needed?","type":"multiple_choice","correct_answer":"260 sq ft","explanation":"15×12=180. 10×8=80. 180+80=260.","standard_code":"4.MD.3","difficulty":3,"options":[{"label":"230 sq ft","value":"230 sq ft"},{"label":"180 sq ft","value":"180 sq ft"},{"label":"260 sq ft","value":"260 sq ft"},{"label":"150 sq ft","value":"150 sq ft"}]},{"id":3,"text":"A pool is 25 m long and 10 m wide. A 2 m wide walkway surrounds it. What is the area of the walkway?","type":"multiple_choice","correct_answer":"168 sq m","explanation":"Outer: 29×14=406. Inner: 25×10=250. Walkway: 406−250=156. Wait: outer is (25+4)×(10+4)=29×14=406. 406−250=156 sq m.","standard_code":"4.MD.3","difficulty":3,"options":[{"label":"196 sq m","value":"196 sq m"},{"label":"250 sq m","value":"250 sq m"},{"label":"168 sq m","value":"168 sq m"},{"label":"120 sq m","value":"120 sq m"}]},{"id":4,"text":"A farmer has 60 m of fencing. What dimensions give the largest rectangular area?","type":"multiple_choice","correct_answer":"15 m × 15 m = 225 sq m","explanation":"Max area of a rectangle with fixed perimeter is a square. 60÷4=15. A=15×15=225.","standard_code":"4.MD.3","difficulty":3,"options":[{"label":"20 m × 10 m = 200 sq m","value":"20 m × 10 m = 200 sq m"},{"label":"18 m × 12 m = 216 sq m","value":"18 m × 12 m = 216 sq m"},{"label":"15 m × 15 m = 225 sq m","value":"15 m × 15 m = 225 sq m"},{"label":"12 m × 12 m = 144 sq m","value":"12 m × 12 m = 144 sq m"}]},{"id":5,"text":"A rectangular yard has area 600 sq ft and width 20 ft. How much fencing is needed to surround it?","type":"numeric","correct_answer":"100","explanation":"L = 600÷20 = 30. P = 2(30+20) = 100 ft.","standard_code":"4.MD.3","difficulty":3}]'::jsonb);

VALUES (4,'MD','4.MD.4','Make a line plot to display a data set of measurements in fractions of a unit (Easy)','Practice Make a line plot to display a data set of measurements in fractions of a unit','practice',1,10,280,'[{"id":1,"text":"Students measured ribbons: 1/4, 1/2, 1/4, 3/4, 1/2. How many measured 1/2 inch?","type":"multiple_choice","correct_answer":"2 ribbons","explanation":"Count 1/2 in the list: appears twice.","standard_code":"4.MD.4","difficulty":1,"options":[{"label":"1 ribbon","value":"1 ribbon"},{"label":"4 ribbons","value":"4 ribbons"},{"label":"2 ribbons","value":"2 ribbons"},{"label":"3 ribbons","value":"3 ribbons"}]},{"id":2,"text":"A line plot shows 3 X''s above 1/4, 2 X''s above 1/2, and 1 X above 3/4. How many data points total?","type":"numeric","correct_answer":"6","explanation":"3 + 2 + 1 = 6 data points.","standard_code":"4.MD.4","difficulty":1},{"id":3,"text":"On a line plot, which value has the most X''s: 1/8(2), 3/8(4), 5/8(1)?","type":"numeric","correct_answer":"3/8","explanation":"3/8 has 4 X''s, which is the most.","standard_code":"4.MD.4","difficulty":1},{"id":4,"text":"What is the difference between the longest and shortest ribbons: 1/4, 1/2, 3/4 inches?","type":"multiple_choice","correct_answer":"1/2 inch","explanation":"3/4 − 1/4 = 2/4 = 1/2 inch.","standard_code":"4.MD.4","difficulty":1,"options":[{"label":"1/4 inch","value":"1/4 inch"},{"label":"1 inch","value":"1 inch"},{"label":"1/2 inch","value":"1/2 inch"},{"label":"3/4 inch","value":"3/4 inch"}]},{"id":5,"text":"Data: 1/2, 1/2, 1, 1/2, 1. How many pieces measure 1/2?","type":"multiple_choice","correct_answer":"3 pieces","explanation":"1/2 appears 3 times.","standard_code":"4.MD.4","difficulty":1,"options":[{"label":"5 pieces","value":"5 pieces"},{"label":"3 pieces","value":"3 pieces"},{"label":"4 pieces","value":"4 pieces"},{"label":"2 pieces","value":"2 pieces"}]}]'::jsonb);

VALUES (4,'MD','4.MD.4','Make a line plot to display a data set of measurements in fractions of a unit (Medium)','Practice Make a line plot to display a data set of measurements in fractions of a unit','practice',2,15,281,'[{"id":1,"text":"Caterpillar lengths (inches): 3/8, 5/8, 3/8, 7/8, 5/8, 3/8. What is the most common length?","type":"multiple_choice","correct_answer":"3/8 inch (3 times)","explanation":"3/8 appears 3 times, more than any other.","standard_code":"4.MD.4","difficulty":2,"options":[{"label":"3/8 inch (2 times)","value":"3/8 inch (2 times)"},{"label":"3/8 inch (3 times)","value":"3/8 inch (3 times)"},{"label":"5/8 inch (2 times)","value":"5/8 inch (2 times)"},{"label":"7/8 inch (2 times)","value":"7/8 inch (2 times)"}]},{"id":2,"text":"A line plot shows plant heights: 2 at 1/4 in, 4 at 1/2 in, 3 at 3/4 in. What is the total of all heights?","type":"multiple_choice","correct_answer":"4 3/4 inches","explanation":"2(1/4)+4(1/2)+3(3/4) = 2/4+8/4+9/4 = 19/4 = 4 3/4.","standard_code":"4.MD.4","difficulty":2,"options":[{"label":"5 inches","value":"5 inches"},{"label":"4 1/4 inches","value":"4 1/4 inches"},{"label":"5 1/2 inches","value":"5 1/2 inches"},{"label":"4 3/4 inches","value":"4 3/4 inches"}]},{"id":3,"text":"Pencil lengths: 5 1/2, 6, 5 1/2, 6 1/2, 6, 6, 5 1/2. What length appears most?","type":"multiple_choice","correct_answer":"5 1/2 and 6 (tied at 3 each)","explanation":"5 1/2 appears 3 times, 6 appears 3 times, 6 1/2 once.","standard_code":"4.MD.4","difficulty":2,"options":[{"label":"6 inches (3 times)","value":"6 inches (3 times)"},{"label":"5 1/2 and 5 3/4 (tied)","value":"5 1/2 and 5 3/4 (tied)"},{"label":"5 1/2 and 6 (tied at 3 each)","value":"5 1/2 and 6 (tied at 3 each)"},{"label":"6 1/2 inches (2 times)","value":"6 1/2 inches (2 times)"}]},{"id":4,"text":"From a line plot: 1/4(3), 2/4(5), 3/4(2). How much longer is the longest than shortest?","type":"multiple_choice","correct_answer":"2/4 = 1/2","explanation":"3/4 − 1/4 = 2/4 = 1/2.","standard_code":"4.MD.4","difficulty":2,"options":[{"label":"2/4 = 1/2","value":"2/4 = 1/2"},{"label":"1/4","value":"1/4"},{"label":"3/4","value":"3/4"},{"label":"1","value":"1"}]},{"id":5,"text":"Data: 1/8, 3/8, 3/8, 5/8, 7/8. Find the sum of all measurements.","type":"multiple_choice","correct_answer":"19/8 = 2 3/8","explanation":"1+3+3+5+7=19 eighths = 19/8 = 2 3/8.","standard_code":"4.MD.4","difficulty":2,"options":[{"label":"18/8 = 2 1/4","value":"18/8 = 2 1/4"},{"label":"19/8 = 2 3/8","value":"19/8 = 2 3/8"},{"label":"20/8 = 2 1/2","value":"20/8 = 2 1/2"},{"label":"21/8 = 2 5/8","value":"21/8 = 2 5/8"}]}]'::jsonb);

VALUES (4,'MD','4.MD.4','Make a line plot to display a data set of measurements in fractions of a unit (Hard)','Practice Make a line plot to display a data set of measurements in fractions of a unit','practice',3,20,282,'[{"id":1,"text":"Ant lengths: 1/4(2), 3/8(3), 1/2(4), 5/8(1). Find the total length if all ants were placed end to end.","type":"multiple_choice","correct_answer":"4 3/8 inches","explanation":"2(1/4)+3(3/8)+4(1/2)+1(5/8) = 4/8+9/8+16/8+5/8 = 34/8 = 4 2/8 = 4 1/4. Let me recalculate: 2(2/8)+3(3/8)+4(4/8)+1(5/8) = 4/8+9/8+16/8+5/8 = 34/8 = 4 2/8 = 4 1/4 inches.","standard_code":"4.MD.4","difficulty":3,"options":[{"label":"4 3/8 inches","value":"4 3/8 inches"},{"label":"5 1/4 inches","value":"5 1/4 inches"},{"label":"3 1/2 inches","value":"3 1/2 inches"},{"label":"4 1/2 inches","value":"4 1/2 inches"}]},{"id":2,"text":"Eight students measured worms. Results: 3/4, 1/2, 5/8, 3/4, 7/8, 1/2, 3/4, 5/8. What fraction of students found worms 3/4 inch or longer?","type":"multiple_choice","correct_answer":"4/8 = 1/2","explanation":"3/4 or longer: 3/4(3 times) + 7/8(1 time) = 4 out of 8 = 1/2.","standard_code":"4.MD.4","difficulty":3,"options":[{"label":"3/8","value":"3/8"},{"label":"6/8 = 3/4","value":"6/8 = 3/4"},{"label":"4/8 = 1/2","value":"4/8 = 1/2"},{"label":"5/8","value":"5/8"}]},{"id":3,"text":"Rainfall over 5 days (inches): 1/4, 0, 3/4, 1/2, 1/4. What was the average daily rainfall?","type":"multiple_choice","correct_answer":"7/20 inch","explanation":"Sum: 1/4+3/4+1/2+1/4 = 7/4. Average: (7/4)÷5 = 7/20.","standard_code":"4.MD.4","difficulty":3,"options":[{"label":"7/20 inch","value":"7/20 inch"},{"label":"9/20 inch","value":"9/20 inch"},{"label":"1/4 inch","value":"1/4 inch"},{"label":"2/5 inch","value":"2/5 inch"}]},{"id":4,"text":"How much more rain fell on the rainiest day vs. least rainy day (above)?","type":"multiple_choice","correct_answer":"3/4 inch","explanation":"Rainiest: 3/4. Least (excluding 0): 1/4. Difference: 3/4−1/4 = 1/2. Including 0: 3/4−0=3/4.","standard_code":"4.MD.4","difficulty":3,"options":[{"label":"1/2 inch","value":"1/2 inch"},{"label":"3/4 inch","value":"3/4 inch"},{"label":"1/4 inch","value":"1/4 inch"},{"label":"7/8 inch","value":"7/8 inch"}]},{"id":5,"text":"Seed lengths: 3/16(4), 5/16(3), 7/16(5), 9/16(2). What is the combined length of all seeds?","type":"multiple_choice","correct_answer":"78/16 = 4 14/16 = 4 7/8 inches","explanation":"4(3)+3(5)+5(7)+2(9) = 12+15+35+18 = 80 sixteenths = 80/16 = 5. Recalculating: 12+15+35+18=80. 80/16=5 inches.","standard_code":"4.MD.4","difficulty":3,"options":[{"label":"82/16 = 5 2/16 inches","value":"82/16 = 5 2/16 inches"},{"label":"80/16 = 5 inches","value":"80/16 = 5 inches"},{"label":"75/16 = 4 11/16 inches","value":"75/16 = 4 11/16 inches"},{"label":"78/16 = 4 14/16 = 4 7/8 inches","value":"78/16 = 4 14/16 = 4 7/8 inches"}]}]'::jsonb);

VALUES (4,'MD','4.MD.5','Recognize angles as geometric shapes formed wherever two rays share a common endpoint (Easy)','Practice Recognize angles as geometric shapes formed wherever two rays share a common endpoint','practice',1,10,283,'[{"id":1,"text":"What is an angle?","type":"multiple_choice","correct_answer":"Two rays sharing a common endpoint (vertex)","explanation":"An angle is formed by two rays that start at the same point, called the vertex.","standard_code":"4.MD.5","difficulty":1,"options":[{"label":"The measurement of how wide something is","value":"The measurement of how wide something is"},{"label":"A line that bends at a point","value":"A line that bends at a point"},{"label":"The space between two parallel lines","value":"The space between two parallel lines"},{"label":"Two rays sharing a common endpoint (vertex)","value":"Two rays sharing a common endpoint (vertex)"}]},{"id":2,"text":"How many degrees are in a right angle?","type":"numeric","correct_answer":"90","explanation":"A right angle measures exactly 90 degrees.","standard_code":"4.MD.5","difficulty":1},{"id":3,"text":"How many degrees are in a full turn (circle)?","type":"numeric","correct_answer":"360","explanation":"A full rotation around a point is 360 degrees.","standard_code":"4.MD.5","difficulty":1},{"id":4,"text":"What fraction of a circle is a right angle?","type":"numeric","correct_answer":"1/4","explanation":"90/360 = 1/4 of a full turn.","standard_code":"4.MD.5","difficulty":1},{"id":5,"text":"An angle that turns through 1/360 of a circle is how many degrees?","type":"numeric","correct_answer":"1","explanation":"By definition, 1 degree = 1/360 of a full turn.","standard_code":"4.MD.5","difficulty":1}]'::jsonb);

VALUES (4,'MD','4.MD.5','Recognize angles as geometric shapes formed wherever two rays share a common endpoint (Medium)','Practice Recognize angles as geometric shapes formed wherever two rays share a common endpoint','practice',2,15,284,'[{"id":1,"text":"How many degrees is half a circle?","type":"numeric","correct_answer":"180","explanation":"360 ÷ 2 = 180°. This is called a straight angle.","standard_code":"4.MD.5","difficulty":2},{"id":2,"text":"An angle is 3/4 of a full turn. How many degrees?","type":"numeric","correct_answer":"270","explanation":"3/4 × 360 = 270°.","standard_code":"4.MD.5","difficulty":2},{"id":3,"text":"A clock''s minute hand moves from 12 to 3. How many degrees did it turn?","type":"numeric","correct_answer":"90","explanation":"12 to 3 is 1/4 of the clock face. 1/4 × 360 = 90°.","standard_code":"4.MD.5","difficulty":2},{"id":4,"text":"Is a 45° angle greater or less than a right angle?","type":"multiple_choice","correct_answer":"Less than a right angle","explanation":"45° < 90°. A 45° angle is half of a right angle.","standard_code":"4.MD.5","difficulty":2,"options":[{"label":"Cannot be compared to a right angle","value":"Cannot be compared to a right angle"},{"label":"Greater than a right angle","value":"Greater than a right angle"},{"label":"Less than a right angle","value":"Less than a right angle"},{"label":"Equal to a right angle","value":"Equal to a right angle"}]},{"id":5,"text":"How many right angles make a straight angle (180°)?","type":"multiple_choice","correct_answer":"2 right angles","explanation":"2 × 90° = 180°.","standard_code":"4.MD.5","difficulty":2,"options":[{"label":"3 right angles","value":"3 right angles"},{"label":"4 right angles","value":"4 right angles"},{"label":"1 right angle","value":"1 right angle"},{"label":"2 right angles","value":"2 right angles"}]}]'::jsonb);

VALUES (4,'MD','4.MD.5','Recognize angles as geometric shapes formed wherever two rays share a common endpoint (Hard)','Practice Recognize angles as geometric shapes formed wherever two rays share a common endpoint','practice',3,20,285,'[{"id":1,"text":"A clock''s minute hand moves from 12 to 8. How many degrees did it turn?","type":"numeric","correct_answer":"240","explanation":"12 to 8 = 8 hours on the clock = 8/12 of a turn = 2/3 × 360 = 240°.","standard_code":"4.MD.5","difficulty":3},{"id":2,"text":"If you face north and turn clockwise to face south, how many degrees did you turn?","type":"numeric","correct_answer":"180","explanation":"North to south is a half turn = 180°.","standard_code":"4.MD.5","difficulty":3},{"id":3,"text":"A pizza is cut into 8 equal slices. What angle does each slice form at the center?","type":"numeric","correct_answer":"45","explanation":"360 ÷ 8 = 45° per slice.","standard_code":"4.MD.5","difficulty":3},{"id":4,"text":"How many 30° angles fit in a straight angle?","type":"multiple_choice","correct_answer":"6 angles","explanation":"180 ÷ 30 = 6.","standard_code":"4.MD.5","difficulty":3,"options":[{"label":"8 angles","value":"8 angles"},{"label":"12 angles","value":"12 angles"},{"label":"6 angles","value":"6 angles"},{"label":"4 angles","value":"4 angles"}]},{"id":5,"text":"A wheel turns 5/6 of a full rotation. How many degrees is that?","type":"numeric","correct_answer":"300","explanation":"5/6 × 360 = 300°.","standard_code":"4.MD.5","difficulty":3}]'::jsonb);

VALUES (4,'MD','4.MD.6','Measure angles in whole-number degrees using a protractor (Easy)','Practice Measure angles in whole-number degrees using a protractor','practice',1,10,286,'[{"id":1,"text":"A protractor shows an angle measuring 45°. Is this acute, right, or obtuse?","type":"multiple_choice","correct_answer":"Acute","explanation":"45° < 90°, so it''s an acute angle.","standard_code":"4.MD.6","difficulty":1,"options":[{"label":"Obtuse","value":"Obtuse"},{"label":"Straight","value":"Straight"},{"label":"Right","value":"Right"},{"label":"Acute","value":"Acute"}]},{"id":2,"text":"An angle measures 90°. What type of angle is it?","type":"multiple_choice","correct_answer":"Right angle","explanation":"Exactly 90° = right angle.","standard_code":"4.MD.6","difficulty":1,"options":[{"label":"Right angle","value":"Right angle"},{"label":"Obtuse angle","value":"Obtuse angle"},{"label":"Straight angle","value":"Straight angle"},{"label":"Acute angle","value":"Acute angle"}]},{"id":3,"text":"An angle measures 120°. Is it acute, right, or obtuse?","type":"multiple_choice","correct_answer":"Obtuse","explanation":"120° > 90° but < 180°, so it''s obtuse.","standard_code":"4.MD.6","difficulty":1,"options":[{"label":"Acute","value":"Acute"},{"label":"Right","value":"Right"},{"label":"Straight","value":"Straight"},{"label":"Obtuse","value":"Obtuse"}]},{"id":4,"text":"Which is larger: a 60° angle or a 75° angle?","type":"multiple_choice","correct_answer":"75° angle","explanation":"75 > 60, so the 75° angle is larger.","standard_code":"4.MD.6","difficulty":1,"options":[{"label":"75° angle","value":"75° angle"},{"label":"They are equal","value":"They are equal"},{"label":"Cannot be compared","value":"Cannot be compared"},{"label":"60° angle","value":"60° angle"}]},{"id":5,"text":"What type of angle is 180°?","type":"multiple_choice","correct_answer":"Straight angle","explanation":"180° forms a straight line.","standard_code":"4.MD.6","difficulty":1,"options":[{"label":"Straight angle","value":"Straight angle"},{"label":"Right angle","value":"Right angle"},{"label":"Reflex angle","value":"Reflex angle"},{"label":"Acute angle","value":"Acute angle"}]}]'::jsonb);

VALUES (4,'MD','4.MD.6','Measure angles in whole-number degrees using a protractor (Medium)','Practice Measure angles in whole-number degrees using a protractor','practice',2,15,287,'[{"id":1,"text":"An angle measures 135°. Is it closer to a right angle or a straight angle?","type":"multiple_choice","correct_answer":"Closer to a straight angle","explanation":"|135−90|=45 and |135−180|=45. It''s equidistant, but since 135>90 it''s obtuse and closer to 180.","standard_code":"4.MD.6","difficulty":2,"options":[{"label":"Exactly between them","value":"Exactly between them"},{"label":"Closer to a straight angle","value":"Closer to a straight angle"},{"label":"Closer to neither one","value":"Closer to neither one"},{"label":"Closer to a right angle","value":"Closer to a right angle"}]},{"id":2,"text":"A triangle has angles of 60° and 80°. What is the third angle?","type":"numeric","correct_answer":"40","explanation":"180 − 60 − 80 = 40°. Triangle angles sum to 180°.","standard_code":"4.MD.6","difficulty":2},{"id":3,"text":"Two angles together form a right angle. One is 35°. What is the other?","type":"numeric","correct_answer":"55","explanation":"90 − 35 = 55°.","standard_code":"4.MD.6","difficulty":2},{"id":4,"text":"Classify these angles: 15°, 90°, 110°, 175°.","type":"multiple_choice","correct_answer":"Acute, right, obtuse, obtuse","explanation":"15°<90(acute), 90°(right), 110°>90(obtuse), 175°>90(obtuse).","standard_code":"4.MD.6","difficulty":2,"options":[{"label":"Acute, right, right, acute","value":"Acute, right, right, acute"},{"label":"Right, right, obtuse, obtuse","value":"Right, right, obtuse, obtuse"},{"label":"Acute, acute, obtuse, straight","value":"Acute, acute, obtuse, straight"},{"label":"Acute, right, obtuse, obtuse","value":"Acute, right, obtuse, obtuse"}]},{"id":5,"text":"How many degrees larger is an obtuse angle of 140° than an acute angle of 50°?","type":"numeric","correct_answer":"90","explanation":"140 − 50 = 90°.","standard_code":"4.MD.6","difficulty":2}]'::jsonb);

VALUES (4,'MD','4.MD.6','Measure angles in whole-number degrees using a protractor (Hard)','Practice Measure angles in whole-number degrees using a protractor','practice',3,20,288,'[{"id":1,"text":"A quadrilateral has angles 85°, 95°, and 110°. What is the fourth angle?","type":"numeric","correct_answer":"70","explanation":"Quadrilateral angles sum to 360°. 360−85−95−110 = 70°.","standard_code":"4.MD.6","difficulty":3},{"id":2,"text":"Two angles are supplementary. One is 63°. What is the other?","type":"numeric","correct_answer":"117","explanation":"Supplementary angles sum to 180°. 180−63=117°.","standard_code":"4.MD.6","difficulty":3},{"id":3,"text":"Two angles are complementary. One is 28°. What is the other?","type":"numeric","correct_answer":"62","explanation":"Complementary angles sum to 90°. 90−28=62°.","standard_code":"4.MD.6","difficulty":3},{"id":4,"text":"A regular hexagon has 6 equal angles. What is each interior angle?","type":"numeric","correct_answer":"120","explanation":"Sum of interior angles = (6−2)×180 = 720°. Each = 720÷6 = 120°.","standard_code":"4.MD.6","difficulty":3},{"id":5,"text":"If you draw both diagonals of a square, what angles do they form at the center?","type":"multiple_choice","correct_answer":"Four 90° angles","explanation":"Diagonals of a square bisect each other at right angles, creating four 90° angles.","standard_code":"4.MD.6","difficulty":3,"options":[{"label":"Four 180° angles","value":"Four 180° angles"},{"label":"Eight 45° angles","value":"Eight 45° angles"},{"label":"Two 45° angles","value":"Two 45° angles"},{"label":"Four 90° angles","value":"Four 90° angles"}]}]'::jsonb);

VALUES (4,'MD','4.MD.7','Recognize angle measure as additive; solve addition and subtraction problems to find unknown angles (Easy)','Practice Recognize angle measure as additive; solve addition and subtraction problems to find unknown angles','practice',1,10,289,'[{"id":1,"text":"Two angles share a side. One is 30° and the other is 50°. What is the total angle?","type":"numeric","correct_answer":"80","explanation":"30 + 50 = 80°. Adjacent angles add up.","standard_code":"4.MD.7","difficulty":1},{"id":2,"text":"An angle is split into 40° and 25°. What is the whole angle?","type":"numeric","correct_answer":"65","explanation":"40 + 25 = 65°.","standard_code":"4.MD.7","difficulty":1},{"id":3,"text":"A right angle is split into two parts. One part is 60°. What is the other?","type":"numeric","correct_answer":"30","explanation":"90 − 60 = 30°.","standard_code":"4.MD.7","difficulty":1},{"id":4,"text":"Two angles form a straight line. One is 110°. What is the other?","type":"numeric","correct_answer":"70","explanation":"180 − 110 = 70°.","standard_code":"4.MD.7","difficulty":1},{"id":5,"text":"Three angles meet at a point on a line: 45°, 85°, and x°. Find x.","type":"numeric","correct_answer":"50","explanation":"45 + 85 + x = 180. 130 + x = 180. x = 50°.","standard_code":"4.MD.7","difficulty":1}]'::jsonb);

VALUES (4,'MD','4.MD.7','Recognize angle measure as additive; solve addition and subtraction problems to find unknown angles (Medium)','Practice Recognize angle measure as additive; solve addition and subtraction problems to find unknown angles','practice',2,15,290,'[{"id":1,"text":"Angle ABC = 125°. Ray BD splits it into angle ABD = 75° and angle DBC. Find angle DBC.","type":"numeric","correct_answer":"50","explanation":"125 − 75 = 50°.","standard_code":"4.MD.7","difficulty":2},{"id":2,"text":"Two angles form a right angle. One is (x + 10)° and the other is 50°. Find x.","type":"numeric","correct_answer":"30","explanation":"(x+10) + 50 = 90. x + 60 = 90. x = 30.","standard_code":"4.MD.7","difficulty":2},{"id":3,"text":"Three angles at a point on a line measure 55°, 65°, and n°. Find n.","type":"numeric","correct_answer":"60","explanation":"55 + 65 + n = 180. 120 + n = 180. n = 60°.","standard_code":"4.MD.7","difficulty":2},{"id":4,"text":"A full turn is divided into 4 angles: 90°, 90°, 85°, and x°. Find x.","type":"numeric","correct_answer":"95","explanation":"90+90+85+x = 360. 265+x=360. x=95°.","standard_code":"4.MD.7","difficulty":2},{"id":5,"text":"An angle of 150° is split into 3 equal parts. What is each part?","type":"numeric","correct_answer":"50","explanation":"150 ÷ 3 = 50° each.","standard_code":"4.MD.7","difficulty":2}]'::jsonb);

VALUES (4,'MD','4.MD.7','Recognize angle measure as additive; solve addition and subtraction problems to find unknown angles (Hard)','Practice Recognize angle measure as additive; solve addition and subtraction problems to find unknown angles','practice',3,20,291,'[{"id":1,"text":"Angles around a point: 120°, 85°, x°, and 70°. Find x.","type":"numeric","correct_answer":"85","explanation":"120+85+x+70=360. 275+x=360. x=85°.","standard_code":"4.MD.7","difficulty":3},{"id":2,"text":"Two supplementary angles are in the ratio 2:3. Find both angles.","type":"multiple_choice","correct_answer":"72° and 108°","explanation":"2x + 3x = 180. 5x = 180. x = 36. Angles: 72° and 108°.","standard_code":"4.MD.7","difficulty":3,"options":[{"label":"72° and 108°","value":"72° and 108°"},{"label":"75° and 105°","value":"75° and 105°"},{"label":"70° and 110°","value":"70° and 110°"},{"label":"80° and 100°","value":"80° and 100°"}]},{"id":3,"text":"Angle PQR = 160°. Point S is inside so that angle PQS = 3x° and angle SQR = 2x°. Find x and both angles.","type":"multiple_choice","correct_answer":"x = 32; angles are 96° and 64°","explanation":"3x + 2x = 160. 5x = 160. x = 32. PQS=96°, SQR=64°.","standard_code":"4.MD.7","difficulty":3,"options":[{"label":"x = 28; angles are 84° and 76°","value":"x = 28; angles are 84° and 76°"},{"label":"x = 35; angles are 105° and 70°","value":"x = 35; angles are 105° and 70°"},{"label":"x = 30; angles are 90° and 60°","value":"x = 30; angles are 90° and 60°"},{"label":"x = 32; angles are 96° and 64°","value":"x = 32; angles are 96° and 64°"}]},{"id":4,"text":"Two complementary angles differ by 20°. Find both.","type":"multiple_choice","correct_answer":"35° and 55°","explanation":"x + (x+20) = 90. 2x + 20 = 90. 2x = 70. x = 35. Other = 55°.","standard_code":"4.MD.7","difficulty":3,"options":[{"label":"25° and 65°","value":"25° and 65°"},{"label":"30° and 50°","value":"30° and 50°"},{"label":"35° and 55°","value":"35° and 55°"},{"label":"40° and 60°","value":"40° and 60°"}]},{"id":5,"text":"Five angles around a point: 60°, 75°, 80°, 55°, and y°. Find y.","type":"numeric","correct_answer":"90","explanation":"60+75+80+55+y = 360. 270+y=360. y=90°.","standard_code":"4.MD.7","difficulty":3}]'::jsonb);

VALUES (4,'G','4.G.1','Draw and identify points, lines, line segments, rays, angles, and perpendicular and parallel lines (Easy)','Practice Draw and identify points, lines, line segments, rays, angles, and perpendicular and parallel lines','practice',1,10,292,'[{"id":1,"text":"What is the difference between a line and a line segment?","type":"multiple_choice","correct_answer":"A line goes on forever in both directions; a line segment has two endpoints","explanation":"A line has no endpoints and extends infinitely. A line segment has two defined endpoints.","standard_code":"4.G.1","difficulty":1,"options":[{"label":"A line is curved; a line segment is straight","value":"A line is curved; a line segment is straight"},{"label":"A line has a starting point; a line segment goes on forever","value":"A line has a starting point; a line segment goes on forever"},{"label":"A line goes on forever in both directions; a line segment has two endpoints","value":"A line goes on forever in both directions; a line segment has two endpoints"},{"label":"A line is shorter; a line segment is longer","value":"A line is shorter; a line segment is longer"}]},{"id":2,"text":"What is a ray?","type":"multiple_choice","correct_answer":"A part of a line with one endpoint that extends infinitely in one direction","explanation":"A ray starts at a point and goes on forever in one direction.","standard_code":"4.G.1","difficulty":1,"options":[{"label":"A line segment with two endpoints that extends in one direction","value":"A line segment with two endpoints that extends in one direction"},{"label":"A part of a line with one endpoint that extends infinitely in one direction","value":"A part of a line with one endpoint that extends infinitely in one direction"},{"label":"A part of a line with one endpoint that stops at a definite point","value":"A part of a line with one endpoint that stops at a definite point"},{"label":"A straight path that goes on forever in both directions","value":"A straight path that goes on forever in both directions"}]},{"id":3,"text":"Do parallel lines ever cross?","type":"multiple_choice","correct_answer":"No","explanation":"Parallel lines are always the same distance apart and never intersect.","standard_code":"4.G.1","difficulty":1,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]},{"id":4,"text":"What do we call two lines that cross at a 90° angle?","type":"multiple_choice","correct_answer":"Perpendicular lines","explanation":"Perpendicular lines intersect forming right angles (90°).","standard_code":"4.G.1","difficulty":1,"options":[{"label":"Parallel lines","value":"Parallel lines"},{"label":"Intersecting lines","value":"Intersecting lines"},{"label":"Acute lines","value":"Acute lines"},{"label":"Perpendicular lines","value":"Perpendicular lines"}]},{"id":5,"text":"Name a real-world example of parallel lines.","type":"multiple_choice","correct_answer":"Railroad tracks (or similar)","explanation":"Railroad tracks, edges of a ruler, or opposite sides of a door are parallel.","standard_code":"4.G.1","difficulty":1,"options":[{"label":"Railroad tracks (or similar)","value":"Railroad tracks (or similar)"},{"label":"The sides of a triangle","value":"The sides of a triangle"},{"label":"The edges of a table top","value":"The edges of a table top"},{"label":"The blades of an open scissors","value":"The blades of an open scissors"}]}]'::jsonb);

VALUES (4,'G','4.G.1','Draw and identify points, lines, line segments, rays, angles, and perpendicular and parallel lines (Medium)','Practice Draw and identify points, lines, line segments, rays, angles, and perpendicular and parallel lines','practice',2,15,293,'[{"id":1,"text":"How many line segments does a triangle have?","type":"numeric","correct_answer":"3","explanation":"A triangle is made of 3 line segments (sides).","standard_code":"4.G.1","difficulty":2},{"id":2,"text":"Can two rays form an angle? Explain.","type":"multiple_choice","correct_answer":"Yes, if they share a common endpoint","explanation":"Two rays with the same endpoint (vertex) form an angle.","standard_code":"4.G.1","difficulty":2,"options":[{"label":"No, rays cannot form angles because they extend infinitely","value":"No, rays cannot form angles because they extend infinitely"},{"label":"Yes, only if they share two endpoints","value":"Yes, only if they share two endpoints"},{"label":"Yes, if they share a common endpoint","value":"Yes, if they share a common endpoint"},{"label":"Yes, if one ray is longer than the other","value":"Yes, if one ray is longer than the other"}]},{"id":3,"text":"In the letter H, identify a pair of parallel line segments and a perpendicular one.","type":"multiple_choice","correct_answer":"The two vertical lines are parallel; the horizontal bar is perpendicular to both","explanation":"The uprights of H are parallel. The crossbar meets them at right angles.","standard_code":"4.G.1","difficulty":2,"options":[{"label":"The two vertical lines are parallel; the horizontal bar is perpendicular to both","value":"The two vertical lines are parallel; the horizontal bar is perpendicular to both"},{"label":"The two vertical lines are perpendicular; the horizontal bar is parallel to both","value":"The two vertical lines are perpendicular; the horizontal bar is parallel to both"},{"label":"All three lines are parallel to each other","value":"All three lines are parallel to each other"},{"label":"The two horizontal lines are parallel; the vertical bar is perpendicular to both","value":"The two horizontal lines are parallel; the vertical bar is perpendicular to both"}]},{"id":4,"text":"Are the opposite sides of a rectangle parallel, perpendicular, or both?","type":"multiple_choice","correct_answer":"Opposite sides are parallel; adjacent sides are perpendicular","explanation":"A rectangle has 2 pairs of parallel sides and 4 right angles.","standard_code":"4.G.1","difficulty":2,"options":[{"label":"Opposite sides are perpendicular; adjacent sides are parallel","value":"Opposite sides are perpendicular; adjacent sides are parallel"},{"label":"Opposite sides are parallel; adjacent sides are perpendicular","value":"Opposite sides are parallel; adjacent sides are perpendicular"},{"label":"All sides are parallel to each other","value":"All sides are parallel to each other"},{"label":"All sides are perpendicular","value":"All sides are perpendicular"}]},{"id":5,"text":"How many right angles are formed when two perpendicular lines cross?","type":"multiple_choice","correct_answer":"4 right angles","explanation":"Two perpendicular lines create 4 angles of 90° each.","standard_code":"4.G.1","difficulty":2,"options":[{"label":"6 right angles","value":"6 right angles"},{"label":"4 right angles","value":"4 right angles"},{"label":"8 right angles","value":"8 right angles"},{"label":"2 right angles","value":"2 right angles"}]}]'::jsonb);

VALUES (4,'G','4.G.1','Draw and identify points, lines, line segments, rays, angles, and perpendicular and parallel lines (Hard)','Practice Draw and identify points, lines, line segments, rays, angles, and perpendicular and parallel lines','practice',3,20,294,'[{"id":1,"text":"Draw a shape that has exactly one pair of parallel sides. What is it called?","type":"multiple_choice","correct_answer":"A trapezoid","explanation":"A trapezoid (or trapezium) has exactly one pair of parallel sides.","standard_code":"4.G.1","difficulty":3,"options":[{"label":"A parallelogram","value":"A parallelogram"},{"label":"A kite","value":"A kite"},{"label":"A trapezoid","value":"A trapezoid"},{"label":"A pentagon","value":"A pentagon"}]},{"id":2,"text":"Can a triangle have a pair of parallel sides? Why or why not?","type":"multiple_choice","correct_answer":"No","explanation":"If two sides were parallel, they would never meet, but a triangle requires all three sides to connect.","standard_code":"4.G.1","difficulty":3,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]},{"id":3,"text":"A figure has 4 sides, 2 pairs of parallel sides, but no right angles. What could it be?","type":"multiple_choice","correct_answer":"A parallelogram (non-rectangular, like a rhombus)","explanation":"A parallelogram has 2 pairs of parallel sides. Without right angles, it''s not a rectangle.","standard_code":"4.G.1","difficulty":3,"options":[{"label":"A square","value":"A square"},{"label":"A trapezoid","value":"A trapezoid"},{"label":"A parallelogram (non-rectangular, like a rhombus)","value":"A parallelogram (non-rectangular, like a rhombus)"},{"label":"A kite","value":"A kite"}]},{"id":4,"text":"In a regular hexagon, how many pairs of parallel sides are there?","type":"multiple_choice","correct_answer":"3 pairs","explanation":"A regular hexagon has 3 pairs of opposite parallel sides.","standard_code":"4.G.1","difficulty":3,"options":[{"label":"6 pairs","value":"6 pairs"},{"label":"4 pairs","value":"4 pairs"},{"label":"2 pairs","value":"2 pairs"},{"label":"3 pairs","value":"3 pairs"}]},{"id":5,"text":"Two lines are both perpendicular to the same line. Are they parallel to each other? Explain.","type":"multiple_choice","correct_answer":"Yes","explanation":"If two lines are both perpendicular to a third line, they must be parallel to each other (both form 90° with the same line).","standard_code":"4.G.1","difficulty":3,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]}]'::jsonb);

VALUES (4,'G','4.G.2','Classify two-dimensional figures based on the presence or absence of parallel or perpendicular lines, or angles of a specified size (Easy)','Practice Classify two-dimensional figures based on the presence or absence of parallel or perpendicular lines, or angles of a specified size','practice',1,10,295,'[{"id":1,"text":"Does a square have parallel sides?","type":"multiple_choice","correct_answer":"Yes, 2 pairs of parallel sides","explanation":"Opposite sides of a square are parallel.","standard_code":"4.G.2","difficulty":1,"options":[{"label":"No, squares have no parallel sides","value":"No, squares have no parallel sides"},{"label":"Yes, 4 pairs of parallel sides","value":"Yes, 4 pairs of parallel sides"},{"label":"Yes, 1 pair of parallel sides","value":"Yes, 1 pair of parallel sides"},{"label":"Yes, 2 pairs of parallel sides","value":"Yes, 2 pairs of parallel sides"}]},{"id":2,"text":"How many right angles does a rectangle have?","type":"numeric","correct_answer":"4","explanation":"All four angles in a rectangle are 90°.","standard_code":"4.G.2","difficulty":1},{"id":3,"text":"Does a triangle always have right angles?","type":"multiple_choice","correct_answer":"No","explanation":"Only right triangles have a 90° angle. Other triangles don''t.","standard_code":"4.G.2","difficulty":1,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]},{"id":4,"text":"Name a quadrilateral with no parallel sides.","type":"multiple_choice","correct_answer":"An irregular quadrilateral (or a general trapezium in some definitions)","explanation":"A quadrilateral with no sides parallel has no special name but exists.","standard_code":"4.G.2","difficulty":1,"options":[{"label":"An irregular quadrilateral (or a general trapezium in some definitions)","value":"An irregular quadrilateral (or a general trapezium in some definitions)"},{"label":"A parallelogram","value":"A parallelogram"},{"label":"A square","value":"A square"},{"label":"A kite","value":"A kite"}]},{"id":5,"text":"Does a rhombus have parallel sides?","type":"multiple_choice","correct_answer":"Yes, 2 pairs","explanation":"A rhombus is a parallelogram - opposite sides are parallel.","standard_code":"4.G.2","difficulty":1,"options":[{"label":"Yes, 2 pairs","value":"Yes, 2 pairs"},{"label":"No parallel sides","value":"No parallel sides"},{"label":"4 pairs of parallel sides","value":"4 pairs of parallel sides"},{"label":"1 pair of parallel sides","value":"1 pair of parallel sides"}]}]'::jsonb);

VALUES (4,'G','4.G.2','Classify two-dimensional figures based on the presence or absence of parallel or perpendicular lines, or angles of a specified size (Medium)','Practice Classify two-dimensional figures based on the presence or absence of parallel or perpendicular lines, or angles of a specified size','practice',2,15,296,'[{"id":1,"text":"Classify a rectangle: how many pairs of parallel sides, perpendicular sides, and right angles?","type":"multiple_choice","correct_answer":"2 pairs parallel, 4 pairs perpendicular adjacent sides, 4 right angles","explanation":"Rectangle: 2 pairs parallel sides, each pair of adjacent sides is perpendicular, 4 right angles.","standard_code":"4.G.2","difficulty":2,"options":[{"label":"1 pair parallel, 4 pairs perpendicular adjacent sides, 4 right angles","value":"1 pair parallel, 4 pairs perpendicular adjacent sides, 4 right angles"},{"label":"2 pairs parallel, 4 pairs perpendicular adjacent sides, 8 right angles","value":"2 pairs parallel, 4 pairs perpendicular adjacent sides, 8 right angles"},{"label":"2 pairs parallel, 2 pairs perpendicular adjacent sides, 2 right angles","value":"2 pairs parallel, 2 pairs perpendicular adjacent sides, 2 right angles"},{"label":"2 pairs parallel, 4 pairs perpendicular adjacent sides, 4 right angles","value":"2 pairs parallel, 4 pairs perpendicular adjacent sides, 4 right angles"}]},{"id":2,"text":"A triangle has angles 90°, 45°, 45°. Classify it by its angles.","type":"multiple_choice","correct_answer":"Right triangle (also isosceles)","explanation":"It has a 90° angle (right) and two equal 45° angles (isosceles).","standard_code":"4.G.2","difficulty":2,"options":[{"label":"Right triangle (also isosceles)","value":"Right triangle (also isosceles)"},{"label":"Acute triangle","value":"Acute triangle"},{"label":"Obtuse triangle (also isosceles)","value":"Obtuse triangle (also isosceles)"},{"label":"Equilateral triangle","value":"Equilateral triangle"}]},{"id":3,"text":"What makes a square different from other rectangles?","type":"multiple_choice","correct_answer":"All four sides are equal length","explanation":"A square is a rectangle with all sides equal. Rectangles only require opposite sides equal.","standard_code":"4.G.2","difficulty":2,"options":[{"label":"All four sides are equal length","value":"All four sides are equal length"},{"label":"It has 2 pairs of parallel sides","value":"It has 2 pairs of parallel sides"},{"label":"It has 4 right angles","value":"It has 4 right angles"},{"label":"It has no perpendicular sides","value":"It has no perpendicular sides"}]},{"id":4,"text":"Can a parallelogram have exactly one right angle?","type":"multiple_choice","correct_answer":"No, it must have 0 or 4","explanation":"If one angle is 90°, the opposite angle must also be 90°, and adjacent angles must be 180°−90°=90°. So all four must be right angles.","standard_code":"4.G.2","difficulty":2,"options":[{"label":"Maybe, depending on how it is drawn","value":"Maybe, depending on how it is drawn"},{"label":"No, it must have 0 or 4","value":"No, it must have 0 or 4"},{"label":"Yes, all parallelograms with one right angle have exactly four","value":"Yes, all parallelograms with one right angle have exactly four"},{"label":"Yes, it can have one or three right angles","value":"Yes, it can have one or three right angles"}]},{"id":5,"text":"A quadrilateral has exactly one pair of parallel sides and no right angles. What is it?","type":"multiple_choice","correct_answer":"A trapezoid (without right angles)","explanation":"One pair of parallel sides = trapezoid. No right angles makes it a non-right trapezoid.","standard_code":"4.G.2","difficulty":2,"options":[{"label":"A parallelogram with right angles","value":"A parallelogram with right angles"},{"label":"A trapezoid (without right angles)","value":"A trapezoid (without right angles)"},{"label":"A kite with one pair of parallel sides","value":"A kite with one pair of parallel sides"},{"label":"A rectangle","value":"A rectangle"}]}]'::jsonb);

VALUES (4,'G','4.G.2','Classify two-dimensional figures based on the presence or absence of parallel or perpendicular lines, or angles of a specified size (Hard)','Practice Classify two-dimensional figures based on the presence or absence of parallel or perpendicular lines, or angles of a specified size','practice',3,20,297,'[{"id":1,"text":"Is every square a rectangle? Is every rectangle a square? Explain.","type":"multiple_choice","correct_answer":"Yes; No","explanation":"Every square IS a rectangle (4 right angles, opposite sides parallel and equal). But not every rectangle is a square (sides may differ).","standard_code":"4.G.2","difficulty":3,"options":[{"label":"No; Yes","value":"No; Yes"},{"label":"Yes; No","value":"Yes; No"},{"label":"Yes; Yes","value":"Yes; Yes"},{"label":"No; No","value":"No; No"}]},{"id":2,"text":"Is every rhombus a parallelogram? Is every parallelogram a rhombus?","type":"multiple_choice","correct_answer":"Yes; No","explanation":"Every rhombus has 2 pairs of parallel sides (parallelogram). But parallelograms don''t need all sides equal.","standard_code":"4.G.2","difficulty":3,"options":[{"label":"No; No","value":"No; No"},{"label":"Yes; No","value":"Yes; No"},{"label":"Yes; Yes","value":"Yes; Yes"},{"label":"No; Yes","value":"No; Yes"}]},{"id":3,"text":"Name all quadrilaterals that always have 4 right angles.","type":"multiple_choice","correct_answer":"Rectangles and squares","explanation":"Rectangles always have 4 right angles. Squares are special rectangles, so they do too.","standard_code":"4.G.2","difficulty":3,"options":[{"label":"Trapezoids and parallelograms","value":"Trapezoids and parallelograms"},{"label":"Squares and triangles","value":"Squares and triangles"},{"label":"Rectangles and rhombuses","value":"Rectangles and rhombuses"},{"label":"Rectangles and squares","value":"Rectangles and squares"}]},{"id":4,"text":"A shape has 4 equal sides and no right angles. What is it?","type":"multiple_choice","correct_answer":"A rhombus (that is not a square)","explanation":"4 equal sides = rhombus. If no right angles, it''s a rhombus but not a square.","standard_code":"4.G.2","difficulty":3,"options":[{"label":"A kite","value":"A kite"},{"label":"A rhombus (that is not a square)","value":"A rhombus (that is not a square)"},{"label":"A trapezoid","value":"A trapezoid"},{"label":"A parallelogram","value":"A parallelogram"}]},{"id":5,"text":"Can a right triangle have two right angles? Explain.","type":"multiple_choice","correct_answer":"No","explanation":"Triangle angles sum to 180°. Two right angles = 180°, leaving 0° for the third angle, which is impossible.","standard_code":"4.G.2","difficulty":3,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]}]'::jsonb);

VALUES (4,'G','4.G.3','Recognize a line of symmetry for a two-dimensional figure (Easy)','Practice Recognize a line of symmetry for a two-dimensional figure','practice',1,10,298,'[{"id":1,"text":"Does a square have lines of symmetry? How many?","type":"multiple_choice","correct_answer":"Yes, 4 lines of symmetry","explanation":"A square can be folded along 4 lines: 2 through midpoints of sides, 2 along diagonals.","standard_code":"4.G.3","difficulty":1,"options":[{"label":"Yes, 8 lines of symmetry","value":"Yes, 8 lines of symmetry"},{"label":"Yes, 2 lines of symmetry","value":"Yes, 2 lines of symmetry"},{"label":"Yes, 4 lines of symmetry","value":"Yes, 4 lines of symmetry"},{"label":"No lines of symmetry","value":"No lines of symmetry"}]},{"id":2,"text":"Does the letter A have a line of symmetry?","type":"multiple_choice","correct_answer":"Yes, 1 vertical line of symmetry","explanation":"The letter A can be folded vertically down the middle.","standard_code":"4.G.3","difficulty":1,"options":[{"label":"No lines of symmetry","value":"No lines of symmetry"},{"label":"Yes, 1 vertical line of symmetry","value":"Yes, 1 vertical line of symmetry"},{"label":"Yes, 2 horizontal lines of symmetry","value":"Yes, 2 horizontal lines of symmetry"},{"label":"Yes, 1 horizontal line of symmetry","value":"Yes, 1 horizontal line of symmetry"}]},{"id":3,"text":"How many lines of symmetry does a circle have?","type":"multiple_choice","correct_answer":"Infinite (unlimited)","explanation":"Any line through the center of a circle is a line of symmetry.","standard_code":"4.G.3","difficulty":1,"options":[{"label":"Infinite (unlimited)","value":"Infinite (unlimited)"},{"label":"2 lines of symmetry","value":"2 lines of symmetry"},{"label":"1 line of symmetry","value":"1 line of symmetry"},{"label":"4 lines of symmetry","value":"4 lines of symmetry"}]},{"id":4,"text":"Does a rectangle (non-square) have lines of symmetry? How many?","type":"multiple_choice","correct_answer":"Yes, 2 lines of symmetry","explanation":"Fold horizontally through the middle or vertically through the middle.","standard_code":"4.G.3","difficulty":1,"options":[{"label":"Yes, 2 lines of symmetry","value":"Yes, 2 lines of symmetry"},{"label":"Yes, 1 line of symmetry","value":"Yes, 1 line of symmetry"},{"label":"Yes, 4 lines of symmetry","value":"Yes, 4 lines of symmetry"},{"label":"No lines of symmetry","value":"No lines of symmetry"}]},{"id":5,"text":"Does the letter B have a line of symmetry?","type":"multiple_choice","correct_answer":"Yes, 1 horizontal line","explanation":"The letter B can be folded along a horizontal line through its middle.","standard_code":"4.G.3","difficulty":1,"options":[{"label":"Yes, 2 lines of symmetry","value":"Yes, 2 lines of symmetry"},{"label":"No lines of symmetry","value":"No lines of symmetry"},{"label":"Yes, 1 horizontal line","value":"Yes, 1 horizontal line"},{"label":"Yes, 1 vertical line","value":"Yes, 1 vertical line"}]}]'::jsonb);

VALUES (4,'G','4.G.3','Recognize a line of symmetry for a two-dimensional figure (Medium)','Practice Recognize a line of symmetry for a two-dimensional figure','practice',2,15,299,'[{"id":1,"text":"How many lines of symmetry does an equilateral triangle have?","type":"numeric","correct_answer":"3","explanation":"Each line goes from a vertex to the midpoint of the opposite side.","standard_code":"4.G.3","difficulty":2},{"id":2,"text":"Does a parallelogram (non-rectangle) have any lines of symmetry?","type":"multiple_choice","correct_answer":"No","explanation":"A general parallelogram has no lines of symmetry. Only special cases (rectangles, rhombi) do.","standard_code":"4.G.3","difficulty":2,"options":[{"label":"Yes","value":"Yes"},{"label":"No","value":"No"}]},{"id":3,"text":"How many lines of symmetry does a regular pentagon have?","type":"numeric","correct_answer":"5","explanation":"A regular pentagon has 5 lines of symmetry, each from a vertex to the midpoint of the opposite side.","standard_code":"4.G.3","difficulty":2},{"id":4,"text":"Does an isosceles triangle have a line of symmetry? How many?","type":"multiple_choice","correct_answer":"Yes, 1 line","explanation":"The line from the vertex angle to the midpoint of the base is the line of symmetry.","standard_code":"4.G.3","difficulty":2,"options":[{"label":"No lines of symmetry","value":"No lines of symmetry"},{"label":"Yes, 3 lines","value":"Yes, 3 lines"},{"label":"Yes, 1 line","value":"Yes, 1 line"},{"label":"Yes, 2 lines","value":"Yes, 2 lines"}]},{"id":5,"text":"Which has more lines of symmetry: a square or an equilateral triangle?","type":"multiple_choice","correct_answer":"A square (4 vs. 3)","explanation":"Square: 4 lines. Equilateral triangle: 3 lines.","standard_code":"4.G.3","difficulty":2,"options":[{"label":"A square (4 vs. 3)","value":"A square (4 vs. 3)"},{"label":"An equilateral triangle (4 vs. 3)","value":"An equilateral triangle (4 vs. 3)"},{"label":"They have the same number","value":"They have the same number"},{"label":"An equilateral triangle (3 vs. 4)","value":"An equilateral triangle (3 vs. 4)"}]}]'::jsonb);

VALUES (4,'G','4.G.3','Recognize a line of symmetry for a two-dimensional figure (Hard)','Practice Recognize a line of symmetry for a two-dimensional figure','practice',3,20,300,'[{"id":1,"text":"A regular hexagon has how many lines of symmetry?","type":"numeric","correct_answer":"6","explanation":"3 lines through opposite vertices + 3 lines through midpoints of opposite sides = 6.","standard_code":"4.G.3","difficulty":3},{"id":2,"text":"Can you draw a quadrilateral with exactly 1 line of symmetry? Describe it.","type":"multiple_choice","correct_answer":"Yes - a kite or an isosceles trapezoid","explanation":"A kite has 1 line of symmetry along its main diagonal. An isosceles trapezoid has 1 vertical line of symmetry.","standard_code":"4.G.3","difficulty":3,"options":[{"label":"Yes - a scalene triangle","value":"Yes - a scalene triangle"},{"label":"Yes - a kite or an isosceles trapezoid","value":"Yes - a kite or an isosceles trapezoid"},{"label":"No, it''s impossible","value":"No, it''s impossible"},{"label":"Yes - a parallelogram","value":"Yes - a parallelogram"}]},{"id":3,"text":"Which capital letters have exactly 2 lines of symmetry?","type":"multiple_choice","correct_answer":"H, I, O, X","explanation":"H, I, O, and X can each be folded both horizontally and vertically.","standard_code":"4.G.3","difficulty":3,"options":[{"label":"H, I, O, X","value":"H, I, O, X"},{"label":"A, B, C, D","value":"A, B, C, D"},{"label":"H, I, M, O","value":"H, I, M, O"},{"label":"B, C, D, E","value":"B, C, D, E"}]},{"id":4,"text":"If a shape has rotational symmetry of order 3, what can you say about its lines of symmetry?","type":"multiple_choice","correct_answer":"It has at least 3 lines of symmetry (if it has line symmetry at all)","explanation":"Shapes with order-3 rotational symmetry and line symmetry have exactly 3 lines (like equilateral triangles).","standard_code":"4.G.3","difficulty":3,"options":[{"label":"It has no lines of symmetry","value":"It has no lines of symmetry"},{"label":"It has at least 3 lines of symmetry (if it has line symmetry at all)","value":"It has at least 3 lines of symmetry (if it has line symmetry at all)"},{"label":"It has 6 or more lines of symmetry","value":"It has 6 or more lines of symmetry"},{"label":"It has exactly 3 lines of symmetry","value":"It has exactly 3 lines of symmetry"}]},{"id":5,"text":"Draw or describe a figure with no lines of symmetry.","type":"multiple_choice","correct_answer":"A scalene triangle or the letter F","explanation":"A scalene triangle has all different sides and angles - no fold line will match both halves.","standard_code":"4.G.3","difficulty":3,"options":[{"label":"A rectangle","value":"A rectangle"},{"label":"A circle","value":"A circle"},{"label":"An equilateral triangle","value":"An equilateral triangle"},{"label":"A scalene triangle or the letter F","value":"A scalene triangle or the letter F"}]}]'::jsonb);


